#[derive(Debug, Deserialize)]
struct ApiRequest {
    path: String,
    method: Option<String>,
    token: Option<String>,
    #[serde(rename = "baseUrl")]
    base_url: Option<String>,
    body: Option<Value>,
    headers: Option<HashMap<String, String>>,
    #[serde(rename = "timeoutMs")]
    timeout_ms: Option<u64>,
}

#[derive(Debug, Serialize)]
struct ApiResponse {
    ok: bool,
    status: u16,
    payload: Value,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct ApiTransportError {
    kind: String,
    message: String,
    retryable: bool,
    elapsed_ms: u64,
    host: Option<String>,
}

impl ApiTransportError {
    fn new(
        kind: impl Into<String>,
        message: impl Into<String>,
        retryable: bool,
        started_at: Instant,
        host: Option<String>,
    ) -> Self {
        Self {
            kind: kind.into(),
            message: message.into(),
            retryable,
            elapsed_ms: started_at.elapsed().as_millis().min(u64::MAX as u128) as u64,
            host,
        }
    }
}

static GAOGE_API_HTTP_CLIENT: Lazy<Result<reqwest::Client, String>> = Lazy::new(|| {
    reqwest::Client::builder()
        .connect_timeout(Duration::from_secs(GAOGE_API_CONNECT_TIMEOUT_SECS))
        .pool_idle_timeout(Duration::from_secs(90))
        .tcp_keepalive(Duration::from_secs(30))
        .user_agent(GAOGE_USER_AGENT)
        .gzip(true)
        .build()
        .map_err(|error| format!("failed to create API client: {error}"))
});

fn api_request_host(url: &str) -> Option<String> {
    url::Url::parse(url)
        .ok()
        .and_then(|parsed| parsed.host_str().map(str::to_string))
}

fn classify_api_transport_error(error: &reqwest::Error) -> (&'static str, bool) {
    if error.is_timeout() {
        return ("timeout", true);
    }
    let detail = error.to_string().to_ascii_lowercase();
    if detail.contains("dns")
        || detail.contains("lookup address")
        || detail.contains("failed to lookup")
        || detail.contains("name or service not known")
    {
        return ("dns", true);
    }
    if detail.contains("tls")
        || detail.contains("ssl")
        || detail.contains("certificate")
        || detail.contains("handshake")
    {
        return ("tls", true);
    }
    if error.is_connect() {
        return ("connect", true);
    }
    if error.is_body() || error.is_decode() {
        return ("response", true);
    }
    ("request", false)
}

fn is_allowed_api_header(name: &str) -> bool {
    matches!(
        name.trim().to_ascii_lowercase().as_str(),
        "idempotency-key" | "accept-language" | "x-request-id"
    )
}

