fn normalize_codex_model_selection_origin(value: Option<&str>) -> String {
    match value.unwrap_or("").trim() {
        CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC => {
            CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC.to_string()
        }
        CODEX_MODEL_SELECTION_ORIGIN_USER => CODEX_MODEL_SELECTION_ORIGIN_USER.to_string(),
        _ => String::new(),
    }
}

fn aggregate_default_model_for_upstream(
    state: &AggregateLoginState,
    upstream_model: &str,
) -> Option<String> {
    state
        .routes
        .iter()
        .find(|route| route.provider_id == "openai" && route.upstream_model == upstream_model)
        .map(|route| route.public_model.clone())
}

fn aggregate_legacy_default_matches_old_automatic_selection(state: &AggregateLoginState) -> bool {
    aggregate_default_model_for_upstream(state, CODEX_LEGACY_DEFAULT_MODEL).as_deref()
        == Some(state.default_model.as_str())
}

fn migrate_aggregate_automatic_default_model(state: &mut AggregateLoginState) -> bool {
    if state.default_model_origin != CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC {
        return false;
    }
    let uses_legacy_default = state.routes.iter().any(|route| {
        route.public_model == state.default_model
            && route.upstream_model == CODEX_LEGACY_DEFAULT_MODEL
    });
    if !uses_legacy_default {
        return false;
    }
    let Some(next_default) = aggregate_default_model_for_upstream(state, CODEX_DEFAULT_MODEL)
    else {
        return false;
    };
    if next_default == state.default_model {
        return false;
    }
    state.default_model = next_default;
    true
}

fn normalize_aggregate_conversation_state(state: &mut AggregateLoginState) -> bool {
    let previous_routes = state.routes.len();
    let previous_default = state.default_model.clone();
    let previous_origin = state.default_model_origin.clone();
    let previous_enabled = state.enabled;
    state
        .routes
        .retain(|route| is_codex_conversation_model(&route.upstream_model));

    if state.routes.is_empty() {
        state.enabled = false;
        state.default_model.clear();
        state.default_model_origin = CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC.to_string();
    } else if !state
        .routes
        .iter()
        .any(|route| route.public_model == state.default_model)
    {
        state.default_model = state
            .routes
            .iter()
            .find(|route| {
                route.provider_id == "openai" && route.upstream_model == CODEX_DEFAULT_MODEL
            })
            .or_else(|| {
                state
                    .routes
                    .iter()
                    .find(|route| route.provider_id == "openai")
            })
            .unwrap_or(&state.routes[0])
            .public_model
            .clone();
        state.default_model_origin = CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC.to_string();
    } else {
        if normalize_codex_model_selection_origin(Some(&state.default_model_origin)).is_empty() {
            state.default_model_origin = CODEX_MODEL_SELECTION_ORIGIN_USER.to_string();
        }
        migrate_aggregate_automatic_default_model(state);
    }

    previous_routes != state.routes.len()
        || previous_default != state.default_model
        || previous_origin != state.default_model_origin
        || previous_enabled != state.enabled
}

