fn update_feed_url() -> String {
    update_feed_url_with_base(None)
}

fn update_feed_url_with_base(update_base_url: Option<&str>) -> String {
    let base = update_base_url
        .filter(|value| !value.trim().is_empty())
        .unwrap_or(UPDATE_FEED_BASE_URL)
        .trim_end_matches('/');
    if base.is_empty() {
        return String::new();
    }
    format!("{base}/{}/latest.json", current_platform_id())
}

fn update_feed_base_from_request(request: Option<&Value>) -> Option<String> {
    request
        .and_then(|value| {
            value
                .get("updateBaseUrl")
                .or_else(|| value.get("update_base_url"))
                .or_else(|| value.get("downloadBaseUrl"))
                .or_else(|| value.get("download_base_url"))
        })
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.trim_end_matches('/').to_string())
}

