fn claude_desktop_paths() -> Option<ClaudeDesktopPaths> {
    if cfg!(target_os = "windows") {
        let base = local_app_data_dir();
        let normal_dir =
            pick_windows_claude_desktop_dir(&base, false).unwrap_or_else(|| base.join("Claude"));
        let threep_dir =
            pick_windows_claude_desktop_dir(&base, true).unwrap_or_else(|| base.join("Claude-3p"));
        Some(claude_desktop_paths_from_dirs(normal_dir, threep_dir))
    } else if cfg!(target_os = "macos") {
        let base = home_dir().join("Library").join("Application Support");
        Some(claude_desktop_paths_from_dirs(
            base.join("Claude"),
            base.join("Claude-3p"),
        ))
    } else {
        None
    }
}

fn pick_windows_claude_desktop_dir(base: &Path, threep: bool) -> Option<PathBuf> {
    let exact = base.join(if threep { "Claude-3p" } else { "Claude" });
    if exact.exists() {
        return Some(exact);
    }

    let mut candidates: Vec<PathBuf> = fs::read_dir(base)
        .ok()?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.is_dir())
        .filter(|path| {
            let Some(name) = path.file_name().and_then(OsStr::to_str) else {
                return false;
            };
            name.starts_with("Claude") && name.contains("-3p") == threep
        })
        .collect();
    candidates.sort();
    candidates.into_iter().next()
}

fn claude_desktop_paths_from_dirs(normal_dir: PathBuf, threep_dir: PathBuf) -> ClaudeDesktopPaths {
    let config_library_path = threep_dir.join(CLAUDE_DESKTOP_CONFIG_LIBRARY_DIR);
    ClaudeDesktopPaths {
        normal_config_path: normal_dir.join(CLAUDE_DESKTOP_CONFIG_FILE),
        threep_config_path: threep_dir.join(CLAUDE_DESKTOP_CONFIG_FILE),
        profile_path: config_library_path.join(format!("{CLAUDE_DESKTOP_PROFILE_ID}.json")),
        meta_path: config_library_path.join("_meta.json"),
        config_library_path,
    }
}

