fn normalize_codex_install_target(selection: &Path) -> PathBuf {
    let trimmed = selection.to_string_lossy().trim().to_string();
    let mut path = if trimmed.is_empty() {
        default_portable_codex_dir()
    } else {
        PathBuf::from(trimmed)
    };
    let expected_name = if cfg!(target_os = "macos") {
        "Codex.app"
    } else {
        "OpenAI Codex Portable"
    };
    let is_named_target = path
        .file_name()
        .and_then(|value| value.to_str())
        .map(|name| name.eq_ignore_ascii_case(expected_name))
        .unwrap_or(false);
    if !is_named_target {
        path = path.join(expected_name);
    }
    path
}

