fn normalize_codex_launch_selection(selection: &Path) -> Option<PathBuf> {
    if is_macos_app_bundle(selection) || selection.is_dir() {
        return Some(selection.to_path_buf());
    }

    let file_name = selection.file_name()?.to_str()?;
    if !file_name.eq_ignore_ascii_case("Codex.exe")
        && !file_name.eq_ignore_ascii_case("ChatGPT.exe")
    {
        return None;
    }
    let parent = selection.parent()?;
    if parent
        .file_name()
        .and_then(OsStr::to_str)
        .is_some_and(|name| name.eq_ignore_ascii_case("resources"))
    {
        parent.parent().map(Path::to_path_buf)
    } else {
        Some(parent.to_path_buf())
    }
}

fn validate_codex_launch_selection(selection: &Path) -> Result<PathBuf, String> {
    let app_dir = normalize_codex_launch_selection(selection)
        .ok_or_else(|| "请选择 Codex.exe、ChatGPT.exe 或 macOS 的 Codex.app。".to_string())?;
    if !is_complete_codex_app_dir(&app_dir) {
        return Err(format!(
            "所选 Codex 程序不完整，必须包含可执行文件和 resources/app.asar：{}",
            selection.display()
        ));
    }
    Ok(app_dir)
}

