fn backup_claude_desktop_config(
    paths: &ClaudeDesktopPaths,
    label: &str,
) -> Result<Vec<String>, String> {
    let mut backups = Vec::new();
    for path in [
        &paths.normal_config_path,
        &paths.threep_config_path,
        &paths.profile_path,
        &paths.meta_path,
    ] {
        if let Some(backup) = backup_claude_desktop_file(path, label)? {
            backups.push(backup.to_string_lossy().to_string());
        }
    }
    Ok(backups)
}

fn escape_toml(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

fn normalize_model(value: Option<&str>) -> String {
    let model = value.unwrap_or("").trim();
    if model.is_empty() {
        CODEX_DEFAULT_MODEL.to_string()
    } else {
        model.trim_start_matches("额度加油包 · ").to_string()
    }
}

#[derive(Clone, Debug)]
struct CodexModelCatalogPlan {
    mode: String,
    source: String,
    models: Vec<String>,
    warning: String,
}

#[derive(Clone, Debug)]
struct CodexModelCatalogWriteResult {
    path: PathBuf,
    models: Vec<String>,
}

#[derive(Clone, Debug)]
struct ResolvedCodexModelCatalog {
    model: String,
    plan: CodexModelCatalogPlan,
    catalog: Value,
}

fn codex_fallback_models() -> Vec<String> {
    CODEX_FALLBACK_MODELS
        .iter()
        .map(|model| (*model).to_string())
        .collect()
}

fn claude_fallback_models() -> Vec<String> {
    CLAUDE_FALLBACK_MODELS
        .iter()
        .map(|model| (*model).to_string())
        .collect()
}

fn normalize_codex_model_names(value: Option<&Value>) -> Vec<String> {
    let mut models = Vec::new();
    let mut seen = HashSet::new();
    if let Some(items) = value.and_then(Value::as_array) {
        for item in items {
            let model = item
                .as_str()
                .or_else(|| item.get("id").and_then(Value::as_str))
                .or_else(|| item.get("slug").and_then(Value::as_str))
                .or_else(|| item.get("name").and_then(Value::as_str))
                .unwrap_or("")
                .trim();
            if !model.is_empty()
                && model.len() <= if model.starts_with("gaoge/") { 240 } else { 200 }
                && !model.chars().any(char::is_control)
                && seen.insert(model.to_string())
            {
                models.push(model.to_string());
            }
        }
    }
    models
}

fn codex_model_catalog_plan(
    request: &Value,
    requested_model: &str,
) -> Result<(String, CodexModelCatalogPlan), String> {
    let mode = match request
        .get("modelSelectionMode")
        .and_then(Value::as_str)
        .unwrap_or(CODEX_MODEL_SELECTION_LOCKED)
    {
        CODEX_MODEL_SELECTION_UPSTREAM => CODEX_MODEL_SELECTION_UPSTREAM,
        _ => CODEX_MODEL_SELECTION_LOCKED,
    };
    let source = match request
        .get("modelCatalogSource")
        .and_then(Value::as_str)
        .unwrap_or(CODEX_MODEL_CATALOG_SOURCE_UPSTREAM)
    {
        CODEX_MODEL_CATALOG_SOURCE_FALLBACK => CODEX_MODEL_CATALOG_SOURCE_FALLBACK,
        _ => CODEX_MODEL_CATALOG_SOURCE_UPSTREAM,
    };
    let supported_models = normalize_codex_model_names(request.get("supportedModels"))
        .into_iter()
        .filter(|model| is_codex_conversation_model(model))
        .collect::<Vec<_>>();
    let requested_model = normalize_model(Some(requested_model));
    let requested_is_conversation = is_codex_conversation_model(&requested_model);

    if mode == CODEX_MODEL_SELECTION_UPSTREAM {
        let models = if source == CODEX_MODEL_CATALOG_SOURCE_FALLBACK {
            codex_fallback_models()
        } else {
            supported_models
        };
        if models.is_empty() {
            return Err("上游没有返回可写入 Codex 的模型，请刷新模型后重试。".to_string());
        }
        let model = if source == CODEX_MODEL_CATALOG_SOURCE_FALLBACK {
            CODEX_DEFAULT_MODEL.to_string()
        } else if requested_is_conversation
            && models.iter().any(|candidate| candidate == &requested_model)
        {
            requested_model.clone()
        } else if models
            .iter()
            .any(|candidate| candidate == CODEX_DEFAULT_MODEL)
        {
            CODEX_DEFAULT_MODEL.to_string()
        } else {
            models[0].clone()
        };
        let mut warnings = Vec::new();
        if source == CODEX_MODEL_CATALOG_SOURCE_FALLBACK {
            warnings.push("上游模型获取失败，已使用默认兼容模型目录。".to_string());
        }
        if !requested_is_conversation {
            warnings.push(format!(
                "旧配置中的生图模型 {requested_model} 不能用于对话，已自动切换到 {model}。"
            ));
        }
        let warning = warnings.join(" ");
        return Ok((
            model,
            CodexModelCatalogPlan {
                mode: mode.to_string(),
                source: source.to_string(),
                models,
                warning,
            },
        ));
    }

    if !requested_is_conversation {
        let replacement = if source == CODEX_MODEL_CATALOG_SOURCE_FALLBACK {
            Some(CODEX_DEFAULT_MODEL.to_string())
        } else {
            supported_models
                .iter()
                .find(|candidate| candidate.as_str() == CODEX_DEFAULT_MODEL)
                .or_else(|| supported_models.first())
                .cloned()
        };
        let replacement = replacement.ok_or_else(|| {
            format!("{requested_model} 是生图模型，且上游没有返回可用对话模型，请刷新模型后重试。")
        })?;
        return Ok((
            replacement.clone(),
            CodexModelCatalogPlan {
                mode: mode.to_string(),
                source: source.to_string(),
                models: vec![replacement.clone()],
                warning: format!(
                    "旧配置中的生图模型 {requested_model} 不能用于对话，已自动切换到 {replacement}。"
                ),
            },
        ));
    }

    let available_locked_models = supported_models;
    if source == CODEX_MODEL_CATALOG_SOURCE_UPSTREAM
        && !available_locked_models.is_empty()
        && !available_locked_models
            .iter()
            .any(|candidate| candidate == &requested_model)
    {
        return Err(format!(
            "上游已不再支持锁定模型 {requested_model}，请刷新后重新选择。"
        ));
    }
    let warning = if source == CODEX_MODEL_CATALOG_SOURCE_FALLBACK {
        "上游模型获取失败，继续使用已锁定模型。".to_string()
    } else {
        String::new()
    };
    Ok((
        requested_model.clone(),
        CodexModelCatalogPlan {
            mode: mode.to_string(),
            source: source.to_string(),
            models: vec![requested_model],
            warning,
        },
    ))
}

fn codex_catalog_model_names(catalog: &Value) -> Vec<String> {
    catalog
        .get("models")
        .and_then(Value::as_array)
        .map(|models| {
            models
                .iter()
                .filter_map(|model| model.get("slug").and_then(Value::as_str))
                .map(ToString::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn codex_catalog_reasoning_effort(catalog: &Value, model: &str, requested: Option<&str>) -> String {
    let requested = normalize_codex_reasoning_effort(requested);
    let Some(entry) = catalog
        .get("models")
        .and_then(Value::as_array)
        .and_then(|models| {
            models
                .iter()
                .find(|entry| entry.get("slug").and_then(Value::as_str) == Some(model))
        })
    else {
        return requested;
    };
    let supported = entry
        .get("supported_reasoning_levels")
        .and_then(Value::as_array)
        .map(|levels| {
            levels
                .iter()
                .filter_map(codex_reasoning_level_effort)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    if supported.is_empty() && (model.starts_with("gaoge/")
        || entry.get("supported_reasoning_levels").is_some_and(Value::is_array)) {
        return "none".to_string();
    }
    if supported.iter().any(|effort| *effort == requested) {
        return requested;
    }
    if let Some(requested_rank) = codex_reasoning_effort_rank(&requested) {
        if let Some(effort) = supported
            .iter()
            .filter_map(|effort| {
                codex_reasoning_effort_rank(effort)
                    .filter(|rank| *rank <= requested_rank)
                    .map(|rank| (*effort, rank))
            })
            .max_by_key(|(_, rank)| *rank)
            .map(|(effort, _)| effort)
        {
            return effort.to_string();
        }
    }
    entry
        .get("default_reasoning_level")
        .and_then(Value::as_str)
        .filter(|effort| supported.iter().any(|supported| supported == effort))
        .unwrap_or("medium")
        .to_string()
}

fn codex_model_display_name(slug: &str) -> String {
    if let Some(rest) = slug.strip_prefix("gaoge/") {
        let mut parts = rest.splitn(3, '/');
        let provider = parts.next().unwrap_or_default();
        let _group = parts.next().unwrap_or_default();
        let model = parts.next().unwrap_or_default();
        if !model.is_empty() {
            let label = match provider {
                "openai" => "GPT",
                "anthropic" | "claude" => "Claude",
                "grok" | "xai" => "Grok",
                "kimi" | "moonshot" => "Kimi",
                "deepseek" => "DeepSeek",
                "glm" | "zhipu" | "bigmodel" | "zai" => "GLM",
                _ => provider,
            };
            return format!("{label} 路 {model}");
        }
    }
    if let Some(model) = slug.strip_prefix("openai/") {
        return format!("GPT · {model}");
    }
    if let Some(model) = slug
        .strip_prefix("anthropic/")
        .or_else(|| slug.strip_prefix("claude/"))
    {
        return format!("Claude · {model}");
    }
    if let Some(model) = slug.strip_prefix("deepseek/") {
        return format!("DeepSeek · {model}");
    }
    if let Some(model) = slug
        .strip_prefix("glm/")
        .or_else(|| slug.strip_prefix("zhipu/"))
    {
        return format!("GLM · {model}");
    }
    match slug {
        "gpt-5.5" => "GPT-5.5".to_string(),
        "gpt-5.4" => "GPT-5.4".to_string(),
        "gpt-5.6-sol" => "GPT-5.6 Sol".to_string(),
        "gpt-5.6-luna" => "GPT-5.6 Luna".to_string(),
        "gpt-5.6-terra" => "GPT-5.6 Terra".to_string(),
        "gpt-image-2" => "GPT Image 2".to_string(),
        _ => slug.to_string(),
    }
}

fn aggregate_provider_short_label(provider_id: &str) -> &str {
    match provider_id {
        "openai" => "GPT",
        "anthropic" | "claude" => "Claude",
        "grok" | "gork" | "xai" => "Grok",
        "kimi" | "moonshot" => "Kimi",
        "deepseek" => "DeepSeek",
        "glm" | "zhipu" | "bigmodel" | "zai" => "GLM",
        _ => provider_id,
    }
}

// Vendor labels are presentation metadata only. Full provider/group/model IDs
// remain the authority for routing when several personal endpoints share a brand.
fn aggregate_route_vendor(route: &AggregateProviderRoute) -> (&str, &str) {
    static PRESET_LABELS: Lazy<HashMap<String, String>> = Lazy::new(|| {
        model_capabilities::provider_presets()
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|preset| Some((preset["id"].as_str()?.to_owned(), preset["name"].as_str()?.to_owned())))
            .collect()
    });
    let vendor = if route.source == aggregate_settings::AggregateSource::Custom {
        route.upstream_platform.as_str()
    } else {
        route.provider_id.as_str()
    };
    let (id, label) = match vendor {
        "openai" => ("openai", "GPT"),
        "anthropic" | "claude" => ("anthropic", "Claude"),
        "grok" | "gork" | "xai" => ("xai", "Grok"),
        "kimi" | "moonshot" => ("kimi", "Kimi"),
        "deepseek" => ("deepseek", "DeepSeek"),
        "glm" | "zhipu" | "bigmodel" | "zai" | "zhipu-glm" => ("glm", "GLM"),
        "google" | "gemini" => ("gemini", "Gemini"),
        "bailian" | "qwen" => ("qwen", "Qwen"),
        "minimax" | "minimax-global" => ("minimax", "MiniMax"),
        "xiaomi-mimo" | "mimo" => ("mimo", "MiMo"),
        "volcano-ark" | "doubao" => ("doubao", "豆包"),
        "custom" | "" => (route.provider_id.as_str(), route.provider_name.as_str()),
        other => (other, PRESET_LABELS.get(other).map(String::as_str).unwrap_or(other)),
    };
    (id, label)
}

fn aggregate_route_native_label(route: &AggregateProviderRoute) -> String {
    if route.source == aggregate_settings::AggregateSource::Custom {
        return format!("{} · {}", route.upstream_model, aggregate_route_vendor(route).1);
    }
    format!(
        "{} · {} · {}",
        route.upstream_model,
        route.group_name,
        if route.provider_id.starts_with("external-") { route.provider_name.as_str() } else { aggregate_provider_short_label(&route.provider_id) }
    )
}

fn claude_reasoning_efforts(model: &str) -> &'static [&'static str] {
    match model.trim().to_ascii_lowercase().as_str() {
        "claude-opus-4-7" | "claude-opus-4-8" | "claude-opus-5" | "claude-sonnet-5" => {
            &["low", "medium", "high", "xhigh", "max"]
        }
        "claude-opus-4-6" | "claude-sonnet-4-6" => &["low", "medium", "high", "max"],
        _ => &["low", "medium", "high"],
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AggregateSpeedTransport {
    OpenAiPriority,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct AggregateSpeedProfile {
    name: &'static str,
    description: &'static str,
    picker_label: &'static str,
    transport: AggregateSpeedTransport,
}

fn normalized_aggregate_model_name(model: &str) -> String {
    model.trim().to_ascii_lowercase().replace('_', "-")
}

fn aggregate_model_matches_release(model: &str, release: &str) -> bool {
    model == release
        || model
            .strip_prefix(release)
            .is_some_and(|suffix| suffix.starts_with('-'))
}

fn codex_speed_release_matches(model: &str, release: &str) -> bool {
    if model == release {
        return true;
    }
    let Some(suffix) = model.strip_prefix(&format!("{release}-")) else {
        return false;
    };
    (suffix.len() == 8 && suffix.bytes().all(|value| value.is_ascii_digit()))
        || (suffix.len() == 10
            && suffix.bytes().enumerate().all(|(index, value)| {
                if index == 4 || index == 7 {
                    value == b'-'
                } else {
                    value.is_ascii_digit()
                }
            }))
}

fn claude_model_max_output_tokens(model: &str) -> u64 {
    let model = normalized_aggregate_model_name(model);
    let high_output_releases = [
        "claude-fable-5",
        "claude-mythos-5",
        "claude-opus-5",
        "claude-sonnet-5",
        "claude-opus-4-8",
        "claude-opus-4-7",
        "claude-opus-4-6",
        "claude-sonnet-4-6",
    ];
    if high_output_releases
        .iter()
        .any(|release| aggregate_model_matches_release(&model, release))
    {
        131_072
    } else {
        16_384
    }
}
fn enforce_claude_max_output_tokens(object: &mut Map<String, Value>, upstream_model: &str) -> u64 {
    let max_output = claude_model_max_output_tokens(upstream_model);
    let requested = object
        .get("max_output_tokens")
        .and_then(Value::as_u64)
        .or_else(|| object.get("max_tokens").and_then(Value::as_u64));
    let safe = requested.map_or(max_output, |value| value.max(max_output));
    object.remove("max_tokens");
    object.insert("max_output_tokens".to_string(), json!(safe));
    safe
}
fn is_aggregate_openai_provider(provider_id: &str) -> bool {
    provider_id.trim().eq_ignore_ascii_case("openai")
}

fn codex_openai_speed_profile(model: &str) -> Option<AggregateSpeedProfile> {
    let model = canonical_model_name(&normalized_aggregate_model_name(model));
    // Current relay models keep native Fast even when an older server sends only IDs.
    if ["gpt-6.1-sol", "gpt-6.2-astra", "gpt-6.2-sol"]
        .iter().any(|release| codex_speed_release_matches(&model, release))
    {
        return Some(AggregateSpeedProfile {
            name: "Fast",
            description: "Faster responses, increased usage",
            picker_label: "快速（用量更高）",
            transport: AggregateSpeedTransport::OpenAiPriority,
        });
    }
    if (codex_speed_release_matches(&model, "gpt-6-astra")
        && fallback_capabilities(&model).verified)
        || codex_speed_release_matches(&model, "gpt-6-sol")
    {
        return Some(AggregateSpeedProfile {
            name: "Fast",
            description: "2x speed, increased usage",
            picker_label: "快速（2 倍速度，用量更高）",
            transport: AggregateSpeedTransport::OpenAiPriority,
        });
    }
    (model == "gpt-5.5"
        || model.starts_with("gpt-5.5-")
        || model == "gpt-5.6"
        || model.starts_with("gpt-5.6-"))
    .then_some(AggregateSpeedProfile {
        name: "Fast",
        description: "1.5x speed, increased usage",
        picker_label: "快速（约 1.5 倍速度，用量更高）",
        transport: AggregateSpeedTransport::OpenAiPriority,
    })
}

fn normalize_aggregate_speed_mode(mode: &str) -> Option<&'static str> {
    match mode.trim().to_ascii_lowercase().as_str() {
        "" | "default" | "standard" | "normal" => Some(AGGREGATE_SPEED_MODE_STANDARD),
        "fast" | "priority" => Some(AGGREGATE_SPEED_MODE_FAST),
        _ => None,
    }
}

fn aggregate_speed_mode_is_fast(mode: &str) -> bool {
    normalize_aggregate_speed_mode(mode) == Some(AGGREGATE_SPEED_MODE_FAST)
}

fn aggregate_entry_supports_fast(entry: &Value) -> bool {
    entry["service_tiers"].as_array().is_some_and(|tiers| tiers.iter().any(|tier| {
        tier.as_str() == Some("priority") || tier["id"].as_str() == Some("priority")
    })) || entry["additional_speed_tiers"].as_array().is_some_and(|tiers| tiers.iter().any(|tier| tier.as_str() == Some("fast")))
}

fn aggregate_route_speed_profile(route: &AggregateProviderRoute) -> Option<AggregateSpeedProfile> {
    // A model name or provider brand is not proof that its endpoint accepts Fast.
    if route.protocol == aggregate_protocol::Protocol::AnthropicMessages || route.model_config["fast"] == "unsupported" {
        return None;
    }
    let supported = route.model_config["fast"] == "supported"
        || model_capabilities::builtin_model_metadata(&route.upstream_model).as_ref().is_some_and(aggregate_entry_supports_fast);
    supported.then_some(AggregateSpeedProfile {
        name: "Fast",
        description: "Priority processing when supported by the upstream account",
        picker_label: "快速（需上游支持）",
        transport: AggregateSpeedTransport::OpenAiPriority,
    })
}

fn aggregate_resolved_speed_profile(route: &AggregateProviderRoute, entry: &Value) -> Option<AggregateSpeedProfile> {
    if route.protocol == aggregate_protocol::Protocol::AnthropicMessages || !aggregate_entry_supports_fast(entry) { return None; }
    Some(AggregateSpeedProfile {
        name: "Fast", description: "Priority processing when supported by the upstream account",
        picker_label: "快速（需上游支持）", transport: AggregateSpeedTransport::OpenAiPriority,
    })
}

fn aggregate_route_context_profile(route: &AggregateProviderRoute) -> AggregateContextProfile {
    fallback_capabilities(&route.upstream_model).context_profile().unwrap_or_else(|| AggregateContextProfile::new(0))
}

fn apply_context_profile_to_model_entry(entry: &mut Value, profile: AggregateContextProfile) {
    let Some(object) = entry.as_object_mut() else {
        return;
    };
    object.insert("context_window".to_string(), json!(profile.context_window));
    object.insert(
        "max_context_window".to_string(),
        json!(profile.max_context_window),
    );
    object.insert(
        "effective_context_window_percent".to_string(),
        json!(profile.effective_context_window_percent),
    );
    object.insert(
        "auto_compact_token_limit".to_string(),
        json!(profile.auto_compact_token_limit),
    );
}

fn apply_speed_profile_to_model_entry(entry: &mut Value, profile: Option<AggregateSpeedProfile>) {
    let Some(object) = entry.as_object_mut() else {
        return;
    };
    if let Some(profile) = profile {
        object.insert("additional_speed_tiers".to_string(), json!(["fast"]));
        object.insert(
            "service_tiers".to_string(),
            json!([{
                "id": "priority",
                "name": profile.name,
                "description": profile.description,
            }]),
        );
    } else {
        object.insert("additional_speed_tiers".to_string(), json!([]));
        object.insert("service_tiers".to_string(), json!([]));
    }
}

fn reconcile_codex_speed_tiers(object: &mut Map<String, Value>, model: &str) {
    let declared = desktop_model_support::entry_override(object, "supportsFast");
    if declared == Some(false) {
        for key in ["additional_speed_tiers", "service_tiers", "additionalSpeedTiers", "serviceTiers"] {
            if let Some(tiers) = object.get_mut(key).and_then(Value::as_array_mut) {
                tiers.retain(|tier| ![tier.as_str(), tier["id"].as_str(), tier["value"].as_str()]
                    .into_iter().flatten().any(|id| matches!(id.trim().to_ascii_lowercase().as_str(), "fast" | "priority")));
            }
        }
        return;
    }
    let Some(profile) = (if declared == Some(true) {
        Some(AggregateSpeedProfile { name: "Fast", description: "Priority processing when supported by upstream",
            picker_label: "快速（需上游支持）", transport: AggregateSpeedTransport::OpenAiPriority })
    } else { codex_openai_speed_profile(model) }) else {
        return;
    };
    // Native caches can contain complete model metadata but empty speed lists.
    // Repair both client formats without replacing existing native tiers or
    // changing the user's selected/default service tier.
    let additional = object
        .entry("additional_speed_tiers")
        .or_insert_with(|| json!([]));
    if !additional.is_array() {
        *additional = json!([]);
    }
    if let Some(tiers) = additional.as_array_mut() {
        tiers.retain(|tier| tier.as_str().is_some_and(|id| !id.trim().is_empty()));
        if !tiers.iter().any(|tier| tier.as_str() == Some("fast")) {
            tiers.push(json!("fast"));
        }
    }
    let service = object.entry("service_tiers").or_insert_with(|| json!([]));
    if !service.is_array() {
        *service = json!([]);
    }
    if let Some(tiers) = service.as_array_mut() {
        tiers.retain(|tier| {
            tier.get("id")
                .and_then(Value::as_str)
                .is_some_and(|id| !id.trim().is_empty())
        });
        if let Some(tier) = tiers.iter_mut().find(|tier| {
            matches!(tier.get("id").and_then(Value::as_str), Some("priority" | "fast"))
        }) {
            if let Some(tier) = tier.as_object_mut() {
                for (field, fallback) in
                    [("name", profile.name), ("description", profile.description)]
                {
                    if !tier
                        .get(field)
                        .and_then(Value::as_str)
                        .is_some_and(|value| !value.trim().is_empty())
                    {
                        tier.insert(field.to_string(), json!(fallback));
                    }
                }
            }
        } else {
            tiers.push(json!({
                "id": "priority",
                "name": profile.name,
                "description": profile.description,
            }));
        }
    }
}

fn is_aggregate_glm_provider(provider_id: &str) -> bool {
    matches!(
        provider_id.trim().to_ascii_lowercase().as_str(),
        "glm" | "zhipu" | "bigmodel" | "zai"
    )
}

fn aggregate_glm_reasoning_efforts() -> &'static [&'static str] {
    &["low", "medium", "high"]
}

fn codex_reasoning_level_effort(level: &Value) -> Option<&str> {
    level.as_str().or_else(|| level.get("effort").and_then(Value::as_str))
        .or_else(|| level.get("reasoningEffort").and_then(Value::as_str))
}

fn codex_reasoning_level_entry(effort: &str) -> Value {
    let description = match effort {
        "low" => "Fast responses with lighter reasoning",
        "medium" => "Balanced reasoning depth and token usage",
        "high" => "High capability for complex reasoning and coding",
        "xhigh" => "Extended capability for long-horizon agentic work",
        "max" => "Maximum capability without token-spend constraints",
        "ultra" => "Ultra reasoning depth for the hardest agentic tasks",
        _ => "Model-supported reasoning level",
    };
    json!({ "effort": effort, "description": description })
}

fn canonical_codex_catalog_model_name(slug: &str) -> String {
    let trimmed = slug.trim();
    let upstream = trimmed
        .strip_prefix("gaoge/")
        .and_then(|route| route.splitn(3, '/').nth(2))
        .unwrap_or(trimmed);
    canonical_model_name(upstream)
}

// A collision route can have an extra `custom/` segment. That string alone is
// ambiguous with a provider actually named custom and a namespaced upstream
// model, so only an exact route or validated catalog identity may remove it.
fn canonical_codex_catalog_entry_model_name(
    entry: &Value,
    slug: &str,
    routes: &[AggregateProviderRoute],
) -> String {
    if let Some(route) = routes.iter().find(|route| route.public_model == slug) {
        return canonical_model_name(&route.upstream_model);
    }
    if let (Some(provider), Some(group), Some(upstream)) = (
        entry["gaoge_aggregate_provider_id"].as_str(),
        entry["gaoge_aggregate_group_id"].as_str(),
        entry["gaoge_aggregate_upstream_model"].as_str(),
    ) {
        let ordinary = format!("gaoge/{provider}/{group}/{upstream}");
        let collision = format!("gaoge/custom/{provider}/{group}/{upstream}");
        if !upstream.is_empty()
            && entry["gaoge_aggregate_public_model"].as_str() == Some(slug)
            && (slug == ordinary
                || (entry["gaoge_aggregate_source"].as_str() == Some("custom") && slug == collision))
        {
            return canonical_model_name(upstream);
        }
    }
    canonical_codex_catalog_model_name(slug)
}

fn codex_model_caps_reasoning_at_xhigh(slug: &str) -> bool {
    codex_speed_release_matches(&canonical_codex_catalog_model_name(slug), "gpt-5.5")
}

fn codex_model_supports_ultra_reasoning(slug: &str) -> bool {
    let canonical = canonical_codex_catalog_model_name(slug);
    ["gpt-5.6-sol", "gpt-5.6-terra", "gpt-6-astra", "gpt-6-sol", "gpt-6.1-sol",
        "gpt-6.2-astra", "gpt-6.2-sol"]
        .iter()
        .any(|release| codex_speed_release_matches(&canonical, release))
}

fn codex_model_caps_reasoning_at_max(slug: &str) -> bool {
    let canonical = canonical_codex_catalog_model_name(slug);
    ["gpt-5.6-luna", "gpt-6-luna"]
        .iter()
        .any(|release| codex_speed_release_matches(&canonical, release))
}

fn reconcile_codex_reasoning_levels(entry: &mut Map<String, Value>, slug: &str) {
    let capped_at_xhigh = codex_model_caps_reasoning_at_xhigh(slug);
    let capped_at_max = codex_model_caps_reasoning_at_max(slug);
    if let Some(declared) = desktop_model_support::entry_override(entry, "supportsUltra") {
        let non_reasoning = entry.get("supported_reasoning_levels").and_then(Value::as_array)
            .is_some_and(|levels| levels.is_empty() || levels.iter().all(|level| codex_reasoning_level_effort(level) == Some("none")));
        if declared && non_reasoning { return; }
        for key in ["supported_reasoning_levels", "supportedReasoningEfforts", "supported_reasoning_efforts"] {
            if let Some(levels) = entry.get_mut(key).and_then(Value::as_array_mut) {
                if !declared { levels.retain(|level| codex_reasoning_level_effort(level) != Some("ultra")); }
            }
        }
        if declared {
            let levels = entry.entry("supported_reasoning_levels").or_insert_with(|| json!([]));
            if let Some(levels) = levels.as_array_mut() {
                for effort in ["max", "ultra"] {
                    if !levels.iter().any(|level| codex_reasoning_level_effort(level) == Some(effort)) { levels.push(codex_reasoning_level_entry(effort)); }
                }
            }
        } else if entry.get("default_reasoning_level").and_then(Value::as_str) == Some("ultra") {
            let fallback = entry.get("supported_reasoning_levels").and_then(Value::as_array)
                .into_iter().flatten().filter_map(codex_reasoning_level_effort)
                .filter_map(|effort| codex_reasoning_effort_rank(effort).map(|rank| (rank, effort.to_string())))
                .max_by_key(|(rank, _)| *rank).map(|(_, effort)| effort).unwrap_or_else(|| "none".into());
            entry.insert("default_reasoning_level".into(), json!(fallback));
        }
        return;
    }
    let supports_ultra = codex_model_supports_ultra_reasoning(slug);
    if !capped_at_xhigh && !capped_at_max && !supports_ultra {
        return;
    }
    let Some(levels) = entry
        .get_mut("supported_reasoning_levels")
        .and_then(Value::as_array_mut)
    else {
        return;
    };

    // An explicit empty/none-only list is a non-reasoning declaration, not a
    // stale ceiling. Never turn it into a reasoning model during repair.
    if levels.is_empty()
        || levels.iter().all(|level| codex_reasoning_level_effort(level) == Some("none"))
    {
        return;
    }

    let target_efforts: &[&str] = if capped_at_xhigh {
        &["low", "medium", "high", "xhigh"]
    } else if capped_at_max {
        &["low", "medium", "high", "xhigh", "max"]
    } else {
        &["low", "medium", "high", "xhigh", "max", "ultra"]
    };
    let mut existing = std::mem::take(levels);
    let mut reconciled = Vec::with_capacity(target_efforts.len() + 2);
    for optional in ["none", "minimal"] {
        if let Some(index) = existing
            .iter()
            .position(|level| codex_reasoning_level_effort(level) == Some(optional))
        {
            reconciled.push(existing.remove(index));
        }
    }
    for effort in target_efforts {
        if let Some(index) = existing
            .iter()
            .position(|level| codex_reasoning_level_effort(level) == Some(*effort))
        {
            reconciled.push(existing.remove(index));
        } else {
            reconciled.push(codex_reasoning_level_entry(effort));
        }
    }
    if supports_ultra {
        reconciled.extend(existing.into_iter().filter(|level| {
            !matches!(
                codex_reasoning_level_effort(level),
                Some("none" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" | "ultra")
            )
        }));
    }
    *levels = reconciled;

    let supported = levels
        .iter()
        .filter_map(codex_reasoning_level_effort)
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    let default_is_supported = entry
        .get("default_reasoning_level")
        .and_then(Value::as_str)
        .is_some_and(|effort| supported.iter().any(|supported| supported == effort));
    if !default_is_supported {
        let fallback = if supported.iter().any(|effort| effort == "medium") {
            "medium".to_string()
        } else {
            supported
                .first()
                .cloned()
                .unwrap_or_else(|| "medium".to_string())
        };
        entry.insert(
            "default_reasoning_level".to_string(),
            Value::String(fallback),
        );
    }
}

fn codex_model_supports_image_input(slug: &str) -> bool {
    fallback_capabilities(slug).image_input == Some(true)
}

fn apply_default_codex_image_capabilities(entry: &mut Map<String, Value>, slug: &str) {
    if !codex_model_supports_image_input(slug) {
        return;
    }
    // Fill missing metadata for verified and forward-compatible models, but
    // never turn an explicit text-only native model into an image model or
    // overwrite a native resolution restriction.
    entry
        .entry("input_modalities".to_string())
        .or_insert_with(|| json!(["text", "image"]));
    entry
        .entry("supports_image_detail_original".to_string())
        .or_insert_with(|| Value::Bool(fallback_capabilities(slug).image_detail_original));
}

#[cfg(test)]
fn aggregate_route_supports_image_input(route: &AggregateProviderRoute) -> bool {
    codex_model_supports_image_input(&route.upstream_model)
}

fn apply_fallback_model_capabilities(entry: &mut Value, model: &str) {
    let capabilities = fallback_capabilities(model);
    apply_context_profile_to_model_entry(entry, capabilities.context);
    let supports_image = capabilities.image_input == Some(true);
    let Some(object) = entry.as_object_mut() else {
        return;
    };
    object.insert(
        "input_modalities".to_string(),
        if supports_image {
            json!(["text", "image"])
        } else {
            json!(["text"])
        },
    );
    object.insert(
        "supports_image_detail_original".to_string(),
        Value::Bool(supports_image && capabilities.image_detail_original),
    );
}

fn codex_native_responses_model_entry(slug: &str, priority: usize) -> Value {
    let display_name = codex_model_display_name(slug);
    let mut entry = json!({
        "slug": slug,
        "display_name": display_name,
        "description": display_name,
        // Codex 26.908 and newer read the current model_messages format. Keep
        // base_instructions below for older clients that still use that field.
        "model_messages": {
            "instructions_template": CODEX_NATIVE_RESPONSES_BASE_INSTRUCTIONS
        },
        "base_instructions": CODEX_NATIVE_RESPONSES_BASE_INSTRUCTIONS,
        "default_reasoning_level": "medium",
        "supported_reasoning_levels": [
            { "effort": "low", "description": "Fast responses with lighter reasoning" },
            { "effort": "medium", "description": "Balances speed and reasoning depth for everyday tasks" },
            { "effort": "high", "description": "Greater reasoning depth for complex problems" },
            { "effort": "xhigh", "description": "Extra high reasoning depth for complex problems" }
        ],
        "shell_type": "shell_command",
        "visibility": "list",
        "supported_in_api": true,
        "priority": 1000 + priority,
        "supports_reasoning_summaries": true,
        "default_reasoning_summary": "none",
        "support_verbosity": false,
        "truncation_policy": { "mode": "bytes", "limit": 10000 },
        "supports_parallel_tool_calls": false,
        "supports_image_detail_original": false,
        "context_window": 262144,
        "max_context_window": 262144,
        "effective_context_window_percent": 95,
        "experimental_supported_tools": [],
        "input_modalities": ["text"],
        "supports_search_tool": false,
        "additional_speed_tiers": [],
        "service_tiers": [],
        "availability_nux": Value::Null,
        "upgrade": Value::Null
    });
    apply_fallback_model_capabilities(&mut entry, slug);
    if let Some(object) = entry.as_object_mut() {
        reconcile_codex_reasoning_levels(object, slug);
        reconcile_codex_multi_agent_version(object, slug);
    }
    apply_speed_profile_to_model_entry(&mut entry, codex_openai_speed_profile(slug));
    entry
}

fn aggregate_claude_model_entry(route: &AggregateProviderRoute, priority: usize) -> Value {
    let mut entry = codex_native_responses_model_entry(&route.upstream_model, priority);
    let label = aggregate_route_native_label(route);
    let efforts = claude_reasoning_efforts(&route.upstream_model)
        .iter()
        .map(|effort| codex_reasoning_level_entry(effort))
        .collect::<Vec<_>>();
    if let Some(object) = entry.as_object_mut() {
        object.insert("display_name".to_string(), Value::String(label.clone()));
        object.insert("description".to_string(), Value::String(label));
        object.insert(
            "default_reasoning_level".to_string(),
            Value::String("high".to_string()),
        );
        object.insert(
            "supported_reasoning_levels".to_string(),
            Value::Array(efforts),
        );
        object.insert(
            "supports_parallel_tool_calls".to_string(),
            Value::Bool(true),
        );
        object.insert("supports_search_tool".to_string(), Value::Bool(false));
    }
    apply_context_profile_to_model_entry(&mut entry, aggregate_route_context_profile(route));
    apply_speed_profile_to_model_entry(&mut entry, aggregate_route_speed_profile(route));
    entry
}

fn aggregate_glm_model_entry(route: &AggregateProviderRoute, priority: usize) -> Value {
    let mut entry = codex_native_responses_model_entry(&route.upstream_model, priority);
    let efforts = aggregate_glm_reasoning_efforts()
        .iter()
        .map(|effort| codex_reasoning_level_entry(effort))
        .collect::<Vec<_>>();
    if let Some(object) = entry.as_object_mut() {
        object.insert(
            "supported_reasoning_levels".to_string(),
            Value::Array(efforts),
        );
    }
    apply_context_profile_to_model_entry(&mut entry, aggregate_route_context_profile(route));
    apply_speed_profile_to_model_entry(&mut entry, aggregate_route_speed_profile(route));
    entry
}

fn codex_model_metadata_has_runtime_fields(entry: &Value) -> bool {
    let has_legacy_instructions = entry
        .get("base_instructions")
        .and_then(Value::as_str)
        .is_some_and(|value| !value.trim().is_empty());
    let has_current_instructions = entry
        .get("model_messages")
        .and_then(|messages| messages.get("instructions_template"))
        .and_then(Value::as_str)
        .is_some_and(|value| !value.trim().is_empty());
    (has_legacy_instructions || has_current_instructions)
        && entry
            .get("supported_reasoning_levels")
            .and_then(Value::as_array)
            .is_some()
        && entry
            .get("shell_type")
            .and_then(Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
}

fn codex_model_metadata_is_complete(entry: &Value) -> bool {
    codex_model_metadata_has_runtime_fields(entry)
        && entry.get("supported_reasoning_levels").and_then(Value::as_array)
            .is_some_and(|levels| !levels.is_empty())
        && entry
            .get("context_window")
            .and_then(Value::as_u64)
            .is_some_and(|value| value > 0)
}

fn sanitize_codex_model_metadata(mut entry: Value, slug: &str) -> Option<Value> {
    if let Some(object) = entry.as_object_mut() { desktop_model_support::restore_entry_capabilities(object); }
    if !codex_model_metadata_is_complete(&entry) {
        return None;
    }
    let object = entry.as_object_mut()?;
    // Current Codex consumes model_messages. Older clients still need the
    // legacy field; use the neutral bridge instructions for that fallback.
    if !object
        .get("base_instructions")
        .and_then(Value::as_str)
        .is_some_and(|text| !text.trim().is_empty())
    {
        object.insert(
            "base_instructions".to_string(),
            Value::String(CODEX_NATIVE_RESPONSES_BASE_INSTRUCTIONS.to_string()),
        );
    }
    object.insert("slug".to_string(), Value::String(slug.to_string()));
    object.insert("visibility".to_string(), Value::String("list".to_string()));
    object.insert("supported_in_api".to_string(), Value::Bool(true));
    object.remove("tool_mode");
    reconcile_codex_multi_agent_version(object, slug);
    if object.contains_key("use_responses_lite") {
        object.insert("use_responses_lite".to_string(), Value::Bool(false));
    }
    reconcile_codex_reasoning_levels(object, slug);
    apply_default_codex_image_capabilities(object, slug);
    reconcile_codex_speed_tiers(object, slug);
    Some(entry)
}

fn reconcile_codex_multi_agent_version(entry: &mut Map<String, Value>, slug: &str) {
    if let Some(declared) = desktop_model_support::entry_override(entry, "supportsUltra") {
        if declared && entry.get("supported_reasoning_levels").and_then(Value::as_array)
            .is_some_and(|levels| levels.iter().any(|level| codex_reasoning_level_effort(level) == Some("ultra"))) {
            entry.insert("multi_agent_version".into(), json!("v2"));
        }
        return;
    }
    // Native Ultra uses maximum reasoning plus proactive delegation. Stripping
    // v2 silently falls back to the legacy tools and loses that behavior even
    // when the picker still offers Ultra. Only supply a fallback for known
    // Ultra models; keep explicit native v2 metadata for other models as well.
    if codex_model_supports_ultra_reasoning(slug) {
        entry.insert("multi_agent_version".to_string(), json!("v2"));
    } else if entry.get("multi_agent_version").and_then(Value::as_str) != Some("v2") {
        entry.remove("multi_agent_version");
    }
}

fn codex_model_cache_paths(targets: &[CodexDirTarget]) -> Vec<PathBuf> {
    let mut paths = targets
        .iter()
        .map(|target| target.dir.join("models_cache.json"))
        .collect::<Vec<_>>();
    paths.push(codex_dir().join("models_cache.json"));
    let mut seen_paths = HashSet::new();
    paths
        .into_iter()
        .filter(|path| seen_paths.insert(path.to_string_lossy().to_lowercase()))
        .collect()
}

fn codex_local_model_metadata(targets: &[CodexDirTarget]) -> HashMap<String, Value> {
    let paths = codex_model_cache_paths(targets);
    let mut seen_paths = HashSet::new();
    let mut metadata = HashMap::new();
    for path in paths {
        if !seen_paths.insert(path.to_string_lossy().to_lowercase()) {
            continue;
        }
        let Ok(Some(catalog)) = read_json_if_exists(&path) else {
            continue;
        };
        let Some(models) = catalog.get("models").and_then(Value::as_array) else {
            continue;
        };
        for entry in models {
            let Some(slug) = entry.get("slug").and_then(Value::as_str).map(str::trim) else {
                continue;
            };
            if slug.is_empty() || metadata.contains_key(slug) {
                continue;
            }
            if let Some(entry) = sanitize_codex_model_metadata(entry.clone(), slug) {
                metadata.insert(slug.to_string(), entry);
            }
        }
    }
    metadata
}

// Preserve raw native declarations per field. Aggregate models may have no
// reasoning levels or only a partial capability record. Generated gaoge entries
// are our own output, not an independent native source for the next refresh.
fn aggregate_local_model_metadata(targets: &[CodexDirTarget]) -> HashMap<String, Value> {
    let mut metadata = HashMap::new();
    for path in codex_model_cache_paths(targets) {
        let Ok(Some(catalog)) = read_json_if_exists(&path) else { continue };
        for raw in catalog["models"].as_array().into_iter().flatten() {
            let Some(slug) = raw["slug"].as_str().map(str::trim)
                .filter(|slug| !slug.is_empty() && !slug.starts_with("gaoge/")) else { continue };
            if !metadata.contains_key(slug) && raw.is_object() {
                metadata.insert(slug.to_owned(), raw.clone());
            }
        }
    }
    metadata
}

fn codex_metadata_for_model(metadata: &HashMap<String, Value>, model: &str) -> Option<Value> {
    metadata
        .get(model)
        .or_else(|| metadata.get(&canonical_model_name(model)))
        .cloned()
        .and_then(|entry| sanitize_codex_model_metadata(entry, model))
}

fn aggregate_model_entry(
    route: &AggregateProviderRoute,
    priority: usize,
    metadata: &HashMap<String, Value>,
) -> Value {
    let native = metadata.get(&route.public_model)
        .or_else(|| metadata.get(&route.upstream_model))
        .or_else(|| metadata.get(&canonical_model_name(&route.upstream_model)));
    let mut entry = if is_aggregate_anthropic_route(&route.provider_id, &route.upstream_platform) {
        aggregate_claude_model_entry(route, priority)
    } else if is_aggregate_glm_provider(&route.provider_id) {
        aggregate_glm_model_entry(route, priority)
    } else {
        codex_native_responses_model_entry(&route.upstream_model, priority)
    };
    // Capability projection is field-validated below. Copy native runtime
    // instructions separately so a partial cache record still gets a complete
    // catalog shell without losing its accurate capability declarations.
    if let (Some(object), Some(native)) = (entry.as_object_mut(), native) {
        for key in ["base_instructions", "shell_type"] {
            if let Some(value) = native.get(key).filter(|value| value.as_str().is_some_and(|text| !text.trim().is_empty())) {
                object.insert(key.into(), value.clone());
            }
        }
        if let Some(messages) = native.get("model_messages").filter(|value| {
            value["instructions_template"].as_str().is_some_and(|text| !text.trim().is_empty())
        }) {
            object.insert("model_messages".into(), messages.clone());
        }
        if let Some(policy) = native.get("truncation_policy").filter(|value| {
            value["mode"].as_str().is_some() && value["limit"].as_u64().is_some()
        }) {
            object.insert("truncation_policy".into(), policy.clone());
        }
        if let Some(tools) = native.get("experimental_supported_tools").filter(|value| {
            value.as_array().is_some_and(|tools| tools.iter().all(Value::is_string))
        }) {
            object.insert("experimental_supported_tools".into(), tools.clone());
        }
        if native["multi_agent_version"].as_str() == Some("v2") {
            object.insert("multi_agent_version".into(), json!("v2"));
        }
    }
    // Resolve every provider using explicit settings > native metadata > the
    // pinned per-model declarations. Do not infer a window from a brand name.
    let resolved = model_capabilities::resolved_model_metadata(&route.upstream_model, native, None);
    apply_speed_profile_to_model_entry(&mut entry, aggregate_route_speed_profile(route));
    if let (Some(object), Some(resolved)) = (entry.as_object_mut(), resolved.as_ref().and_then(Value::as_object)) {
        for key in ["service_tiers", "additional_speed_tiers"] { object.insert(key.into(), json!([])); }
        if resolved.contains_key("context_window") {
            object.insert("max_context_window".into(), Value::Null);
            object.insert("auto_compact_token_limit".into(), Value::Null);
            object.insert("effective_context_window_percent".into(), json!(95));
        }
        if resolved.contains_key("input_modalities") { object.insert("supports_image_detail_original".into(), json!(false)); }
        object.extend(resolved.clone());
        if let Some(levels) = object.get("supported_reasoning_levels").and_then(Value::as_array) {
            let default = object.get("default_reasoning_level").and_then(Value::as_str);
            if !levels.iter().any(|level| level["effort"].as_str() == default) {
                let first = levels.first().and_then(|level| level.get("effort")).cloned().unwrap_or(Value::Null);
                object.insert("default_reasoning_level".into(), first);
            }
        }
    }
    let known_window = resolved.as_ref().and_then(|v| v["context_window"].as_u64()).is_some()
        || fallback_capabilities(&route.upstream_model).verified;
    if !known_window {
        if let Some(object) = entry.as_object_mut() {
            object.insert("context_window".into(), Value::Null);
            object.insert("max_context_window".into(), Value::Null);
            object.insert("auto_compact_token_limit".into(), Value::Null);
        }
    }
    aggregate_settings::apply_model_overrides(&mut entry, &route.model_config, route.protocol);
    // Native caches can predate our reviewed GPT ceiling. Reconcile after all
    // capability layers, using the actual upstream ID rather than a public
    // route alias. Other vendors and explicit non-reasoning lists stay intact.
    if let Some(object) = entry.as_object_mut() {
        reconcile_codex_reasoning_levels(object, &route.upstream_model);
    }
    let label = aggregate_route_native_label(route);
    if let Some(object) = entry.as_object_mut() {
        object.insert("slug".into(), json!(route.public_model));
        object.insert("gaoge_aggregate_source".into(), json!(route.source));
        object.insert("gaoge_aggregate_provider_id".into(), json!(route.provider_id));
        object.insert("gaoge_aggregate_provider_name".into(), json!(route.provider_name));
        object.insert("gaoge_aggregate_group_id".into(), json!(route.group_id));
        object.insert("gaoge_aggregate_group_name".into(), json!(route.group_name));
        object.insert("gaoge_aggregate_public_model".into(), json!(route.public_model));
        object.insert("gaoge_aggregate_upstream_model".into(), json!(route.upstream_model));
        object.insert("display_name".into(), json!(label));
        object.insert("description".into(), json!(label));
        object.insert("priority".into(), json!(1000 + priority));
        object.insert("visibility".into(), json!("list"));
        object.insert("supported_in_api".into(), json!(true));
        object.remove("tool_mode");
        if object.contains_key("use_responses_lite") {
            object.insert("use_responses_lite".into(), json!(false));
        }
        // The aggregate provider uses Codex's local compaction path. Upstreams
        // without /responses/compact must not advertise remote compaction.
        if route.protocol != aggregate_protocol::Protocol::Responses {
            object.insert("supports_search_tool".into(), json!(false));
            object.insert("experimental_supported_tools".into(), json!([]));
        }
    }
    entry
}

fn extend_aggregate_model_metadata(metadata: &mut HashMap<String, Value>) {
    let state = aggregate_login_state_snapshot();
    if !state.enabled {
        return;
    }
    let aggregate_native = aggregate_local_model_metadata(&codex_route_targets());
    for (priority, route) in state.routes.iter().enumerate() {
        let entry = aggregate_model_entry(route, priority, &aggregate_native);
        metadata.insert(route.public_model.clone(), entry);
    }
}

#[allow(dead_code)]
fn codex_native_visible_models(targets: &[CodexDirTarget]) -> Vec<String> {
    let mut seen = HashSet::new();
    let mut models = Vec::new();
    for path in codex_model_cache_paths(targets) {
        let Ok(Some(catalog)) = read_json_if_exists(&path) else {
            continue;
        };
        let Some(entries) = catalog.get("models").and_then(Value::as_array) else {
            continue;
        };
        for entry in entries {
            let Some(slug) = entry.get("slug").and_then(Value::as_str).map(str::trim) else {
                continue;
            };
            let visibility = entry
                .get("visibility")
                .and_then(Value::as_str)
                .unwrap_or("list")
                .trim()
                .to_ascii_lowercase();
            let hidden = entry
                .get("hidden")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if slug.is_empty()
                || hidden
                || matches!(visibility.as_str(), "hide" | "hidden" | "none")
                || !seen.insert(slug.to_string())
            {
                continue;
            }
            models.push(slug.to_string());
        }
    }
    models
}

#[allow(dead_code)]
fn choose_codex_native_fallback_model(targets: &[CodexDirTarget]) -> String {
    let models = codex_native_visible_models(targets);
    for preferred in [CODEX_DEFAULT_MODEL, "gpt-5.4"] {
        if models.iter().any(|model| model == preferred) {
            return preferred.to_string();
        }
    }
    models
        .into_iter()
        .next()
        .unwrap_or_else(|| CODEX_DEFAULT_MODEL.to_string())
}

