fn current_codex_runtime_revision() -> u64 {
    CODEX_RUNTIME_REVISION.load(Ordering::SeqCst)
}

fn codex_runtime_revision_token(revision: u64) -> String {
    format!("{}:{revision}", PROCESS_INSTANCE_ID.as_str())
}

fn invalidate_codex_runtime_injection_state() {
    if let Ok(mut state) = CODEX_RUNTIME_INJECTION_STATE.lock() {
        *state = CodexRuntimeInjectionState::default();
    }
}

fn bump_codex_runtime_revision() -> u64 {
    let revision = CODEX_RUNTIME_REVISION.fetch_add(1, Ordering::SeqCst) + 1;
    invalidate_codex_runtime_injection_state();
    codex_ultra_runtime::reset();
    codex_native_fast_runtime::reset();
    codex_api_mode::reset();
    revision
}

fn mark_codex_runtime_injection(websocket_url: &str, revision: u64) {
    if let Ok(mut state) = CODEX_RUNTIME_INJECTION_STATE.lock() {
        state.websocket_url.clear();
        state.websocket_url.push_str(websocket_url);
        state.revision = revision;
        state.verified_at = Some(Instant::now());
    }
}

fn codex_runtime_injection_recent(websocket_url: &str, revision: u64) -> bool {
    CODEX_RUNTIME_INJECTION_STATE
        .lock()
        .ok()
        .is_some_and(|state| {
            state.websocket_url == websocket_url
                && state.revision == revision
                && state.verified_at.is_some_and(|verified_at| {
                    verified_at.elapsed() < Duration::from_millis(CODEX_RUNTIME_HEALTHCHECK_MS)
                })
        })
}

fn set_codex_runtime_debug_port(debug_port: u16) {
    CODEX_RUNTIME_DEBUG_PORT.store(debug_port as u64, Ordering::SeqCst);
}

fn codex_runtime_debug_port() -> u16 {
    u16::try_from(CODEX_RUNTIME_DEBUG_PORT.load(Ordering::SeqCst))
        .ok()
        .filter(|port| *port > 1)
        .unwrap_or(CODEX_PLUGIN_CDP_DEBUG_PORT)
}

struct CodexConfigureActivityGuard;

impl CodexConfigureActivityGuard {
    fn start() -> Self {
        CODEX_CONFIGURE_ACTIVE.fetch_add(1, Ordering::SeqCst);
        CODEX_SESSION_SYNC_FOREGROUND_PRIORITY.store(true, Ordering::SeqCst);
        CODEX_SESSION_SYNC_GENERATION.fetch_add(1, Ordering::SeqCst);
        Self
    }
}

impl Drop for CodexConfigureActivityGuard {
    fn drop(&mut self) {
        let previous = CODEX_CONFIGURE_ACTIVE.fetch_sub(1, Ordering::SeqCst);
        if previous <= 1 {
            CODEX_SESSION_SYNC_FOREGROUND_PRIORITY.store(false, Ordering::SeqCst);
        }
    }
}

fn codex_session_sync_should_yield_background() -> bool {
    CODEX_SESSION_SYNC_FOREGROUND_PRIORITY.load(Ordering::Acquire)
        || CODEX_CONFIGURE_ACTIVE.load(Ordering::Acquire) != 0
}

fn codex_background_merge_should_yield() -> bool {
    CODEX_SESSION_SYNC_BACKGROUND.with(Cell::get)
        && (codex_session_sync_should_yield_background()
            || CODEX_SESSION_SYNC_BACKGROUND_GENERATION
                .with(Cell::get)
                .is_some_and(|generation| !codex_background_generation_is_current(generation)))
}

fn codex_background_generation_is_current(generation: u64) -> bool {
    CODEX_SESSION_SYNC_GENERATION.load(Ordering::Acquire) == generation
}

fn with_canonical_rollout_publication<T>(
    publish: impl FnOnce() -> Result<T, String>,
) -> Result<T, String> {
    if !CODEX_SESSION_SYNC_BACKGROUND.with(Cell::get) {
        return publish();
    }
    // Only the final atomic rename belongs under the sync locks. Reading,
    // sorting and comparing large histories must remain outside them.
    let _guard = try_lock_recover(
        &CODEX_SESSION_SYNC_LOCK,
        "前台同步正在进行，后台会话文件发布已取消。",
    )?;
    let _file_lock = acquire_codex_lock("session-sync")?;
    if codex_background_merge_should_yield() {
        return Err("会话路由已切换，后台旧会话文件发布已取消。".to_string());
    }
    publish()
}

struct CodexSessionSyncPriorityGuard {
    armed: bool,
}

impl CodexSessionSyncPriorityGuard {
    fn start() -> Self {
        let background = CODEX_SESSION_SYNC_BACKGROUND.with(Cell::get);
        if !background {
            CODEX_SESSION_SYNC_FOREGROUND_PRIORITY.store(true, Ordering::SeqCst);
            CODEX_SESSION_SYNC_GENERATION.fetch_add(1, Ordering::SeqCst);
        }
        Self { armed: !background }
    }
}

impl Drop for CodexSessionSyncPriorityGuard {
    fn drop(&mut self) {
        if self.armed && CODEX_CONFIGURE_ACTIVE.load(Ordering::Acquire) == 0 {
            CODEX_SESSION_SYNC_FOREGROUND_PRIORITY.store(false, Ordering::SeqCst);
        }
    }
}

fn try_lock_recover<'a, T>(
    mutex: &'a Mutex<T>,
    busy_message: &str,
) -> Result<MutexGuard<'a, T>, String> {
    match mutex.try_lock() {
        Ok(guard) => Ok(guard),
        Err(TryLockError::WouldBlock) => Err(busy_message.to_string()),
        Err(TryLockError::Poisoned(poisoned)) => {
            mutex.clear_poison();
            Ok(poisoned.into_inner())
        }
    }
}

#[cfg(test)]
mod codex_foreground_operation_tests;

struct CodexForegroundOperationGuard<'a> {
    // Release the file and memory locks before allowing background work again.
    _file_lock: CodexFileLock,
    _guard: MutexGuard<'a, ()>,
    _activity: CodexConfigureActivityGuard,
}

fn lock_codex_foreground_operation() -> Result<CodexForegroundOperationGuard<'static>, String> {
    lock_codex_foreground_operation_with_timeout(&CODEX_CONFIGURE_LOCK, Duration::from_secs(120))
}

fn lock_codex_foreground_operation_with_timeout(
    mutex: &Mutex<()>,
    timeout: Duration,
) -> Result<CodexForegroundOperationGuard<'_>, String> {
    // A confirmed user action must wait for a brief background read instead
    // of failing immediately. Announce priority before waiting for either lock.
    let activity = CodexConfigureActivityGuard::start();
    let deadline = Instant::now() + timeout;
    let wait = || -> Result<(), String> {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err("等待上一项 Codex 操作结束超时，本次操作尚未执行，请稍后重试。".to_string());
        }
        thread::sleep(remaining.min(Duration::from_millis(50)));
        Ok(())
    };
    let guard = loop {
        match mutex.try_lock() {
            Ok(guard) => break guard,
            Err(TryLockError::Poisoned(poisoned)) => {
                mutex.clear_poison();
                break poisoned.into_inner();
            }
            Err(TryLockError::WouldBlock) => wait()?,
        }
    };
    loop {
        if let Some(file_lock) = try_acquire_codex_lock("configure")? {
            return Ok(CodexForegroundOperationGuard {
                _file_lock: file_lock,
                _guard: guard,
                _activity: activity,
            });
        }
        // Retry only contention. Surface actual filesystem failures, preserve
        // live owners, and share the deadline with the in-process lock wait.
        wait()?;
    }
}

fn random_session_helper_token() -> String {
    let mut bytes = [0u8; 32];
    OsRng.fill_bytes(&mut bytes);
    general_purpose::URL_SAFE_NO_PAD.encode(bytes)
}

fn http_reason(status: u16) -> &'static str {
    match status {
        200 => "OK",
        204 => "No Content",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Payload Too Large",
        502 => "Bad Gateway",
        503 => "Service Unavailable",
        _ => "Internal Server Error",
    }
}

fn write_json_http_response(stream: &mut TcpStream, status: u16, payload: &Value) {
    let body = payload.to_string();
    let response = format!(
        "HTTP/1.1 {status} {}\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type, X-Gaoge-Token\r\nAccess-Control-Allow-Private-Network: true\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n{body}",
        http_reason(status),
        body.as_bytes().len(),
    );
    let _ = stream.write_all(response.as_bytes());
    let _ = stream.flush();
}

fn write_options_http_response(stream: &mut TcpStream) {
    let response = "HTTP/1.1 204 No Content\r\nContent-Length: 0\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type, X-Gaoge-Token\r\nAccess-Control-Allow-Private-Network: true\r\nAccess-Control-Max-Age: 600\r\nConnection: close\r\n\r\n";
    let _ = stream.write_all(response.as_bytes());
    let _ = stream.flush();
}

fn read_local_http_request(
    stream: &mut TcpStream,
) -> Result<(String, String, HashMap<String, String>, Vec<u8>), String> {
    let _ = stream.set_read_timeout(Some(Duration::from_secs(3)));
    let mut request = Vec::new();
    let mut buffer = [0u8; 4096];
    let header_end = loop {
        let read = stream
            .read(&mut buffer)
            .map_err(|error| format!("读取本地会话请求失败：{error}"))?;
        if read == 0 {
            return Err("本地会话请求提前结束。".to_string());
        }
        request.extend_from_slice(&buffer[..read]);
        if request.len() > CODEX_SESSION_HELPER_MAX_REQUEST_BYTES {
            return Err("本地会话请求过大。".to_string());
        }
        if let Some(index) = request.windows(4).position(|window| window == b"\r\n\r\n") {
            break index + 4;
        }
    };
    let header_text = String::from_utf8_lossy(&request[..header_end]);
    let mut lines = header_text.split("\r\n");
    let request_line = lines.next().unwrap_or_default();
    let mut request_parts = request_line.split_whitespace();
    let method = request_parts.next().unwrap_or_default().to_string();
    let path = request_parts.next().unwrap_or_default().to_string();
    let mut headers = HashMap::new();
    for line in lines {
        let Some((name, value)) = line.split_once(':') else {
            continue;
        };
        headers.insert(name.trim().to_ascii_lowercase(), value.trim().to_string());
    }
    let content_length = headers
        .get("content-length")
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(0);
    if header_end + content_length > CODEX_SESSION_HELPER_MAX_REQUEST_BYTES {
        return Err("本地会话请求正文过大。".to_string());
    }
    while request.len() < header_end + content_length {
        let read = stream
            .read(&mut buffer)
            .map_err(|error| format!("读取本地会话请求正文失败：{error}"))?;
        if read == 0 {
            break;
        }
        request.extend_from_slice(&buffer[..read]);
    }
    let body_end = (header_end + content_length).min(request.len());
    Ok((
        method,
        path,
        headers,
        request[header_end..body_end].to_vec(),
    ))
}

fn valid_codex_session_id(value: &str) -> bool {
    let value = value.trim();
    (8..=128).contains(&value.len())
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
}

fn normalize_codex_session_id(value: &str) -> Option<&str> {
    let value = value.trim();
    let value = value.strip_prefix("local:").unwrap_or(value);
    valid_codex_session_id(value).then_some(value)
}

fn set_gaoge_live_auth_session(session: Option<Value>) {
    if let Ok(mut guard) = GAOGE_AUTH_SESSION_MEMORY.lock() {
        *guard = session;
    }
}

fn gaoge_live_auth_session_snapshot() -> Option<Value> {
    GAOGE_AUTH_SESSION_MEMORY
        .lock()
        .ok()
        .and_then(|guard| guard.clone())
}

fn load_gaoge_auth_session_for_balance() -> Result<Map<String, Value>, String> {
    if let Some(Value::Object(session)) = gaoge_live_auth_session_snapshot() {
        if session
            .get("accessToken")
            .and_then(Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
        {
            return Ok(session);
        }
    }

    let saved = read_json_if_exists(&auth_session_path())?
        .ok_or_else(|| "Gaoge Free 登录已失效，请重新登录。".to_string())?;
    let encrypted_session = saved
        .get("encryptedSession")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    if encrypted_session.is_empty() {
        return Err("Gaoge Free 登录会话备份为空。".to_string());
    }
    let session_text = decrypt_secret(encrypted_session)?
        .ok_or_else(|| "当前系统无法解密 Gaoge Free 登录会话。".to_string())?;
    let Value::Object(session) = serde_json::from_str::<Value>(&session_text)
        .map_err(|error| format!("Gaoge Free 登录会话格式无效：{error}"))?
    else {
        return Err("Gaoge Free 登录会话格式无效。".to_string());
    };
    if !session
        .get("accessToken")
        .and_then(Value::as_str)
        .is_some_and(|value| !value.trim().is_empty())
    {
        return Err("Gaoge Free 登录会话缺少访问令牌。".to_string());
    }
    set_gaoge_live_auth_session(Some(Value::Object(session.clone())));
    Ok(session)
}

fn gaoge_auth_me_url(api_base_url: &str) -> Result<String, String> {
    gaoge_auth_me_url_with_default(api_base_url, GAOGE_DEFAULT_API_BASE_URL)
}

fn gaoge_auth_me_url_with_default(
    api_base_url: &str,
    deployment_default: &str,
) -> Result<String, String> {
    let candidate = if api_base_url.trim().is_empty() {
        deployment_default.trim()
    } else {
        api_base_url.trim()
    };
    if candidate.is_empty() {
        return Err("登录会话未配置服务地址，请先选择服务线路并重新登录。".to_string());
    }
    let mut parsed =
        url::Url::parse(candidate).map_err(|_| "Gaoge Free API 地址无效。".to_string())?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err("Gaoge Free API 地址必须使用 HTTP 或 HTTPS。".to_string());
    }
    let base_path = parsed.path().trim_end_matches('/');
    let next_path = if base_path.to_ascii_lowercase().ends_with("/auth/me") {
        base_path.to_string()
    } else if base_path.is_empty() {
        "/api/v1/auth/me".to_string()
    } else {
        format!("{base_path}/auth/me")
    };
    parsed.set_path(&next_path);
    parsed.set_query(None);
    parsed.set_fragment(None);
    Ok(parsed.to_string())
}

fn json_number(value: Option<&Value>) -> Option<f64> {
    value.and_then(|value| {
        value.as_f64().or_else(|| {
            value
                .as_str()
                .and_then(|text| text.trim().parse::<f64>().ok())
        })
    })
}

fn gaoge_account_balance_from_payload(payload: &Value) -> Result<(f64, f64), String> {
    let data = payload
        .get("data")
        .filter(|value| value.is_object())
        .unwrap_or(payload);
    let balance = json_number(data.get("balance"))
        .filter(|value| value.is_finite())
        .ok_or_else(|| "余额响应缺少有效余额。".to_string())?;
    let frozen_balance = json_number(data.get("frozen_balance"))
        .filter(|value| value.is_finite())
        .unwrap_or(0.0);
    Ok((balance, frozen_balance))
}

fn fetch_gaoge_account_balance() -> Result<Value, String> {
    let session = load_gaoge_auth_session_for_balance()?;
    let access_token = session
        .get("accessToken")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    if access_token.is_empty() {
        return Err("Gaoge Free 登录会话缺少访问令牌。".to_string());
    }
    let api_base_url = session
        .get("apiBaseUrl")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let request_url = gaoge_auth_me_url(api_base_url)?;
    let client = reqwest::blocking::Client::builder()
        .connect_timeout(Duration::from_secs(5))
        .timeout(Duration::from_secs(
            GAOGE_ACCOUNT_BALANCE_REQUEST_TIMEOUT_SECS,
        ))
        .user_agent(GAOGE_USER_AGENT)
        .gzip(true)
        .build()
        .map_err(|error| format!("创建余额请求客户端失败：{error}"))?;
    let response = client
        .get(request_url)
        .bearer_auth(access_token)
        .header(reqwest::header::ACCEPT, "application/json")
        .send()
        .map_err(|error| format!("解析余额响应失败：{error}"))?;
    let status = response.status();
    if status == reqwest::StatusCode::UNAUTHORIZED || status == reqwest::StatusCode::FORBIDDEN {
        return Err("Gaoge Free 登录已失效，请重新登录。".to_string());
    }
    if !status.is_success() {
        return Err(format!("余额接口返回 HTTP {}。", status.as_u16()));
    }
    let payload = response
        .json::<Value>()
        .map_err(|error| format!("解析余额响应失败：{error}"))?;
    let (balance, frozen_balance) = gaoge_account_balance_from_payload(&payload)?;
    Ok(json!({
      "ok": true,
      "balance": balance,
      "frozenBalance": frozen_balance,
      "currency": "USD",
      "updatedAt": unix_now(),
    }))
}

fn handle_codex_session_helper_request(mut stream: TcpStream, token: &str) {
    let request = read_local_http_request(&mut stream);
    let Ok((method, path, headers, body)) = request else {
        write_json_http_response(
            &mut stream,
            400,
            &json!({"ok": false, "message": request.err().unwrap_or_default()}),
        );
        return;
    };
    if method.eq_ignore_ascii_case("OPTIONS") {
        write_options_http_response(&mut stream);
        return;
    }
    if !method.eq_ignore_ascii_case("POST") {
        write_json_http_response(
            &mut stream,
            405,
            &json!({"ok": false, "message": "仅支持 POST。"}),
        );
        return;
    }
    if headers.get("x-gaoge-token").map(String::as_str) != Some(token) {
        write_json_http_response(
            &mut stream,
            401,
            &json!({"ok": false, "message": "本地会话令牌无效。"}),
        );
        return;
    }
    if path == "/status" {
        write_json_http_response(&mut stream, 200, &json!({"ok": true, "active": true}));
        return;
    }
    if path == "/fuel/status" || path == "/speed/select" || path == "/projects/local-state" {
        let payload = if path == "/fuel/status" {
            json!({})
        } else {
            match serde_json::from_slice::<Value>(&body) {
                Ok(value) if value.is_object() => value,
                _ => {
                    write_json_http_response(
                        &mut stream,
                        400,
                        &json!({"ok": false, "message": "速度请求格式无效。"}),
                    );
                    return;
                }
            }
        };
        let result = handle_codex_session_delete_bridge_request(&path, &payload);
        write_json_http_response(
            &mut stream,
            if json_bool(&result, "ok") { 200 } else { 400 },
            &result,
        );
        return;
    }
    if path == "/account/balance" {
        match fetch_gaoge_account_balance() {
            Ok(result) => write_json_http_response(&mut stream, 200, &result),
            Err(error) => {
                let status = if error.contains("尚未登录") || error.contains("登录已失效")
                {
                    401
                } else {
                    502
                };
                write_json_http_response(
                    &mut stream,
                    status,
                    &json!({"ok": false, "message": error, "updatedAt": unix_now()}),
                );
            }
        }
        return;
    }
    if path == "/aggregate/select-model" {
        let payload: Value = match serde_json::from_slice(&body) {
            Ok(value) => value,
            Err(error) => {
                write_json_http_response(
                    &mut stream,
                    400,
                    &json!({"ok": false, "message": format!("聚合模型切换请求格式错误：{error}")}),
                );
                return;
            }
        };
        let public_model = payload
            .get("model")
            .or_else(|| payload.get("publicModel"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .trim();
        match select_aggregate_model(public_model) {
            Ok(result) => write_json_http_response(&mut stream, 200, &result),
            Err(error) => write_json_http_response(
                &mut stream,
                400,
                &json!({"ok": false, "status": "failed", "message": error}),
            ),
        }
        return;
    }
    if path == "/aggregate/select-speed" {
        let payload: Value = match serde_json::from_slice(&body) {
            Ok(value) => value,
            Err(error) => {
                write_json_http_response(
                    &mut stream,
                    400,
                    &json!({"ok": false, "message": format!("聚合速度切换请求格式错误：{error}")}),
                );
                return;
            }
        };
        let speed_mode = payload
            .get("speedMode")
            .or_else(|| payload.get("speed"))
            .or_else(|| payload.get("mode"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .trim();
        match select_aggregate_speed(speed_mode, payload.get("model").and_then(Value::as_str)) {
            Ok(result) => write_json_http_response(&mut stream, 200, &result),
            Err(error) => write_json_http_response(
                &mut stream,
                400,
                &json!({"ok": false, "status": "failed", "message": error}),
            ),
        }
        return;
    }
    if path != "/delete" {
        write_json_http_response(
            &mut stream,
            404,
            &json!({"ok": false, "message": "未知本地会话接口。"}),
        );
        return;
    }
    let payload: Value = match serde_json::from_slice(&body) {
        Ok(value) => value,
        Err(error) => {
            write_json_http_response(
                &mut stream,
                400,
                &json!({"ok": false, "message": format!("删除请求格式错误：{error}")}),
            );
            return;
        }
    };
    let raw_session_id = payload
        .get("session_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    let Some(session_id) = normalize_codex_session_id(raw_session_id) else {
        write_json_http_response(
            &mut stream,
            400,
            &json!({"ok": false, "message": "会话 ID 无效。"}),
        );
        return;
    };
    match delete_codex_session_local(session_id) {
        Ok(result) => write_json_http_response(&mut stream, 200, &result),
        Err(error) => {
            write_json_http_response(&mut stream, 500, &json!({"ok": false, "message": error}))
        }
    }
}

fn ensure_codex_session_helper() -> Result<CodexSessionHelper, String> {
    let mut guard = CODEX_SESSION_HELPER
        .lock()
        .map_err(|_| "本地会话服务状态锁失败。".to_string())?;
    if let Some(helper) = guard.as_ref() {
        return Ok(helper.clone());
    }
    let listener = TcpListener::bind(("127.0.0.1", 0))
        .map_err(|error| format!("启动本地会话服务失败：{error}"))?;
    let port = listener
        .local_addr()
        .map_err(|error| format!("读取本地会话服务端口失败：{error}"))?
        .port();
    let token = random_session_helper_token();
    let thread_token = token.clone();
    thread::Builder::new()
        .name("gaoge-codex-session-helper".to_string())
        .spawn(move || {
            for stream in listener.incoming().flatten() {
                handle_codex_session_helper_request(stream, &thread_token);
            }
        })
        .map_err(|error| format!("创建本地会话服务线程失败：{error}"))?;
    let helper = CodexSessionHelper {
        base_url: format!("http://127.0.0.1:{port}"),
        token,
    };
    *guard = Some(helper.clone());
    Ok(helper)
}

fn read_aggregate_stream_chunk(
    stream: &mut TcpStream,
    buffer: &mut [u8],
    deadline: Instant,
    context: &str,
) -> Result<usize, String> {
    loop {
        match stream.read(buffer) {
            Ok(read) => return Ok(read),
            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                if Instant::now() >= deadline {
                    return Err(format!("{context}超时：{error}"));
                }
                thread::sleep(Duration::from_millis(2));
            }
            Err(error) => return Err(format!("{context}失败：{error}")),
        }
    }
}

fn write_aggregate_continue_response(stream: &mut TcpStream) -> Result<(), String> {
    stream
        .write_all(b"HTTP/1.1 100 Continue\r\n\r\n")
        .and_then(|_| stream.flush())
        .map_err(|error| format!("确认聚合模型请求正文失败：{error}"))
}

fn read_aggregate_http_request(
    stream: &mut TcpStream,
) -> Result<(String, String, HashMap<String, String>, Vec<u8>), String> {
    stream
        .set_nonblocking(false)
        .map_err(|error| format!("设置聚合模型请求读取模式失败：{error}"))?;
    let _ = stream.set_read_timeout(Some(Duration::from_secs(
        CODEX_AGGREGATE_ROUTER_READ_TIMEOUT_SECS,
    )));
    let deadline = Instant::now() + Duration::from_secs(CODEX_AGGREGATE_ROUTER_READ_TIMEOUT_SECS);
    let mut request = Vec::new();
    let mut buffer = [0u8; 16 * 1024];
    let header_end = loop {
        let read = read_aggregate_stream_chunk(stream, &mut buffer, deadline, "读取聚合模型请求")?;
        if read == 0 {
            return Err("聚合模型请求提前结束。".to_string());
        }
        request.extend_from_slice(&buffer[..read]);
        if request.len() > CODEX_AGGREGATE_ROUTER_MAX_REQUEST_BYTES {
            return Err("聚合模型请求过大。".to_string());
        }
        if let Some(index) = request.windows(4).position(|window| window == b"\r\n\r\n") {
            break index + 4;
        }
    };
    let header_text = String::from_utf8_lossy(&request[..header_end]);
    let mut lines = header_text.split("\r\n");
    let request_line = lines.next().unwrap_or_default();
    let mut request_parts = request_line.split_whitespace();
    let method = request_parts.next().unwrap_or_default().to_string();
    let path = request_parts.next().unwrap_or_default().to_string();
    let mut headers = HashMap::new();
    for line in lines {
        let Some((name, value)) = line.split_once(':') else {
            continue;
        };
        headers.insert(name.trim().to_ascii_lowercase(), value.trim().to_string());
    }
    if headers
        .get("transfer-encoding")
        .is_some_and(|value| value.to_ascii_lowercase().contains("chunked"))
    {
        return Err("本地聚合路由暂不接受分块上传请求。".to_string());
    }
    let content_length = headers
        .get("content-length")
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(0);
    let total_request_bytes = header_end
        .checked_add(content_length)
        .ok_or_else(|| "聚合模型请求正文长度无效。".to_string())?;
    if total_request_bytes > CODEX_AGGREGATE_ROUTER_MAX_REQUEST_BYTES {
        return Err("聚合模型请求正文过大。".to_string());
    }
    let received_body_bytes = request.len().saturating_sub(header_end);
    if content_length > received_body_bytes
        && headers.get("expect").is_some_and(|value| {
            value
                .split(',')
                .any(|part| part.trim().eq_ignore_ascii_case("100-continue"))
        })
    {
        write_aggregate_continue_response(stream)?;
    }
    while request.len() < total_request_bytes {
        let read =
            read_aggregate_stream_chunk(stream, &mut buffer, deadline, "读取聚合模型请求正文")?;
        if read == 0 {
            break;
        }
        request.extend_from_slice(&buffer[..read]);
        if request.len() > CODEX_AGGREGATE_ROUTER_MAX_REQUEST_BYTES {
            return Err("聚合模型请求正文过大。".to_string());
        }
    }
    if request.len() < total_request_bytes {
        return Err("聚合模型请求正文不完整。".to_string());
    }
    Ok((
        method,
        path,
        headers,
        request[header_end..total_request_bytes].to_vec(),
    ))
}

fn write_aggregate_json_response(stream: &mut TcpStream, status: u16, payload: &Value) {
    let body = payload.to_string();
    let response = format!(
        "HTTP/1.1 {status} {}\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: {}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n{body}",
        http_reason(status),
        body.len(),
    );
    let _ = stream.write_all(response.as_bytes());
    let _ = stream.flush();
}

fn aggregate_request_authorized(headers: &HashMap<String, String>, token: &str) -> bool {
    let bearer = headers
        .get("authorization")
        .and_then(|value| value.split_once(' '))
        .filter(|(scheme, _)| scheme.eq_ignore_ascii_case("bearer"))
        .map(|(_, value)| value.trim());
    bearer == Some(token) || headers.get("x-api-key").map(|value| value.trim()) == Some(token)
}

fn aggregate_upstream_url(base_url: &str, request_path: &str) -> Result<String, String> {
    let mut parsed =
        url::Url::parse(base_url).map_err(|_| "聚合模型供应商地址无效。".to_string())?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err("聚合模型供应商地址必须使用 http 或 https。".to_string());
    }
    let incoming_path = request_path
        .split('?')
        .next()
        .unwrap_or(request_path)
        .trim_end_matches('/');
    let response_suffix = if incoming_path.ends_with("/responses/compact") {
        "responses/compact"
    } else {
        "responses"
    };
    let base_path = parsed.path().trim_end_matches('/').to_string();
    let lower = base_path.to_ascii_lowercase();
    let next_path = if lower.ends_with("/responses") || lower.ends_with("/responses/compact") {
        base_path
    } else if lower.ends_with("/v1") {
        format!("{base_path}/{response_suffix}")
    } else if base_path.is_empty() {
        format!("/v1/{response_suffix}")
    } else {
        format!("{base_path}/v1/{response_suffix}")
    };
    parsed.set_path(&next_path);
    parsed.set_query(None);
    Ok(parsed.to_string().trim_end_matches('/').to_string())
}

fn aggregate_route_for_model(
    state: &AggregateLoginState,
    model: &str,
) -> Option<AggregateProviderRoute> {
    state
        .routes
        .iter()
        .find(|route| {
            route.public_model == model && is_codex_conversation_model(&route.upstream_model)
        })
        .cloned()
}

fn aggregate_route_for_request(
    state: &AggregateLoginState,
    requested_model: &str,
) -> Option<AggregateProviderRoute> {
    let requested = requested_model.trim();
    // A task's explicit route must win over the default chosen in another task.
    // Never send an expired/unknown aggregate ID to a different billing group.
    if requested.starts_with("gaoge/") {
        return aggregate_route_for_model(state, requested);
    }
    aggregate_route_for_model(state, state.default_model.trim()).or_else(|| {
        state
            .routes
            .iter()
            .find(|route| is_codex_conversation_model(&route.upstream_model))
            .cloned()
    })
}

fn select_aggregate_model_in_state(
    state: &mut AggregateLoginState,
    public_model: &str,
) -> Result<AggregateProviderRoute, String> {
    if !state.enabled {
        return Err("聚合登录当前未启用。".to_string());
    }
    let public_model = public_model.trim();
    let route = aggregate_route_for_model(state, public_model)
        .ok_or_else(|| format!("聚合模型不存在或已经失效：{public_model}"))?;
    if !is_codex_conversation_model(&route.upstream_model) {
        return Err("此模型用于生图，请为 Codex 选择对话模型。".to_string());
    }
    state.default_model = route.public_model.clone();
    state.default_model_origin = CODEX_MODEL_SELECTION_ORIGIN_USER.to_string();
    state.updated_at = unix_now();
    Ok(route)
}

#[cfg(test)]
fn select_aggregate_speed_in_state(
    state: &mut AggregateLoginState,
    requested_mode: &str,
) -> Result<(AggregateProviderRoute, Option<AggregateSpeedProfile>), String> {
    select_aggregate_speed_in_state_with_metadata(state, requested_mode, &HashMap::new())
}

fn select_aggregate_speed_in_state_with_metadata(
    state: &mut AggregateLoginState,
    requested_mode: &str,
    metadata: &HashMap<String, Value>,
) -> Result<(AggregateProviderRoute, Option<AggregateSpeedProfile>), String> {
    if !state.enabled {
        return Err("聚合登录当前未启用。".to_string());
    }
    let mode = normalize_aggregate_speed_mode(requested_mode)
        .ok_or_else(|| format!("不支持的聚合速度模式：{requested_mode}"))?;
    let route = aggregate_route_for_model(state, state.default_model.trim())
        .ok_or_else(|| "当前聚合模型不存在或已经失效。".to_string())?;
    let entry = aggregate_model_entry(&route, 0, metadata);
    let profile = aggregate_resolved_speed_profile(&route, &entry);
    if mode == AGGREGATE_SPEED_MODE_FAST && profile.is_none() {
        return Err(format!("模型 {} 暂不支持加速模式。", route.upstream_model));
    }
    state.speed_mode = mode.to_string();
    state.updated_at = unix_now();
    Ok((route, profile))
}

fn aggregate_speed_config(
    config: &str,
    route: &AggregateProviderRoute,
    speed_mode: &str,
) -> String {
    let supported = aggregate_route_speed_profile(route).is_some();
    let mut parts = split_codex_config(config);
    parts.root_lines.retain(|line| {
        !parse_toml_key_value(trim_toml_line(line)).is_some_and(|(key, _)| {
            key == "service_tier" || (supported && key == "features.fast_mode")
        })
    });
    parts.root_lines = trim_blank_lines(parts.root_lines);
    if supported && aggregate_speed_mode_is_fast(speed_mode) {
        parts.root_lines.push("service_tier = \"fast\"".to_string());
    }
    if supported {
        // The feature stays available in Standard mode; only its default tier
        // changes. Preserve every unrelated feature and provider setting.
        if let Some(features) = parts
            .sections
            .iter_mut()
            .find(|section| trim_toml_line(&section.header) == "[features]")
        {
            features.lines.retain(|line| {
                !parse_toml_key_value(trim_toml_line(line))
                    .is_some_and(|(key, _)| key == "fast_mode")
            });
            features.lines = trim_blank_lines(std::mem::take(&mut features.lines));
            features.lines.push("fast_mode = true".to_string());
        } else {
            parts.sections.push(CodexConfigSection {
                header: "[features]".to_string(),
                lines: vec!["fast_mode = true".to_string()],
            });
        }
    }
    render_codex_config_parts(parts)
}

fn sync_aggregate_model_config(
    state: &AggregateLoginState,
    route: &AggregateProviderRoute,
) -> Result<Value, String> {
    sync_aggregate_model_config_for_targets(state, route, &codex_route_targets())
}

fn sync_aggregate_model_config_for_targets(
    state: &AggregateLoginState,
    route: &AggregateProviderRoute,
    targets: &[CodexDirTarget],
) -> Result<Value, String> {
    sync_aggregate_model_config_for_targets_with_speed(state, route, targets, None)
}

fn sync_aggregate_model_config_for_targets_with_speed(
    state: &AggregateLoginState,
    route: &AggregateProviderRoute,
    targets: &[CodexDirTarget],
    requested_speed: Option<&str>,
) -> Result<Value, String> {
    if state.router_port == 0 || state.router_token.trim().is_empty() {
        return Err("聚合路由尚未就绪，无法同步 Codex 模型上下文配置。".to_string());
    }
    let metadata = aggregate_local_model_metadata(targets);
    let entry = aggregate_model_entry(route, 0, &metadata);
    let mut speed_route = route.clone();
    if !speed_route.model_config.is_object() { speed_route.model_config = json!({}); }
    speed_route.model_config["fast"] = json!(if aggregate_resolved_speed_profile(route, &entry).is_some() { "supported" } else { "unsupported" });
    let profile = AggregateContextProfile::from_entry(&entry);
    let base_url = format!("http://127.0.0.1:{}/v1", state.router_port);
    let mut updated_paths = Vec::new();
    let mut warnings = Vec::new();
    let mut current_service_tier = None;

    for target in targets {
        let config_path = target.dir.join("config.toml");
        if !target.primary && !config_path.exists() {
            continue;
        }
        let update = (|| -> Result<bool, String> {
            if target.primary {
                fs::create_dir_all(&target.dir).map_err(|error| {
                    format!("创建 Codex 配置目录失败 {}：{error}", target.dir.display())
                })?;
            }
            for attempt in 0..3 {
                // Re-read and re-merge on every retry. Never reuse a
                // candidate built from an older native-client version.
                let existing = read_text_if_exists(&config_path)?;
                let catalog_path = configured_root_value(&existing, "model_catalog_json")
                    .filter(|value| !value.trim().is_empty())
                    .map(PathBuf::from);
                let existing_effort = configured_root_value(&existing, "model_reasoning_effort");
                let reasoning_effort = catalog_path
                    .as_ref()
                    .and_then(|path| read_json_if_exists(path).ok().flatten())
                    .map(|catalog| {
                        codex_catalog_reasoning_effort(
                            &catalog,
                            &route.public_model,
                            existing_effort.as_deref(),
                        )
                    })
                    .unwrap_or_else(|| {
                        normalize_codex_reasoning_effort(existing_effort.as_deref())
                    });
                if !catalog_path.as_ref().is_some_and(|path| path.is_file()) {
                    return Err("模型目录不存在，请重新启用聚合登录以更新模型能力。".to_string());
                }
                let managed = build_codex_direct_config_with_catalog(
                    &state.router_token,
                    &base_url,
                    &route.public_model,
                    catalog_path.as_deref(),
                    Some(&reasoning_effort),
                );
                let merged = merge_codex_config(&existing, &managed);
                // Only an explicit speed-selection request may change the
                // native tier. Login, refresh and model changes preserve it.
                let next = match requested_speed {
                    Some(mode) => aggregate_speed_config(&merged, &speed_route, mode),
                    None => merged,
                };
                if target.primary {
                    current_service_tier = configured_root_value(&next, "service_tier");
                }
                if next == existing {
                    return Ok(false);
                }
                match write_codex_config_atomic(&config_path, Some(&existing), &next) {
                    Ok(()) => {}
                    Err(error) if attempt < 2 && is_codex_config_write_conflict(&error) => {
                        continue;
                    }
                    Err(error) => return Err(error),
                }
                let verified = read_text_if_exists(&config_path)?;
                let relay_matches = codex_relay_config_verified(
                    &verified,
                    &state.router_token,
                    &base_url,
                    &route.public_model,
                    catalog_path.as_deref(),
                );
                let context_matches =
                    configured_root_value(&verified, "model_context_window").is_none();
                let compact_matches =
                    configured_root_value(&verified, "model_auto_compact_token_limit").is_none();
                let speed_matches = requested_speed
                    .map_or(true, |mode| aggregate_speed_config(&verified, &speed_route, mode) == verified);
                if target.primary {
                    current_service_tier = configured_root_value(&verified, "service_tier");
                }
                if !relay_matches || !context_matches || !compact_matches || !speed_matches {
                    return Err(format!(
                        "Codex 模型与速度配置写入后校验失败：{}",
                        config_path.display()
                    ));
                }
                return Ok(true);
            }
            Err("Codex 配置持续被其他程序更新，已保留最新配置；请稍后重试。".to_string())
        })();
        match update {
            Ok(true) => updated_paths.push(config_path.to_string_lossy().to_string()),
            Ok(false) => {}
            Err(error) if target.primary => return Err(error),
            Err(error) => warnings.push(format!("{}：{error}", target.source)),
        }
    }

    Ok(json!({
      "ok": true,
      "configUpdated": !updated_paths.is_empty(),
      "updatedPaths": updated_paths,
      "warnings": warnings,
      "contextWindow": profile.map(|value| value.context_window),
      "maxContextWindow": profile.map(|value| value.max_context_window),
      "autoCompactTokenLimit": profile.and_then(|value| value.auto_compact_token_limit),
      "contextSource": "model-catalog",
      "serviceTier": current_service_tier,
    }))
}

fn select_aggregate_model(public_model: &str) -> Result<Value, String> {
    let mut next = aggregate_login_state_snapshot();
    let metadata = aggregate_local_model_metadata(&codex_route_targets());
    let previous_profile =
        aggregate_route_for_model(&next, next.default_model.trim()).and_then(|route| {
            AggregateContextProfile::from_entry(&aggregate_model_entry(&route, 0, &metadata))
        });
    let route = select_aggregate_model_in_state(&mut next, public_model)?;
    let entry = aggregate_model_entry(&route, 0, &metadata);
    let profile = AggregateContextProfile::from_entry(&entry);
    let config_sync = sync_aggregate_model_config(&next, &route)?;
    save_aggregate_login_state(&next)?;
    Ok(json!({
      "ok": true,
      "status": "ok",
      "publicModel": route.public_model,
      "upstreamModel": route.upstream_model,
      "providerId": route.provider_id,
      "providerName": route.provider_name,
      "upstreamPlatform": route.upstream_platform,
      "groupId": route.group_id,
      "groupName": route.group_name,
      "groupRateText": route.group_rate_text,
      "contextWindow": profile.map(|value| value.context_window),
      "maxContextWindow": profile.map(|value| value.max_context_window),
      "inputModalities": entry["input_modalities"],
      "autoCompactTokenLimit": profile.and_then(|value| value.auto_compact_token_limit),
      "contextReduced": previous_profile.zip(profile).is_some_and(|(previous, current)| previous.context_window > current.context_window),
      "speedMode": normalize_aggregate_speed_mode(&next.speed_mode).unwrap_or(AGGREGATE_SPEED_MODE_STANDARD),
      "speedSupported": aggregate_resolved_speed_profile(&route, &entry).is_some(),
      "configSync": config_sync,
    }))
}

fn select_aggregate_speed(
    requested_mode: &str,
    public_model: Option<&str>,
) -> Result<Value, String> {
    let mut next = aggregate_login_state_snapshot();
    if let Some(model) = public_model {
        select_aggregate_model_in_state(&mut next, model)?;
    }
    let metadata = aggregate_local_model_metadata(&codex_route_targets());
    let (route, profile) = select_aggregate_speed_in_state_with_metadata(&mut next, requested_mode, &metadata)?;
    let config_sync = sync_aggregate_model_config_for_targets_with_speed(
        &next, &route, &codex_route_targets(), Some(&next.speed_mode),
    )?;
    save_aggregate_login_state(&next)?;
    bump_codex_runtime_revision();
    start_codex_runtime_watcher();
    Ok(json!({
      "ok": true,
      "status": "ok",
      "publicModel": route.public_model,
      "upstreamModel": route.upstream_model,
      "providerId": route.provider_id,
      "speedMode": normalize_aggregate_speed_mode(&next.speed_mode).unwrap_or(AGGREGATE_SPEED_MODE_STANDARD),
      "speedSupported": profile.is_some(),
      "speedLabel": profile.map(|value| value.picker_label).unwrap_or_default(),
      "configSync": config_sync,
    }))
}

fn write_aggregate_response_head(
    stream: &mut TcpStream,
    status: reqwest::StatusCode,
    headers: &reqwest::header::HeaderMap,
) -> Result<(), String> {
    let reason = status.canonical_reason().unwrap_or("Upstream Response");
    let mut head = format!("HTTP/1.1 {} {reason}\r\n", status.as_u16());
    for (name, value) in headers {
        let lower = name.as_str().to_ascii_lowercase();
        if matches!(
            lower.as_str(),
            "connection"
                | "keep-alive"
                | "proxy-authenticate"
                | "proxy-authorization"
                | "te"
                | "trailer"
                | "transfer-encoding"
                | "upgrade"
                | "content-length"
                | "content-encoding"
        ) {
            continue;
        }
        if let Ok(value) = value.to_str() {
            head.push_str(name.as_str());
            head.push_str(": ");
            head.push_str(value);
            head.push_str("\r\n");
        }
    }
    head.push_str("Cache-Control: no-store\r\nConnection: close\r\n\r\n");
    stream
        .write_all(head.as_bytes())
        .map_err(|error| format!("写入聚合模型响应头失败：{error}"))?;
    Ok(())
}

fn write_aggregate_upstream_response(
    stream: &mut TcpStream,
    mut response: reqwest::blocking::Response,
) -> Result<(), String> {
    write_aggregate_response_head(stream, response.status(), response.headers())?;
    std::io::copy(&mut response, stream)
        .map_err(|error| format!("转发聚合模型流式响应失败：{error}"))?;
    stream
        .flush()
        .map_err(|error| format!("刷新聚合模型响应失败：{error}"))?;
    Ok(())
}

fn is_aggregate_claude_provider(provider_id: &str) -> bool {
    matches!(
        provider_id.trim().to_ascii_lowercase().as_str(),
        "anthropic" | "claude"
    )
}

fn is_aggregate_anthropic_route(provider_id: &str, upstream_platform: &str) -> bool {
    is_aggregate_claude_provider(provider_id)
        || matches!(
            upstream_platform.trim().to_ascii_lowercase().as_str(),
            "anthropic" | "claude"
        )
}

fn is_aggregate_nonportable_reasoning_provider(provider_id: &str) -> bool {
    matches!(
        provider_id.trim().to_ascii_lowercase().as_str(),
        "grok"
            | "gork"
            | "xai"
            | "kimi"
            | "moonshot"
            | "deepseek"
            | "glm"
            | "zhipu"
            | "bigmodel"
            | "zai"
    )
}

fn legacy_aggregate_item_id_suffix(id: &str) -> Option<&str> {
    let suffix = id.strip_prefix("item_")?;
    // The legacy Anthropic -> Responses bridge generated exactly 12 random
    // bytes as lowercase hex. Keep the compatibility rewrite restricted to
    // that known shape so unrelated provider IDs are never changed.
    if suffix.len() == 24
        && suffix
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        Some(suffix)
    } else {
        None
    }
}

fn sanitize_aggregate_openai_response_payload(payload: &mut Value) -> usize {
    let Some(input) = payload.get_mut("input").and_then(Value::as_array_mut) else {
        return 0;
    };

    let mut changed = 0usize;
    input.retain_mut(|item| {
        let item_type = item.get("type").and_then(Value::as_str).unwrap_or("");
        let legacy_suffix = item
            .get("id")
            .and_then(Value::as_str)
            .and_then(legacy_aggregate_item_id_suffix)
            .map(str::to_string);

        if item_type.eq_ignore_ascii_case("message")
            && item
                .get("role")
                .and_then(Value::as_str)
                .is_some_and(|role| role.eq_ignore_ascii_case("assistant"))
        {
            if let (Some(suffix), Some(object)) = (legacy_suffix.as_deref(), item.as_object_mut()) {
                object.insert("id".to_string(), Value::String(format!("msg_{suffix}")));
                changed += 1;
            }
            return true;
        }

        // Claude reasoning blocks are provider-private and cannot be replayed
        // to OpenAI. Dropping only the bridge's known legacy ID shape keeps
        // native OpenAI `rs_...` reasoning items intact.
        if item_type.eq_ignore_ascii_case("reasoning") && legacy_suffix.is_some() {
            changed += 1;
            return false;
        }

        // OpenAI Responses requires function-call item IDs to use `fc_...`.
        // Keep call_id untouched because it links the function_call to its
        // function_call_output.
        if item_type.eq_ignore_ascii_case("function_call") {
            if let (Some(suffix), Some(object)) = (legacy_suffix.as_deref(), item.as_object_mut()) {
                object.insert("id".to_string(), Value::String(format!("fc_{suffix}")));
                changed += 1;
            }
        }
        true
    });

    changed
}

fn is_server_web_search_tool_type(tool_type: &str) -> bool {
    matches!(
        tool_type.trim().to_ascii_lowercase().as_str(),
        "web_search"
            | "web_search_preview"
            | "web_search_20250305"
            | "web_search_preview_2025_03_11"
            | "google_search"
            | "google_search_retrieval"
    )
}

fn aggregate_tool_choice_targets_web_search(tool_choice: &Value) -> bool {
    if let Some(value) = tool_choice.as_str() {
        return is_server_web_search_tool_type(value);
    }
    let Some(object) = tool_choice.as_object() else {
        return false;
    };
    object
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(is_server_web_search_tool_type)
}

fn sanitize_aggregate_claude_response_payload(payload: &mut Value) -> usize {
    let history_rewritten = codex_response_compat::normalize_search_history(payload);
    let Some(object) = payload.as_object_mut() else {
        return 0;
    };
    let mut removed_tools = 0usize;
    if let Some(tools) = object.get_mut("tools").and_then(Value::as_array_mut) {
        tools.retain(|tool| {
            let remove = tool
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(is_server_web_search_tool_type);
            if remove {
                removed_tools += 1;
            }
            !remove
        });
    }

    let has_tools = object
        .get("tools")
        .and_then(Value::as_array)
        .is_some_and(|tools| !tools.is_empty());
    if has_tools {
        if object
            .get("tool_choice")
            .is_some_and(aggregate_tool_choice_targets_web_search)
        {
            object.insert("tool_choice".to_string(), Value::String("auto".to_string()));
        }
    } else {
        object.remove("tools");
        object.remove("tool_choice");
    }

    object.remove("web_search_options");
    let include_is_empty =
        if let Some(include) = object.get_mut("include").and_then(Value::as_array_mut) {
            include.retain(|item| {
                !item.as_str().is_some_and(|value| {
                    value.trim().to_ascii_lowercase().starts_with("web_search")
                })
            });
            include.is_empty()
        } else {
            false
        };
    if include_is_empty {
        object.remove("include");
    }
    removed_tools + history_rewritten
}

fn sanitize_aggregate_nonportable_reasoning_payload(payload: &mut Value) -> usize {
    let Some(object) = payload.as_object_mut() else {
        return 0;
    };

    let mut removed_items = 0usize;
    if let Some(input) = object.get_mut("input").and_then(Value::as_array_mut) {
        input.retain(|item| {
            let remove = item
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|item_type| item_type.eq_ignore_ascii_case("reasoning"));
            if remove {
                removed_items += 1;
            }
            !remove
        });
    }

    let include_is_empty =
        if let Some(include) = object.get_mut("include").and_then(Value::as_array_mut) {
            include.retain(|item| {
                let remove = item
                    .as_str()
                    .is_some_and(|value| value.eq_ignore_ascii_case("reasoning.encrypted_content"));
                if remove {
                    removed_items += 1;
                }
                !remove
            });
            include.is_empty()
        } else {
            false
        };
    if include_is_empty {
        object.remove("include");
    }

    removed_items
}

fn normalize_aggregate_glm_reasoning_effort(payload: &mut Value) -> usize {
    let model = canonical_codex_catalog_model_name(payload["model"].as_str().unwrap_or_default());
    let metadata = model_capabilities::builtin_model_metadata(&model);
    let supported = metadata.as_ref().and_then(|v|v["supported_reasoning_levels"].as_array()).map(|levels| {
        levels.iter().filter_map(|level| level["effort"].as_str().map(str::to_owned)).collect::<Vec<_>>()
    });
    let Some(reasoning) = payload.get_mut("reasoning").and_then(Value::as_object_mut) else { return 0 };
    let Some(effort) = reasoning.get("effort").and_then(Value::as_str).map(|v|v.trim().to_ascii_lowercase()) else { return 0 };
    if let Some(supported) = supported.filter(|v| !v.is_empty()) {
        if supported.contains(&effort) { return 0; }
        let fallback = if supported.iter().any(|v| v == "high") { "high" } else { &supported[0] };
        reasoning.insert("effort".into(),json!(fallback));
        return 1;
    }
    if !matches!(effort.as_str(), "xhigh" | "max") { return 0; }
    reasoning.insert("effort".into(), json!("high"));
    1
}

fn metadata_value_marks_compaction(value: &Value) -> bool {
    match value {
        Value::Object(object) => object.iter().any(|(key, value)| {
            let key = key.trim().to_ascii_lowercase().replace('-', "_");
            if key == "request_kind" || key == "requestkind" {
                return value
                    .as_str()
                    .is_some_and(|kind| kind.trim().eq_ignore_ascii_case("compaction"));
            }
            metadata_value_marks_compaction(value)
        }),
        Value::Array(values) => values.iter().any(metadata_value_marks_compaction),
        Value::String(text) => {
            let text = text.trim();
            if text.eq_ignore_ascii_case("compaction") {
                return true;
            }
            serde_json::from_str::<Value>(text)
                .ok()
                .is_some_and(|parsed| metadata_value_marks_compaction(&parsed))
        }
        _ => false,
    }
}

fn aggregate_request_is_compaction(headers: &HashMap<String, String>, payload: &Value) -> bool {
    headers
        .get("x-codex-turn-metadata")
        .and_then(|value| serde_json::from_str::<Value>(value).ok())
        .is_some_and(|value| metadata_value_marks_compaction(&value))
        || payload
            .get("client_metadata")
            .is_some_and(metadata_value_marks_compaction)
}

fn sanitize_aggregate_compaction_payload(payload: &mut Value) -> usize {
    const COMPACTION_INSTRUCTIONS: &str = "This is a Codex context compaction request. Return one complete standalone plain-text summary of the conversation, decisions, files changed, unfinished work, and the latest user intent. Do not call tools, do not answer the latest user request, and never return a placeholder or an empty response.";
    let mut changed = sanitize_aggregate_nonportable_reasoning_payload(payload);
    let Some(object) = payload.as_object_mut() else {
        return changed;
    };
    for key in [
        "tools",
        "tool_choice",
        "parallel_tool_calls",
        "web_search_options",
        "include",
        "reasoning",
        "service_tier",
    ] {
        if object.remove(key).is_some() {
            changed += 1;
        }
    }
    let existing = object
        .get("instructions")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    if !existing.contains("Codex context compaction request") {
        let instructions = if existing.is_empty() {
            COMPACTION_INSTRUCTIONS.to_string()
        } else {
            format!("{existing}\n\n{COMPACTION_INSTRUCTIONS}")
        };
        object.insert("instructions".to_string(), Value::String(instructions));
        changed += 1;
    }
    changed
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct AggregateRequestRouting {
    upstream_model: String,
    anthropic_fast_beta: bool,
}

fn prepare_aggregate_speed_request(
    route: &AggregateProviderRoute,
    payload: &mut Value,
) -> AggregateRequestRouting {
    // Native Standard can omit the tier entirely. Historical helper settings
    // must never turn an absent/default task tier into a priority request.
    let wants_fast = payload.get("service_tier").and_then(Value::as_str)
        .is_some_and(aggregate_speed_mode_is_fast);
    let profile = aggregate_route_speed_profile(route);
    let routing = AggregateRequestRouting {
        upstream_model: route.upstream_model.clone(),
        anthropic_fast_beta: false,
    };
    let Some(object) = payload.as_object_mut() else {
        return routing;
    };
    object.remove("service_tier");
    if !wants_fast {
        return routing;
    }
    match profile.map(|profile| profile.transport) {
        Some(AggregateSpeedTransport::OpenAiPriority) => {
            object.insert(
                "service_tier".to_string(),
                Value::String("priority".to_string()),
            );
        }
        None => {}
    }
    routing
}

fn sanitize_aggregate_response_payload_for_request(
    provider_id: &str,
    upstream_platform: &str,
    payload: &mut Value,
    is_compaction: bool,
) -> usize {
    let mut removed = 0usize;
    if is_aggregate_openai_provider(provider_id) {
        removed += sanitize_aggregate_openai_response_payload(payload);
    }
    if is_aggregate_anthropic_route(provider_id, upstream_platform) {
        removed += sanitize_aggregate_claude_response_payload(payload);
    }
    if is_aggregate_nonportable_reasoning_provider(provider_id) {
        removed += sanitize_aggregate_nonportable_reasoning_payload(payload);
    }
    if is_aggregate_glm_provider(provider_id) {
        removed += normalize_aggregate_glm_reasoning_effort(payload);
    }
    if is_compaction && !is_aggregate_openai_provider(provider_id) {
        removed += sanitize_aggregate_compaction_payload(payload);
    }
    removed
}

#[cfg_attr(not(test), allow(dead_code))]
fn sanitize_aggregate_response_payload(
    provider_id: &str,
    upstream_platform: &str,
    payload: &mut Value,
) -> usize {
    sanitize_aggregate_response_payload_for_request(provider_id, upstream_platform, payload, false)
}

fn forward_aggregate_response_request(
    stream: &mut TcpStream,
    path: &str,
    headers: &HashMap<String, String>,
    body: &[u8],
    state: &AggregateLoginState,
) -> Result<(), String> {
    let mut payload: Value = serde_json::from_slice(body)
        .map_err(|error| format!("聚合模型请求不是有效 JSON：{error}"))?;
    let requested_model = payload.get("model").and_then(Value::as_str).map(str::trim)
        .filter(|value| !value.is_empty()).unwrap_or(state.default_model.as_str()).to_string();
    let route = aggregate_route_for_request(state, &requested_model)
        .ok_or_else(|| format!("聚合登录没有为模型 {requested_model} 配置供应商。"))?;
    let is_compaction = aggregate_request_is_compaction(headers, &payload);
    if route.protocol == aggregate_protocol::Protocol::Responses {
        sanitize_aggregate_response_payload_for_request(&route.provider_id, &route.upstream_platform, &mut payload, is_compaction);
    } else if is_compaction {
        if let Some(object) = payload.as_object_mut() { object.remove("service_tier"); }
    }
    let wants_fast = payload["service_tier"].as_str().is_some_and(aggregate_speed_mode_is_fast);
    let mut request_route = route.clone();
    if wants_fast {
        let metadata = aggregate_local_model_metadata(&codex_route_targets());
        let entry = aggregate_model_entry(&route, 0, &metadata);
        if !aggregate_entry_supports_fast(&entry) {
            return Err(format!("{} / {} 的当前接口未声明支持 Fast，请选择标准速度或确认线路能力。",route.provider_name,route.upstream_model));
        }
        if !request_route.model_config.is_object() { request_route.model_config = json!({}); }
        request_route.model_config["fast"] = json!("supported");
    }
    let request_routing = prepare_aggregate_speed_request(&request_route, &mut payload);
    let object = payload.as_object_mut().ok_or("聚合模型请求正文必须是 JSON 对象。")?;
    object.insert("model".into(), json!(request_routing.upstream_model));
    if route.protocol == aggregate_protocol::Protocol::Responses {
        if is_aggregate_anthropic_route(&route.provider_id, &route.upstream_platform) {
            enforce_claude_max_output_tokens(object, &route.upstream_model);
        }
        return forward_response_request_with_recovery(stream, path, headers, payload, &route, request_routing.anthropic_fast_beta);
    }
    forward_aggregate_adapted_request(stream, path, headers, payload, &route)
}

fn forward_aggregate_adapted_request(
    stream: &mut TcpStream,
    path: &str,
    headers: &HashMap<String, String>,
    payload: Value,
    route: &AggregateProviderRoute,
) -> Result<(), String> {
    use aggregate_protocol::{Protocol, StreamAdapter};
    let endpoint = aggregate_protocol::endpoint(route.protocol, &route.base_url, path)?;
    let adapted = aggregate_protocol::prepare_request(route.protocol, &payload)?;
    let streaming = payload["stream"].as_bool().unwrap_or(false);
    let client = reqwest::blocking::Client::builder().connect_timeout(Duration::from_secs(10))
        .gzip(true).build().map_err(|error| format!("创建聚合协议客户端失败：{error}"))?;
    let mut request = client.post(endpoint).header("content-type", "application/json")
        .header("accept", if streaming { "text/event-stream" } else { "application/json" })
        .header("user-agent",GAOGE_USER_AGENT);
    if route.protocol == Protocol::AnthropicMessages {
        request = request.header("x-api-key",&route.api_key).header("anthropic-version","2023-06-01");
    } else { request = request.bearer_auth(&route.api_key); }
    // Do not leak the local router's credentials, Codex account headers, or
    // provider-specific beta flags to a different upstream protocol.
    for name in ["accept-language", "x-request-id", "idempotency-key"] {
        if let Some(value) = headers.get(name) { request = request.header(name, value); }
    }
    let mut response = request.json(&adapted).send().map_err(|error| format!("请求 {} 模型失败：{error}",route.provider_name))?;
    let status = response.status();
    if !status.is_success() { return write_aggregate_upstream_response(stream,response); }
    let event_stream = response.headers().get(reqwest::header::CONTENT_TYPE).and_then(|v|v.to_str().ok())
        .is_some_and(|v|v.split(';').next().unwrap_or_default().trim().eq_ignore_ascii_case("text/event-stream"));
    let mut response_headers = response.headers().clone();
    if event_stream {
        if !streaming { return Err("上游返回流式响应，但请求未启用流式输出。".into()); }
        let mut adapter = StreamAdapter::new(route.protocol,&payload)?;
        response_headers.insert(reqwest::header::CONTENT_TYPE,reqwest::header::HeaderValue::from_static("text/event-stream; charset=utf-8"));
        write_aggregate_response_head(stream,status,&response_headers)?;
        let mut buffer = [0_u8;16_384];
        loop {
            let output = match response.read(&mut buffer) {
                Ok(0) => match adapter.finish() { Ok(bytes)=>bytes, Err(error)=>adapter.abort(&error) },
                Ok(size) => match adapter.push(&buffer[..size]) {
                    Ok(bytes) => { stream.write_all(&bytes).map_err(|e|e.to_string())?; stream.flush().map_err(|e|e.to_string())?; continue; },
                    Err(error) => adapter.abort(&error),
                },
                Err(error) => adapter.abort(&format!("上游响应中断：{error}")),
            };
            stream.write_all(&output).map_err(|e|e.to_string())?;
            return stream.flush().map_err(|e|e.to_string());
        }
    }
    let mut bytes=Vec::new();
    response.take(32*1024*1024+1).read_to_end(&mut bytes).map_err(|e|format!("读取上游响应失败：{e}"))?;
    if bytes.len()>32*1024*1024 { return Err("上游响应超过 32 MiB 限制。".into()); }
    let value: Value=serde_json::from_slice(&bytes).map_err(|e|format!("上游没有返回有效 JSON：{e}"))?;
    let output = if streaming {
        response_headers.insert(reqwest::header::CONTENT_TYPE,reqwest::header::HeaderValue::from_static("text/event-stream; charset=utf-8"));
        aggregate_protocol::convert_response_sse(route.protocol,&value,&payload)?
    } else {
        response_headers.insert(reqwest::header::CONTENT_TYPE,reqwest::header::HeaderValue::from_static("application/json; charset=utf-8"));
        serde_json::to_vec(&aggregate_protocol::convert_response(route.protocol,&value,&payload)?).map_err(|e|e.to_string())?
    };
    write_aggregate_response_head(stream,status,&response_headers)?;
    stream.write_all(&output).map_err(|e|e.to_string())?;
    stream.flush().map_err(|e|e.to_string())
}

fn forward_response_stream_with_recovery(
    stream: &mut TcpStream,
    response: reqwest::blocking::Response,
    retry: reqwest::blocking::RequestBuilder,
    mut payload: Value,
) -> Result<(), String> {
    use codex_response_stream::{BodyReader, PrefixProbe, ReadError, Rejection, Verdict};
    let status = response.status();
    let headers = response.headers().clone();
    let mut body = BodyReader::new(response).map_err(|error| error.to_string())?;
    let mut probe = PrefixProbe::new();
    let deadline = Instant::now() + codex_response_stream::PROBE_TIMEOUT;
    let mut prefix = Vec::new();
    let mut ended = false;
    let mut read_error = None;
    loop {
        let Some(remaining) = deadline.checked_duration_since(Instant::now()) else { break };
        let chunk = match body.next(Some(remaining)) {
            Ok(chunk) if chunk.is_empty() => { ended = true; break; }
            Ok(chunk) => chunk,
            Err(ReadError::Timeout) => break,
            Err(ReadError::Io(error)) => { read_error = Some(error.to_string()); break; }
        };
        prefix.extend_from_slice(&chunk);
        match probe.feed(&chunk) {
            Verdict::Pending => {}
            Verdict::Forward => break,
            Verdict::Rejected(kind) => {
                let changed = match kind {
                    Rejection::ToolPair => codex_response_compat::recover_tool_context(&mut payload),
                    Rejection::SearchType => codex_response_compat::normalize_search_history(&mut payload),
                };
                if changed > 0 {
                    // No accepted event has reached the client and the reader
                    // is waiting for demand, so dropping it closes the old body.
                    drop(body);
                    log::info!("Recovering Responses history after an initial SSE validation rejection");
                    let response = retry.json(&payload).send()
                        .map_err(|error| format!("历史上下文兼容请求失败：{error}"))?;
                    // Exactly one retry. A second failure is passed through.
                    return write_aggregate_upstream_response(stream, response);
                }
                break;
            }
        }
    }
    // Timeout, size limit, malformed data, or any accepted/unknown event: keep
    // every original byte, flush promptly, and never reopen the retry window.
    write_aggregate_response_head(stream, status, &headers)?;
    stream.write_all(&prefix).map_err(|error| error.to_string())?;
    stream.flush().map_err(|error| error.to_string())?;
    if let Some(error) = read_error { return Err(error); }
    while !ended {
        match body.next(None) {
            Ok(chunk) if chunk.is_empty() => ended = true,
            Ok(chunk) => {
                stream.write_all(&chunk).map_err(|error| error.to_string())?;
                stream.flush().map_err(|error| error.to_string())?;
            }
            Err(ReadError::Io(error)) => return Err(error.to_string()),
            Err(ReadError::Timeout) => unreachable!("no timeout requested"),
        }
    }
    Ok(())
}

// Both ordinary API login modes use the same bounded recovery as aggregate
// login, without changing their model, speed, auth identity or normal payload.
fn forward_response_request_with_recovery(
    stream: &mut TcpStream,
    path: &str,
    headers: &HashMap<String, String>,
    mut payload: Value,
    route: &AggregateProviderRoute,
    anthropic_fast_beta: bool,
) -> Result<(), String> {
    let upstream_url = aggregate_upstream_url(&route.base_url, path)?;
    let client = reqwest::blocking::Client::builder()
        .connect_timeout(Duration::from_secs(10))
        .gzip(true)
        .build()
        .map_err(|error| format!("创建聚合模型请求客户端失败：{error}"))?;
    let mut request = client
        .post(upstream_url)
        .bearer_auth(&route.api_key)
        .header("content-type", "application/json")
        .header(
            "accept",
            headers
                .get("accept")
                .map(String::as_str)
                .unwrap_or("text/event-stream"),
        )
        .header("user-agent", GAOGE_USER_AGENT);
    if is_aggregate_anthropic_route(&route.provider_id, &route.upstream_platform) {
        request = request.header("x-api-key", &route.api_key).header(
            "anthropic-version",
            headers
                .get("anthropic-version")
                .map(String::as_str)
                .unwrap_or("2023-06-01"),
        );
        let mut anthropic_beta = headers
            .get("anthropic-beta")
            .map(|value| value.trim().to_string())
            .unwrap_or_default();
        if anthropic_fast_beta
            && !anthropic_beta
                .split(',')
                .any(|value| value.trim() == "fast-mode-2026-02-01")
        {
            if !anthropic_beta.is_empty() {
                anthropic_beta.push(',');
            }
            anthropic_beta.push_str("fast-mode-2026-02-01");
        }
        if !anthropic_beta.is_empty() {
            request = request.header("anthropic-beta", anthropic_beta);
        }
    }
    for (name, value) in headers {
        if matches!(
            name.as_str(),
            "host"
                | "authorization"
                | "x-api-key"
                | "content-length"
                | "content-type"
                | "accept"
                | "connection"
                | "transfer-encoding"
                | "accept-encoding"
                | "expect"
                | "user-agent"
                | "anthropic-beta"
        ) {
            continue;
        }
        let Ok(name) = reqwest::header::HeaderName::from_bytes(name.as_bytes()) else {
            continue;
        };
        let Ok(value) = reqwest::header::HeaderValue::from_str(value) else {
            continue;
        };
        request = request.header(name, value);
    }
    let fallback_request = request.try_clone();
    let mut response = request
        .json(&payload)
        .send()
        .map_err(|error| format!("请求 {} 模型失败：{error}", route.provider_name))?;
    let event_stream = response.headers().get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .is_some_and(|value| value.trim().eq_ignore_ascii_case("text/event-stream"));
    if event_stream && matches!(response.status().as_u16(), 200 | 400 | 422)
        && codex_response_stream::recoverable_input(&payload)
    {
        if let Some(retry) = fallback_request {
            return forward_response_stream_with_recovery(stream, response, retry, payload);
        }
        return write_aggregate_upstream_response(stream, response);
    }
    // Retry only a definite validation rejection, never a transport timeout,
    // authentication failure, uncertain disconnect, or accepted turn.
    if matches!(response.status().as_u16(), 400 | 422) {
        let status = response.status();
        let headers = response.headers().clone();
        let mut prefix = Vec::new();
        (&mut response).take(65_537).read_to_end(&mut prefix)
            .map_err(|error| format!("读取模型错误响应失败：{error}"))?;
        if prefix.len() <= 65_536 {
            if let Some(retry) = fallback_request {
                let repaired = if codex_response_compat::is_search_type_rejection(&prefix) {
                    codex_response_compat::normalize_search_history(&mut payload)
                } else if codex_response_compat::is_tool_pair_rejection(&prefix) {
                    codex_response_compat::recover_tool_context(&mut payload)
                } else { 0 };
                if repaired > 0 {
                    let retried = retry.json(&payload).send()
                        .map_err(|error| format!("历史上下文兼容请求失败：{error}"))?;
                    return write_aggregate_upstream_response(stream, retried);
                }
            }
        }
        write_aggregate_response_head(stream, status, &headers)?;
        stream.write_all(&prefix).map_err(|error| error.to_string())?;
        std::io::copy(&mut response, stream).map_err(|error| error.to_string())?;
        return stream.flush().map_err(|error| error.to_string());
    }
    write_aggregate_upstream_response(stream, response)
}

fn aggregate_models_payload(state: &AggregateLoginState) -> Value {
    let models = state
        .routes
        .iter()
        .filter(|route| is_codex_conversation_model(&route.upstream_model))
        .map(|route| {
            json!({
              "id": route.public_model,
              "source": route.source,
              "gaoge_aggregate_source": route.source,
              "gaoge_aggregate_provider_id": route.provider_id,
              "gaoge_aggregate_group_id": route.group_id,
              "gaoge_aggregate_public_model": route.public_model,
              "object": "model",
              "owned_by": route.provider_id,
              "provider": route.provider_name,
              "upstream_platform": route.upstream_platform,
              "group_id": route.group_id,
              "group": route.group_name,
              "group_rate": route.group_rate_text,
              "upstream_model": route.upstream_model,
            })
        })
        .collect::<Vec<_>>();
    json!({ "object": "list", "data": models })
}

fn handle_aggregate_router_request(mut stream: TcpStream, token: String) {
    let request = read_aggregate_http_request(&mut stream);
    let Ok((method, path, headers, body)) = request else {
        write_aggregate_json_response(
            &mut stream,
            400,
            &json!({"error": {"message": request.err().unwrap_or_default(), "type": "invalid_request_error"}}),
        );
        return;
    };
    if method.eq_ignore_ascii_case("OPTIONS") {
        let response = "HTTP/1.1 204 No Content\r\nContent-Length: 0\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Authorization, Content-Type, X-Api-Key\r\nConnection: close\r\n\r\n";
        let _ = stream.write_all(response.as_bytes());
        let _ = stream.flush();
        return;
    }
    if !aggregate_request_authorized(&headers, &token) {
        write_aggregate_json_response(
            &mut stream,
            401,
            &json!({"error": {"message": "聚合登录令牌无效。", "type": "authentication_error"}}),
        );
        return;
    }
    let state = AGGREGATE_LOGIN_STATE
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_else(|_| default_aggregate_login_state());
    if !state.enabled {
        write_aggregate_json_response(
            &mut stream,
            503,
            &json!({"error": {"message": "聚合登录当前未启用。", "type": "service_unavailable"}}),
        );
        return;
    }
    let clean_path = path
        .split('?')
        .next()
        .unwrap_or(path.as_str())
        .trim_end_matches('/');
    if method.eq_ignore_ascii_case("GET") && matches!(clean_path, "/health" | "/v1/health") {
        write_aggregate_json_response(
            &mut stream,
            200,
            &json!({"ok": true, "mode": "aggregate", "models": state.routes.len()}),
        );
        return;
    }
    if method.eq_ignore_ascii_case("GET") && matches!(clean_path, "/models" | "/v1/models") {
        write_aggregate_json_response(&mut stream, 200, &aggregate_models_payload(&state));
        return;
    }
    if !method.eq_ignore_ascii_case("POST") {
        write_aggregate_json_response(
            &mut stream,
            405,
            &json!({"error": {"message": "聚合模型接口仅支持 GET 或 POST。", "type": "invalid_request_error"}}),
        );
        return;
    }
    if !matches!(
        clean_path,
        "/responses" | "/v1/responses" | "/responses/compact" | "/v1/responses/compact"
    ) {
        write_aggregate_json_response(
            &mut stream,
            404,
            &json!({"error": {"message": "未知的聚合模型接口。", "type": "invalid_request_error"}}),
        );
        return;
    }
    if
        forward_aggregate_response_request(&mut stream, &path, &headers, &body, &state)
            .is_err()
    {
        // As in ordinary API mode, the stream may have already started. Never
        // append a second HTTP response to SSE or replay an uncertain request.
        log::warn!("Aggregate response ended before completion; no automatic replay");
    }
}

fn stop_aggregate_router_runtime() {
    let runtime = AGGREGATE_ROUTER_RUNTIME
        .lock()
        .ok()
        .and_then(|mut guard| guard.take());
    if let Some(runtime) = runtime {
        runtime.stop.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(("127.0.0.1", runtime.port));
    }
}

fn ensure_aggregate_router_runtime(state: &mut AggregateLoginState) -> Result<String, String> {
    if state.router_token.trim().is_empty() {
        state.router_token = random_session_helper_token();
    }
    if let Ok(guard) = AGGREGATE_ROUTER_RUNTIME.lock() {
        if let Some(runtime) = guard.as_ref() {
            if !runtime.stop.load(Ordering::SeqCst)
                && runtime.port == state.router_port
                && runtime.token == state.router_token
            {
                return Ok(format!("http://127.0.0.1:{}/v1", runtime.port));
            }
        }
    }
    stop_aggregate_router_runtime();
    let listener = if state.router_port > 0 {
        TcpListener::bind(("127.0.0.1", state.router_port))
    } else {
        TcpListener::bind(("127.0.0.1", 0))
    }
    .map_err(|error| format!("启动本地聚合模型路由失败：{error}"))?;
    listener
        .set_nonblocking(true)
        .map_err(|error| format!("设置本地聚合模型路由失败：{error}"))?;
    let port = listener
        .local_addr()
        .map_err(|error| format!("读取本地聚合模型路由端口失败：{error}"))?
        .port();
    let stop = Arc::new(AtomicBool::new(false));
    let thread_stop = Arc::clone(&stop);
    let thread_token = state.router_token.clone();
    thread::Builder::new()
        .name("gaoge-codex-aggregate-router".to_string())
        .spawn(move || {
            while !thread_stop.load(Ordering::SeqCst) {
                match listener.accept() {
                    Ok((stream, _)) => {
                        let request_token = thread_token.clone();
                        let _ = thread::Builder::new()
                            .name("gaoge-codex-aggregate-request".to_string())
                            .spawn(move || handle_aggregate_router_request(stream, request_token));
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(25));
                    }
                    Err(error) => {
                        log::warn!("Aggregate router accept failed: {error}");
                        thread::sleep(Duration::from_millis(100));
                    }
                }
            }
        })
        .map_err(|error| format!("创建本地聚合模型路由线程失败：{error}"))?;
    state.router_port = port;
    let runtime = AggregateRouterRuntime {
        port,
        token: state.router_token.clone(),
        stop,
    };
    *AGGREGATE_ROUTER_RUNTIME
        .lock()
        .map_err(|_| "本地聚合模型路由状态锁失败。".to_string())? = Some(runtime);
    Ok(format!("http://127.0.0.1:{port}/v1"))
}

async fn run_blocking_task<F, T>(task: F) -> Result<T, String>
where
    F: FnOnce() -> Result<T, String> + Send + 'static,
    T: Send + 'static,
{
    tauri::async_runtime::spawn_blocking(task)
        .await
        .map_err(|error| format!("blocking task failed: {error}"))?
}

fn hidden_command<P: AsRef<OsStr>>(program: P) -> Command {
    let mut command = Command::new(program);
    #[cfg(target_os = "windows")]
    {
        command.creation_flags(CREATE_NO_WINDOW);
    }
    command
}

fn wait_child_output_with_timeout(
    mut child: Child,
    timeout: Duration,
    label: &str,
) -> Result<Output, String> {
    let deadline = Instant::now() + timeout;
    loop {
        match child.try_wait() {
            Ok(Some(_)) => {
                return child
                    .wait_with_output()
                    .map_err(|error| format!("{label} wait failed: {error}"));
            }
            Ok(None) if Instant::now() < deadline => thread::sleep(Duration::from_millis(25)),
            Ok(None) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(format!(
                    "{label} timed out after {} seconds",
                    timeout.as_secs()
                ));
            }
            Err(error) => return Err(format!("{label} wait failed: {error}")),
        }
    }
}

fn run_powershell(script: &str) -> Result<String, String> {
    let child = hidden_command("powershell.exe")
        .args([
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-Command",
            script,
        ])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| format!("PowerShell failed: {error}"))?;
    let output = wait_child_output_with_timeout(
        child,
        Duration::from_secs(HELPER_PROCESS_TIMEOUT_SECS),
        "PowerShell",
    )?;
    if !output.status.success() {
        return Err(String::from_utf8_lossy(&output.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}

fn secure_storage_available() -> bool {
    cfg!(any(target_os = "windows", target_os = "macos"))
}

fn encrypt_secret(secret: &str) -> Result<Option<String>, String> {
    if !secure_storage_available() || secret.is_empty() {
        return Ok(None);
    }
    #[cfg(target_os = "macos")]
    {
        macos_secure_storage::encrypt(secret).map(Some)
    }
    #[cfg(target_os = "windows")]
    {
        windows_secure_storage::encrypt(secret).map(Some)
    }
    #[cfg(not(any(target_os = "windows", target_os = "macos")))]
    {
        Ok(None)
    }
}

fn decrypt_secret(encrypted: &str) -> Result<Option<String>, String> {
    if !secure_storage_available() || encrypted.trim().is_empty() {
        return Ok(None);
    }
    #[cfg(target_os = "macos")]
    {
        macos_secure_storage::decrypt(encrypted).map(Some)
    }
    #[cfg(target_os = "windows")]
    {
        windows_secure_storage::decrypt(encrypted).map(Some)
    }
    #[cfg(not(any(target_os = "windows", target_os = "macos")))]
    {
        Ok(None)
    }
}

fn save_codex_image_tool_credentials_from_request(request: &Value) -> Result<Value, String> {
    let api_key = request
        .get("imageApiKey")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    if api_key.is_empty() {
        let configured = read_json_if_exists(&codex_image_tools_settings_path())?
            .and_then(|saved| {
                saved
                    .get("encryptedApiKey")
                    .and_then(Value::as_str)
                    .map(|value| !value.trim().is_empty())
            })
            .unwrap_or(false);
        return Ok(json!({
          "configured": configured,
          "updated": false,
        }));
    }
    if !secure_storage_available() {
        return Err("当前系统没有可用的安全存储，无法为 Codex 保存 Image2 生图 Key。".to_string());
    }
    let base_url = normalize_base_url(
        request
            .get("imageBaseUrl")
            .and_then(Value::as_str)
            .or_else(|| request.get("baseUrl").and_then(Value::as_str)),
        GAOGE_OPENAI_BASE_URL,
    )?;
    let encrypted_api_key = encrypt_secret(api_key)?.ok_or_else(|| {
        "当前系统没有可用的安全存储，无法为 Codex 保存 Image2 生图 Key。".to_string()
    })?;
    let path = codex_image_tools_settings_path();
    write_json_pretty(
        &path,
        &json!({
          "version": 1,
          "baseUrl": base_url,
          "encryptedApiKey": encrypted_api_key,
          "updatedAt": unix_now(),
        }),
    )?;
    Ok(json!({
      "configured": true,
      "updated": true,
      "settingsPath": path.to_string_lossy(),
    }))
}

fn load_codex_image_tool_credentials() -> Result<CodexImageToolCredentials, String> {
    let started = Instant::now();
    let mut stage = "read_config";
    let result = (|| {
        let path = codex_image_tools_settings_path();
        let bytes = fs::read(&path).map_err(|error| {
            if error.kind() == std::io::ErrorKind::NotFound {
                "Codex 生图工具还没有 Image2 Key，请在 Gaoge Free 中重新执行一次 API 登录。"
                    .to_string()
            } else {
                "读取本地生图密钥配置失败，请检查配置文件是否可读；生图请求尚未发送。"
                    .to_string()
            }
        })?;
        stage = "parse_config";
        let saved: Value = serde_json::from_slice(&bytes).map_err(|_| {
            "读取本地生图密钥配置失败，配置文件格式损坏；生图请求尚未发送。".to_string()
        })?;
        let encrypted_api_key = saved
            .get("encryptedApiKey")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .trim();
        if encrypted_api_key.is_empty() {
            return Err(
                "Codex 生图工具的 Image2 Key 配置无效，请在 Gaoge Free 中重新执行一次 API 登录。"
                    .to_string(),
            );
        }
        stage = "decrypt";
        let api_key = decrypt_secret(encrypted_api_key)
            .map_err(|error| format!("本地生图密钥解密失败，生图请求尚未发送。{error}"))?
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| {
                "无法读取本地 Image2 生图密钥，生图请求尚未发送，请重新执行一次 API 登录。"
                    .to_string()
            })?;
        stage = "validate_endpoint";
        let base_url = normalize_base_url(
            saved.get("baseUrl").and_then(Value::as_str),
            GAOGE_OPENAI_BASE_URL,
        )
        .map_err(|_| {
            "Codex 生图工具的服务地址无效，请在 Gaoge Free 中重新执行一次 API 登录。"
                .to_string()
        })?;
        Ok(CodexImageToolCredentials { api_key, base_url })
    })();
    // MCP runs without the desktop logger. Keep diagnostics on stderr, never on its
    // JSON-RPC stdout, and omit errors/config values that could contain credentials.
    let status = if result.is_ok() { "ok" } else { "failed" };
    let _ = writeln!(
        std::io::stderr().lock(),
        "[gaoge-image] credentials status={status} stage={stage} elapsed_ms={}",
        started.elapsed().as_millis()
    );
    result
}

fn load_aggregate_login_state() -> Result<AggregateLoginState, String> {
    let Some(saved) = read_json_if_exists(&aggregate_login_state_path())? else {
        let mut state = default_aggregate_login_state();
        codex_aggregate_model_recovery::recover_managed_catalogs(&mut state.recovery_models);
        if !state.recovery_models.is_empty() {
            save_aggregate_login_state(&state)?;
        }
        *AGGREGATE_LOGIN_STATE
            .lock()
            .map_err(|_| "聚合登录状态锁失败。".to_string())? = state.clone();
        return Ok(state);
    };
    let mut state = default_aggregate_login_state();
    state.recovery_models = codex_aggregate_model_recovery::deserialize(saved.get("recoveryModels"));
    let original_recovery_models = state.recovery_models.clone();
    codex_aggregate_model_recovery::recover_managed_catalogs(&mut state.recovery_models);
    let saved_version = saved.get("version").and_then(Value::as_u64);
    let saved_origin = normalize_codex_model_selection_origin(
        saved.get("defaultModelOrigin").and_then(Value::as_str),
    );
    let missing_or_invalid_origin = saved_origin.is_empty();
    state.default_model_origin = saved_origin;
    state.enabled = saved
        .get("enabled")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    state.router_port = saved
        .get("routerPort")
        .and_then(Value::as_u64)
        .and_then(|value| u16::try_from(value).ok())
        .unwrap_or(0);
    state.router_token = saved
        .get("encryptedRouterToken")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .and_then(|value| decrypt_secret(value).ok().flatten())
        .or_else(|| {
            saved
                .get("routerToken")
                .and_then(Value::as_str)
                .map(ToString::to_string)
        })
        .unwrap_or_default();
    state.default_model = saved
        .get("defaultModel")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim()
        .to_string();
    state.speed_mode = saved
        .get("speedMode")
        .and_then(Value::as_str)
        .and_then(normalize_aggregate_speed_mode)
        .unwrap_or(AGGREGATE_SPEED_MODE_STANDARD)
        .to_string();
    state.official_account_key = saved
        .get("officialAccountKey")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim()
        .to_string();
    state.updated_at = saved.get("updatedAt").and_then(Value::as_i64).unwrap_or(0);
    let mut decrypted_api_keys: HashMap<String, String> = HashMap::new();
    let mut removed_non_conversation_route = false;
    let mut migrated_route_source = false;
    if let Some(routes) = saved.get("routes").and_then(Value::as_array) {
        for item in routes {
            let provider_id = item
                .get("providerId")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let provider_name = item
                .get("providerName")
                .and_then(Value::as_str)
                .unwrap_or(provider_id)
                .trim();
            let upstream_platform = item
                .get("upstreamPlatform")
                .or_else(|| item.get("platform"))
                .and_then(Value::as_str)
                .unwrap_or(provider_id)
                .trim()
                .to_ascii_lowercase();
            let group_id = item
                .get("groupId")
                .and_then(Value::as_str)
                .unwrap_or("legacy")
                .trim();
            let group_name = item
                .get("groupName")
                .and_then(Value::as_str)
                .unwrap_or("默认分组")
                .trim();
            let group_rate_text = item
                .get("groupRateText")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let public_model = item
                .get("publicModel")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let upstream_model = item
                .get("upstreamModel")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let base_url = item
                .get("baseUrl")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let encrypted_api_key = item
                .get("encryptedApiKey")
                .and_then(Value::as_str)
                .filter(|value| !value.trim().is_empty());
            let api_key = if let Some(encrypted_api_key) = encrypted_api_key {
                if let Some(cached) = decrypted_api_keys.get(encrypted_api_key) {
                    cached.clone()
                } else {
                    let decrypted = decrypt_secret(encrypted_api_key)
                        .ok()
                        .flatten()
                        .unwrap_or_default();
                    decrypted_api_keys.insert(encrypted_api_key.to_string(), decrypted.clone());
                    decrypted
                }
            } else {
                item.get("apiKey")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string()
            };
            if !upstream_model.is_empty() && !is_codex_conversation_model(upstream_model) {
                removed_non_conversation_route = true;
                continue;
            }
            if provider_id.is_empty()
                || group_id.is_empty()
                || public_model.is_empty()
                || upstream_model.is_empty()
                || base_url.is_empty()
                || api_key.is_empty()
            {
                continue;
            }
            let protocol = match item.get("protocol") {
                None => aggregate_protocol::Protocol::Responses,
                Some(Value::String(value)) => match aggregate_protocol::Protocol::parse(value) {
                    Ok(protocol) => protocol,
                    Err(_) => { log::warn!("Ignoring aggregate route with unsupported protocol"); continue; }
                },
                Some(_) => continue,
            };
            let source = aggregate_settings::AggregateSource::from_legacy(
                item.get("source").and_then(Value::as_str), provider_id, group_id,
            );
            migrated_route_source |= item.get("source") != Some(&json!(source));
            state.routes.push(AggregateProviderRoute {
                source,
                protocol,
                model_config: aggregate_settings::validate_model_config(&item["modelConfig"]).unwrap_or_else(|_| json!({})),
                provider_id: provider_id.to_string(),
                provider_name: provider_name.to_string(),
                upstream_platform,
                group_id: group_id.to_string(),
                group_name: group_name.to_string(),
                group_rate_text: group_rate_text.to_string(),
                public_model: public_model.to_string(),
                upstream_model: upstream_model.to_string(),
                base_url: base_url.to_string(),
                api_key,
            });
        }
    }
    if state.default_model_origin.is_empty() {
        state.default_model_origin = if saved_version.unwrap_or(0) < AGGREGATE_LOGIN_STATE_VERSION
            && aggregate_legacy_default_matches_old_automatic_selection(&state)
        {
            CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC
        } else {
            CODEX_MODEL_SELECTION_ORIGIN_USER
        }
        .to_string();
    }
    let normalized_state = normalize_aggregate_conversation_state(&mut state);
    state.recovery_models = codex_aggregate_model_recovery::remembered_models(&state);
    let migrated = saved_version != Some(AGGREGATE_LOGIN_STATE_VERSION)
        || missing_or_invalid_origin
        || removed_non_conversation_route
        || migrated_route_source
        || normalized_state
        || state.recovery_models != original_recovery_models;
    if state.routes.is_empty()
        || state.router_token.is_empty()
        || !state
            .routes
            .iter()
            .any(|route| route.public_model == state.default_model)
    {
        state.enabled = false;
    }
    *AGGREGATE_LOGIN_STATE
        .lock()
        .map_err(|_| "聚合登录状态锁失败。".to_string())? = state.clone();
    if migrated {
        if let Err(error) = save_aggregate_login_state(&state) {
            log::warn!("Failed to persist aggregate model migration: {error}");
        }
    }
    Ok(state)
}

fn save_aggregate_login_state(state: &AggregateLoginState) -> Result<(), String> {
    let mut state = state.clone();
    normalize_aggregate_conversation_state(&mut state);
    state.recovery_models = codex_aggregate_model_recovery::remembered_models(&state);
    let encrypted_router_token = encrypt_secret(&state.router_token).ok().flatten();
    let mut routes = Vec::with_capacity(state.routes.len());
    let mut encrypted_api_keys: HashMap<String, Option<String>> = HashMap::new();
    for route in &state.routes {
        if !encrypted_api_keys.contains_key(&route.api_key) {
            encrypted_api_keys.insert(
                route.api_key.clone(),
                encrypt_secret(&route.api_key).ok().flatten(),
            );
        }
        let encrypted_api_key = encrypted_api_keys.get(&route.api_key).cloned().flatten();
        routes.push(json!({
          "source": route.source,
          "providerId": route.provider_id,
          "providerName": route.provider_name,
          "upstreamPlatform": route.upstream_platform,
          "groupId": route.group_id,
          "groupName": route.group_name,
          "groupRateText": route.group_rate_text,
          "publicModel": route.public_model,
          "upstreamModel": route.upstream_model,
          "protocol": route.protocol,
          "modelConfig": route.model_config,
          "baseUrl": route.base_url,
          "encryptedApiKey": encrypted_api_key.clone().unwrap_or_default(),
          "apiKey": if encrypted_api_key.is_some() { "" } else { route.api_key.as_str() },
        }));
    }
    write_json_pretty_atomic(
        &aggregate_login_state_path(),
        &json!({
          "version": AGGREGATE_LOGIN_STATE_VERSION,
          "enabled": state.enabled,
          "routerPort": state.router_port,
          "encryptedRouterToken": encrypted_router_token.clone().unwrap_or_default(),
          "routerToken": if encrypted_router_token.is_some() { "" } else { state.router_token.as_str() },
          "defaultModel": state.default_model,
          "defaultModelOrigin": state.default_model_origin,
          "speedMode": normalize_aggregate_speed_mode(&state.speed_mode).unwrap_or(AGGREGATE_SPEED_MODE_STANDARD),
          "officialAccountKey": state.official_account_key,
          "routes": routes,
          "recoveryModels": state.recovery_models,
          "updatedAt": state.updated_at,
        }),
    )?;
    *AGGREGATE_LOGIN_STATE
        .lock()
        .map_err(|_| "聚合登录状态锁失败。".to_string())? = state.clone();
    Ok(())
}

fn deactivate_aggregate_login_state() -> Result<(), String> {
    let mut state = AGGREGATE_LOGIN_STATE
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_else(|_| default_aggregate_login_state());
    if !state.enabled && state.routes.is_empty() {
        stop_aggregate_router_runtime();
        return Ok(());
    }
    // Capture exact aliases in the same atomic state write that removes the
    // authenticated routes, before any later native session is reopened.
    state.recovery_models = codex_aggregate_model_recovery::remembered_models(&state);
    state.enabled = false;
    state.default_model.clear();
    state.default_model_origin = CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC.to_string();
    state.speed_mode = AGGREGATE_SPEED_MODE_STANDARD.to_string();
    state.official_account_key.clear();
    state.routes.clear();
    state.router_token.clear();
    state.updated_at = unix_now();
    save_aggregate_login_state(&state)?;
    stop_aggregate_router_runtime();
    bump_codex_runtime_revision();
    start_codex_runtime_watcher();
    Ok(())
}

fn public_aggregate_login_state(state: &AggregateLoginState, running: bool) -> Value {
    let mut state = state.clone();
    normalize_aggregate_conversation_state(&mut state);
    let mut providers: Vec<Value> = Vec::new();
    let mut provider_indexes: HashMap<(aggregate_settings::AggregateSource, String), usize> = HashMap::new();
    let mut group_indexes: HashMap<(aggregate_settings::AggregateSource, String, String), usize> = HashMap::new();
    for route in &state.routes {
        let index = if let Some(index) = provider_indexes.get(&(route.source, route.provider_id.clone())) {
            *index
        } else {
            let index = providers.len();
            provider_indexes.insert((route.source, route.provider_id.clone()), index);
            providers.push(json!({
              "id": route.provider_id,
              "source": route.source,
              "name": route.provider_name,
              "upstreamPlatform": route.upstream_platform,
              "baseUrl": route.base_url,
              "keyConfigured": true,
              "groups": Vec::<Value>::new(),
              "models": Vec::<Value>::new(),
            }));
            index
        };
        let group_key = (route.source, route.provider_id.clone(), route.group_id.clone());
        let group_index = if let Some(group_index) = group_indexes.get(&group_key) {
            *group_index
        } else {
            let Some(groups) = providers[index]
                .get_mut("groups")
                .and_then(Value::as_array_mut)
            else {
                continue;
            };
            let group_index = groups.len();
            groups.push(json!({
              "id": route.group_id,
              "source": route.source,
              "providerId": route.provider_id,
              "name": route.group_name,
              "platform": route.upstream_platform,
              "rateText": route.group_rate_text,
              "keyConfigured": true,
              "models": Vec::<Value>::new(),
            }));
            group_indexes.insert(group_key, group_index);
            group_index
        };
        let model_status = json!({
          "publicModel": route.public_model,
              "source": route.source,
              "providerId": route.provider_id,
              "providerName": route.provider_name,
              "groupId": route.group_id,
              "groupName": route.group_name,
          "upstreamModel": route.upstream_model,
          "platform": route.upstream_platform,
          "protocol": route.protocol,
          "modelConfig": route.model_config,
        });
        if let Some(models) = providers[index]
            .get_mut("models")
            .and_then(Value::as_array_mut)
        {
            models.push(model_status.clone());
        }
        if let Some(models) = providers[index]
            .get_mut("groups")
            .and_then(Value::as_array_mut)
            .and_then(|groups| groups.get_mut(group_index))
            .and_then(|group| group.get_mut("models"))
            .and_then(Value::as_array_mut)
        {
            models.push(model_status);
        }
    }
    let group_count = group_indexes.len();
    json!({
      "enabled": state.enabled,
      "running": running,
      "routerBaseUrl": if state.router_port > 0 { format!("http://127.0.0.1:{}/v1", state.router_port) } else { String::new() },
      "defaultModel": state.default_model,
      "defaultModelOrigin": state.default_model_origin,
      "speedMode": normalize_aggregate_speed_mode(&state.speed_mode).unwrap_or(AGGREGATE_SPEED_MODE_STANDARD),
      "providerCount": providers.len(),
      "groupCount": group_count,
      "modelCount": state.routes.len(),
      "providers": providers,
      "updatedAt": state.updated_at,
    })
}

fn aggregate_model_picker_catalog() -> Value {
    let state = aggregate_login_state_snapshot();
    let metadata = aggregate_local_model_metadata(&codex_route_targets());
    aggregate_model_picker_catalog_for_state(&state, &metadata)
}

fn aggregate_model_picker_catalog_for_state(
    state: &AggregateLoginState,
    metadata: &HashMap<String, Value>,
) -> Value {
    let mut state = state.clone();
    normalize_aggregate_conversation_state(&mut state);
    if !state.enabled || state.routes.is_empty() {
        return json!({
          "enabled": false,
          "defaultModel": "",
          "selectedSpeed": AGGREGATE_SPEED_MODE_STANDARD,
          "providers": Vec::<Value>::new(),
        });
    }

    let mut providers: Vec<Value> = Vec::new();
    let mut provider_indexes: HashMap<(aggregate_settings::AggregateSource, String), usize> = HashMap::new();
    let mut group_indexes: HashMap<(aggregate_settings::AggregateSource, String, String), usize> = HashMap::new();
    for route in state
        .routes
        .iter()
        .filter(|route| is_codex_conversation_model(&route.upstream_model))
    {
        let (vendor_id, vendor_label) = aggregate_route_vendor(route);
        let provider_index = if let Some(index) = provider_indexes.get(&(route.source, route.provider_id.clone())) {
            *index
        } else {
            let index = providers.len();
            provider_indexes.insert((route.source, route.provider_id.clone()), index);
            let provider_label = if route.provider_id.starts_with("external-") { route.provider_name.as_str() } else { aggregate_provider_short_label(&route.provider_id) };
            let logo = match route.provider_id.as_str() {
                "openai" => AGGREGATE_OPENAI_LOGO_DATA_URI,
                "anthropic" | "claude" => AGGREGATE_CLAUDE_LOGO_DATA_URI,
                "grok" | "gork" | "xai" => AGGREGATE_GROK_LOGO_DATA_URI,
                "kimi" | "moonshot" => AGGREGATE_KIMI_LOGO_DATA_URI.as_str(),
                "deepseek" => AGGREGATE_DEEPSEEK_LOGO_DATA_URI.as_str(),
                "glm" | "zhipu" | "bigmodel" | "zai" => AGGREGATE_GLM_LOGO_DATA_URI.as_str(),
                _ => "",
            };
            providers.push(json!({
              "id": route.provider_id,
              "source": route.source,
              "name": route.provider_name,
              "label": provider_label,
              "vendorId": vendor_id,
              "vendorLabel": vendor_label,
              "logo": logo,
              "groups": Vec::<Value>::new(),
            }));
            index
        };
        let group_key = (route.source, route.provider_id.clone(), route.group_id.clone());
        let group_index = if let Some(index) = group_indexes.get(&group_key) {
            *index
        } else {
            let Some(groups) = providers[provider_index]
                .get_mut("groups")
                .and_then(Value::as_array_mut)
            else {
                continue;
            };
            let index = groups.len();
            groups.push(json!({
              "id": route.group_id,
              "source": route.source,
              "providerId": route.provider_id,
              "name": route.group_name,
              "platform": route.upstream_platform,
              "rateText": route.group_rate_text,
              "models": Vec::<Value>::new(),
            }));
            group_indexes.insert(group_key, index);
            index
        };
        // Use the same resolved entry as the native catalog so the label and
        // upload gate cannot disagree about the selected model's capabilities.
        let entry = aggregate_model_entry(route, 0, metadata);
        let reasoning_levels = entry["supported_reasoning_levels"]
            .as_array()
            .map(|levels| {
                levels
                    .iter()
                    .filter_map(|level| level["effort"].as_str())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let speed_profile = aggregate_resolved_speed_profile(route, &entry);
        let speed_options = if aggregate_entry_supports_fast(&entry) {
            vec!["fast"]
        } else {
            Vec::new()
        };
        let known_context = AggregateContextProfile::from_entry(&entry);
        let context_profile = known_context.unwrap_or_else(|| AggregateContextProfile::new(0));
        let native_metadata = metadata.get(&route.public_model)
            .or_else(|| metadata.get(&route.upstream_model))
            .or_else(|| metadata.get(&canonical_model_name(&route.upstream_model)));
        let builtin_metadata = model_capabilities::builtin_model_metadata(&route.upstream_model);
        let fallback = fallback_capabilities(&route.upstream_model);
        let declared_images = |value: &Value| value["input_modalities"].as_array().is_some_and(|items| {
            !items.is_empty() && items.iter().all(|item| matches!(item.as_str(), Some("text" | "image")))
        });
        // A cache hit or a generated upload default does not establish image
        // capability. Report confirmation only from a valid source declaration.
        let image_capability_known = native_metadata.is_some_and(declared_images)
            || builtin_metadata.as_ref().is_some_and(declared_images)
            || (builtin_metadata.is_none() && fallback.verified && fallback.image_input.is_some());
        let native_window = native_metadata.is_some_and(|value| value["context_window"].as_u64().is_some_and(|window| window > 0));
        let builtin_window = builtin_metadata.as_ref().is_some_and(|value| value["context_window"].as_u64().is_some_and(|window| window > 0));
        if let Some(models) = providers[provider_index]
            .get_mut("groups")
            .and_then(Value::as_array_mut)
            .and_then(|groups| groups.get_mut(group_index))
            .and_then(|group| group.get_mut("models"))
            .and_then(Value::as_array_mut)
        {
            models.push(json!({
              "publicModel": route.public_model,
              "source": route.source,
              "providerId": route.provider_id,
              "providerName": route.provider_name,
              "groupId": route.group_id,
              "groupName": route.group_name,
              "upstreamModel": route.upstream_model,
              "nativeLabel": aggregate_route_native_label(route),
              "vendorId": vendor_id,
              "vendorLabel": vendor_label,
              "inputModalities": entry["input_modalities"],
              "supportsImageDetailOriginal": entry["supports_image_detail_original"],
              // Unknown models default to image input for forward
              // compatibility, but remain visibly marked as unverified.
              "imageCapabilityKnown": image_capability_known,
              "reasoningLevels": reasoning_levels,
              "speedOptions": speed_options,
              "speedLabel": speed_profile.map(|profile| profile.picker_label).unwrap_or_default(),
              "contextWindow": known_context.map(|p| p.context_window),
              "maxContextWindow": known_context.map(|p| p.max_context_window),
              "autoCompactTokenLimit": context_profile.auto_compact_token_limit,
              "contextLabel": context_profile.label(),
              "maxContextLabel": context_profile.max_label(),
              "contextSource": if route.model_config["contextWindow"].as_u64().is_some_and(|window| window > 0) { "user" } else if native_window { "codex" } else if builtin_window { "builtin" } else if fallback.verified { "official-fallback" } else { "unverified-fallback" },
              "protocol": route.protocol,
            }));
        }
    }
    json!({
      "enabled": true,
      "defaultModel": state.default_model,
      "selectedSpeed": normalize_aggregate_speed_mode(&state.speed_mode).unwrap_or(AGGREGATE_SPEED_MODE_STANDARD),
      "providers": providers,
    })
}

fn aggregate_login_state_snapshot() -> AggregateLoginState {
    let mut state = AGGREGATE_LOGIN_STATE
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_else(|_| default_aggregate_login_state());
    normalize_aggregate_conversation_state(&mut state);
    state
}

fn ps_quote(value: &Path) -> String {
    value.to_string_lossy().replace('\'', "''")
}

fn command_succeeded(program: &str, args: &[&str]) -> bool {
    let mut command = hidden_command(program);
    command
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    let Ok(mut child) = command.spawn() else {
        return false;
    };
    let deadline = Instant::now() + Duration::from_secs(APP_STOP_COMMAND_TIMEOUT_SECS);
    loop {
        match child.try_wait() {
            Ok(Some(status)) => return status.success(),
            Ok(None) if Instant::now() < deadline => thread::sleep(Duration::from_millis(50)),
            Ok(None) => {
                let _ = child.kill();
                let _ = child.wait();
                return false;
            }
            Err(_) => return false,
        }
    }
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
#[derive(Clone, Debug, PartialEq, Eq)]
struct RunningCodexProcess {
    pid: u32,
    executable_path: PathBuf,
    app_dir: PathBuf,
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
fn persisted_codex_process_app_dir() -> Option<PathBuf> {
    let value = read_json_if_exists(&codex_launch_target_override_path())
        .ok()
        .flatten()?;
    if let Some(app_dir) = value
        .get("appDir")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return Some(PathBuf::from(app_dir));
    }
    let selected_path = value
        .get("selectedPath")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)?;
    normalize_codex_launch_selection(&selected_path)
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
fn configured_codex_process_app_dir() -> Option<PathBuf> {
    load_codex_launch_target_override().map(|(_, app_dir)| app_dir)
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
fn stale_codex_process_app_dir() -> Option<PathBuf> {
    configured_codex_process_app_dir()
        .is_none()
        .then(persisted_codex_process_app_dir)
        .flatten()
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
fn same_codex_process_path(left: &Path, right: &Path) -> bool {
    codex_path_identity(left) == codex_path_identity(right)
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
fn codex_process_priority(process: &RunningCodexProcess, manual_app_dir: Option<&Path>) -> u8 {
    if manual_app_dir.is_some_and(|manual| same_codex_process_path(&process.app_dir, manual)) {
        return 0;
    }
    let executable_name = process
        .executable_path
        .file_name()
        .and_then(OsStr::to_str)
        .unwrap_or_default();
    let app_name = process
        .app_dir
        .file_name()
        .and_then(OsStr::to_str)
        .unwrap_or_default();
    if executable_name.eq_ignore_ascii_case("ChatGPT.exe")
        || executable_name.eq_ignore_ascii_case("ChatGPT")
        || app_name.eq_ignore_ascii_case("ChatGPT.app")
    {
        1
    } else {
        2
    }
}

#[cfg(any(test, target_os = "windows", target_os = "macos"))]
fn sort_and_deduplicate_codex_processes(
    mut processes: Vec<RunningCodexProcess>,
    manual_app_dir: Option<&Path>,
) -> Vec<RunningCodexProcess> {
    processes.sort_by_key(|process| (codex_process_priority(process, manual_app_dir), process.pid));
    let mut seen = HashSet::new();
    processes.retain(|process| seen.insert(process.pid));
    processes
}

#[cfg(any(test, target_os = "macos"))]
fn is_standard_macos_codex_bundle(app_dir: &Path) -> bool {
    app_dir
        .file_name()
        .and_then(OsStr::to_str)
        .is_some_and(|name| {
            name.eq_ignore_ascii_case("ChatGPT.app") || name.eq_ignore_ascii_case("Codex.app")
        })
}

#[cfg(any(test, target_os = "macos"))]
fn macos_codex_bundle_for_process_path(
    executable_path: &Path,
    manual_app_dir: Option<&Path>,
) -> Option<PathBuf> {
    let app_bundles = executable_path
        .ancestors()
        .filter(|ancestor| is_macos_app_bundle(ancestor))
        .collect::<Vec<_>>();
    if let Some(manual) = manual_app_dir {
        if app_bundles
            .iter()
            .any(|candidate| same_codex_process_path(candidate, manual))
        {
            return Some(manual.to_path_buf());
        }
        return None;
    }
    app_bundles
        .into_iter()
        .find(|candidate| is_standard_macos_codex_bundle(candidate))
        .map(Path::to_path_buf)
}

#[cfg(any(test, target_os = "macos"))]
fn parse_macos_running_codex_processes(
    output: &str,
    manual_app_dir: Option<&Path>,
) -> Vec<RunningCodexProcess> {
    let processes = output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            let separator = trimmed.find(char::is_whitespace)?;
            let pid = trimmed[..separator].parse::<u32>().ok()?;
            let executable_path = PathBuf::from(trimmed[separator..].trim());
            let app_dir = macos_codex_bundle_for_process_path(&executable_path, manual_app_dir)?;
            Some(RunningCodexProcess {
                pid,
                executable_path,
                app_dir,
            })
        })
        .collect();
    sort_and_deduplicate_codex_processes(processes, manual_app_dir)
}

#[cfg(any(test, target_os = "macos"))]
fn parse_macos_running_codex_processes_for_scope(
    output: &str,
    manual_app_dir: Option<&Path>,
    stale_manual_app_dir: Option<&Path>,
    additional_app_dir: Option<&Path>,
) -> Vec<RunningCodexProcess> {
    let mut processes = parse_macos_running_codex_processes(output, None);
    for app_dir in [manual_app_dir, stale_manual_app_dir, additional_app_dir]
        .into_iter()
        .flatten()
    {
        processes.extend(parse_macos_running_codex_processes(output, Some(app_dir)));
    }
    sort_and_deduplicate_codex_processes(
        processes,
        manual_app_dir
            .or(stale_manual_app_dir)
            .or(additional_app_dir),
    )
}

#[cfg(any(test, target_os = "macos"))]
fn macos_process_snapshot_has_expected_shape(output: &str) -> bool {
    output.lines().any(|line| {
        let trimmed = line.trim();
        let Some(separator) = trimmed.find(char::is_whitespace) else {
            return false;
        };
        trimmed[..separator].parse::<u32>().is_ok() && trimmed[separator..].trim().starts_with('/')
    })
}

#[cfg(any(test, target_os = "windows"))]
fn windows_codex_app_dir_for_process_path(
    executable_path: &Path,
    manual_app_dir: Option<&Path>,
) -> Option<PathBuf> {
    let executable_name = executable_path.file_name()?.to_str()?;
    let recognized_name = executable_name.eq_ignore_ascii_case("ChatGPT.exe")
        || executable_name.eq_ignore_ascii_case("Codex.exe");
    let parent = executable_path.parent()?;
    let detected_app_dir = if parent
        .file_name()
        .and_then(OsStr::to_str)
        .is_some_and(|name| name.eq_ignore_ascii_case("resources"))
    {
        parent.parent()?.to_path_buf()
    } else {
        parent.to_path_buf()
    };
    if let Some(manual) = manual_app_dir {
        let manual_executable = codex_direct_launch_exe_path(manual);
        if same_codex_process_path(executable_path, &manual_executable)
            || same_codex_process_path(&detected_app_dir, manual)
        {
            return Some(manual.to_path_buf());
        }
        return None;
    }
    recognized_name.then_some(detected_app_dir)
}

#[cfg(any(test, target_os = "windows"))]
fn filter_windows_running_codex_processes(
    processes: impl IntoIterator<Item = (u32, PathBuf)>,
    manual_app_dir: Option<&Path>,
) -> Vec<RunningCodexProcess> {
    let processes = processes
        .into_iter()
        .filter_map(|(pid, executable_path)| {
            let app_dir = windows_codex_app_dir_for_process_path(&executable_path, manual_app_dir)?;
            Some(RunningCodexProcess {
                pid,
                executable_path,
                app_dir,
            })
        })
        .collect();
    sort_and_deduplicate_codex_processes(processes, manual_app_dir)
}

#[cfg(any(test, target_os = "windows"))]
fn filter_windows_running_codex_processes_for_scope(
    processes: Vec<(u32, PathBuf)>,
    manual_app_dir: Option<&Path>,
    stale_manual_app_dir: Option<&Path>,
    additional_app_dir: Option<&Path>,
) -> Vec<RunningCodexProcess> {
    let mut filtered = filter_windows_running_codex_processes(processes.clone(), None);
    for app_dir in [manual_app_dir, stale_manual_app_dir, additional_app_dir]
        .into_iter()
        .flatten()
    {
        filtered.extend(filter_windows_running_codex_processes(
            processes.clone(),
            Some(app_dir),
        ));
    }
    sort_and_deduplicate_codex_processes(
        filtered,
        manual_app_dir
            .or(stale_manual_app_dir)
            .or(additional_app_dir),
    )
}

#[cfg(test)]
fn stop_codex_app_with_additional_target(_additional_app_dir: Option<&Path>) -> bool {
    false
}

#[cfg(all(not(test), target_os = "windows"))]
fn stop_codex_app_with_additional_target(additional_app_dir: Option<&Path>) -> bool {
    let Ok(processes) = probe_running_codex_processes_with_additional_target(additional_app_dir)
    else {
        return false;
    };
    let mut stop_requested = false;
    for process in processes {
        // Do not terminate the process tree here. When Gaoge is launched from
        // Codex during testing, a tree kill can close Gaoge together with Codex.
        if terminate_windows_codex_process(&process) {
            stop_requested = true;
        }
    }
    stop_requested
}

#[cfg(all(not(test), target_os = "windows"))]
fn terminate_windows_codex_process(process: &RunningCodexProcess) -> bool {
    unsafe {
        let handle = OpenProcessSys(
            PROCESS_QUERY_LIMITED_INFORMATION | PROCESS_TERMINATE,
            0,
            process.pid,
        );
        if handle.is_null() {
            return false;
        }
        // The process list may change between the probe and this retry. Verify the
        // executable through the same handle that will be terminated, so PID reuse
        // cannot make us stop an unrelated process.
        let matches = windows_process_executable_path_from_handle(handle)
            .is_some_and(|path| same_codex_process_path(&path, &process.executable_path));
        let terminated = matches && TerminateProcess(handle, 1) != 0;
        let _ = CloseHandleSys(handle);
        terminated
    }
}

#[cfg(all(not(test), target_os = "windows"))]
fn retry_stop_windows_codex_processes(processes: &[RunningCodexProcess]) -> bool {
    processes.iter().fold(false, |stop_requested, process| {
        terminate_windows_codex_process(process) || stop_requested
    })
}

#[cfg(all(not(test), target_os = "macos"))]
fn stop_codex_app_with_additional_target(additional_app_dir: Option<&Path>) -> bool {
    let Ok(initial) = probe_running_codex_processes_with_additional_target(additional_app_dir)
    else {
        return false;
    };
    if initial.is_empty() {
        return false;
    }

    let mut seen_apps = HashSet::new();
    let mut stop_requested = false;
    for process in &initial {
        let app_identity = process.app_dir.to_string_lossy().to_lowercase();
        if !seen_apps.insert(app_identity) {
            continue;
        }
        let application = process
            .app_dir
            .to_string_lossy()
            .replace('\\', "\\\\")
            .replace('"', "\\\"");
        let script = format!("tell application \"{application}\" to quit");
        if command_succeeded("osascript", &["-e", &script]) {
            stop_requested = true;
        }
    }

    thread::sleep(Duration::from_millis(800));
    if let Ok(running) = probe_running_codex_processes_with_additional_target(additional_app_dir) {
        for process in running {
            let pid = process.pid.to_string();
            if command_succeeded("kill", &["-TERM", &pid]) {
                stop_requested = true;
            }
        }
    }
    thread::sleep(Duration::from_millis(400));
    if let Ok(running) = probe_running_codex_processes_with_additional_target(additional_app_dir) {
        for process in running {
            let pid = process.pid.to_string();
            if command_succeeded("kill", &["-KILL", &pid]) {
                stop_requested = true;
            }
        }
    }
    stop_requested
}

#[cfg(all(not(test), not(target_os = "windows"), not(target_os = "macos")))]
fn stop_codex_app_with_additional_target(_additional_app_dir: Option<&Path>) -> bool {
    let mut closed = false;
    for process in ["Codex", "codex"] {
        if command_succeeded("pkill", &["-x", process]) {
            closed = true;
        }
    }
    closed
}

fn stop_codex_app() -> bool {
    stop_codex_app_with_additional_target(None)
}

fn stop_codex_app_with_additional_targets(additional_app_dirs: &[PathBuf]) -> bool {
    if additional_app_dirs.is_empty() {
        return stop_codex_app();
    }
    additional_app_dirs
        .iter()
        .fold(false, |stop_requested, app_dir| {
            stop_codex_app_with_additional_target(Some(app_dir)) || stop_requested
        })
}

#[cfg(test)]
fn wait_for_codex_app_exit_with_additional_target(
    _timeout: Duration,
    _additional_app_dir: Option<&Path>,
) -> Result<(), String> {
    Ok(())
}

fn observe_codex_exit_probe(
    consecutive_stopped_checks: &mut u8,
    probe: Result<bool, String>,
) -> Result<bool, String> {
    if probe? {
        *consecutive_stopped_checks = consecutive_stopped_checks.saturating_add(1);
        Ok(*consecutive_stopped_checks >= 2)
    } else {
        *consecutive_stopped_checks = 0;
        Ok(false)
    }
}

#[cfg(any(test, target_os = "windows"))]
fn format_codex_exit_timeout_error(running: &[RunningCodexProcess]) -> String {
    if running.is_empty() {
        return "Codex 未能完全关闭，请结束 Codex 进程后重试。".to_string();
    }
    let remaining = running
        .iter()
        .take(8)
        .map(|process| {
            format!(
                "PID {} ({})",
                process.pid,
                process.executable_path.display()
            )
        })
        .collect::<Vec<_>>()
        .join("；");
    let omitted = running.len().saturating_sub(8);
    let suffix = if omitted == 0 {
        String::new()
    } else {
        format!("；另有 {omitted} 个进程")
    };
    format!("Codex 未能完全关闭，请结束 Codex 进程后重试。最后检测到：{remaining}{suffix}。")
}

#[cfg(any(test, target_os = "windows"))]
fn wait_for_codex_process_exit_with_probe<P, R>(
    timeout: Duration,
    poll_interval: Duration,
    mut probe: P,
    mut retry_stop: R,
) -> Result<(), String>
where
    P: FnMut() -> Result<Vec<RunningCodexProcess>, String>,
    R: FnMut(&[RunningCodexProcess]),
{
    let deadline = Instant::now() + timeout;
    let mut consecutive_stopped_checks = 0u8;
    let mut last_running = Vec::new();
    loop {
        let running = probe()
            .map_err(|error| format!("无法确认 Codex/ChatGPT 已完全关闭，未修改配置：{error}"))?;
        let stopped = running.is_empty();
        if stopped {
            if observe_codex_exit_probe(&mut consecutive_stopped_checks, Ok(true))? {
                return Ok(());
            }
        } else {
            last_running = running.clone();
            let _ = observe_codex_exit_probe(&mut consecutive_stopped_checks, Ok(false))?;
            retry_stop(&running);
        }
        if Instant::now() >= deadline {
            return Err(format_codex_exit_timeout_error(&last_running));
        }
        thread::sleep(poll_interval);
    }
}

#[cfg(all(not(test), target_os = "windows"))]
fn wait_for_codex_app_exit_with_additional_target(
    timeout: Duration,
    additional_app_dir: Option<&Path>,
) -> Result<(), String> {
    wait_for_codex_process_exit_with_probe(
        timeout,
        Duration::from_millis(300),
        || probe_running_codex_processes_with_additional_target(additional_app_dir),
        |running| {
            let _ = retry_stop_windows_codex_processes(running);
        },
    )
}

#[cfg(all(not(test), not(target_os = "windows")))]
fn wait_for_codex_app_exit_with_additional_target(
    timeout: Duration,
    additional_app_dir: Option<&Path>,
) -> Result<(), String> {
    let deadline = Instant::now() + timeout;
    let mut consecutive_stopped_checks = 0u8;
    loop {
        let stopped = probe_running_codex_app_dirs_with_additional_target(additional_app_dir)
            .map(|running| running.is_empty());
        if observe_codex_exit_probe(&mut consecutive_stopped_checks, stopped)
            .map_err(|error| format!("无法确认 Codex/ChatGPT 已完全关闭，未修改配置：{error}"))?
        {
            return Ok(());
        }
        if Instant::now() >= deadline {
            return Err("Codex 未能完全关闭，请结束 Codex 进程后重试。".to_string());
        }
        thread::sleep(Duration::from_millis(300));
    }
}

fn wait_for_codex_app_exit(timeout: Duration) -> Result<(), String> {
    wait_for_codex_app_exit_with_additional_target(timeout, None)
}

#[cfg(test)]
fn wait_for_codex_app_exit_with_additional_targets(
    _timeout: Duration,
    _additional_app_dirs: &[PathBuf],
) -> Result<(), String> {
    Ok(())
}

#[cfg(all(not(test), target_os = "windows"))]
fn wait_for_codex_app_exit_with_additional_targets(
    timeout: Duration,
    additional_app_dirs: &[PathBuf],
) -> Result<(), String> {
    wait_for_codex_process_exit_with_probe(
        timeout,
        Duration::from_millis(300),
        || {
            if additional_app_dirs.is_empty() {
                return probe_running_codex_processes_with_additional_target(None);
            }
            let mut running = Vec::new();
            let mut seen = HashSet::new();
            for app_dir in additional_app_dirs {
                running.extend(
                    probe_running_codex_processes_with_additional_target(Some(app_dir))?
                        .into_iter()
                        .filter(|process| seen.insert(process.pid)),
                );
            }
            Ok(running)
        },
        |running| {
            let _ = retry_stop_windows_codex_processes(running);
        },
    )
}

#[cfg(all(not(test), not(target_os = "windows")))]
fn wait_for_codex_app_exit_with_additional_targets(
    timeout: Duration,
    additional_app_dirs: &[PathBuf],
) -> Result<(), String> {
    if additional_app_dirs.is_empty() {
        return wait_for_codex_app_exit(timeout);
    }
    let deadline = Instant::now() + timeout;
    let mut consecutive_stopped_checks = 0u8;
    loop {
        let stopped = additional_app_dirs
            .iter()
            .try_fold(true, |all_stopped, app_dir| {
                probe_running_codex_app_dirs_with_additional_target(Some(app_dir))
                    .map(|running| all_stopped && running.is_empty())
            });
        if observe_codex_exit_probe(&mut consecutive_stopped_checks, stopped)
            .map_err(|error| format!("无法确认 Codex/ChatGPT 已完全关闭，未修改配置：{error}"))?
        {
            return Ok(());
        }
        if Instant::now() >= deadline {
            return Err("Codex 未能完全关闭，请结束 Codex 进程后重试。".to_string());
        }
        thread::sleep(Duration::from_millis(300));
    }
}

fn require_codex_exit_before_config_write<S, W>(stop: S, wait: W) -> Result<bool, String>
where
    S: FnOnce() -> bool,
    W: FnOnce() -> Result<(), String>,
{
    let _ = stop();
    wait().map_err(|error| format!("Codex 未能完全关闭，未修改账号、路由或会话数据：{error}"))?;
    // A successful process check is the authoritative signal. taskkill/pkill
    // legitimately returns false when Codex was already stopped.
    Ok(true)
}

fn stop_codex_app_and_confirm_exit_before_config_write() -> Result<bool, String> {
    codex_api_project_bridge::request_graceful_native_exit();
    let closed = require_codex_exit_before_config_write(stop_codex_app, || {
        wait_for_codex_app_exit(Duration::from_secs(CODEX_APP_EXIT_WAIT_SECS))
    })?;
    codex_api_project_bridge::finalize_after_native_exit()?;
    Ok(closed)
}

#[cfg(test)]
fn wait_for_codex_app_ready(_app_dir: &Path, _timeout: Duration) -> Result<(), String> {
    Ok(())
}

#[cfg(not(test))]
fn wait_for_codex_app_ready(app_dir: &Path, timeout: Duration) -> Result<(), String> {
    let deadline = Instant::now() + timeout;
    let mut first_running_at = None;
    loop {
        let running = list_running_codex_app_dirs()
            .iter()
            .any(|path| same_windows_path(path, app_dir));
        if running {
            let first_seen = first_running_at.get_or_insert_with(Instant::now);
            if first_seen.elapsed() >= Duration::from_millis(CODEX_APP_READY_SETTLE_MS) {
                return Ok(());
            }
        } else {
            first_running_at = None;
        }
        if Instant::now() >= deadline {
            return Err(format!(
                "Codex 启动命令已发送，但应用未能在 {} 秒内完成打开，请检查系统配置中的启动路径。",
                timeout.as_secs()
            ));
        }
        thread::sleep(Duration::from_millis(400));
    }
}

fn codex_app_is_running(app_dir: &Path) -> bool {
    list_running_codex_app_dirs()
        .iter()
        .any(|path| same_windows_path(path, app_dir))
}

fn confirm_codex_launch_with_probe<P, W>(
    attempts: usize,
    poll_interval: Duration,
    mut probe: P,
    mut wait: W,
) -> bool
where
    P: FnMut() -> bool,
    W: FnMut(Duration),
{
    for attempt in 0..=attempts {
        if probe() {
            return true;
        }
        if attempt < attempts {
            wait(poll_interval);
        }
    }
    false
}

fn confirm_codex_launch_lightweight(app_dir: &Path) -> bool {
    confirm_codex_launch_with_probe(
        CODEX_BACKGROUND_LAUNCH_CONFIRM_ATTEMPTS,
        Duration::from_millis(CODEX_BACKGROUND_LAUNCH_CONFIRM_POLL_MS),
        || codex_app_is_running(app_dir),
        thread::sleep,
    )
}

#[cfg(target_os = "windows")]
fn stop_claude_app() -> bool {
    let mut closed = false;
    for image in ["Claude.exe", "claude.exe", "claude-code.exe"] {
        if command_succeeded("taskkill", &["/IM", image, "/T", "/F"]) {
            closed = true;
        }
    }

    let script = r#"
$patterns = @(
  '@anthropic-ai[\\/]+claude-code',
  '[\\/]node_modules[\\/]@anthropic-ai[\\/]claude-code[\\/]',
  '[\\/]claude-code[\\/]',
  '[\\/]claude(?:\.js)?(?:\s|$)'
)
$stopped = 0
Get-CimInstance Win32_Process |
  Where-Object {
    $commandLine = $_.CommandLine
    ($_.Name -ieq 'node.exe' -or $_.Name -ieq 'bun.exe' -or $_.Name -ieq 'deno.exe') -and
    $commandLine -and
    ($patterns | Where-Object { $commandLine -match $_ } | Select-Object -First 1)
  } |
  ForEach-Object {
    Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
    $stopped += 1
  }
if ($stopped -gt 0) { exit 0 } else { exit 1 }
"#;
    if command_succeeded(
        "powershell",
        &[
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-Command",
            script,
        ],
    ) {
        closed = true;
    }
    closed
}

