#[cfg(target_os = "windows")]
fn windows_process_executable_path_from_handle(process: HANDLE) -> Option<PathBuf> {
    unsafe {
        let mut buffer = vec![0u16; 32_768];
        let mut length = buffer.len() as u32;
        let succeeded =
            QueryFullProcessImageNameW(process, 0, buffer.as_mut_ptr(), &mut length) != 0;
        succeeded.then(|| PathBuf::from(String::from_utf16_lossy(&buffer[..length as usize])))
    }
}

#[cfg(target_os = "windows")]
fn windows_process_executable_path(process_id: u32) -> Option<PathBuf> {
    unsafe {
        let process = OpenProcessSys(PROCESS_QUERY_LIMITED_INFORMATION, 0, process_id);
        if process.is_null() {
            return None;
        }
        let path = windows_process_executable_path_from_handle(process);
        let _ = CloseHandleSys(process);
        path
    }
}

#[cfg(target_os = "windows")]
fn probe_running_codex_processes_with_additional_target(
    additional_app_dir: Option<&Path>,
) -> Result<Vec<RunningCodexProcess>, String> {
    let manual_app_dir = configured_codex_process_app_dir();
    let stale_manual_app_dir = stale_codex_process_app_dir();
    let process_target_app_dir = manual_app_dir
        .as_deref()
        .or(stale_manual_app_dir.as_deref());
    let manual_executable_name = process_target_app_dir
        .map(codex_direct_launch_exe_path)
        .and_then(|path| path.file_name().map(OsStr::to_os_string))
        .and_then(|name| name.to_str().map(str::to_ascii_lowercase));
    let additional_executable_name = additional_app_dir
        .map(codex_direct_launch_exe_path)
        .and_then(|path| path.file_name().map(OsStr::to_os_string))
        .and_then(|name| name.to_str().map(str::to_ascii_lowercase));
    let mut resolved = Vec::new();
    let mut unresolved = Vec::new();
    let mut unresolved_manual_target = None;
    let mut seen = HashSet::new();
    unsafe {
        let snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if snapshot == INVALID_HANDLE_VALUE {
            return Err("无法枚举 Windows Codex/ChatGPT 进程。".to_string());
        }
        let mut entry = PROCESSENTRY32W::default();
        entry.dwSize = std::mem::size_of::<PROCESSENTRY32W>() as u32;
        if Process32FirstW(snapshot, &mut entry) == 0 {
            let error = GetLastError();
            let _ = CloseHandleSys(snapshot);
            return Err(format!(
                "无法读取 Windows Codex/ChatGPT 进程列表（错误 {error}）。"
            ));
        }
        loop {
            let name_length = entry
                .szExeFile
                .iter()
                .position(|character| *character == 0)
                .unwrap_or(entry.szExeFile.len());
            let process_name =
                String::from_utf16_lossy(&entry.szExeFile[..name_length]).to_ascii_lowercase();
            let recognized_name = matches!(process_name.as_str(), "codex.exe" | "chatgpt.exe");
            let manual_name = manual_executable_name
                .as_deref()
                .is_some_and(|name| name == process_name);
            let additional_name = additional_executable_name
                .as_deref()
                .is_some_and(|name| name == process_name);
            if recognized_name || manual_name || additional_name {
                if let Some(path) = windows_process_executable_path(entry.th32ProcessID) {
                    resolved.push((entry.th32ProcessID, path));
                } else if (manual_app_dir.is_some() && recognized_name) || additional_name {
                    unresolved_manual_target = Some(format!(
                        "无法确认手动路径对应的 Windows 进程 {}（PID {}）。",
                        process_name, entry.th32ProcessID
                    ));
                } else if manual_app_dir.is_none() && recognized_name {
                    unresolved.push(RunningCodexProcess {
                        pid: entry.th32ProcessID,
                        executable_path: PathBuf::from(&process_name),
                        app_dir: PathBuf::from(&process_name),
                    });
                }
            }
            if Process32NextW(snapshot, &mut entry) == 0 {
                let error = GetLastError();
                let _ = CloseHandleSys(snapshot);
                if error != ERROR_NO_MORE_FILES {
                    return Err(format!(
                        "Windows Codex/ChatGPT 进程枚举中断（错误 {error}）。"
                    ));
                }
                break;
            }
        }
    }
    if let Some(error) = unresolved_manual_target {
        return Err(error);
    }
    let mut processes = filter_windows_running_codex_processes_for_scope(
        resolved,
        manual_app_dir.as_deref(),
        stale_manual_app_dir.as_deref(),
        additional_app_dir,
    );
    processes.extend(unresolved);
    processes.retain(|process| seen.insert(process.pid));
    Ok(sort_and_deduplicate_codex_processes(
        processes,
        process_target_app_dir.or(additional_app_dir),
    ))
}

#[cfg(target_os = "macos")]
fn probe_running_codex_processes_with_additional_target(
    additional_app_dir: Option<&Path>,
) -> Result<Vec<RunningCodexProcess>, String> {
    let output = hidden_command("ps")
        .args(["-axo", "pid=,comm="])
        .output()
        .map_err(|error| format!("无法读取 macOS Codex/ChatGPT 进程：{error}"))?;
    if !output.status.success() {
        return Err(format!(
            "macOS Codex/ChatGPT 进程扫描失败（状态 {}）。",
            output.status
        ));
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    if !macos_process_snapshot_has_expected_shape(&stdout) {
        return Err("macOS Codex/ChatGPT 进程扫描未返回可验证的完整路径。".to_string());
    }
    let manual_app_dir = configured_codex_process_app_dir();
    let stale_manual_app_dir = stale_codex_process_app_dir();
    Ok(parse_macos_running_codex_processes_for_scope(
        &stdout,
        manual_app_dir.as_deref(),
        stale_manual_app_dir.as_deref(),
        additional_app_dir,
    ))
}

#[cfg(any(target_os = "windows", target_os = "macos"))]
fn probe_running_codex_app_dirs_with_additional_target(
    additional_app_dir: Option<&Path>,
) -> Result<Vec<PathBuf>, String> {
    let mut seen = HashSet::new();
    Ok(
        probe_running_codex_processes_with_additional_target(additional_app_dir)?
            .into_iter()
            .map(|process| process.app_dir)
            .filter(|path| seen.insert(path.to_string_lossy().to_lowercase()))
            .collect(),
    )
}

#[cfg(any(target_os = "windows", target_os = "macos"))]
fn probe_running_codex_app_dirs() -> Result<Vec<PathBuf>, String> {
    probe_running_codex_app_dirs_with_additional_target(None)
}

#[cfg(target_os = "linux")]
fn probe_running_codex_app_dirs() -> Result<Vec<PathBuf>, String> {
    let mut seen = HashSet::new();
    let entries =
        fs::read_dir("/proc").map_err(|error| format!("无法读取 Linux Codex 进程：{error}"))?;
    Ok(entries
        .flatten()
        .filter(|entry| {
            entry
                .file_name()
                .to_string_lossy()
                .chars()
                .all(|character| character.is_ascii_digit())
        })
        .filter_map(|entry| fs::read_link(entry.path().join("exe")).ok())
        .filter(|path| {
            path.file_name()
                .and_then(OsStr::to_str)
                .is_some_and(|name| {
                    matches!(name.to_ascii_lowercase().as_str(), "codex" | "chatgpt")
                })
        })
        .filter_map(|path| path.parent().map(Path::to_path_buf))
        .filter(|path| seen.insert(path.to_string_lossy().to_lowercase()))
        .collect())
}

#[cfg(not(any(target_os = "windows", target_os = "macos")))]
fn probe_running_codex_app_dirs_with_additional_target(
    _additional_app_dir: Option<&Path>,
) -> Result<Vec<PathBuf>, String> {
    probe_running_codex_app_dirs()
}

#[cfg(not(any(target_os = "windows", target_os = "macos", target_os = "linux")))]
fn probe_running_codex_app_dirs() -> Result<Vec<PathBuf>, String> {
    Ok(Vec::new())
}

fn list_running_codex_app_dirs() -> Vec<PathBuf> {
    probe_running_codex_app_dirs().unwrap_or_default()
}

fn is_macos_app_bundle(app_dir: &Path) -> bool {
    app_dir
        .extension()
        .and_then(OsStr::to_str)
        .is_some_and(|extension| extension.eq_ignore_ascii_case("app"))
}

fn codex_resources_dir(app_dir: &Path) -> PathBuf {
    if is_macos_app_bundle(app_dir) {
        app_dir.join("Contents").join("Resources")
    } else if app_dir
        .file_name()
        .and_then(|v| v.to_str())
        .unwrap_or("")
        .eq_ignore_ascii_case("resources")
    {
        app_dir.to_path_buf()
    } else {
        app_dir.join("resources")
    }
}

fn macos_bundle_executable_name(app_dir: &Path) -> Option<String> {
    let plist = fs::read_to_string(app_dir.join("Contents").join("Info.plist")).ok()?;
    let key_index = plist.find("<key>CFBundleExecutable</key>")?;
    let value = &plist[key_index + "<key>CFBundleExecutable</key>".len()..];
    let start = value.find("<string>")? + "<string>".len();
    let end = value[start..].find("</string>")? + start;
    let name = value[start..end].trim();
    if name.is_empty() || name.contains(['/', '\\']) {
        None
    } else {
        Some(name.to_string())
    }
}

fn codex_exe_path(app_dir: &Path) -> PathBuf {
    if is_macos_app_bundle(app_dir) {
        let executable_dir = app_dir.join("Contents").join("MacOS");
        if let Some(name) = macos_bundle_executable_name(app_dir) {
            let configured = executable_dir.join(name);
            if configured.exists() {
                return configured;
            }
        }
        for name in ["Codex", "ChatGPT"] {
            let candidate = executable_dir.join(name);
            if candidate.exists() {
                return candidate;
            }
        }
        return executable_dir.join("Codex");
    }
    if app_dir
        .file_name()
        .and_then(|v| v.to_str())
        .unwrap_or("")
        .eq_ignore_ascii_case("resources")
    {
        app_dir.parent().unwrap_or(app_dir).join("Codex.exe")
    } else {
        app_dir.join("Codex.exe")
    }
}

fn codex_direct_launch_exe_path(app_dir: &Path) -> PathBuf {
    if is_macos_app_bundle(app_dir) {
        return codex_exe_path(app_dir);
    }
    let root = if app_dir
        .file_name()
        .and_then(|value| value.to_str())
        .is_some_and(|name| name.eq_ignore_ascii_case("resources"))
    {
        app_dir.parent().unwrap_or(app_dir)
    } else {
        app_dir
    };
    let chatgpt = root.join("ChatGPT.exe");
    if chatgpt.exists() {
        chatgpt
    } else {
        codex_exe_path(app_dir)
    }
}

fn has_codex_asar(app_dir: &Path) -> bool {
    let resources = codex_resources_dir(app_dir);
    resources.join("app.asar").exists() || resources.join("app.asar1").exists()
}

fn is_complete_codex_app_dir(app_dir: &Path) -> bool {
    codex_direct_launch_exe_path(app_dir).exists()
        && codex_resources_dir(app_dir).exists()
        && has_codex_asar(app_dir)
}

#[allow(dead_code)]
fn is_windows_apps_codex_dir(app_dir: &Path) -> bool {
    let lower = app_dir.to_string_lossy().to_lowercase();
    lower.contains("\\windowsapps\\") || lower.contains("/windowsapps/")
}

fn windows_packaged_codex_aumid(app_dir: &Path) -> Option<String> {
    let package_dir = if app_dir
        .file_name()
        .and_then(OsStr::to_str)
        .is_some_and(|name| name.eq_ignore_ascii_case("app"))
    {
        app_dir.parent()?
    } else {
        app_dir
    };
    let package_name = package_dir.file_name()?.to_str()?;
    let (identity_and_version, publisher_id) = package_name.rsplit_once("__")?;
    let identity = identity_and_version.split('_').next()?;
    if !matches!(identity, "OpenAI.Codex" | "OpenAI.CodexBeta") || publisher_id.is_empty() {
        return None;
    }
    Some(format!("{identity}_{publisher_id}!App"))
}

fn codex_cdp_arguments(debug_port: u16) -> Vec<String> {
    vec![
        format!("--remote-debugging-port={debug_port}"),
        format!("--remote-allow-origins=http://127.0.0.1:{debug_port}"),
        "--no-first-run".to_string(),
    ]
}

fn select_available_codex_cdp_port() -> Result<u16, String> {
    if let Ok(listener) = TcpListener::bind(("127.0.0.1", CODEX_PLUGIN_CDP_DEBUG_PORT)) {
        drop(listener);
        return Ok(CODEX_PLUGIN_CDP_DEBUG_PORT);
    }
    let listener = TcpListener::bind(("127.0.0.1", 0))
        .map_err(|error| format!("无法分配 Codex 本机调试端口：{error}"))?;
    let port = listener
        .local_addr()
        .map_err(|error| format!("无法读取 Codex 本机调试端口：{error}"))?
        .port();
    drop(listener);
    Ok(port)
}

#[cfg(target_os = "windows")]
fn activate_windows_packaged_codex(app_dir: &Path, arguments: &[String]) -> Result<u32, String> {
    use windows::core::HSTRING;
    use windows::Win32::System::Com::{
        CoCreateInstance, CoInitializeEx, CoUninitialize, CLSCTX_LOCAL_SERVER,
        COINIT_APARTMENTTHREADED,
    };
    use windows::Win32::UI::Shell::{
        ApplicationActivationManager, IApplicationActivationManager, ACTIVATEOPTIONS,
    };

    let aumid = windows_packaged_codex_aumid(app_dir)
        .ok_or_else(|| format!("无法识别 Codex 商店应用标识：{}", app_dir.display()))?;
    let command_line = arguments.join(" ");
    unsafe {
        let initialized = CoInitializeEx(None, COINIT_APARTMENTTHREADED).ok();
        let should_uninitialize = initialized.is_ok();
        if let Err(error) = initialized {
            const RPC_E_CHANGED_MODE: i32 = -2147417850;
            if error.code().0 != RPC_E_CHANGED_MODE {
                return Err(format!("初始化 Windows 应用启动服务失败：{error}"));
            }
        }
        let result = (|| -> windows::core::Result<u32> {
            let manager: IApplicationActivationManager =
                CoCreateInstance(&ApplicationActivationManager, None, CLSCTX_LOCAL_SERVER)?;
            manager.ActivateApplication(
                &HSTRING::from(aumid),
                &HSTRING::from(command_line),
                ACTIVATEOPTIONS(0),
            )
        })();
        if should_uninitialize {
            CoUninitialize();
        }
        result.map_err(|error| format!("启动微软商店版 Codex 失败：{error}"))
    }
}

fn windows_apps_codex_version(app_dir: &Path) -> Vec<u32> {
    let Some(name) = app_dir
        .parent()
        .and_then(Path::file_name)
        .and_then(|value| value.to_str())
    else {
        return Vec::new();
    };
    let Some(version) = name
        .strip_prefix("OpenAI.Codex_")
        .and_then(|rest| rest.split('_').next())
    else {
        return Vec::new();
    };
    version
        .split('.')
        .map(|part| part.parse::<u32>().unwrap_or(0))
        .collect()
}

fn codex_app_version_string(app_dir: &Path) -> String {
    let mut parts = windows_apps_codex_version(app_dir);
    if parts.is_empty() {
        parts = read_json_if_exists(&codex_model_picker_source_marker(app_dir))
            .ok()
            .flatten()
            .and_then(|value| {
                value
                    .get("sourceAppDir")
                    .and_then(Value::as_str)
                    .map(PathBuf::from)
            })
            .map(|source| windows_apps_codex_version(&source))
            .unwrap_or_default();
    }
    parts
        .into_iter()
        .map(|part| part.to_string())
        .collect::<Vec<_>>()
        .join(".")
}

fn compare_version_parts_desc(left: &[u32], right: &[u32]) -> std::cmp::Ordering {
    let length = left.len().max(right.len());
    for index in 0..length {
        let left = left.get(index).copied().unwrap_or(0);
        let right = right.get(index).copied().unwrap_or(0);
        match right.cmp(&left) {
            std::cmp::Ordering::Equal => continue,
            ordering => return ordering,
        }
    }
    std::cmp::Ordering::Equal
}

fn registered_windows_appx_codex_dir() -> Option<PathBuf> {
    if !cfg!(target_os = "windows") {
        return None;
    }
    let script = r#"
$pkg = Get-AppxPackage -Name OpenAI.Codex -ErrorAction SilentlyContinue | Select-Object -First 1
if ($pkg -and $pkg.InstallLocation) {
  Join-Path $pkg.InstallLocation 'app'
}
"#;
    run_powershell(script)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

fn list_windows_apps_codex_dirs() -> Vec<PathBuf> {
    let root = PathBuf::from(
        std::env::var_os("ProgramFiles").unwrap_or_else(|| "C:\\Program Files".into()),
    )
    .join("WindowsApps");
    let mut dirs = Vec::new();
    if let Ok(entries) = fs::read_dir(root) {
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().to_string();
            if name.starts_with("OpenAI.Codex_") && name.ends_with("__2p2nqsd0c76g0") {
                push_unique_path(&mut dirs, entry.path().join("app"));
            }
        }
    }
    if dirs.is_empty() {
        if let Some(app_dir) = registered_windows_appx_codex_dir() {
            push_unique_path(&mut dirs, app_dir);
        }
    }
    dirs.sort_by(|left, right| {
        compare_version_parts_desc(
            &windows_apps_codex_version(left),
            &windows_apps_codex_version(right),
        )
        .then_with(|| right.to_string_lossy().cmp(&left.to_string_lossy()))
    });
    dirs
}

fn read_windows_shortcut_target(shortcut: &Path) -> Option<PathBuf> {
    if !cfg!(target_os = "windows") || !shortcut.exists() {
        return None;
    }
    let script = format!(
        "$s=(New-Object -ComObject WScript.Shell).CreateShortcut('{}');$s.TargetPath",
        ps_quote(shortcut)
    );
    run_powershell(&script)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

fn codex_app_dir_from_exe_path(path: PathBuf) -> Option<PathBuf> {
    let file_name = path.file_name()?.to_str()?;
    if !file_name.eq_ignore_ascii_case("Codex.exe")
        && !file_name.eq_ignore_ascii_case("ChatGPT.exe")
    {
        return None;
    }
    path.parent().map(Path::to_path_buf)
}

fn codex_launch_path_priority(path: &Path) -> u8 {
    let name = path.file_name().and_then(OsStr::to_str).unwrap_or_default();
    if name.eq_ignore_ascii_case("ChatGPT.exe") || name.eq_ignore_ascii_case("ChatGPT.app") {
        0
    } else if name.eq_ignore_ascii_case("Codex.exe") || name.eq_ignore_ascii_case("Codex.app") {
        1
    } else {
        2
    }
}

fn codex_app_dir_launch_priority(app_dir: &Path) -> u8 {
    let app_name = app_dir
        .file_name()
        .and_then(OsStr::to_str)
        .unwrap_or_default();
    if app_name.eq_ignore_ascii_case("ChatGPT") || app_name.eq_ignore_ascii_case("ChatGPT.app") {
        return 0;
    }
    codex_launch_path_priority(&codex_direct_launch_exe_path(app_dir))
}

fn list_shortcut_codex_app_dirs() -> Vec<PathBuf> {
    let mut targets = codex_shortcut_paths()
        .iter()
        .filter_map(|shortcut| read_windows_shortcut_target(shortcut))
        .collect::<Vec<_>>();
    targets.sort_by_key(|path| codex_launch_path_priority(path));
    targets
        .into_iter()
        .filter_map(codex_app_dir_from_exe_path)
        .collect()
}

#[allow(dead_code)]
fn choose_patchable_codex_app_dir(preferred: Vec<PathBuf>) -> Option<PathBuf> {
    let mut candidates = preferred;
    candidates.extend(list_shortcut_codex_app_dirs());
    if cfg!(target_os = "macos") {
        candidates.push(PathBuf::from("/Applications/ChatGPT.app"));
        candidates.push(home_dir().join("Applications").join("ChatGPT.app"));
    }
    candidates.push(local_app_data_dir().join("Programs").join("ChatGPT"));
    candidates.push(portable_codex_dir());
    candidates.push(local_app_data_dir().join("Programs").join("Codex"));
    if cfg!(target_os = "macos") {
        candidates.push(PathBuf::from("/Applications/Codex.app"));
        candidates.push(home_dir().join("Applications").join("Codex.app"));
    }

    candidates.sort_by_key(|path| {
        (
            if is_windows_apps_codex_dir(path) {
                0
            } else {
                1
            },
            codex_app_dir_launch_priority(path),
        )
    });

    let mut seen = HashSet::new();
    candidates
        .into_iter()
        .filter(|path| seen.insert(path.to_string_lossy().to_lowercase()))
        .find(|path| !is_windows_apps_codex_dir(path) && is_complete_codex_app_dir(path))
}

fn preferred_running_codex_app_dir(preferred: &[PathBuf]) -> Option<PathBuf> {
    let mut seen = HashSet::new();
    preferred
        .iter()
        .filter(|path| seen.insert(path.to_string_lossy().to_lowercase()))
        .find(|path| is_complete_codex_app_dir(path))
        .cloned()
}

fn choose_auto_launchable_codex_app_dir(preferred: Vec<PathBuf>) -> Option<PathBuf> {
    // `preferred` is captured before Codex is closed. Relaunch that exact app
    // first so Store and portable installations cannot silently swap profiles.
    if let Some(app_dir) = preferred_running_codex_app_dir(&preferred) {
        return Some(app_dir);
    }

    let mut candidates = Vec::new();
    if cfg!(target_os = "windows") {
        candidates.extend(list_windows_apps_codex_dirs());
    }
    candidates.extend(list_shortcut_codex_app_dirs());
    if cfg!(target_os = "macos") {
        candidates.push(PathBuf::from("/Applications/ChatGPT.app"));
        candidates.push(home_dir().join("Applications").join("ChatGPT.app"));
    }
    candidates.push(local_app_data_dir().join("Programs").join("ChatGPT"));
    candidates.push(local_app_data_dir().join("Programs").join("Codex"));
    candidates.push(portable_codex_dir());
    if cfg!(target_os = "macos") {
        candidates.push(PathBuf::from("/Applications/Codex.app"));
        candidates.push(home_dir().join("Applications").join("Codex.app"));
    }

    candidates.sort_by_key(|path| {
        (
            if is_windows_apps_codex_dir(path) {
                0
            } else {
                1
            },
            codex_app_dir_launch_priority(path),
        )
    });

    let mut seen = HashSet::new();
    candidates
        .into_iter()
        .filter(|path| seen.insert(path.to_string_lossy().to_lowercase()))
        .find(|path| is_complete_codex_app_dir(path))
}

fn choose_launchable_codex_app_dir(preferred: Vec<PathBuf>) -> Option<PathBuf> {
    load_codex_launch_target_override()
        .map(|(_, app_dir)| app_dir)
        .or_else(|| choose_auto_launchable_codex_app_dir(preferred))
}

fn choose_runtime_enhancement_codex_app_dir(preferred: Vec<PathBuf>) -> Option<PathBuf> {
    if let Some((_, app_dir)) = load_codex_launch_target_override() {
        return Some(app_dir);
    }

    // Keep runtime enhancements on the same official-first discovery path as a
    // normal launch. The packaged launcher verifies CDP and retries the official
    // executable directly if Windows activation drops Chromium arguments.
    choose_auto_launchable_codex_app_dir(preferred)
}

fn verify_copied_codex_file_size(
    source: &Path,
    target: &Path,
    copied: u64,
) -> std::io::Result<u64> {
    let expected = fs::metadata(source)?.len();
    let actual = fs::metadata(target)?.len();
    if copied != expected || actual != expected {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!(
                "Codex file copy size mismatch: expected {expected}, copied {copied}, target {actual}"
            ),
        ));
    }
    Ok(actual)
}

fn codex_copy_timeout_error() -> std::io::Error {
    std::io::Error::new(std::io::ErrorKind::TimedOut, "Codex 模型下拉增强复制超时")
}

fn ensure_codex_copy_deadline(deadline: Option<Instant>) -> std::io::Result<()> {
    if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
        return Err(codex_copy_timeout_error());
    }
    Ok(())
}

fn copy_codex_file_as_plain_stream(
    source: &Path,
    target: &Path,
    deadline: Option<Instant>,
) -> std::io::Result<u64> {
    ensure_codex_copy_deadline(deadline)?;
    let mut input = fs::File::open(source)?;
    let mut output = fs::OpenOptions::new()
        .create(true)
        .truncate(true)
        .write(true)
        .open(target)?;
    let mut copied = 0u64;
    let mut buffer = vec![0u8; 1024 * 1024];
    loop {
        ensure_codex_copy_deadline(deadline)?;
        let read = input.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        output.write_all(&buffer[..read])?;
        copied = copied.saturating_add(read as u64);
    }
    output.flush()?;
    verify_copied_codex_file_size(source, target, copied)
}

fn copy_codex_file_with_encryption_fallback<F>(
    source: &Path,
    target: &Path,
    deadline: Option<Instant>,
    primary_copy: F,
) -> std::io::Result<u64>
where
    F: FnOnce(&Path, &Path, Option<Instant>) -> std::io::Result<u64>,
{
    ensure_codex_copy_deadline(deadline)?;
    match primary_copy(source, target, deadline) {
        Ok(copied) => verify_copied_codex_file_size(source, target, copied),
        Err(error) if error.raw_os_error() == Some(WINDOWS_ERROR_ENCRYPTION_FAILED) => {
            match fs::remove_file(target) {
                Ok(()) => {}
                Err(remove_error) if remove_error.kind() == std::io::ErrorKind::NotFound => {}
                Err(remove_error) => return Err(remove_error),
            }
            copy_codex_file_as_plain_stream(source, target, deadline)
        }
        Err(error) => Err(error),
    }
}

#[cfg(target_os = "windows")]
fn windows_extended_path_wide(path: &Path) -> std::io::Result<Vec<u16>> {
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()?.join(path)
    };
    let wide: Vec<u16> = absolute.as_os_str().encode_wide().collect();
    let slash = b'\\' as u16;
    let question = b'?' as u16;
    let mut extended = if wide.starts_with(&[slash, slash, question, slash]) {
        wide
    } else if wide.starts_with(&[slash, slash]) {
        "\\\\?\\UNC\\"
            .encode_utf16()
            .chain(wide.into_iter().skip(2))
            .collect()
    } else {
        "\\\\?\\".encode_utf16().chain(wide).collect()
    };
    extended.push(0);
    Ok(extended)
}

#[cfg(target_os = "windows")]
struct CodexCopyProgressContext {
    deadline: Instant,
}

#[cfg(target_os = "windows")]
unsafe extern "system" fn codex_copy_progress_callback(
    _total_file_size: i64,
    _total_bytes_transferred: i64,
    _stream_size: i64,
    _stream_bytes_transferred: i64,
    _stream_number: u32,
    _callback_reason: u32,
    _source_file: *mut std::ffi::c_void,
    _destination_file: *mut std::ffi::c_void,
    data: *const std::ffi::c_void,
) -> u32 {
    if data.is_null() {
        return PROGRESS_CONTINUE;
    }
    let context = unsafe { &*(data as *const CodexCopyProgressContext) };
    if Instant::now() >= context.deadline {
        PROGRESS_CANCEL
    } else {
        PROGRESS_CONTINUE
    }
}

#[cfg(target_os = "windows")]
fn copy_codex_file_allow_decrypted(
    source: &Path,
    target: &Path,
    deadline: Option<Instant>,
) -> std::io::Result<u64> {
    ensure_codex_copy_deadline(deadline)?;
    let source_wide = windows_extended_path_wide(source)?;
    let target_wide = windows_extended_path_wide(target)?;
    let progress_context = deadline.map(|deadline| CodexCopyProgressContext { deadline });
    let progress_callback: LPPROGRESS_ROUTINE = if progress_context.is_some() {
        Some(codex_copy_progress_callback)
    } else {
        None
    };
    let progress_data = progress_context
        .as_ref()
        .map(|context| context as *const CodexCopyProgressContext as *const std::ffi::c_void)
        .unwrap_or(std::ptr::null());
    let mut cancelled = 0;
    let copied = unsafe {
        CopyFileExW(
            source_wide.as_ptr(),
            target_wide.as_ptr(),
            progress_callback,
            progress_data,
            &mut cancelled,
            COPY_FILE_ALLOW_DECRYPTED_DESTINATION,
        )
    };
    if copied == 0 {
        if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            return Err(codex_copy_timeout_error());
        }
        return Err(std::io::Error::last_os_error());
    }
    Ok(fs::metadata(target)?.len())
}

fn copy_codex_app_file(
    source: &Path,
    target: &Path,
    deadline: Option<Instant>,
) -> std::io::Result<u64> {
    #[cfg(target_os = "windows")]
    {
        return copy_codex_file_with_encryption_fallback(
            source,
            target,
            deadline,
            copy_codex_file_allow_decrypted,
        );
    }
    #[cfg(not(target_os = "windows"))]
    {
        ensure_codex_copy_deadline(deadline)?;
        fs::copy(source, target)
    }
}

#[allow(dead_code)]
fn copy_codex_app_dir_to_patchable(
    source: &Path,
    target: &Path,
    force_refresh: bool,
) -> Result<(), String> {
    copy_codex_app_dir_to_patchable_with_deadline(source, target, force_refresh, None)
}

fn cleanup_stale_codex_staging_dirs(parent: &Path) {
    let Ok(entries) = fs::read_dir(parent) else {
        return;
    };
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if !name.starts_with(".gaoge-codex-portable-") {
            continue;
        }
        let path = entry.path();
        if entry
            .file_type()
            .map(|file_type| file_type.is_dir())
            .unwrap_or(false)
        {
            let _ = remove_dir_retry(&path);
        }
    }
}

fn copy_codex_app_dir_to_patchable_with_deadline(
    source: &Path,
    target: &Path,
    force_refresh: bool,
    deadline: Option<Instant>,
) -> Result<(), String> {
    ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
    if is_complete_codex_app_dir(target) && !force_refresh {
        return Ok(());
    }
    if !is_complete_codex_app_dir(source) {
        return Err(format!("Codex 源目录不完整：{}", source.display()));
    }
    validate_install_target(target)?;
    if target
        .components()
        .any(|component| matches!(component, Component::ParentDir | Component::CurDir))
    {
        return Err(format!(
            "Codex 本地副本路径不能包含 . 或 ..：{}",
            target.display()
        ));
    }
    if same_windows_path(source, target) || target.starts_with(source) {
        return Err(format!(
            "Codex 本地副本路径不能与源目录相同或位于源目录内部：{}",
            target.display()
        ));
    }
    if target.exists()
        && fs::symlink_metadata(target)
            .map(|metadata| metadata.file_type().is_symlink())
            .unwrap_or(false)
    {
        return Err(format!(
            "Codex 本地副本路径不能是符号链接：{}",
            target.display()
        ));
    }
    let parent = target
        .parent()
        .ok_or_else(|| format!("Codex 安装路径无效：{}", target.display()))?;
    cleanup_stale_codex_staging_dirs(parent);
    let staging = parent.join(format!(".gaoge-codex-portable-{}", timestamp_for_path()));
    let _ = remove_dir_retry(&staging);
    fs::create_dir_all(&staging)
        .map_err(|error| format!("创建 Codex 临时目录失败 {}: {error}", staging.display()))?;

    let copy_result = (|| -> Result<(usize, u64), String> {
        let mut file_count = 0usize;
        let mut byte_count = 0u64;
        for entry in WalkDir::new(source) {
            ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
            let entry = entry.map_err(|error| format!("遍历 Codex 源目录失败：{error}"))?;
            let source_path = entry.path();
            let relative = source_path
                .strip_prefix(source)
                .map_err(|error| format!("计算 Codex 复制路径失败：{error}"))?;
            let target_path = staging.join(relative);
            if entry.file_type().is_dir() {
                fs::create_dir_all(&target_path).map_err(|error| {
                    format!("创建 Codex 目录失败 {}: {error}", target_path.display())
                })?;
            } else if entry.file_type().is_file() {
                ensure_parent(&target_path)?;
                let copied =
                    copy_codex_app_file(source_path, &target_path, deadline).map_err(|error| {
                        format!(
                            "复制 Codex 文件失败 {} -> {} ({error})",
                            source_path.display(),
                            target_path.display()
                        )
                    })?;
                file_count += 1;
                byte_count = byte_count.saturating_add(copied);
            } else {
                return Err(format!(
                    "Codex 源目录包含不支持的链接或重解析项：{}",
                    source_path.display()
                ));
            }
        }
        if file_count == 0 || byte_count == 0 {
            return Err("Codex 源目录没有可复制文件。".to_string());
        }
        Ok((file_count, byte_count))
    })();
    if let Err(error) = copy_result {
        let _ = remove_dir_retry(&staging);
        return Err(error);
    }

    if !is_complete_codex_app_dir(&staging) {
        let _ = remove_dir_retry(&staging);
        return Err("复制出的 Codex 本地副本不完整。".to_string());
    }
    ensure_codex_copy_deadline(deadline).map_err(|error| {
        let _ = remove_dir_retry(&staging);
        error.to_string()
    })?;
    if target.exists() {
        remove_dir_retry(target)?;
    }
    fs::rename(&staging, target)
        .map_err(|error| format!("启用 Codex 本地副本失败 {}: {error}", target.display()))?;
    persist_codex_install_dir_override(target)?;
    Ok(())
}

#[allow(dead_code)]
fn choose_or_prepare_patchable_codex_app_dir(preferred: Vec<PathBuf>) -> Result<PathBuf, String> {
    if let Some(app_dir) = choose_patchable_codex_app_dir(preferred.clone()) {
        return Ok(app_dir);
    }

    if cfg!(target_os = "windows") {
        let source = choose_launchable_codex_app_dir(preferred)
            .ok_or_else(|| "没有找到可用的 Codex 安装目录。".to_string())?;
        let target = portable_codex_dir();
        copy_codex_app_dir_to_patchable(&source, &target, false)?;
        return Ok(target);
    }

    Err("没有找到可补丁的 Codex App 目录。".to_string())
}

fn codex_model_picker_source_marker(app_dir: &Path) -> PathBuf {
    app_dir.join(CODEX_MODEL_PICKER_SOURCE_MARKER_FILE)
}

#[cfg_attr(test, allow(dead_code))]
fn codex_model_picker_source_identity(source: &Path) -> Value {
    let asar = codex_resources_dir(source).join("app.asar");
    let metadata = fs::metadata(&asar).ok();
    let asar_bytes = metadata.as_ref().map(|value| value.len()).unwrap_or(0);
    let asar_modified_ms = metadata
        .and_then(|value| value.modified().ok())
        .and_then(|value| value.duration_since(UNIX_EPOCH).ok())
        .map(|value| value.as_millis() as u64)
        .unwrap_or(0);
    json!({
        "sourceAppDir": source.to_string_lossy(),
        "sourceAsarBytes": asar_bytes,
        "sourceAsarModifiedMs": asar_modified_ms,
    })
}

#[cfg_attr(test, allow(dead_code))]
fn prepare_codex_model_picker_app(
    preferred: Vec<PathBuf>,
    deadline: Option<Instant>,
) -> Result<PathBuf, String> {
    ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
    if !cfg!(target_os = "windows") {
        return choose_or_prepare_patchable_codex_app_dir(preferred);
    }

    let target = portable_codex_dir();
    if let Some(app_dir) = choose_patchable_codex_app_dir(preferred.clone()) {
        let is_managed_portable = same_windows_path(&app_dir, &target)
            && codex_model_picker_source_marker(&target).exists();
        if !is_managed_portable {
            return Ok(app_dir);
        }
    }

    let source = preferred
        .iter()
        .find(|path| is_windows_apps_codex_dir(path) && is_complete_codex_app_dir(path))
        .cloned()
        .or_else(registered_windows_appx_codex_dir)
        .or_else(|| list_windows_apps_codex_dirs().into_iter().next())
        .or_else(|| choose_launchable_codex_app_dir(preferred))
        .or_else(|| is_complete_codex_app_dir(&target).then(|| target.clone()))
        .ok_or_else(|| "没有找到可用于模型下拉增强的 Codex 安装目录。".to_string())?;

    if !is_windows_apps_codex_dir(&source) {
        return Ok(source);
    }

    let source_identity = codex_model_picker_source_identity(&source);
    let marker_path = codex_model_picker_source_marker(&target);
    let marker_matches =
        read_json_if_exists(&marker_path).ok().flatten().as_ref() == Some(&source_identity);
    let force_refresh = is_complete_codex_app_dir(&target) && !marker_matches;
    copy_codex_app_dir_to_patchable_with_deadline(&source, &target, force_refresh, deadline)?;
    ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
    write_json_pretty(&marker_path, &source_identity)?;
    Ok(target)
}

fn resource_file(app: &AppHandle, name: &str) -> Result<PathBuf, String> {
    let resource_dir = app
        .path()
        .resource_dir()
        .map_err(|error| format!("resource dir failed: {error}"))?;
    let direct = resource_dir.join(name);
    if direct.exists() {
        return Ok(direct);
    }
    for entry in WalkDir::new(&resource_dir).into_iter().flatten() {
        if entry.file_type().is_file() && entry.file_name().to_string_lossy() == name {
            return Ok(entry.path().to_path_buf());
        }
    }
    Err(format!("resource not found: {name}"))
}

#[allow(dead_code)]
fn same_windows_path(left: &Path, right: &Path) -> bool {
    let normalize = |path: &Path| {
        path.to_string_lossy()
            .replace('/', "\\")
            .trim_end_matches('\\')
            .to_lowercase()
    };
    normalize(left) == normalize(right)
}

fn is_gaoge_managed_codex_shortcut_target(target: &Path) -> bool {
    let is_codex_exe = target
        .file_name()
        .and_then(OsStr::to_str)
        .is_some_and(|name| name.eq_ignore_ascii_case("Codex.exe"));
    if !is_codex_exe {
        return false;
    }
    let Some(app_dir) = target.parent() else {
        return false;
    };
    same_windows_path(app_dir, &portable_codex_dir())
        || same_windows_path(app_dir, &default_portable_codex_dir())
        || codex_model_picker_source_marker(app_dir).exists()
}

fn remove_gaoge_managed_codex_shortcuts() -> Vec<String> {
    if !cfg!(target_os = "windows") {
        return Vec::new();
    }
    let mut removed = Vec::new();
    for shortcut in codex_shortcut_paths() {
        let Some(current_target) = read_windows_shortcut_target(&shortcut) else {
            continue;
        };
        if !is_gaoge_managed_codex_shortcut_target(&current_target) {
            continue;
        }
        if fs::remove_file(&shortcut).is_ok() {
            removed.push(shortcut.to_string_lossy().to_string());
        }
    }
    removed
}

#[allow(dead_code)]
fn find_codex_node(resources_dir: &Path) -> Option<PathBuf> {
    let direct = resources_dir.join("node.exe");
    if direct.exists() {
        return Some(direct);
    }
    let app_dir = resources_dir.parent()?;
    let nested = app_dir.join("resources").join("node.exe");
    if nested.exists() {
        return Some(nested);
    }
    None
}

fn byte_slice_contains(haystack: &[u8], needle: &[u8]) -> bool {
    !needle.is_empty()
        && haystack
            .windows(needle.len())
            .any(|window| window == needle)
}

fn byte_pattern_offsets(haystack: &[u8], needle: &[u8]) -> Vec<usize> {
    if needle.is_empty() || haystack.len() < needle.len() {
        return Vec::new();
    }
    memchr::memmem::find_iter(haystack, needle).collect()
}

#[derive(Clone, Debug)]
struct AsarFileRecord {
    path: String,
    archive_offset: usize,
    offset: usize,
    size: usize,
    integrity_hash: String,
    block_size: usize,
    blocks: Vec<String>,
}

fn asar_header_layout(content: &[u8]) -> Option<(std::ops::Range<usize>, usize)> {
    if content.len() < 16 || u32::from_le_bytes(content[0..4].try_into().ok()?) != 4 {
        return None;
    }
    let header_size = u32::from_le_bytes(content[4..8].try_into().ok()?) as usize;
    let pickle_payload_size = u32::from_le_bytes(content[8..12].try_into().ok()?) as usize;
    let json_size = u32::from_le_bytes(content[12..16].try_into().ok()?) as usize;
    let data_start = 8usize.checked_add(header_size)?;
    let json_end = 16usize.checked_add(json_size)?;
    if header_size < 8
        || pickle_payload_size.checked_add(4)? != header_size
        || json_end > data_start
        || data_start > content.len()
    {
        return None;
    }
    Some((16..json_end, data_start))
}

fn collect_asar_files_containing_offset(
    directory: &Value,
    parent: &str,
    data_start: usize,
    target_offset: usize,
    records: &mut Vec<AsarFileRecord>,
) {
    let Some(files) = directory.get("files").and_then(Value::as_object) else {
        return;
    };
    for (name, entry) in files {
        let path = if parent.is_empty() {
            name.clone()
        } else {
            format!("{parent}/{name}")
        };
        if entry.get("files").is_some() {
            collect_asar_files_containing_offset(entry, &path, data_start, target_offset, records);
            continue;
        }
        let Some(size) = entry.get("size").and_then(Value::as_u64) else {
            continue;
        };
        let Some(offset) = entry
            .get("offset")
            .and_then(Value::as_str)
            .and_then(|value| value.parse::<usize>().ok())
        else {
            continue;
        };
        let Some(absolute_start) = data_start.checked_add(offset) else {
            continue;
        };
        let Some(absolute_end) = absolute_start.checked_add(size as usize) else {
            continue;
        };
        if !(absolute_start..absolute_end).contains(&target_offset) {
            continue;
        }
        let Some(integrity) = entry.get("integrity") else {
            continue;
        };
        let Some(integrity_hash) = integrity.get("hash").and_then(Value::as_str) else {
            continue;
        };
        let Some(block_size) = integrity.get("blockSize").and_then(Value::as_u64) else {
            continue;
        };
        let blocks = integrity
            .get("blocks")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(Value::as_str)
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        records.push(AsarFileRecord {
            path,
            archive_offset: offset,
            offset: absolute_start,
            size: size as usize,
            integrity_hash: integrity_hash.to_string(),
            block_size: block_size as usize,
            blocks,
        });
    }
}

fn json_object_end(content: &[u8], start: usize) -> Option<usize> {
    if content.get(start) != Some(&b'{') {
        return None;
    }
    let mut depth = 0usize;
    let mut quoted = false;
    let mut escaped = false;
    for (index, byte) in content.iter().enumerate().skip(start) {
        if quoted {
            if escaped {
                escaped = false;
            } else if *byte == b'\\' {
                escaped = true;
            } else if *byte == b'"' {
                quoted = false;
            }
            continue;
        }
        match *byte {
            b'"' => quoted = true,
            b'{' => depth += 1,
            b'}' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(index + 1);
                }
            }
            _ => {}
        }
    }
    None
}

fn asar_file_header_record_range(
    header: &[u8],
    record: &AsarFileRecord,
) -> Result<std::ops::Range<usize>, String> {
    let file_name = record
        .path
        .rsplit('/')
        .next()
        .ok_or_else(|| "Codex ASAR 模型文件名无效。".to_string())?;
    let quoted_name = serde_json::to_string(file_name)
        .map_err(|error| format!("Codex ASAR 文件名编码失败：{error}"))?;
    let mut matches = Vec::new();
    for key_offset in byte_pattern_offsets(header, quoted_name.as_bytes()) {
        let mut cursor = key_offset + quoted_name.len();
        while matches!(header.get(cursor), Some(b' ' | b'\t' | b'\r' | b'\n')) {
            cursor += 1;
        }
        if header.get(cursor) != Some(&b':') {
            continue;
        }
        cursor += 1;
        while matches!(header.get(cursor), Some(b' ' | b'\t' | b'\r' | b'\n')) {
            cursor += 1;
        }
        let Some(end) = json_object_end(header, cursor) else {
            continue;
        };
        let Ok(value) = serde_json::from_slice::<Value>(&header[cursor..end]) else {
            continue;
        };
        let same_offset = value
            .get("offset")
            .and_then(Value::as_str)
            .and_then(|value| value.parse::<usize>().ok())
            == Some(record.archive_offset);
        let same_size = value.get("size").and_then(Value::as_u64) == Some(record.size as u64);
        let same_hash = value
            .get("integrity")
            .and_then(|integrity| integrity.get("hash"))
            .and_then(Value::as_str)
            == Some(record.integrity_hash.as_str());
        if same_offset && same_size && same_hash {
            matches.push(cursor..end);
        }
    }
    if matches.len() != 1 {
        return Err(format!(
            "Codex ASAR 模型文件完整性记录不唯一（{}）：{}",
            matches.len(),
            record.path
        ));
    }
    Ok(matches.remove(0))
}

fn refresh_asar_file_integrity(
    content: &mut [u8],
    header_range: std::ops::Range<usize>,
    record: &AsarFileRecord,
) -> Result<bool, String> {
    if record.block_size == 0 {
        return Err(format!(
            "Codex 模型下拉文件完整性块大小无效：{}",
            record.path
        ));
    }
    let expected_blocks = record
        .size
        .checked_add(record.block_size - 1)
        .ok_or_else(|| format!("Codex ASAR 模型文件块数量溢出：{}", record.path))?
        / record.block_size;
    if record.blocks.len() != expected_blocks {
        return Err(format!(
            "Codex 模型下拉文件完整性块数量异常（{} != {}）：{}",
            record.blocks.len(),
            expected_blocks,
            record.path,
        ));
    }
    let end = record
        .offset
        .checked_add(record.size)
        .ok_or_else(|| "Codex ASAR 模型文件范围溢出。".to_string())?;
    if end > content.len() {
        return Err(format!("Codex ASAR 模型文件越界：{}", record.path));
    }
    let file_content = &content[record.offset..end];
    let next_hash = format!("{:x}", Sha256::digest(file_content));
    let next_blocks = file_content
        .chunks(record.block_size)
        .map(|block| format!("{:x}", Sha256::digest(block)))
        .collect::<Vec<_>>();
    if next_hash == record.integrity_hash && next_blocks == record.blocks {
        return Ok(false);
    }
    let local_range = asar_file_header_record_range(&content[header_range.clone()], record)?;
    let absolute_range =
        (header_range.start + local_range.start)..(header_range.start + local_range.end);
    let mut replacements = HashMap::<String, (String, usize)>::new();
    for (old, next) in std::iter::once((&record.integrity_hash, &next_hash))
        .chain(record.blocks.iter().zip(next_blocks.iter()))
    {
        if old.len() != next.len() {
            return Err(format!("Codex ASAR 模型文件摘要长度变化：{}", record.path));
        }
        let entry = replacements
            .entry(old.clone())
            .or_insert_with(|| (next.clone(), 0));
        if entry.0 != *next {
            return Err(format!(
                "Codex ASAR 模型文件重复摘要无法安全更新：{}",
                record.path
            ));
        }
        entry.1 += 1;
    }
    for (old, (next, expected_count)) in replacements {
        let offsets = byte_pattern_offsets(&content[absolute_range.clone()], old.as_bytes());
        if offsets.len() != expected_count {
            return Err(format!(
                "Codex ASAR 模型文件摘要出现次数异常（{} != {}）：{}",
                offsets.len(),
                expected_count,
                record.path
            ));
        }
        if old == next {
            continue;
        }
        for offset in offsets {
            let start = absolute_range.start + offset;
            let end = start + old.len();
            content[start..end].copy_from_slice(next.as_bytes());
        }
    }
    Ok(true)
}

fn patch_codex_model_picker_asar_content(
    content: &mut [u8],
) -> Result<Option<(bool, bool, String)>, String> {
    let Some((header_range, data_start)) = asar_header_layout(content) else {
        return Ok(None);
    };
    let header: Value = serde_json::from_slice(&content[header_range.clone()])
        .map_err(|error| format!("Codex ASAR 目录解析失败：{error}"))?;
    let original = codex_model_picker_filter_offsets(
        &content[data_start..],
        CODEX_MODEL_PICKER_FILTER_ORIGINAL,
    );
    let patched = codex_model_picker_filter_offsets(
        &content[data_start..],
        CODEX_MODEL_PICKER_FILTER_PATCHED,
    );
    let (relative_offset, code_changed) = match (original.as_slice(), patched.as_slice()) {
        ([offset], []) => (*offset, true),
        ([], [offset]) => (*offset, false),
        _ => {
            return Err(format!(
                "Codex 模型下拉过滤器签名不唯一（原始 {}，已增强 {}），已停止修改。",
                original.len(),
                patched.len()
            ))
        }
    };
    let absolute_offset = data_start
        .checked_add(relative_offset)
        .ok_or_else(|| "Codex ASAR 模型下拉偏移溢出。".to_string())?;
    let mut records = Vec::new();
    collect_asar_files_containing_offset(&header, "", data_start, absolute_offset, &mut records);
    if records.len() != 1 {
        return Err(format!(
            "Codex ASAR 模型下拉文件定位不唯一（{}），已停止修改。",
            records.len()
        ));
    }
    let record = records.remove(0);
    if code_changed {
        let end = absolute_offset + CODEX_MODEL_PICKER_FILTER_ORIGINAL.len();
        content[absolute_offset..end].copy_from_slice(CODEX_MODEL_PICKER_FILTER_PATCHED);
    }
    let integrity_changed = refresh_asar_file_integrity(content, header_range, &record)?;
    Ok(Some((
        code_changed || integrity_changed,
        code_changed,
        record.path,
    )))
}

fn codex_api_key_service_tier_gate_marker_offsets(content: &[u8]) -> Vec<usize> {
    byte_pattern_offsets(content, b"featureRequirements?.fast_mode")
        .into_iter()
        .filter(|offset| {
            let start = offset.saturating_sub(1024);
            let end = content.len().min(offset.saturating_add(1024));
            let window = &content[start..end];
            byte_slice_contains(window, b"authMethod===`chatgpt`")
                && byte_slice_contains(window, b"isPending:")
                && byte_slice_contains(window, b"isServiceTierAllowed:")
        })
        .collect()
}

fn codex_api_key_service_tier_gate_offsets(content: &[u8], signature: &[u8]) -> Vec<usize> {
    byte_pattern_offsets(content, signature)
        .into_iter()
        .filter(|offset| {
            let start = offset.saturating_sub(1024);
            let end = content.len().min(offset.saturating_add(1024));
            let window = &content[start..end];
            byte_slice_contains(window, b"authMethod===`chatgpt`")
                && byte_slice_contains(window, b"authMethod??null")
                && byte_slice_contains(window, b"isPending:")
                && byte_slice_contains(window, b"isServiceTierAllowed:d,isLoading:u")
        })
        .collect()
}

fn codex_api_key_service_tier_gate_match(content: &[u8]) -> Result<Option<(usize, bool)>, String> {
    if CODEX_APIKEY_SERVICE_TIER_GATE_ORIGINAL.len() != CODEX_APIKEY_SERVICE_TIER_GATE_PATCHED.len()
    {
        return Err("Codex API Key 速度补丁标记长度不一致。".to_string());
    }
    let original =
        codex_api_key_service_tier_gate_offsets(content, CODEX_APIKEY_SERVICE_TIER_GATE_ORIGINAL);
    let patched =
        codex_api_key_service_tier_gate_offsets(content, CODEX_APIKEY_SERVICE_TIER_GATE_PATCHED);
    match (original.as_slice(), patched.as_slice()) {
        ([offset], []) => Ok(Some((*offset, false))),
        ([], [offset]) => Ok(Some((*offset, true))),
        ([], []) if codex_api_key_service_tier_gate_marker_offsets(content).is_empty() => Ok(None),
        _ => Err(format!(
            "Codex API Key 速度门槛签名不唯一或结构已变化（原始 {}，已增强 {}），已停止修改。",
            original.len(),
            patched.len()
        )),
    }
}

fn codex_api_key_service_tier_gate_asset(content: &[u8]) -> Result<Option<(bool, String)>, String> {
    let layout = asar_header_layout(content);
    let data_start = layout.as_ref().map(|(_, start)| *start).unwrap_or(0);
    let Some((relative_offset, patched)) =
        codex_api_key_service_tier_gate_match(&content[data_start..])?
    else {
        return Ok(None);
    };
    let Some((header_range, _)) = layout else {
        return Ok(Some((patched, String::new())));
    };
    let header: Value = serde_json::from_slice(&content[header_range])
        .map_err(|error| format!("Codex ASAR 目录解析失败：{error}"))?;
    let mut records = Vec::new();
    collect_asar_files_containing_offset(
        &header,
        "",
        data_start,
        data_start + relative_offset,
        &mut records,
    );
    if records.len() != 1 || !records[0].path.ends_with(".js") {
        return Err("Codex API Key 速度门槛文件定位失败。".to_string());
    }
    Ok(Some((patched, records.remove(0).path)))
}

// Recognize the native catalog predicate by its parameter bindings AND behavior.
// Field names alone also occur in call sites, caches and schemas.
fn codex_native_model_catalog_offsets(content: &[u8]) -> Vec<usize> {
    let fields = [
        "additionalAvailableModels",
        "authMethod",
        "availableModels",
        "hasConfiguredModelCatalog",
        "isCustomModelProvider",
        "model",
        "useHiddenModels",
    ];
    byte_pattern_offsets(content, b"hasConfiguredModelCatalog:")
        .into_iter()
        .filter_map(|offset| {
            let start = offset.saturating_sub(400);
            let end = content.len().min(offset + 1800);
            let function_start = *byte_pattern_offsets(&content[start..offset], b"function ").last()?;
            let function = String::from_utf8_lossy(&content[start + function_start..end]);
            let params_start = function.find("({")? + 2;
            let params_end = function.find("}){")?;
            let params = &function[params_start..params_end];
            let pairs = params.split(',').map(|p| p.split_once(':')).collect::<Option<Vec<_>>>()?;
            let bindings: HashMap<_, _> = pairs.iter().copied().collect();
            let daybreak = bindings.get("apiKeyDaybreakSupported").copied();
            let expected_count = fields.len() + usize::from(daybreak.is_some());
            if pairs.len() != expected_count || bindings.len() != expected_count { return None; }
            let aliases: Vec<&str> = fields.iter().map(|key| bindings.get(key).copied()).collect::<Option<_>>()?;
            let valid_identifier = |name: &str| {
                !name.is_empty() && name.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'$')
            };
            let all_aliases = aliases.iter().copied().chain(daybreak).collect::<Vec<_>>();
            if all_aliases.iter().any(|name| !valid_identifier(name))
                || all_aliases.iter().copied().collect::<HashSet<_>>().len() != expected_count {
                return None;
            }
            let body = function[params_end + "}){".len()..].split('}').next()?.trim_end_matches(';');
            let [extra, auth, available, catalog, custom, model, hidden] = aliases.as_slice() else { return None; };
            let prefix = format!("{extra}?.has({model}.model)===!0||{model}.model!==`codex-auto-review`&&({catalog}&&!{model}.hidden||({hidden}&&!{custom}&&{auth}!==`amazonBedrock`?{available}.has({model}.model)");
            let expected = if let Some(daybreak) = daybreak {
                // 26.1007: preserve the native access-program checks. A partial
                // match must never mistake a changed permission rule for this one.
                let programs = body.strip_prefix("let ")?.split_once('=')?.0;
                if !valid_identifier(programs) || all_aliases.contains(&programs) { return None; }
                let program = body.split("?.some(").nth(1)?.split_once("=>")?.0;
                if !valid_identifier(program) { return None; }
                format!("let {programs}={model}.availableAccessPrograms?.cyber;return {auth}===`apikey`&&!{daybreak}&&{programs}!=null&&{programs}.length>0&&!{programs}.includes(`standard`)?!1:{prefix}||{auth}===`apikey`&&{daybreak}&&!{model}.hidden&&{programs}?.some({program}=>{program}!==`standard`)===!0:!{model}.hidden))")
            } else {
                format!("return {prefix}:!{model}.hidden))")
            };
            (body == expected).then_some(start + function_start)
        })
        .collect()
}

fn codex_native_model_catalog_asset(content: &[u8]) -> Result<Option<String>, String> {
    let layout = asar_header_layout(content);
    let data_start = layout.as_ref().map(|(_, start)| *start).unwrap_or(0);
    let offsets = codex_native_model_catalog_offsets(&content[data_start..]);
    if offsets.is_empty() {
        return Ok(None);
    }
    if offsets.len() != 1 {
        return Err(format!(
            "Codex 原生模型目录能力不唯一（{}），已停止修改。",
            offsets.len()
        ));
    }
    let Some((header_range, _)) = layout else {
        return Ok(Some(String::new()));
    };
    let header: Value = serde_json::from_slice(&content[header_range])
        .map_err(|error| format!("Codex ASAR 目录解析失败：{error}"))?;
    let mut records = Vec::new();
    collect_asar_files_containing_offset(
        &header,
        "",
        data_start,
        data_start + offsets[0],
        &mut records,
    );
    if records.len() != 1 || !records[0].path.ends_with(".js") {
        return Err("Codex 原生模型目录文件定位失败。".to_string());
    }
    Ok(Some(records.remove(0).path))
}
fn codex_model_picker_filter_offsets(content: &[u8], key: &[u8]) -> Vec<usize> {
    const REQUIRED_MARKERS: [&[u8]; 10] = [
        b"function ",
        b"authMethod:",
        b"availableModels:",
        b"defaultModel:",
        b"enabledReasoningEfforts:",
        b"includeUltraReasoningEffort:",
        b"models:",
        b"amazonBedrock",
        b"forEach",
        b".hidden",
    ];
    byte_pattern_offsets(content, key)
        .into_iter()
        .filter(|offset| {
            let start = offset.saturating_sub(768);
            let end = content.len().min(offset.saturating_add(1280));
            let window = &content[start..end];
            REQUIRED_MARKERS
                .iter()
                .all(|marker| byte_slice_contains(window, marker))
        })
        .collect()
}

fn patch_codex_model_picker_content(content: &mut [u8]) -> Result<bool, String> {
    if CODEX_MODEL_PICKER_FILTER_ORIGINAL.len() != CODEX_MODEL_PICKER_FILTER_PATCHED.len() {
        return Err("Codex 模型下拉增强标记长度不一致。".to_string());
    }
    let original = codex_model_picker_filter_offsets(content, CODEX_MODEL_PICKER_FILTER_ORIGINAL);
    let patched = codex_model_picker_filter_offsets(content, CODEX_MODEL_PICKER_FILTER_PATCHED);
    match (original.as_slice(), patched.as_slice()) {
        ([offset], []) => {
            let end = offset + CODEX_MODEL_PICKER_FILTER_ORIGINAL.len();
            content[*offset..end].copy_from_slice(CODEX_MODEL_PICKER_FILTER_PATCHED);
            Ok(true)
        }
        ([], [_]) => Ok(false),
        _ => Err(format!(
            "Codex 模型下拉过滤器签名不唯一（原始 {}，已增强 {}），已停止修改。",
            original.len(),
            patched.len()
        )),
    }
}

#[cfg(target_os = "windows")]
fn windows_atomic_file_path(path: &Path) -> Result<Vec<u16>, String> {
    let name = path
        .file_name()
        .ok_or_else(|| format!("原子替换文件路径无效：{}", path.display()))?;
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    // Rust canonicalization supplies Windows' extended-length path prefix.
    // Resolve only the parent: the destination need not exist, and a final
    // symlink must be replaced itself rather than moving its referent.
    let absolute = fs::canonicalize(parent)
        .map_err(|error| format!("解析原子替换目录失败 {}: {error}", parent.display()))?
        .join(name);
    let mut wide = absolute.as_os_str().encode_wide().collect::<Vec<_>>();
    if wide.contains(&0) {
        return Err(format!("原子替换文件路径包含空字符：{}", path.display()));
    }
    wide.push(0);
    Ok(wide)
}

#[cfg(target_os = "windows")]
fn replace_file_atomically(source: &Path, target: &Path) -> Result<(), String> {
    #[link(name = "Kernel32")]
    extern "system" {
        fn MoveFileExW(
            lp_existing_file_name: *const u16,
            lp_new_file_name: *const u16,
            dw_flags: u32,
        ) -> i32;
    }
    const MOVEFILE_REPLACE_EXISTING: u32 = 0x0000_0001;
    const MOVEFILE_WRITE_THROUGH: u32 = 0x0000_0008;
    let source_wide = windows_atomic_file_path(source)?;
    let target_wide = windows_atomic_file_path(target)?;
    // SAFETY: both paths are encoded as owned, NUL-terminated UTF-16 buffers
    // that remain alive for the entire synchronous MoveFileExW call.
    let moved = unsafe {
        MoveFileExW(
            source_wide.as_ptr(),
            target_wide.as_ptr(),
            MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH,
        )
    };
    if moved == 0 {
        return Err(format!(
            "原子替换文件失败 {}: {}",
            target.display(),
            std::io::Error::last_os_error()
        ));
    }
    Ok(())
}

#[cfg(not(target_os = "windows"))]
fn replace_file_atomically(source: &Path, target: &Path) -> Result<(), String> {
    fs::rename(source, target)
        .map_err(|error| format!("原子替换文件失败 {}: {error}", target.display()))
}

#[derive(Default)]
struct CodexModelPickerBytePatch {
    changed: bool,
    code_changed: bool,
    native_model_catalog: bool,
    model_picker_asset: Option<String>,
    api_key_service_tier_patched: bool,
    service_tier_asset: Option<String>,
    ultra_reasoning_patched: bool,
    ultra_reasoning_asset: Option<String>,
}

fn patch_codex_model_picker_bytes(content: &mut Vec<u8>) -> Result<CodexModelPickerBytePatch, String> {
    let native_model_catalog = codex_native_model_catalog_asset(content)?;
    let is_asar = asar_header_layout(content).is_some();
    let mut result = CodexModelPickerBytePatch {
        native_model_catalog: native_model_catalog.is_some(),
        model_picker_asset: native_model_catalog.filter(|asset| !asset.is_empty()),
        ..CodexModelPickerBytePatch::default()
    };

    if !result.native_model_catalog {
        if is_asar {
            let Some((changed, code_changed, asset)) =
                patch_codex_model_picker_asar_content(content)?
            else {
                return Err("Codex ASAR 中没有找到模型下拉过滤器。".to_string());
            };
            result.changed |= changed;
            result.code_changed |= code_changed;
            result.model_picker_asset = Some(asset);
        } else {
            let changed = patch_codex_model_picker_content(content)?;
            result.changed |= changed;
            result.code_changed |= changed;
        }
    }

    // Fast is prepared and verified by the pinned four-gate runtime adapter.
    // The legacy UI-only patch is recognized for diagnostics, never applied.
    if let Some((changed, code_changed, asset)) = codex_ultra_patch::patch(content)? {
        result.changed |= changed;
        result.code_changed |= code_changed;
        result.ultra_reasoning_patched = true;
        result.ultra_reasoning_asset = (!asset.is_empty()).then_some(asset);
    }
    Ok(result)
}

fn patch_codex_model_picker_file(path: &Path, backup_path: &Path) -> Result<Value, String> {
    let mut content = fs::read(path)
        .map_err(|error| format!("读取 Codex 模型下拉文件失败 {}: {error}", path.display()))?;
    let patch = patch_codex_model_picker_bytes(&mut content)?;
    if patch.changed {
        if patch.code_changed || !backup_path.exists() {
            ensure_parent(backup_path)?;
            fs::copy(path, backup_path).map_err(|error| {
                format!(
                    "备份 Codex 模型下拉文件失败 {} -> {} ({error})",
                    path.display(),
                    backup_path.display()
                )
            })?;
        }
        let temp_path = temp_write_path(path);
        let write_result = (|| -> Result<(), String> {
            {
                let mut file = fs::File::create(&temp_path).map_err(|error| {
                    format!(
                        "创建 Codex 模型下拉临时文件失败 {}: {error}",
                        temp_path.display()
                    )
                })?;
                file.write_all(&content).map_err(|error| {
                    format!(
                        "写入 Codex 模型下拉临时文件失败 {}: {error}",
                        temp_path.display()
                    )
                })?;
                file.sync_all().map_err(|error| {
                    format!(
                        "同步 Codex 模型下拉临时文件失败 {}: {error}",
                        temp_path.display()
                    )
                })?;
            }
            let mut pending = fs::read(&temp_path).map_err(|error| {
                format!(
                    "读取 Codex 模型下拉临时文件失败 {}: {error}",
                    temp_path.display()
                )
            })?;
            if patch_codex_model_picker_bytes(&mut pending)?.changed {
                return Err("Codex 模型下拉临时文件校验失败。".to_string());
            }
            replace_file_atomically(&temp_path, path)?;
            Ok(())
        })();
        if let Err(error) = write_result {
            let _ = fs::remove_file(&temp_path);
            let _ = fs::copy(backup_path, path);
            return Err(error);
        }
    }
    let verification = (|| -> Result<(), String> {
        let mut verified = fs::read(path)
            .map_err(|error| format!("校验 Codex 模型下拉文件失败 {}: {error}", path.display()))?;
        if patch_codex_model_picker_bytes(&mut verified)?.changed {
            return Err(format!(
                "Codex 模型下拉增强写入后校验失败：{}",
                path.display()
            ));
        }
        Ok(())
    })();
    if let Err(error) = verification {
        if patch.changed {
            let _ = fs::copy(backup_path, path);
        }
        return Err(error);
    }
    let backup_value = if patch.changed || backup_path.exists() {
        Value::String(backup_path.to_string_lossy().to_string())
    } else {
        Value::Null
    };
    Ok(json!({
        "changed": patch.changed,
        "alreadyPatched": !patch.changed && !patch.native_model_catalog,
        "nativeModelCatalog": patch.native_model_catalog,
        "patchTarget": path.to_string_lossy(),
        "backupPath": backup_value,
        "modelPickerAsset": patch.model_picker_asset,
        "apiKeyServiceTierPatched": patch.api_key_service_tier_patched,
        "serviceTierAsset": patch.service_tier_asset,
        "ultraReasoningPatched": patch.ultra_reasoning_patched,
        "ultraReasoningAsset": patch.ultra_reasoning_asset,
    }))
}

#[cfg_attr(test, allow(dead_code))]
fn patch_codex_model_picker_app(app_dir: &Path) -> Result<Value, String> {
    let resources = codex_resources_dir(app_dir);
    let extracted_assets = resources.join("app").join("webview").join("assets");
    if !resources.join("app.asar").exists()
        && resources.join("app.asar1").exists()
        && extracted_assets.exists()
    {
        let mut candidates = Vec::new();
        for entry in WalkDir::new(&extracted_assets).into_iter().flatten() {
            if !entry.file_type().is_file()
                || entry.path().extension().and_then(OsStr::to_str) != Some("js")
            {
                continue;
            }
            let Ok(content) = fs::read(entry.path()) else {
                continue;
            };
            let original =
                codex_model_picker_filter_offsets(&content, CODEX_MODEL_PICKER_FILTER_ORIGINAL);
            let patched =
                codex_model_picker_filter_offsets(&content, CODEX_MODEL_PICKER_FILTER_PATCHED);
            if !original.is_empty()
                || !patched.is_empty()
                || !codex_native_model_catalog_offsets(&content).is_empty()
            {
                candidates.push(entry.path().to_path_buf());
            }
        }
        if candidates.len() != 1 {
            return Err(format!(
                "Codex 解包目录中的模型下拉文件不唯一（{}），已停止修改。",
                candidates.len()
            ));
        }
        let target = &candidates[0];
        let backup = target.with_extension("js.gaoge-model-picker.bak");
        let result = patch_codex_model_picker_file(target, &backup)?;
        return Ok(result);
    }

    let target = resources.join("app.asar");
    if !target.exists() {
        return Err(format!(
            "没有找到可增强的 Codex app.asar：{}",
            resources.display()
        ));
    }
    let backup = resources.join(CODEX_MODEL_PICKER_PATCH_BACKUP_FILE);
    patch_codex_model_picker_file(&target, &backup)
}

#[allow(dead_code)]
fn launch_codex_app(app_dir: &Path) -> Result<(), String> {
    let exe = codex_exe_path(app_dir);
    if !exe.exists() {
        return Err(format!("没有找到 Codex 应用入口：{}", exe.display()));
    }
    let mut command = hidden_command(&exe);
    if let Some(workdir) = exe.parent() {
        command.current_dir(workdir);
    }
    let mut child = command
        .spawn()
        .map_err(|error| format!("启动增强后的 Codex 失败：{error}"))?;
    for _ in 0..15 {
        thread::sleep(Duration::from_millis(200));
        if list_running_codex_app_dirs()
            .iter()
            .any(|running| same_windows_path(running, app_dir))
        {
            return Ok(());
        }
        if let Some(status) = child
            .try_wait()
            .map_err(|error| format!("检查增强后的 Codex 启动状态失败：{error}"))?
        {
            if !status.success() {
                return Err(format!("增强后的 Codex 启动后立即退出：{status}"));
            }
        }
    }
    Err("增强后的 Codex 未在 3 秒内启动，请使用新的 Codex 快捷方式手动打开。".to_string())
}

#[cfg_attr(test, allow(dead_code))]
fn launch_codex_normally(app_dir: &Path) -> Result<(), String> {
    #[cfg(target_os = "windows")]
    if is_windows_apps_codex_dir(app_dir) {
        activate_windows_packaged_codex(app_dir, &[])?;
        return Ok(());
    }
    #[cfg(target_os = "macos")]
    if is_macos_app_bundle(app_dir) {
        let mut command = hidden_command("open");
        command.arg("-a").arg(app_dir);
        return command
            .spawn()
            .map(|_| ())
            .map_err(|error| format!("启动 Codex 失败：{error}"));
    }

    let exe = codex_direct_launch_exe_path(app_dir);
    if !exe.exists() {
        return Err(format!("没有找到 Codex 应用入口：{}", exe.display()));
    }
    let mut command = hidden_command(&exe);
    if let Some(workdir) = exe.parent() {
        command.current_dir(workdir);
    }
    command
        .spawn()
        .map(|_| ())
        .map_err(|error| format!("启动 Codex 失败：{error}"))
}

fn launch_codex_normally_and_wait(app_dir: &Path) -> Result<(), String> {
    launch_codex_normally(app_dir)?;
    wait_for_codex_app_ready(app_dir, Duration::from_secs(CODEX_APP_READY_WAIT_SECS))
}

fn codex_native_catalog_runtime_hint(content: &[u8]) -> bool {
    memchr::memmem::find(content, b"hasConfiguredModelCatalog").is_some()
        && memchr::memmem::find(content, b"model/list").is_some()
}

fn enhance_codex_model_picker(
    preferred: Vec<PathBuf>,
    deadline: Option<Instant>,
) -> Result<Value, String> {
    ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
    // Native catalogs use the signed-bundle-safe runtime adapter. Copying an
    // installation just for its renderer gates can silently launch a different
    // client/profile than the one whose configuration was prepared.
    let mut legacy_filter_recognized = false;
    if let Some(app_dir) = choose_launchable_codex_app_dir(preferred.clone()) {
        if let Ok(content) = fs::read(codex_resources_dir(&app_dir).join("app.asar")) {
            let native_asset = codex_native_model_catalog_asset(&content).ok().flatten();
            let native_verified = native_asset.is_some();
            if native_verified || codex_native_catalog_runtime_hint(&content) {
                let service_tier = codex_api_key_service_tier_gate_asset(&content).ok().flatten();
                let ultra = codex_ultra_patch::inspect(&content).ok().flatten();
                    let service_tier_asset = service_tier
                        .as_ref()
                        .map(|(_, value)| value.clone())
                        .filter(|value| !value.is_empty());
                    return Ok(json!({
                        "applied": native_verified, "changed": false, "nativeModelCatalog": native_verified,
                        "method": if native_verified { "native-model-catalog" } else { "signed-runtime" },
                        "modelPickerEnhanced": false,
                        "modelCatalogReady": native_verified, "ultraRuntimePending": true,
                        "ready": false, "verified": false,
                        "ultraReady": false, "ultraVerified": false,
                        "ultraReason": "awaiting-runtime-verification",
                        "modelPickerAsset": native_asset, "backupPath": Value::Null,
                        "apiKeyServiceTierPatched": false,
                        "serviceTierAsset": service_tier_asset,
                        "ultraReasoningPatched": ultra.as_ref().is_some_and(|(patched, _)| *patched),
                        "ultraReasoningAsset": ultra.as_ref().map(|(_, asset)| asset),
                        "appPath": codex_exe_path(&app_dir).to_string_lossy(),
                        "resourcesDir": codex_resources_dir(&app_dir).to_string_lossy(),
                        "standardShortcuts": [], "warnings": [], "needsRestart": true,
                    }));
            }
            legacy_filter_recognized = !codex_model_picker_filter_offsets(&content, CODEX_MODEL_PICKER_FILTER_ORIGINAL).is_empty()
                || !codex_model_picker_filter_offsets(&content, CODEX_MODEL_PICKER_FILTER_PATCHED).is_empty();
        }
    }
    if cfg!(target_os = "macos") {
        return Err(
            "当前 macOS Codex 版本未提供可直接使用的原生模型目录；为保护应用签名，未修改应用包。"
                .to_string(),
        );
    }
    if !legacy_filter_recognized {
        return Err("未确认当前 Codex 模型面板结构；已保留原应用，等待运行时验证 Ultra 适配。".to_string());
    }
    let app_dir = prepare_codex_model_picker_app(preferred, deadline)?;
    ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
    let mut result = patch_codex_model_picker_app(&app_dir)?;
    ensure_codex_copy_deadline(deadline).map_err(|error| error.to_string())?;
    let app_path = codex_exe_path(&app_dir);
    if let Some(object) = result.as_object_mut() {
        object.insert("applied".to_string(), Value::Bool(true));
        let native = object.get("nativeModelCatalog").and_then(Value::as_bool) == Some(true);
        object.insert(
            "method".to_string(),
            Value::String(
                if native {
                    "native-model-catalog"
                } else {
                    "asar-byte"
                }
                .to_string(),
            ),
        );
        object.insert("modelPickerEnhanced".to_string(), Value::Bool(true));
        object.insert(
            "appPath".to_string(),
            Value::String(app_path.to_string_lossy().to_string()),
        );
        object.insert(
            "resourcesDir".to_string(),
            Value::String(codex_resources_dir(&app_dir).to_string_lossy().to_string()),
        );
        object.insert("standardShortcuts".to_string(), Value::Array(Vec::new()));
        object.insert("warnings".to_string(), Value::Array(Vec::new()));
        object.insert("needsRestart".to_string(), Value::Bool(true));
    }
    Ok(result)
}
#[allow(dead_code)]
fn queue_codex_model_picker_enhancement(preferred: Vec<PathBuf>) -> Value {
    #[cfg(not(test))]
    {
        let launch_candidates = preferred.clone();
        let _ = thread::Builder::new()
            .name("gaoge-codex-model-picker-background".to_string())
            .spawn(move || {
                let result = try_lock_recover(
                    &CODEX_MODEL_PICKER_ENHANCEMENT_LOCK,
                    "模型下拉增强正在后台处理中。",
                )
                .and_then(|_guard| enhance_codex_model_picker(preferred, None));
                let app_dir = result
                    .as_ref()
                    .ok()
                    .and_then(|value| value.get("appPath"))
                    .and_then(Value::as_str)
                    .map(PathBuf::from)
                    .and_then(|path| path.parent().map(Path::to_path_buf))
                    .or_else(|| choose_launchable_codex_app_dir(launch_candidates));
                if let Some(app_dir) = app_dir {
                    let _ = launch_codex_with_cdp(&app_dir, CODEX_PLUGIN_CDP_DEBUG_PORT);
                }
            });
    }
    #[cfg(test)]
    let _ = preferred;

    json!({
        "applied": false,
        "method": "background",
        "background": true,
        "modelPickerEnhanced": false,
        "needsRestart": false,
        "warnings": Vec::<String>::new(),
    })
}

#[allow(dead_code)]
fn run_plugin_patch(
    app: &AppHandle,
    enabled: bool,
    request: &Value,
    preferred: Vec<PathBuf>,
) -> Result<Value, String> {
    let app_dir = if let Some(resources_dir) = request
        .get("resourcesDir")
        .and_then(Value::as_str)
        .filter(|v| !v.trim().is_empty())
    {
        PathBuf::from(resources_dir)
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from(resources_dir))
    } else {
        choose_or_prepare_patchable_codex_app_dir(preferred)?
    };
    let resources_dir = codex_resources_dir(&app_dir);
    let app_path = codex_exe_path(&app_dir);
    let node = find_codex_node(&resources_dir)
        .ok_or_else(|| format!("没有找到 Codex 自带 node.exe：{}", resources_dir.display()))?;
    let script = resource_file(app, "codex-plugin-patch.cjs")?;
    let payload = json!({
      "resourcesDir": request.get("resourcesDir").and_then(Value::as_str).unwrap_or(resources_dir.to_string_lossy().as_ref()),
      "appPath": request.get("appPath").and_then(Value::as_str).unwrap_or(app_path.to_string_lossy().as_ref())
    });
    let action = if enabled { "patch" } else { "rollback" };
    let mut command = hidden_command(node);
    command
        .arg(&script)
        .arg(action)
        .arg(payload.to_string())
        .current_dir(script.parent().unwrap_or_else(|| Path::new(".")))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let child = command
        .spawn()
        .map_err(|error| format!("运行 Codex 补丁脚本失败：{error}"))?;
    let output = wait_child_output_with_timeout(
        child,
        Duration::from_secs(CODEX_PATCH_PROCESS_TIMEOUT_SECS),
        "Codex patch",
    )?;
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    if !output.status.success() {
        if let Ok(value) = serde_json::from_str::<Value>(&stderr) {
            if let Some(message) = value.get("error").and_then(Value::as_str) {
                return Err(message.to_string());
            }
        }
        return Err(if stderr.is_empty() {
            "Codex 补丁脚本执行失败。".to_string()
        } else {
            stderr
        });
    }
    let parsed: Value = serde_json::from_str(&stdout)
        .map_err(|error| format!("补丁脚本返回无效 JSON：{error}; {stdout}"))?;
    let mut result = parsed.get("result").cloned().unwrap_or(parsed);
    if enabled {
        if let Some(object) = result.as_object_mut() {
            object.insert("standardShortcuts".to_string(), Value::Array(Vec::new()));
        }
    }
    Ok(result)
}

fn plugin_support_error_code(stage: &str, error: &str) -> String {
    let digest = Sha256::digest(format!("{stage}|{error}").as_bytes());
    let hex = format!("{:x}", digest);
    format!("GCP-{}-{}", stage, &hex[..8].to_uppercase())
}

#[allow(dead_code)]
fn plugin_patch_failure_value(enabled: bool, error: String) -> Value {
    let stage = if enabled { "CDP" } else { "CONFIG" };
    let error_code = plugin_support_error_code(stage, &error);
    json!({
      "applied": false,
      "restored": false,
      "degraded": true,
      "recoverable": true,
      "needsRestart": false,
      "patchedFiles": 0,
      "patchActions": 0,
      "alreadyPatchedActions": 0,
      "actions": [],
      "warnings": ["插件入口增强未完成，请联系售后处理。"],
      "errorCode": error_code,
      "errorMessage": error,
    })
}

