#[derive(Clone, Debug)]
struct PreparedCodexAccountActivation {
    account_key: String,
    auth: Value,
    snapshot_path: PathBuf,
}

impl PreparedCodexAccountActivation {
    fn active_snapshot(&self) -> ActiveCodexAccountSnapshot {
        ActiveCodexAccountSnapshot {
            account_key: self.account_key.clone(),
            auth: self.auth.clone(),
            snapshot_path: self.snapshot_path.clone(),
        }
    }
}

fn codex_registry_item_for_key(registry: &Value, account_key: &str) -> Option<Value> {
    registry
        .get("items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items
                .iter()
                .find(|item| item.get("accountKey").and_then(Value::as_str) == Some(account_key))
        })
        .cloned()
}

fn live_auth_matches_active_account(
    auth: &Value,
    active_key: &str,
    active_item: Option<&Value>,
) -> bool {
    if active_key.is_empty() {
        return true;
    }
    if let Some(item) = active_item {
        return auth_matches_account_item(auth, item, active_key);
    }
    auth_account_key(auth) == active_key
}

fn active_codex_account_snapshot() -> Result<Option<ActiveCodexAccountSnapshot>, String> {
    let registry = read_registry()?;
    let active_key = registry
        .get("activeAccountKey")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or("")
        .to_string();
    let active_item = if active_key.is_empty() {
        None
    } else {
        codex_registry_item_for_key(&registry, &active_key)
    };

    if let Some(auth) = read_json_if_exists(&codex_auth_path())? {
        if codex_auth_is_real_account_snapshot(&auth)
            && live_auth_matches_active_account(&auth, &active_key, active_item.as_ref())
        {
            let account = upsert_account(&auth, active_item.as_ref(), true)?;
            let account_key = account
                .get("accountKey")
                .and_then(Value::as_str)
                .ok_or_else(|| "无法识别当前 Codex 账号。".to_string())?
                .to_string();
            let snapshot_path = snapshot_path_for_key(&account_key);
            let stored_auth = read_json_if_exists(&snapshot_path)?;
            let auth = codex_auth_with_newest_credentials(&auth, stored_auth.as_ref());
            return Ok(Some(ActiveCodexAccountSnapshot {
                snapshot_path,
                account_key,
                auth,
            }));
        }
    }

    Ok(None)
}

fn save_current_live_codex_auth_snapshot() -> Result<Option<String>, String> {
    let Some(auth) = read_json_if_exists(&codex_auth_path())? else {
        return Ok(None);
    };
    if !codex_auth_is_real_account_snapshot(&auth) {
        return Ok(None);
    }
    let account = upsert_account(&auth, None, true)?;
    Ok(account
        .get("accountKey")
        .and_then(Value::as_str)
        .map(ToString::to_string))
}

fn prepare_codex_account_activation(
    account_key: &str,
) -> Result<PreparedCodexAccountActivation, String> {
    if account_key.trim().is_empty() {
        return Err("请选择要启用的 Codex 账号。".to_string());
    }
    let _ = save_current_live_codex_auth_snapshot();
    let registry = read_registry()?;
    let item = registry
        .get("items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items
                .iter()
                .find(|item| item.get("accountKey").and_then(Value::as_str) == Some(account_key))
        })
        .cloned()
        .ok_or_else(|| "没有找到该账号。".to_string())?;
    let snapshot_path = item
        .get("snapshotPath")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| snapshot_path_for_key(account_key));
    let snapshot = read_json_if_exists(&snapshot_path)?
        .or_else(|| {
            recover_account_snapshot_from_current_auth(&item, account_key)
                .ok()
                .flatten()
        })
        .ok_or_else(|| {
            "账号登录快照不存在或无法读取；请先点击“添加账号”重建快照，或在 Codex 中重新登录该账号。"
                .to_string()
        })?;
    if !codex_auth_is_real_account_snapshot(&snapshot) {
        return Err(
            "该记录不是可用的真实 Codex 账号快照，请重新导入 ChatGPT Session。".to_string(),
        );
    }
    let fresh_snapshot =
        match ensure_fresh_codex_auth_or_mark(account_key, &snapshot, &snapshot_path) {
            Ok(snapshot) => snapshot,
            Err(error) => {
                // Never delete the live auth merely because token refresh failed.
                // The existing session may still be usable and Codex can retry it;
                // removing auth.json here forces an unnecessary browser login.
                return Err(error);
            }
        };
    let activated_account = upsert_account(&fresh_snapshot, Some(&item), false)?;
    let activated_account_key = activated_account
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or(account_key)
        .to_string();
    Ok(PreparedCodexAccountActivation {
        snapshot_path: snapshot_path_for_key(&activated_account_key),
        account_key: activated_account_key,
        auth: fresh_snapshot,
    })
}

fn commit_codex_account_activation(
    prepared: &PreparedCodexAccountActivation,
) -> Result<(), String> {
    write_json_pretty(&codex_auth_path(), &prepared.auth)?;
    let mut registry = read_registry()?;
    registry["activeAccountKey"] = Value::String(prepared.account_key.clone());
    registry["updatedAt"] = Value::Number(unix_now().into());
    write_registry(&registry)
}

fn sync_codex_auth_from_active_snapshot(
    active: &ActiveCodexAccountSnapshot,
    reason: &str,
) -> Result<Value, String> {
    let current_auth = read_json_if_exists(&codex_auth_path())?;
    if current_auth.as_ref() == Some(&active.auth) {
        return Ok(json!({
          "changed": false,
          "restored": true,
          "source": "active_account",
          "reason": "already_active_account",
          "restoredAccountKey": active.account_key,
          "snapshotPath": active.snapshot_path.to_string_lossy()
        }));
    }

    let backup_path = backup_codex_auth(reason)?;
    write_json_pretty(&codex_auth_path(), &active.auth)?;
    Ok(json!({
      "changed": true,
      "restored": true,
      "source": "active_account",
      "restoredAccountKey": active.account_key,
      "snapshotPath": active.snapshot_path.to_string_lossy(),
      "backupPath": backup_path.map(|path| path.to_string_lossy().to_string())
    }))
}

/// Switch the live ChatGPT account while leaving an already configured relay
/// untouched. Every discovered CODEX_HOME receives the same auth snapshot and
/// active-account marker so a subsequent launch cannot fall back to an older
/// account in a secondary installation.
fn sync_codex_auth_to_all_route_targets(
    active: &ActiveCodexAccountSnapshot,
) -> Result<Vec<Value>, String> {
    let targets = codex_route_targets();
    let transaction = CodexRouteTransactionSnapshot::capture(&targets)?;
    let mut results = Vec::new();
    let mut errors = Vec::new();
    for target in &targets {
        match with_codex_dir(&target.dir, || -> Result<Value, String> {
            let auth = sync_codex_auth_from_active_snapshot(active, "codex-active-account-relay")?;
            let saved = upsert_account(&active.auth, None, true)?;
            let account_key = saved
                .get("accountKey")
                .and_then(Value::as_str)
                .ok_or_else(|| "无法识别切换后的 Codex 账号。".to_string())?;
            codex_relay_restore::select_official_account(account_key)?;
            Ok(json!({
              "codexDir": target.dir.to_string_lossy(),
              "codexDirSource": target.source,
              "primary": target.primary,
              "configPath": codex_config_path().to_string_lossy(),
              "activeAccountAuth": auth,
            }))
        }) {
            Ok(result) => results.push(result),
            Err(error) => {
                errors.push(format!("{}: {error}", target.dir.display()));
                break;
            }
        }
    }
    if !errors.is_empty() {
        let error = errors.join("\n");
        return match transaction.restore() {
            Ok(()) => Err(format!(
                "同步 Codex 中转账号失败：{error}\n已恢复切换前所有可恢复的 Codex 配置目录。"
            )),
            Err(rollback) => Err(format!(
                "同步 Codex 中转账号失败：{error}\n多目录账号切换失败后的自动回滚也未完整完成：{rollback}"
            )),
        };
    }
    if results.is_empty() {
        return Err("没有成功同步任何 Codex 配置目录。".to_string());
    }
    Ok(results)
}

fn codex_relay_configured_for_account_switch() -> bool {
    let state = load_router_state().unwrap_or_else(|_| default_router_state());
    codex_route_targets().iter().any(|target| {
        let config = read_text_if_exists(&target.dir.join("config.toml")).unwrap_or_default();
        let Ok(provider) = codex_configured_session_provider(&config) else {
            return false;
        };
        provider_has_gaoge_route(&config, &provider)
            || provider_has_current_gaoge_route(&config, &provider, &state.relay_base_url)
    })
}

fn codex_account_switch_preserves_relay(request: &Value) -> bool {
    // Account changes preserve the route that is actually configured at the
    // time of the operation. OAuth activation and older callers omit this
    // field; only an explicit false requests a return to the official route.
    request.get("preserveRelay").and_then(Value::as_bool) != Some(false)
        && codex_relay_configured_for_account_switch()
}

fn codex_refresh_snapshot_path(item: &Value, account_key: &str) -> PathBuf {
    item.get("snapshotPath")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| snapshot_path_for_key(account_key))
}

fn capture_codex_snapshot_for_refresh(account_key: &str) -> Result<Option<Value>, String> {
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK,
        "Codex 正在切换账号，请稍后刷新账号快照。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let registry = read_registry()?;
    let Some(item) = codex_registry_item_for_key(&registry, account_key) else {
        return Ok(None);
    };
    if let Some(snapshot) = read_json_if_exists(&codex_refresh_snapshot_path(&item, account_key))? {
        return Ok(Some(snapshot));
    }
    recover_account_snapshot_from_current_auth(&item, account_key)?
        .map(Some)
        .ok_or_else(|| "Codex account snapshot is missing".to_string())
}

fn commit_codex_snapshot_refresh(
    account_key: &str,
    original_auth: &Value,
    refreshed_auth: &Value,
) -> Result<Option<(Value, bool)>, String> {
    // OAuth runs outside this lock. Re-read identity and active selection at
    // commit time: a completed account switch must win over a late refresh.
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK,
        "Codex 正在切换账号，请稍后刷新账号快照。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let registry = read_registry()?;
    let Some(item) = codex_registry_item_for_key(&registry, account_key) else {
        // A refresh must not re-create an account removed while OAuth ran.
        return Ok(None);
    };
    if !codex_auth_is_real_account_snapshot(refreshed_auth)
        || !auth_matches_account_item(refreshed_auth, &item, account_key)
    {
        return Err("Codex 刷新结果与原账号不匹配，已保留当前登录。".to_string());
    }
    let live_auth = read_json_if_exists(&codex_auth_path())?;
    let still_active = registry.get("activeAccountKey").and_then(Value::as_str)
        == Some(account_key);
    // Never activate an account as a side effect of refreshing its snapshot.
    let account = upsert_account(refreshed_auth, Some(&item), false)?;
    let saved_key = account.get("accountKey").and_then(Value::as_str).unwrap_or(account_key);
    let saved_auth = read_json_if_exists(&snapshot_path_for_key(saved_key))?
        .ok_or_else(|| "Codex 账号刷新后的快照不可用。".to_string())?;
    let mut active_live_refreshed = false;
    if let Some(live) = live_auth.as_ref() {
        let same_identity = codex_auth_is_real_account_snapshot(live)
            && auth_matches_account_item(live, &item, account_key);
        let may_replace = codex_saved_auth_is_newer(&saved_auth, live)
            || (live == original_auth && !codex_saved_auth_is_newer(live, &saved_auth));
        if still_active && same_identity && may_replace && saved_auth != *live {
            // Native Codex does not share our configure lock. Respect an auth
            // change observed after the saved snapshot was committed as well.
            if read_json_if_exists(&codex_auth_path())?.as_ref() == Some(live) {
                write_json_pretty_atomic(&codex_auth_path(), &saved_auth)?;
                active_live_refreshed = true;
            }
        }
    }
    Ok(Some((account, active_live_refreshed)))
}

fn mark_codex_snapshot_refresh_failure(
    account_key: &str,
    original_auth: &Value,
    reason: &str,
) -> Result<(), String> {
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK,
        "Codex 正在切换账号，请稍后刷新账号快照。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let registry = read_registry()?;
    let Some(item) = codex_registry_item_for_key(&registry, account_key) else {
        return Ok(());
    };
    let current = read_json_if_exists(&codex_refresh_snapshot_path(&item, account_key))?;
    if current.as_ref() != Some(original_auth) {
        // A late OAuth error says nothing about credentials replaced meanwhile.
        return Ok(());
    }
    if let Some(live) = read_json_if_exists(&codex_auth_path())? {
        if auth_matches_account_item(&live, &item, account_key)
            && codex_saved_auth_is_newer(&live, original_auth)
        {
            return Ok(());
        }
    }
    mark_codex_account_requires_reauth(account_key, reason)
}

fn refresh_codex_account_snapshots_inner() -> Result<Value, String> {
    let registry = {
        let _configure_guard = try_lock_recover(
            &CODEX_CONFIGURE_LOCK,
            "Codex 正在切换账号，请稍后刷新账号快照。",
        )?;
        let _configure_file_lock = acquire_codex_lock("configure")?;
        read_registry()?
    };
    let items = registry
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut refreshed = Vec::new();
    let mut failed = Vec::new();
    let mut skipped = Vec::new();
    let mut active_live_refreshed = false;

    for item in items {
        if registry_item_is_gaoge_api_account(&item) {
            continue;
        }
        let account_key = item
            .get("accountKey")
            .and_then(Value::as_str)
            .unwrap_or("")
            .trim()
            .to_string();
        if account_key.is_empty() {
            skipped.push(json!({ "reason": "missing-account-key" }));
            continue;
        }
        let snapshot = match capture_codex_snapshot_for_refresh(&account_key) {
            Ok(Some(snapshot)) => snapshot,
            Ok(None) => {
                skipped.push(json!({ "accountKey": account_key, "reason": "account-removed" }));
                continue;
            }
            Err(error) => {
                failed.push(json!({ "accountKey": account_key, "message": error }));
                continue;
            }
        };
        if !codex_auth_is_real_account_snapshot(&snapshot) {
            skipped.push(json!({
              "accountKey": account_key,
              "reason": "not-codex-account"
            }));
            continue;
        }

        let was_stale =
            !codex_auth_tokens_are_fresh(&snapshot, unix_now(), CODEX_AUTH_REFRESH_SKEW_SECS);
        // Refresh only in memory. Neither credentials nor registry selection
        // may be written until the short guarded commit below rechecks them.
        let refreshed_auth = if was_stale {
            refresh_codex_auth_tokens(&snapshot)
        } else {
            Ok(snapshot.clone())
        };
        match refreshed_auth {
            Ok(fresh_snapshot) => match commit_codex_snapshot_refresh(
                &account_key, &snapshot, &fresh_snapshot,
            ) {
                Ok(Some((account, live_refreshed))) => {
                    active_live_refreshed |= live_refreshed;
                    refreshed.push(json!({
                      "accountKey": account.get("accountKey").and_then(Value::as_str).unwrap_or(account_key.as_str()),
                      "email": account.get("email").and_then(Value::as_str).unwrap_or(""),
                      "refreshed": was_stale,
                      "tokenStatus": account.get("tokenStatus").cloned().unwrap_or(Value::Null)
                    }));
                }
                Ok(None) => {
                    skipped.push(json!({ "accountKey": account_key, "reason": "account-removed" }));
                }
                Err(error) => {
                    let reason = format!("Codex 账号快照写入失败：{error}");
                    failed.push(json!({
                      "accountKey": account_key,
                      "message": reason
                    }));
                }
            },
            Err(error) => {
                let reason = codex_snapshot_refresh_failure_message(&error);
                if codex_refresh_failure_requires_reauth(&error) {
                    let _ = mark_codex_snapshot_refresh_failure(&account_key, &snapshot, &reason);
                }
                failed.push(json!({
                  "accountKey": account_key,
                  "message": reason
                }));
            }
        }
    }

    Ok(json!({
      "refreshed": refreshed,
      "failed": failed,
      "skipped": skipped,
      "activeLiveRefreshed": active_live_refreshed,
      "state": accounts_state_from_snapshot(capture_codex_accounts_state_for_request()?)
    }))
}

#[tauri::command]
async fn gaoge_refresh_codex_account_snapshots() -> Result<Value, String> {
    run_blocking_task(refresh_codex_account_snapshots_inner).await
}

fn read_usage_store_by_account_key() -> Result<Map<String, Value>, String> {
    let mut by_key = Map::new();
    let Some(store) = read_json_if_exists(&codex_usage_store_path())? else {
        return Ok(by_key);
    };
    let items = store
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    for item in items {
        let Some(account_key) = item
            .get("accountKey")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        by_key.insert(account_key.to_string(), json!({
      "primaryWindow": item.get("primaryWindow").cloned().unwrap_or(Value::Null),
      "secondaryWindow": item.get("secondaryWindow").cloned().unwrap_or(Value::Null),
      "usageSource": item.get("usageSource").and_then(Value::as_str).unwrap_or("gaoge-cache"),
      "lastUsageAt": item.get("capturedAt").cloned().unwrap_or(Value::Null),
      "tokenStatus": item.get("tokenStatus").cloned().unwrap_or(Value::Null),
      "plan": item.get("plan").and_then(Value::as_str).unwrap_or(""),
      "email": item.get("email").and_then(Value::as_str).unwrap_or("")
    }));
    }
    Ok(by_key)
}

fn write_codex_usage_snapshot(account_key: &str, usage: &Value) -> Result<(), String> {
    if account_key.is_empty() || !usage.is_object() {
        return Ok(());
    }
    let store = read_json_if_exists(&codex_usage_store_path())?.unwrap_or_else(|| json!({}));
    let mut items: Vec<Value> = store
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .filter(|item| item.get("accountKey").and_then(Value::as_str) != Some(account_key))
        .collect();
    items.push(json!({
      "accountKey": account_key,
      "capturedAt": usage.get("lastUsageAt").cloned().unwrap_or_else(|| json!(unix_now())),
      "usageSource": usage.get("usageSource").and_then(Value::as_str).unwrap_or("official-wham"),
      "plan": usage.get("plan").and_then(Value::as_str).unwrap_or(""),
      "email": usage.get("email").and_then(Value::as_str).unwrap_or(""),
      "primaryWindow": usage.get("primaryWindow").cloned().unwrap_or(Value::Null),
      "secondaryWindow": usage.get("secondaryWindow").cloned().unwrap_or(Value::Null),
      "tokenStatus": usage.get("tokenStatus").cloned().unwrap_or(Value::Null)
    }));
    write_json_pretty(
        &codex_usage_store_path(),
        &json!({
          "schemaVersion": 1,
          "updatedAt": unix_now(),
          "items": items
        }),
    )
}

fn fetch_official_codex_usage(
    auth: &Value,
    auth_file_path: &Path,
    account_key: &str,
) -> Result<Value, String> {
    let next_auth = ensure_fresh_codex_usage_auth(auth, auth_file_path)?;
    let access_token = next_auth
        .get("tokens")
        .and_then(|tokens| tokens.get("access_token"))
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "Codex account has no access token".to_string())?;
    let account_id = codex_auth_account_id(&next_auth);

    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(ACCOUNT_USAGE_TIMEOUT_SECS))
        .build()
        .map_err(|error| format!("create http client failed: {error}"))?;
    let mut request = client
        .get(format!("{CHATGPT_BACKEND_BASE_URL}/wham/usage"))
        .bearer_auth(access_token)
        .header(reqwest::header::ACCEPT, "application/json")
        .header(reqwest::header::USER_AGENT, "codex-cli");
    if !account_id.is_empty() {
        request = request.header("ChatGPT-Account-Id", account_id);
    }
    let response = request
        .send()
        .map_err(|error| format!("fetch Codex usage failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!(
            "fetch Codex usage failed: HTTP {}",
            response.status().as_u16()
        ));
    }
    let payload: Value = response
        .json()
        .map_err(|error| format!("Codex usage JSON failed: {error}"))?;
    let rate_limit = payload.get("rate_limit").unwrap_or(&Value::Null);
    let plan = payload
        .get("plan_type")
        .and_then(Value::as_str)
        .or_else(|| {
            payload
                .get("plan")
                .and_then(|plan| plan.get("plan_type"))
                .and_then(Value::as_str)
        })
        .or_else(|| {
            payload
                .get("account")
                .and_then(|account| account.get("plan_type"))
                .and_then(Value::as_str)
        })
        .map(normalize_codex_plan_value)
        .unwrap_or_default();
    let usage = json!({
      "plan": plan,
      "email": payload.get("email").and_then(Value::as_str).unwrap_or(""),
      "primaryWindow": normalize_usage_window(rate_limit.get("primary_window")),
      "secondaryWindow": normalize_usage_window(rate_limit.get("secondary_window")),
      "usageSource": "official-wham",
      "lastUsageAt": unix_now(),
      "tokenStatus": account_summary_from_auth(&next_auth, None).get("tokenStatus").cloned().unwrap_or_else(|| json!({ "code": "unknown" }))
    });
    let usage_key = if account_key.is_empty() {
        auth_account_key(&next_auth)
    } else {
        account_key.to_string()
    };
    write_codex_usage_snapshot(&usage_key, &usage)?;
    Ok(usage)
}

fn read_codex_usage_for_auth(
    auth: &Value,
    account_key: &str,
    auth_file_path: &Path,
    cached_usage: &Value,
) -> Value {
    let auth = auth.clone();
    let account_key = account_key.to_string();
    let auth_file_path = auth_file_path.to_path_buf();
    let cached_usage = cached_usage.clone();
    let (sender, receiver) = mpsc::channel();
    thread::spawn(move || {
        let _ = sender.send(fetch_official_codex_usage(
            &auth,
            &auth_file_path,
            &account_key,
        ));
    });
    receiver
        .recv_timeout(Duration::from_secs(CODEX_USAGE_REFRESH_WAIT_SECS))
        .ok()
        .and_then(Result::ok)
        .unwrap_or(cached_usage)
}

fn merge_account_usage(account: &Value, summary: &Value, quota: &Value, active_key: &str) -> Value {
    let mut object = account.as_object().cloned().unwrap_or_default();
    if let Some(summary_object) = summary.as_object() {
        for (key, value) in summary_object {
            object.entry(key.clone()).or_insert_with(|| value.clone());
        }
    }
    if let Some(quota_object) = quota.as_object() {
        for key in [
            "primaryWindow",
            "secondaryWindow",
            "usageSource",
            "lastUsageAt",
            "tokenStatus",
        ] {
            if let Some(value) = quota_object.get(key) {
                object.insert(key.to_string(), value.clone());
            }
        }
        if let Some(email) = quota_object
            .get("email")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        {
            object.insert("email".to_string(), Value::String(email.to_string()));
        }
    }
    let stored_plan = object.get("plan").and_then(Value::as_str).unwrap_or("");
    let official_plan = quota.get("plan").and_then(Value::as_str).unwrap_or("");
    let fallback_plan = summary.get("plan").and_then(Value::as_str).unwrap_or("");
    let plan = choose_codex_plan(stored_plan, official_plan, fallback_plan);
    let plan_key = codex_plan_key(&plan);
    if is_paid_codex_plan(&plan) {
        if !object
            .get("hasActiveSubscription")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            object.insert("hasActiveSubscription".to_string(), Value::Bool(true));
        }
    } else if plan_key == "free" || plan_key == "chatgptfree" {
        object.insert("hasActiveSubscription".to_string(), Value::Bool(false));
        object.insert("subscriptionExpiresAt".to_string(), Value::Null);
        object.insert("subscriptionWillRenew".to_string(), Value::Null);
    }
    object.insert("plan".to_string(), Value::String(plan));
    public_account(&Value::Object(object), active_key)
}

fn auth_matches_account_item(auth: &Value, item: &Value, account_key: &str) -> bool {
    let summary = account_summary_from_auth(auth, None);
    let auth_key = summary
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("");
    if !auth_key.is_empty() && auth_key == account_key {
        return true;
    }
    if identity_matches(item, &summary) {
        return true;
    }
    if !is_legacy_email_only_item(item) {
        return false;
    }

    let item_email = item
        .get("email")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    let auth_email = summary
        .get("email")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    !item_email.is_empty() && !auth_email.is_empty() && item_email.eq_ignore_ascii_case(auth_email)
}

fn recover_account_snapshot_from_current_auth(
    item: &Value,
    account_key: &str,
) -> Result<Option<Value>, String> {
    let Some(auth) = read_json_if_exists(&codex_auth_path())? else {
        return Ok(None);
    };
    if !codex_auth_is_real_account_snapshot(&auth) {
        return Ok(None);
    }
    if !auth_matches_account_item(&auth, item, account_key) {
        return Ok(None);
    }
    let _ = upsert_account(&auth, Some(item), false)?;
    Ok(Some(auth))
}

struct CodexAccountsStateSnapshot {
    registry: Value,
    live_auth: Option<Value>,
    accounts: Vec<(Value, Value, PathBuf)>,
    usage_by_key: Map<String, Value>,
}

fn capture_codex_accounts_state() -> Result<CodexAccountsStateSnapshot, String> {
    let mut registry = read_registry()?;
    let live_auth = read_json_if_exists(&codex_auth_path())?
        .filter(|auth| codex_auth_is_real_account_snapshot(auth));
    if let Some(auth) = live_auth.as_ref() {
        let _ = upsert_account(auth, None, true);
        registry = read_registry()?;
    }
    let usage_by_key = read_usage_store_by_account_key()?;
    let accounts = registry
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .filter_map(|account| {
            if registry_item_is_gaoge_api_account(&account) {
                return None;
            }
            let account_key = account
                .get("accountKey")
                .and_then(Value::as_str)
                .unwrap_or("");
            if account_key.is_empty() {
                return None;
            }
            let snapshot_with_path = if let Some(snapshot_path) = account
                .get("snapshotPath")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
            {
                match read_json_if_exists(Path::new(snapshot_path)) {
                    Ok(Some(snapshot)) if codex_auth_is_real_account_snapshot(&snapshot) => {
                        Some((snapshot, PathBuf::from(snapshot_path)))
                    }
                    _ => None,
                }
            } else if let Ok(Some(snapshot)) =
                recover_account_snapshot_from_current_auth(&account, account_key)
            {
                if codex_auth_is_real_account_snapshot(&snapshot) {
                    Some((snapshot, snapshot_path_for_key(account_key)))
                } else {
                    None
                }
            } else {
                None
            };
            snapshot_with_path.map(|(snapshot, path)| (account, snapshot, path))
        })
        .collect();
    Ok(CodexAccountsStateSnapshot { registry, live_auth, accounts, usage_by_key })
}

fn capture_codex_accounts_state_for_request() -> Result<CodexAccountsStateSnapshot, String> {
    // The live-auth read and registry upsert must share the configure lock
    // with account switches. Release it before any usage/network requests.
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK,
        "Codex 正在切换账号，请稍后刷新账号列表。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    capture_codex_accounts_state()
}

fn accounts_state_from_snapshot(snapshot: CodexAccountsStateSnapshot) -> Value {
    let CodexAccountsStateSnapshot { registry, live_auth, accounts, usage_by_key } = snapshot;
    let live_account_key = live_auth.as_ref().map(auth_account_key).unwrap_or_default();
    let saved_active_key = registry
        .get("activeAccountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let should_refresh_usage = registry
        .get("api")
        .and_then(|api| api.get("usageRefreshEnabled"))
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let accounts: Vec<Value> = accounts
        .into_iter()
        .map(|(account, snapshot, snapshot_path)| {
            let account_key = account.get("accountKey").and_then(Value::as_str).unwrap_or("");
            let cached_usage = usage_by_key.get(account_key).cloned().unwrap_or_else(|| json!({}));
            let mut quota = cached_usage.clone();
            let summary = account_summary_from_auth(&snapshot, Some(&account));
            let is_live_current = live_auth
                .as_ref()
                .is_some_and(|auth| auth_matches_account_item(auth, &account, account_key));
            if should_refresh_usage && is_live_current {
                quota = read_codex_usage_for_auth(
                    &snapshot,
                    account_key,
                    &snapshot_path,
                    &cached_usage,
                );
            }
            let mut public_account = merge_account_usage(
                &account,
                &summary,
                &quota,
                if is_live_current { account_key } else { "" },
            );
            annotate_account_login_state(&mut public_account, &snapshot, is_live_current);
            public_account
        })
        .collect();
    let current_account = accounts
        .iter()
        .find(|account| {
            account
                .get("isActive")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .cloned()
        .unwrap_or(Value::Null);
    json!({
      "authPath": codex_auth_path().to_string_lossy(),
      "registryPath": codex_registry_path().to_string_lossy(),
      "activeAccountKey": live_account_key,
      "savedActiveAccountKey": saved_active_key,
      "currentAccount": current_account,
      "accounts": accounts
    })
}

fn get_accounts_state_inner() -> Result<Value, String> {
    // Internal configuration callers already hold the configure lock.
    Ok(accounts_state_from_snapshot(capture_codex_accounts_state()?))
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct RolloutSummary {
    id: String,
    path: PathBuf,
    provider: String,
    timestamp_ms: i64,
    source: String,
    thread_source: String,
    cwd: String,
    title: String,
    has_user_event: bool,
    cli_version: String,
    model: Option<String>,
    reasoning_effort: Option<String>,
    #[serde(default)]
    parent_thread_id: Option<String>,
    #[serde(default)]
    agent_nickname: Option<String>,
    #[serde(default)]
    agent_role: Option<String>,
    #[serde(default)]
    agent_path: Option<String>,
    #[serde(default)]
    subagent_depth: Option<i64>,
    archived: bool,
    line_count: usize,
    #[serde(default)]
    first_ordinal: Option<i64>,
    #[serde(default)]
    last_ordinal: Option<i64>,
    /// Whether the whole JSONL body has been inspected.  Fast session
    /// synchronization intentionally fills summaries from the header/tail;
    /// those summaries remain valid for listing and provider switching but
    /// must not be treated as a complete legacy-format audit.
    #[serde(default = "default_body_scanned")]
    body_scanned: bool,
    /// Thread this rollout continues from (`history_base.thread_id`). When set,
    /// the referenced rollout is an immutable prefix: its byte length must not
    /// change, or this file's stored `end_byte_offset` falls past its end.
    #[serde(default)]
    history_base_thread_id: Option<String>,
    /// `history_base.end_byte_offset` recorded by the branch. Kept for reporting;
    /// the repair never shrinks it to hide a truncated source.
    #[serde(default)]
    history_base_end_byte_offset: Option<u64>,
}

fn default_body_scanned() -> bool {
    true
}

fn is_hidden_codex_thread_source(thread_source: &str) -> bool {
    matches!(thread_source.trim(), "subagent" | "guardian_review")
}

impl RolloutSummary {
    fn is_subagent(&self) -> bool {
        is_hidden_codex_thread_source(&self.thread_source) || self.parent_thread_id.is_some()
    }

    fn sqlite_thread_source(&self) -> &str {
        if is_hidden_codex_thread_source(&self.thread_source) {
            "subagent"
        } else {
            self.thread_source.as_str()
        }
    }
}

fn rollout_is_better_canonical(candidate: &RolloutSummary, current: &RolloutSummary) -> bool {
    let candidate_rank = (
        candidate.timestamp_ms,
        candidate.has_user_event,
        !candidate.archived,
        candidate.line_count,
    );
    let current_rank = (
        current.timestamp_ms,
        current.has_user_event,
        !current.archived,
        current.line_count,
    );
    candidate_rank > current_rank
        || (candidate_rank == current_rank
            && codex_path_identity(&candidate.path) < codex_path_identity(&current.path))
}

#[cfg(test)]
fn canonical_rollout_summaries(rollouts: &[RolloutSummary]) -> Vec<RolloutSummary> {
    let mut by_id: HashMap<String, RolloutSummary> = HashMap::new();
    for rollout in rollouts {
        let id = rollout.id.trim();
        if id.is_empty() {
            continue;
        }
        match by_id.get_mut(id) {
            Some(current) if rollout_is_better_canonical(rollout, current) => {
                *current = rollout.clone();
            }
            None => {
                by_id.insert(id.to_string(), rollout.clone());
            }
            Some(_) => {}
        }
    }
    let mut canonical = by_id.into_values().collect::<Vec<_>>();
    canonical.sort_by(|left, right| {
        left.id
            .cmp(&right.id)
            .then_with(|| codex_path_identity(&left.path).cmp(&codex_path_identity(&right.path)))
    });
    canonical
}

fn rollout_event_ordinal(value: &Value) -> Option<i64> {
    match value.get("ordinal") {
        Some(Value::Number(number)) => number.as_i64(),
        Some(Value::String(text)) => text.trim().parse::<i64>().ok(),
        _ => None,
    }
}

fn is_managed_canonical_rollout_path(path: &Path) -> bool {
    path.components().any(|component| {
        component
            .as_os_str()
            .to_string_lossy()
            .eq_ignore_ascii_case(CODEX_CANONICAL_ROLLOUT_DIR)
    })
}

/// The official Codex thread store only accepts the timestamp/thread-id
/// rollout basename for paginated history. Older internal cache names do not
/// satisfy this parser and must never be written to `threads.rollout_path`.
fn is_official_rollout_filename(path: &Path) -> bool {
    official_rollout_ids(path).is_some()
}

fn is_official_uuid_component(value: &str) -> bool {
    let value = value.trim();
    match value.len() {
        // `Uuid::parse_str` also accepts the compact 32-hex representation.
        32 => value.bytes().all(|byte| byte.is_ascii_hexdigit()),
        // RolloutFileName::render emits the canonical hyphenated form.
        36 => value.bytes().enumerate().all(|(index, byte)| {
            matches!(index, 8 | 13 | 18 | 23)
                .then_some(byte == b'-')
                .unwrap_or_else(|| byte.is_ascii_hexdigit())
        }),
        _ => false,
    }
}

fn official_rollout_ids(path: &Path) -> Option<(&str, &str)> {
    let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
        return None;
    };
    let Some(core) = name
        .strip_prefix("rollout-")
        .and_then(|value| value.strip_suffix(".jsonl"))
    else {
        return None;
    };
    if core.len() < 20 || core.as_bytes().get(19) != Some(&b'-') {
        return None;
    }
    let timestamp = &core[..19];
    if NaiveDateTime::parse_from_str(timestamp, "%Y-%m-%dT%H-%M-%S").is_err() {
        return None;
    }
    let ids = &core[20..];
    let (thread_id, rollout_id) = ids.split_once('_').unwrap_or((ids, ids));
    if is_official_uuid_component(thread_id) && is_official_uuid_component(rollout_id) {
        Some((thread_id, rollout_id))
    } else {
        None
    }
}

fn is_compatible_canonical_rollout_path(path: &Path, session_id: &str) -> bool {
    is_managed_canonical_rollout_path(path)
        && official_rollout_ids(path).is_some_and(|(thread_id, _)| thread_id == session_id.trim())
}

fn canonical_rollout_id_component(session_id: &str, variant: &str) -> String {
    // Keep the deterministic fallback UUID-shaped and RFC 4122 compatible;
    // the official resolver validates the filename components as UUIDs.
    let mut digest = Sha256::digest(format!("gaoge-canonical:{variant}:{session_id}").as_bytes());
    digest[6] = (digest[6] & 0x0f) | 0x40;
    digest[8] = (digest[8] & 0x3f) | 0x80;
    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        digest[0],
        digest[1],
        digest[2],
        digest[3],
        digest[4],
        digest[5],
        digest[6],
        digest[7],
        digest[8],
        digest[9],
        digest[10],
        digest[11],
        digest[12],
        digest[13],
        digest[14],
        digest[15]
    )
}

fn official_rollout_timestamp(timestamp_ms: i64) -> String {
    Local
        .timestamp_millis_opt(timestamp_ms)
        .single()
        .unwrap_or_else(Local::now)
        .format("%Y-%m-%dT%H-%M-%S")
        .to_string()
}

fn official_rollout_path(
    session_id: &str,
    timestamp_ms: i64,
    archived: bool,
    variant: &str,
) -> PathBuf {
    let session_id = session_id.trim();
    let safe_session_id = if is_official_uuid_component(session_id) {
        session_id.to_owned()
    } else {
        // Keep malformed/legacy IDs out of path components while retaining a
        // UUID-shaped thread component for the official filename parser.
        canonical_rollout_id_component(session_id, "thread")
    };
    let root = if archived {
        codex_dir().join("archived_sessions")
    } else {
        codex_dir().join("sessions")
    };
    let date = official_rollout_timestamp(timestamp_ms);
    let rollout_id = canonical_rollout_id_component(session_id, variant);
    root.join(CODEX_CANONICAL_ROLLOUT_DIR).join(format!(
        "rollout-{date}-{safe_session_id}_{rollout_id}.jsonl"
    ))
}

fn compatible_rollout_path_for_segments(
    session_id: &str,
    segments: &[&RolloutSummary],
    metadata_source: &RolloutSummary,
) -> PathBuf {
    // Reuse a previously generated compatible copy when present.  This keeps
    // repeated background passes idempotent and avoids creating a new SQLite
    // path on every provider switch.
    if let Some(existing) = segments
        .iter()
        .find(|segment| is_compatible_canonical_rollout_path(&segment.path, session_id))
    {
        return existing.path.clone();
    }
    if let Some(source) = segments.iter().find(|segment| {
        !is_managed_canonical_rollout_path(&segment.path)
            && is_official_rollout_filename(&segment.path)
    }) {
        if let Some(name) = source.path.file_name() {
            return codex_dir()
                .join(if metadata_source.archived {
                    "archived_sessions"
                } else {
                    "sessions"
                })
                .join(CODEX_CANONICAL_ROLLOUT_DIR)
                .join(name);
        }
    }
    let candidate = official_rollout_path(
        session_id,
        metadata_source.timestamp_ms,
        metadata_source.archived,
        "primary",
    );
    let occupied = segments
        .iter()
        .any(|segment| codex_path_identity(&segment.path) == codex_path_identity(&candidate));
    if !occupied {
        return candidate;
    }
    official_rollout_path(
        session_id,
        metadata_source.timestamp_ms,
        metadata_source.archived,
        "fallback",
    )
}

fn canonical_rollout_temp_path(target: &Path) -> PathBuf {
    target.with_file_name(format!(
        ".gaoge-canonical-tmp-{}-{}-{}",
        std::process::id(),
        timestamp_for_path(),
        TEMP_WRITE_SEQUENCE.fetch_add(1, Ordering::Relaxed)
    ))
}

fn rollout_event_identity(value: &Value) -> String {
    let payload = value.get("payload").unwrap_or(&Value::Null);
    let event_type = value
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let payload_type = payload
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let stable_id = value
        .get("id")
        .or_else(|| payload.get("id"))
        .or_else(|| payload.get("event_id"))
        .or_else(|| payload.get("item").and_then(|item| item.get("id")))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty());
    if let Some(stable_id) = stable_id {
        return format!("id:{event_type}:{payload_type}:{stable_id}");
    }
    let mut normalized_value = value.clone();
    if let Some(object) = normalized_value.as_object_mut() {
        object.remove("ordinal");
    }
    let normalized = serde_json::to_vec(&normalized_value).unwrap_or_default();
    format!("sha256:{:x}", Sha256::digest(&normalized))
}

fn rollout_event_timestamp_millis(value: &Value) -> Option<i64> {
    parse_timestamp_millis(value.get("timestamp"))
}

#[derive(Clone, Debug)]
struct CanonicalRolloutEventRef {
    timestamp_ms: Option<i64>,
    segment_index: usize,
    line_index: usize,
    byte_offset: u64,
    byte_len: usize,
    identity: String,
}

fn read_rollout_session_meta(path: &Path) -> Result<Value, String> {
    let source = fs::File::open(path)
        .map_err(|error| format!("读取会话元数据失败 {}：{error}", path.display()))?;
    let mut reader = BufReader::with_capacity(256 * 1024, source);
    let mut line = String::new();
    loop {
        line.clear();
        if reader
            .read_line(&mut line)
            .map_err(|error| format!("读取会话元数据失败 {}：{error}", path.display()))?
            == 0
        {
            break;
        }
        if let Some(meta) = session_meta_value_from_line(&line) {
            return Ok(meta);
        }
    }
    Err(format!(
        "会话分段缺少有效 session_meta，无法生成完整历史：{}",
        path.display()
    ))
}

fn canonical_session_meta(
    earliest_source: &RolloutSummary,
    latest_source: &RolloutSummary,
) -> Result<Value, String> {
    let mut earliest = read_rollout_session_meta(&earliest_source.path)?;
    let latest =
        if codex_path_identity(&earliest_source.path) == codex_path_identity(&latest_source.path) {
            earliest.clone()
        } else {
            read_rollout_session_meta(&latest_source.path)?
        };
    if let (Some(earliest_payload), Some(latest_payload)) = (
        earliest.get_mut("payload").and_then(Value::as_object_mut),
        latest.get("payload").and_then(Value::as_object),
    ) {
        // Keep the earliest session identity and creation timestamp. Only copy
        // fields that legitimately describe the current routing/location.
        for key in [
            "model_provider",
            "cwd",
            "cli_version",
            "source",
            "thread_source",
            "parent_thread_id",
            "agent_nickname",
            "agent_role",
            "agent_path",
            "subagent_depth",
            "model",
            "model_reasoning_effort",
            "reasoning_effort",
            "title",
        ] {
            if let Some(value) = latest_payload.get(key) {
                let usable = match value {
                    Value::Null => false,
                    Value::String(text) => !text.trim().is_empty(),
                    _ => true,
                };
                if usable {
                    earliest_payload.insert(key.to_string(), value.clone());
                }
            }
        }
    }
    if let Some(object) = earliest.as_object_mut() {
        object.insert("ordinal".to_string(), Value::Number(0.into()));
    }
    Ok(earliest)
}

fn files_have_same_contents(left: &Path, right: &Path) -> Result<bool, String> {
    let left_metadata = fs::metadata(left)
        .map_err(|error| format!("读取文件状态失败 {}：{error}", left.display()))?;
    let right_metadata = match fs::metadata(right) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(error) => return Err(format!("读取文件状态失败 {}：{error}", right.display())),
    };
    if left_metadata.len() != right_metadata.len() {
        return Ok(false);
    }
    let mut left_reader = BufReader::with_capacity(
        256 * 1024,
        fs::File::open(left)
            .map_err(|error| format!("读取文件失败 {}：{error}", left.display()))?,
    );
    let mut right_reader = BufReader::with_capacity(
        256 * 1024,
        fs::File::open(right)
            .map_err(|error| format!("读取文件失败 {}：{error}", right.display()))?,
    );
    let mut left_buffer = [0u8; 64 * 1024];
    let mut right_buffer = [0u8; 64 * 1024];
    loop {
        let left_read = left_reader
            .read(&mut left_buffer)
            .map_err(|error| format!("读取文件失败 {}：{error}", left.display()))?;
        let right_read = right_reader
            .read(&mut right_buffer)
            .map_err(|error| format!("读取文件失败 {}：{error}", right.display()))?;
        if left_read != right_read || left_buffer[..left_read] != right_buffer[..right_read] {
            return Ok(false);
        }
        if left_read == 0 {
            return Ok(true);
        }
    }
}

fn materialize_canonical_rollout(
    session_id: &str,
    segments: &[&RolloutSummary],
    metadata_source: &RolloutSummary,
) -> Result<(RolloutSummary, bool, Option<String>), String> {
    // The merged file itself must keep an official Codex filename.  The
    // `.gaoge-canonical` directory remains an internal cache only; paths
    // written to SQLite are validated by Codex's strict timestamp/UUID parser.
    let target = compatible_rollout_path_for_segments(session_id, segments, metadata_source);
    ensure_parent(&target)?;
    let mut ordered = segments.to_vec();
    ordered.sort_by(|left, right| {
        is_managed_canonical_rollout_path(&left.path)
            .cmp(&is_managed_canonical_rollout_path(&right.path))
            .then_with(|| {
                left.first_ordinal
                    .is_none()
                    .cmp(&right.first_ordinal.is_none())
            })
            .then_with(|| {
                left.first_ordinal
                    .unwrap_or(i64::MAX)
                    .cmp(&right.first_ordinal.unwrap_or(i64::MAX))
            })
            .then_with(|| {
                left.last_ordinal
                    .unwrap_or(i64::MAX)
                    .cmp(&right.last_ordinal.unwrap_or(i64::MAX))
            })
            .then_with(|| left.timestamp_ms.cmp(&right.timestamp_ms))
            .then_with(|| codex_path_identity(&left.path).cmp(&codex_path_identity(&right.path)))
    });
    let guards = ordered
        .iter()
        .map(|segment| file_write_guard(&segment.path).map(|guard| (segment.path.clone(), guard)))
        .collect::<Result<Vec<_>, _>>()?;
    let metadata_base_candidates = ordered
        .iter()
        .copied()
        .filter(|segment| !is_managed_canonical_rollout_path(&segment.path))
        .collect::<Vec<_>>();
    let metadata_base_candidates = if metadata_base_candidates.is_empty() {
        ordered.clone()
    } else {
        metadata_base_candidates
    };
    let mut earliest_metadata_source = metadata_base_candidates[0];
    let mut earliest_metadata_timestamp = read_rollout_session_meta(&earliest_metadata_source.path)
        .ok()
        .and_then(|meta| {
            parse_timestamp_millis(meta.get("timestamp")).or_else(|| {
                meta.get("payload")
                    .and_then(|payload| parse_timestamp_millis(payload.get("timestamp")))
            })
        });
    for candidate in metadata_base_candidates.into_iter().skip(1) {
        let candidate_timestamp =
            read_rollout_session_meta(&candidate.path)
                .ok()
                .and_then(|meta| {
                    parse_timestamp_millis(meta.get("timestamp")).or_else(|| {
                        meta.get("payload")
                            .and_then(|payload| parse_timestamp_millis(payload.get("timestamp")))
                    })
                });
        let candidate_rank = (
            candidate_timestamp.is_none(),
            candidate_timestamp.unwrap_or(i64::MAX),
            codex_path_identity(&candidate.path),
        );
        let current_rank = (
            earliest_metadata_timestamp.is_none(),
            earliest_metadata_timestamp.unwrap_or(i64::MAX),
            codex_path_identity(&earliest_metadata_source.path),
        );
        if candidate_rank < current_rank {
            earliest_metadata_source = candidate;
            earliest_metadata_timestamp = candidate_timestamp;
        }
    }
    let session_meta = canonical_session_meta(earliest_metadata_source, metadata_source)?;

    // Do not repeat the SHA-256 target name in the temporary filename. That
    // can cross the legacy Win32 path limit even when the final path is valid.
    let temp_path = canonical_rollout_temp_path(&target);
    let write_result = (|| -> Result<(), String> {
        let mut events = Vec::new();
        for (segment_index, segment) in ordered.iter().enumerate() {
            if codex_background_merge_should_yield() {
                return Err("前台会话同步已开始，后台 canonical 合并让路。".to_string());
            }
            let source = fs::File::open(&segment.path)
                .map_err(|error| format!("读取会话分段失败 {}：{error}", segment.path.display()))?;
            let mut reader = BufReader::with_capacity(256 * 1024, source);
            let mut line = String::new();
            let mut line_index = 0usize;
            let mut byte_offset = 0u64;
            loop {
                line.clear();
                let byte_len = reader.read_line(&mut line).map_err(|error| {
                    format!("读取会话分段失败 {}：{error}", segment.path.display())
                })?;
                if byte_len == 0 {
                    break;
                }
                if line_index % 4096 == 0 && codex_background_merge_should_yield() {
                    return Err("前台会话同步已开始，后台 canonical 合并让路。".to_string());
                }
                line_index += 1;
                let current_offset = byte_offset;
                byte_offset = byte_offset.saturating_add(byte_len as u64);
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }
                let value = serde_json::from_str::<Value>(trimmed).map_err(|error| {
                    format!(
                        "会话分段存在无效 JSON，已停止 canonical 合并 {} 第 {line_index} 行：{error}",
                        segment.path.display()
                    )
                })?;
                if value.get("type").and_then(Value::as_str) == Some("session_meta") {
                    continue;
                }
                events.push(CanonicalRolloutEventRef {
                    timestamp_ms: rollout_event_timestamp_millis(&value),
                    segment_index,
                    line_index,
                    byte_offset: current_offset,
                    byte_len,
                    identity: rollout_event_identity(&value),
                });
            }
        }
        events.sort_by(|left, right| {
            left.timestamp_ms
                .is_none()
                .cmp(&right.timestamp_ms.is_none())
                .then_with(|| {
                    left.timestamp_ms
                        .unwrap_or(i64::MAX)
                        .cmp(&right.timestamp_ms.unwrap_or(i64::MAX))
                })
                .then_with(|| left.segment_index.cmp(&right.segment_index))
                .then_with(|| left.line_index.cmp(&right.line_index))
        });

        let output = fs::File::create(&temp_path).map_err(|error| {
            format!(
                "创建 canonical 会话临时文件失败 {}：{error}",
                temp_path.display()
            )
        })?;
        let mut writer = BufWriter::with_capacity(256 * 1024, output);
        serde_json::to_writer(&mut writer, &session_meta)
            .map_err(|error| format!("写入 canonical session_meta 失败：{error}"))?;
        writer
            .write_all(b"\n")
            .map_err(|error| format!("写入 canonical 会话失败 {}：{error}", temp_path.display()))?;
        let mut sources = ordered
            .iter()
            .map(|segment| {
                fs::File::open(&segment.path).map_err(|error| {
                    format!("读取会话分段失败 {}：{error}", segment.path.display())
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        let mut emitted_identities = HashSet::new();
        let mut emitted_events = 0usize;
        for event in events {
            if emitted_events % 4096 == 0 && codex_background_merge_should_yield() {
                return Err("前台会话同步已开始，后台 canonical 合并让路。".to_string());
            }
            if !emitted_identities.insert(event.identity) {
                continue;
            }
            let source = &mut sources[event.segment_index];
            source
                .seek(SeekFrom::Start(event.byte_offset))
                .map_err(|error| {
                    format!(
                        "定位会话分段失败 {} 第 {} 行：{error}",
                        ordered[event.segment_index].path.display(),
                        event.line_index
                    )
                })?;
            let mut bytes = vec![0u8; event.byte_len];
            source.read_exact(&mut bytes).map_err(|error| {
                format!(
                    "读取会话分段失败 {} 第 {} 行：{error}",
                    ordered[event.segment_index].path.display(),
                    event.line_index
                )
            })?;
            let text = std::str::from_utf8(&bytes).map_err(|error| {
                format!(
                    "会话分段不是有效 UTF-8 {} 第 {} 行：{error}",
                    ordered[event.segment_index].path.display(),
                    event.line_index
                )
            })?;
            let mut value = serde_json::from_str::<Value>(text.trim()).map_err(|error| {
                format!(
                    "重新读取会话分段失败 {} 第 {} 行：{error}",
                    ordered[event.segment_index].path.display(),
                    event.line_index
                )
            })?;
            emitted_events += 1;
            let ordinal = i64::try_from(emitted_events)
                .map_err(|_| "canonical 会话事件数量超出 ordinal 范围。".to_string())?;
            let object = value.as_object_mut().ok_or_else(|| {
                format!(
                    "会话事件不是 JSON 对象 {} 第 {} 行。",
                    ordered[event.segment_index].path.display(),
                    event.line_index
                )
            })?;
            object.insert("ordinal".to_string(), Value::Number(ordinal.into()));
            serde_json::to_writer(&mut writer, &value)
                .map_err(|error| format!("写入 canonical 会话事件失败：{error}"))?;
            writer.write_all(b"\n").map_err(|error| {
                format!("写入 canonical 会话失败 {}：{error}", temp_path.display())
            })?;
        }
        writer
            .flush()
            .map_err(|error| format!("刷新 canonical 会话失败 {}：{error}", temp_path.display()))?;
        writer
            .get_ref()
            .sync_all()
            .map_err(|error| format!("同步 canonical 会话失败 {}：{error}", temp_path.display()))?;
        Ok(())
    })();
    if let Err(error) = write_result {
        let _ = fs::remove_file(&temp_path);
        return Err(error);
    }
    for (path, guard) in &guards {
        if !file_guard_matches(path, guard) {
            let _ = fs::remove_file(&temp_path);
            return Err(format!(
                "{} 在 canonical 合并期间发生变化，已保留全部原始分段并停止同步。",
                path.display()
            ));
        }
    }
    let changed = match files_have_same_contents(&temp_path, &target) {
        Ok(same) => !same,
        Err(error) => {
            let _ = fs::remove_file(&temp_path);
            return Err(error);
        }
    };
    let publication = with_canonical_rollout_publication(|| {
        // Recheck under the publication lock. Equal-size provider writes can
        // restore mtime, so background workers also require the generation
        // check in with_canonical_rollout_publication.
        if guards
            .iter()
            .any(|(path, guard)| !file_guard_matches(path, guard))
        {
            return Err("会话分段在发布前发生变化，已保留原始文件。".to_string());
        }
        if changed {
            replace_file_atomically(&temp_path, &target)?;
        }
        Ok(())
    });
    let _ = fs::remove_file(&temp_path);
    if let Err(error) = publication {
        return Err(error);
    }
    let summary = scan_rollout_file(&target)?;
    let mut summary = summary;
    summary.body_scanned = true;
    let warning = restore_rollout_modified_time(&summary).err();
    Ok((summary, changed, warning))
}

fn materialize_canonical_rollouts(
    rollouts: &[RolloutSummary],
) -> Result<CanonicalRolloutMaterialization, String> {
    let mut grouped: BTreeMap<String, Vec<&RolloutSummary>> = BTreeMap::new();
    for rollout in rollouts {
        let id = rollout.id.trim();
        if !id.is_empty() {
            grouped.entry(id.to_string()).or_default().push(rollout);
        }
    }
    let mut result = CanonicalRolloutMaterialization::default();
    let mut native_history = codex_history_safety::NativeHistorySelector::default();
    for (session_id, segments) in grouped {
        if codex_background_merge_should_yield() {
            return Err("前台会话同步已开始，后台 canonical 合并让路。".to_string());
        }
        if let Some(head) = native_history.select_native_head(&segments)? {
            result.rollouts.push(head);
            continue;
        }
        // A normal single raw rollout needs no materialization.  An internal
        // managed copy, however, may be the only surviving source after an
        // interrupted migration; publish a compatible filename for it.
        if segments.len() == 1 && !is_managed_canonical_rollout_path(&segments[0].path) {
            result.rollouts.push(segments[0].clone());
            continue;
        }
        let metadata_candidates = {
            let raw = segments
                .iter()
                .copied()
                .filter(|segment| !is_managed_canonical_rollout_path(&segment.path))
                .collect::<Vec<_>>();
            if raw.is_empty() {
                segments.clone()
            } else {
                raw
            }
        };
        let mut metadata_source = metadata_candidates[0];
        for candidate in metadata_candidates.into_iter().skip(1) {
            if rollout_is_better_canonical(candidate, metadata_source) {
                metadata_source = candidate;
            }
        }
        let (summary, changed, warning) =
            materialize_canonical_rollout(&session_id, &segments, metadata_source)?;
        if changed {
            result.changed_files += 1;
            result.changed_ids.insert(session_id);
        }
        if let Some(warning) = warning {
            result.warnings.push(warning);
        }
        result.rollouts.push(summary);
    }
    result.rollouts.sort_by(|left, right| {
        left.id
            .cmp(&right.id)
            .then_with(|| codex_path_identity(&left.path).cmp(&codex_path_identity(&right.path)))
    });
    Ok(result)
}

/// Select the already materialized representation without opening the body of
/// every duplicate rollout.  The login path must stay bounded even when a
/// user's history contains several gigabytes of raw JSONL.  Raw segments are
/// never removed: when a session has no usable canonical file, the best raw
/// segment is selected as a temporary SQLite/index source and the session is
/// reported as pending for the background materializer.
fn select_canonical_rollouts_fast(
    rollouts: &[RolloutSummary],
) -> Result<CanonicalRolloutMaterialization, String> {
    let mut grouped: BTreeMap<String, Vec<&RolloutSummary>> = BTreeMap::new();
    for rollout in rollouts {
        let id = rollout.id.trim();
        if !id.is_empty() {
            grouped.entry(id.to_string()).or_default().push(rollout);
        }
    }

    let mut result = CanonicalRolloutMaterialization::default();
    let mut native_history = codex_history_safety::NativeHistorySelector::default();
    for (session_id, segments) in grouped {
        if let Some(head) = native_history.select_native_head(&segments)? {
            result.rollouts.push(head);
            continue;
        }
        if segments.len() == 1 && !is_managed_canonical_rollout_path(&segments[0].path) {
            result.rollouts.push(segments[0].clone());
            continue;
        }

        let raw_segments = segments
            .iter()
            .copied()
            .filter(|segment| !is_managed_canonical_rollout_path(&segment.path))
            .collect::<Vec<_>>();
        let metadata_source = raw_segments
            .iter()
            .copied()
            .reduce(|current, candidate| {
                if rollout_is_better_canonical(candidate, current) {
                    candidate
                } else {
                    current
                }
            })
            .or_else(|| {
                segments.iter().copied().reduce(|current, candidate| {
                    if rollout_is_better_canonical(candidate, current) {
                        candidate
                    } else {
                        current
                    }
                })
            })
            .ok_or_else(|| format!("会话 {session_id} 没有可用的 rollout 分段。"))?;

        // Managed copies are migration inputs only. SQLite must point at an
        // official timestamp/UUID basename that the paginated resolver can
        // reopen.
        let usable_canonical = segments
            .iter()
            .copied()
            .filter(|segment| {
                is_managed_canonical_rollout_path(&segment.path)
                    && fs::metadata(&segment.path)
                        .map(|metadata| metadata.is_file() && metadata.len() > 0)
                        .unwrap_or(false)
            })
            .collect::<Vec<_>>();
        // SQLite must always point at an official raw-compatible basename.
        // Prefer a current managed copy, then a raw source, and migrate an
        // older synthetic managed copy when it is the only available source.
        let selected = usable_canonical
            .iter()
            .copied()
            .filter(|segment| is_compatible_canonical_rollout_path(&segment.path, &session_id))
            .reduce(|current, candidate| {
                if rollout_is_better_canonical(candidate, current) {
                    candidate
                } else {
                    current
                }
            })
            .or_else(|| {
                raw_segments
                    .iter()
                    .copied()
                    .filter(|segment| is_official_rollout_filename(&segment.path))
                    .reduce(|current, candidate| {
                        if rollout_is_better_canonical(candidate, current) {
                            candidate
                        } else {
                            current
                        }
                    })
            })
            .or_else(|| {
                raw_segments.iter().copied().reduce(|current, candidate| {
                    if rollout_is_better_canonical(candidate, current) {
                        candidate
                    } else {
                        current
                    }
                })
            })
            .or_else(|| {
                usable_canonical
                    .iter()
                    .copied()
                    .find(|segment| is_official_rollout_filename(&segment.path))
            })
            .unwrap_or(metadata_source);
        let mut selected = selected.clone();
        if is_managed_canonical_rollout_path(&selected.path)
            && !is_official_rollout_filename(&selected.path)
        {
            let compatible = official_rollout_path(
                &session_id,
                selected.timestamp_ms,
                selected.archived,
                "primary",
            );
            if !compatible.exists() {
                ensure_parent(&compatible)?;
                fs::copy(&selected.path, &compatible).map_err(|error| {
                    format!(
                        "迁移 managed rollout 到官方兼容文件名失败 {} -> {}：{error}",
                        selected.path.display(),
                        compatible.display()
                    )
                })?;
            }
            selected.path = compatible;
        }

        // Only queue a merge when the deterministic canonical target is
        // missing or its metadata is older than one of the raw segments.  A
        // previous implementation marked every duplicate on every sync,
        // which created an endless stream of no-op background workers and
        // repeatedly contended with the foreground login lock.
        let canonical_is_current =
            is_compatible_canonical_rollout_path(&selected.path, &session_id)
                && raw_segments.iter().all(|segment| {
                    segment.timestamp_ms <= selected.timestamp_ms
                        && segment.line_count <= selected.line_count
                        && segment.last_ordinal <= selected.last_ordinal
                });
        if !canonical_is_current {
            result.pending_ids.insert(session_id);
        }
        result.rollouts.push(selected);
    }
    result.rollouts.sort_by(|left, right| {
        left.id
            .cmp(&right.id)
            .then_with(|| codex_path_identity(&left.path).cmp(&codex_path_identity(&right.path)))
    });
    if !result.pending_ids.is_empty() {
        result.warnings.push(format!(
            "检测到 {} 个会话存在多个原始分段，已先复用现有 canonical/原始文件；完整合并将在 Codex 关闭后后台执行。",
            result.pending_ids.len()
        ));
    }
    Ok(result)
}

fn select_rollouts_for_provider_sync(
    rollouts: &[RolloutSummary],
) -> Result<CanonicalRolloutMaterialization, String> {
    // Synchronization only selects metadata for the directory. It must never
    // merge histories, create a replacement rollout, or choose another branch.
    // Keep the exact native head selected by each existing state database.
    let mut heads = HashMap::<String, String>::new();
    for path in codex_state_sqlite_paths().into_iter().filter(|p| p.is_file()) {
        let conn = Connection::open_with_flags(&path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)
            .map_err(|error| format!("读取会话目录失败 {}: {error}", path.display()))?;
        if !sqlite_table_exists(&conn, "threads") {
            continue;
        }
        let columns = sqlite_columns(&conn, "threads");
        if !["id", "rollout_path"].iter().all(|name| columns.iter().any(|c| c == name)) {
            continue;
        }
        let mut stmt = conn.prepare("SELECT id, rollout_path FROM threads")
            .map_err(|error| format!("读取原生会话入口失败: {error}"))?;
        let rows = stmt.query_map([], |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)))
            .map_err(|error| format!("读取原生会话入口失败: {error}"))?;
        for row in rows {
            let (id, path) = row.map_err(|error| format!("读取原生会话入口失败: {error}"))?;
            heads.entry(id).or_insert(path);
        }
    }
    let mut grouped = BTreeMap::<String, Vec<&RolloutSummary>>::new();
    for rollout in rollouts {
        if !rollout.id.trim().is_empty() {
            grouped.entry(rollout.id.clone()).or_default().push(rollout);
        }
    }
    let mut result = CanonicalRolloutMaterialization::default();
    for (id, candidates) in grouped {
        if let Some(path) = heads.get(&id) {
            if let Some(head) = candidates.iter().find(|candidate|
                codex_path_identity(&candidate.path) == codex_path_identity(Path::new(path))) {
                result.rollouts.push((**head).clone());
            } else {
                result.warnings.push(format!("会话 {id} 的原生入口暂不可读，已保留数据库入口，未自动替换历史。"));
            }
            continue;
        }
        let raw: Vec<_> = candidates.into_iter()
            .filter(|candidate| !is_managed_canonical_rollout_path(&candidate.path))
            .collect();
        if raw.len() == 1 {
            result.rollouts.push(raw[0].clone());
        } else {
            result.warnings.push(format!("会话 {id} 缺少原生入口且有 {} 份原始记录，已保留记录，未猜测分支或合并历史。", raw.len()));
        }
    }
    Ok(result)
}

#[derive(Clone, Debug, Default)]
struct RolloutHierarchy {
    source: String,
    thread_source: String,
    parent_thread_id: Option<String>,
    agent_nickname: Option<String>,
    agent_role: Option<String>,
    agent_path: Option<String>,
    subagent_depth: Option<i64>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct RolloutScanCacheEntry {
    size_bytes: u64,
    modified_ns: u64,
    legacy_message_ids: usize,
    legacy_api_incompatible_items: usize,
    // Missing means this cache predates the official tool-call ID check.
    // It must be scanned once instead of treating unchecked history as clean.
    #[serde(default)]
    legacy_function_call_ids: Option<usize>,
    encrypted_content: bool,
    summary: RolloutSummary,
    #[serde(default = "default_body_scanned")]
    body_scanned: bool,
}

impl RolloutScanCacheEntry {
    fn matches(&self, file: &Path) -> bool {
        self.legacy_function_call_ids.is_some()
            && rollout_cache_file_state(file) == Some((self.size_bytes, self.modified_ns))
            && codex_path_identity(&self.summary.path) == codex_path_identity(file)
    }

    fn needs_legacy_response_repair(&self, provider: &str) -> bool {
        if !self.body_scanned {
            return false;
        }
        match provider {
            "openai" => {
                self.legacy_message_ids > 0 || self.legacy_function_call_ids.unwrap_or(0) > 0
            }
            CODEX_DIRECT_PROVIDER_ID => {
                self.legacy_message_ids > 0 || self.legacy_api_incompatible_items > 0
            }
            _ => false,
        }
    }

    fn refresh_file_state(&mut self) -> Result<(), String> {
        let (size_bytes, modified_ns) = rollout_cache_file_state(&self.summary.path)
            .ok_or_else(|| format!("无法读取会话文件状态：{}", self.summary.path.display()))?;
        self.size_bytes = size_bytes;
        self.modified_ns = modified_ns;
        Ok(())
    }
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct RolloutScanCache {
    version: u32,
    entries: HashMap<String, RolloutScanCacheEntry>,
}

#[derive(Default)]
struct RolloutSyncStats {
    rollouts: Vec<RolloutSummary>,
    warnings: Vec<String>,
    cache_hits: usize,
    cache_misses: usize,
    body_bytes_scanned: u64,
    changed: usize,
    repaired_legacy_response_items: usize,
    encrypted: usize,
    /// Files left byte-identical because another rollout stores coordinates
    /// into them.  Reported so a silent skip can never look like success.
    lineage_sources_preserved: usize,
}

/// Whether `entry` is the source file of a native paginated branch.
///
/// The reference is resolved by thread ID rather than by filename: a native
/// branch is named after its own thread, while the file it continues from is
/// named inside the branch header.  A rollout whose own ID appears in
/// `referenced` is an immutable byte prefix — another file's `history_base`
/// stores an offset into it, so changing its length invalidates that branch
/// with `cutoff byte offset is past the source rollout`.
fn is_referenced_lineage_source(entry: &RolloutScanCacheEntry, referenced: &HashSet<String>) -> bool {
    // A history base references a physical rollout ID, not the stable thread ID.
    let id = official_rollout_ids(&entry.summary.path)
        .map(|(_, rollout_id)| rollout_id)
        .unwrap_or(entry.summary.id.trim());
    !id.is_empty() && referenced.contains(id)
}

struct CodexLoginProgress<'a> {
    app: &'a AppHandle,
    started: Instant,
    stage_started: Instant,
    stage: &'static str,
}

impl<'a> CodexLoginProgress<'a> {
    fn new(app: &'a AppHandle) -> Self {
        Self {
            app,
            started: Instant::now(),
            stage_started: Instant::now(),
            stage: "prepare",
        }
    }

    fn stage(&mut self, stage: &'static str, message: &str) {
        log::info!(
            "Codex login stage: stage={}, elapsed_ms={}",
            self.stage,
            self.stage_started.elapsed().as_millis()
        );
        self.stage = stage;
        self.stage_started = Instant::now();
        let _ = self.app.emit(
            "gaoge-codex-login-progress",
            json!({
                "stage": stage, "message": message,
                "elapsedMs": self.started.elapsed().as_millis() as u64,
            }),
        );
    }
}

impl Drop for CodexLoginProgress<'_> {
    fn drop(&mut self) {
        log::info!(
            "Codex login stage: stage={}, elapsed_ms={}, total_ms={}",
            self.stage,
            self.stage_started.elapsed().as_millis(),
            self.started.elapsed().as_millis()
        );
    }
}

