fn ensure_codex_account_save_allowed(
    summary: &Value,
    overwrite_existing: bool,
) -> Result<(), String> {
    let registry = read_registry()?;
    let account_key = summary
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("");
    let active_key = registry
        .get("activeAccountKey")
        .and_then(Value::as_str)
        .unwrap_or("");
    let existing_account_key = registry_canonical_account_key(&registry, summary);
    let exists = registry
        .get("items")
        .and_then(Value::as_array)
        .map(|items| {
            items.iter().any(|item| {
                item.get("accountKey").and_then(Value::as_str) == Some(account_key)
                    || item.get("accountKey").and_then(Value::as_str)
                        == Some(existing_account_key.as_str())
            })
        })
        .unwrap_or(false);

    if exists && existing_account_key == active_key {
        return Err("本机当前活跃账号不会被覆盖，请先切换到其他账号后再覆盖。".to_string());
    }
    if exists && !overwrite_existing {
        return Err("本机已存在同一账号，请勾选覆盖旧快照后再添加。".to_string());
    }
    Ok(())
}

fn gaoge_start_codex_oauth_login_inner() -> Result<Value, String> {
    let login_id = random_urlsafe_token(18);
    let state = random_urlsafe_token(32);
    let code_verifier = random_urlsafe_token(64);
    let code_challenge = codex_oauth_code_challenge(&code_verifier);
    let auth_url = build_codex_oauth_authorize_url(&state, &code_challenge)?;
    let now = unix_now();
    let expires_at = now + CODEX_OAUTH_LOGIN_TTL_SECS;
    let login = CodexOauthLogin {
        state,
        code_verifier,
        redirect_uri: OPENAI_CODEX_OAUTH_REDIRECT_URI.to_string(),
        created_at: now,
    };
    let mut logins = CODEX_OAUTH_LOGINS
        .lock()
        .map_err(|_| "Codex OAuth 状态锁定失败。".to_string())?;
    cleanup_codex_oauth_logins(&mut logins, now);
    logins.insert(login_id.clone(), login);
    Ok(json!({
      "loginId": login_id,
      "authUrl": auth_url,
      "authorizationUrl": auth_url,
      "redirectUri": OPENAI_CODEX_OAUTH_REDIRECT_URI,
      "scope": OPENAI_CODEX_OAUTH_SCOPES,
      "expiresAt": expires_at,
      "expiresIn": CODEX_OAUTH_LOGIN_TTL_SECS
    }))
}

