fn gaoge_add_codex_account_from_session_inner(request: Value) -> Result<Value, String> {
    let session_text = request
        .get("sessionJson")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    if session_text.is_empty() {
        return Err("请粘贴 ChatGPT Session JSON。".to_string());
    }

    let session: Value = serde_json::from_str(session_text)
        .map_err(|error| format!("Session JSON 解析失败：{error}"))?;
    let (auth, metadata) = chatgpt_session_to_auth(&session)?;
    let account_key = metadata
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("");
    let overwrite_existing = request
        .get("overwriteExisting")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let set_active = request
        .get("setActive")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let summary = account_summary_from_auth(&auth, Some(&metadata));
    ensure_codex_account_save_allowed(&summary, overwrite_existing)?;

    let _ = write_session_snapshot_for_key(account_key, &session)?;
    let account = upsert_account(&auth, Some(&metadata), set_active)?;
    Ok(json!({ "account": account, "state": get_accounts_state_inner()? }))
}

