fn save_official_chatgpt_session(session: Value, set_active: bool) -> Result<Value, String> {
    if !is_full_chatgpt_session_json(&session) {
        return Err("官方 Session 仍未登录或缺少 accessToken。".to_string());
    }
    let email = session_email(&session);
    if email.is_empty() {
        return Err("已读取官方 Session，但没有识别到邮箱。".to_string());
    }

    let (auth, metadata) = chatgpt_session_to_auth(&session)?;
    let account_key = metadata
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    if account_key.is_empty() {
        return Err("已读取官方 Session，但无法识别账号标识。".to_string());
    }

    let _ = write_session_snapshot_for_key(account_key, &session)?;
    let account = upsert_account(&auth, Some(&metadata), set_active)?;
    let public_account_key = account
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or(account_key)
        .to_string();
    let summary = account_summary_from_auth(&auth, Some(&metadata));
    let session_json = serde_json::to_string(&session)
        .map_err(|error| format!("Session JSON 序列化失败：{error}"))?;

    Ok(json!({
      "accountKey": public_account_key,
      "email": email,
      "displayName": metadata.get("profileName").and_then(Value::as_str).unwrap_or(email.as_str()),
      "sessionJson": session_json,
      "sessionSource": "official_chatgpt_window",
      "sessionUrl": CHATGPT_SESSION_URL,
      "isFullSessionJson": true,
      "tokenStatus": summary.get("tokenStatus").cloned().unwrap_or(Value::Null),
      "account": account,
      "state": get_accounts_state_inner()?
    }))
}

fn gaoge_identify_official_chatgpt_session_text_inner(request: Value) -> Result<Value, String> {
    let session_text = request
        .get("sessionJson")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    if session_text.is_empty() {
        return Err("请把 Session 页面里的文本全部复制到输入框内。".to_string());
    }
    let session: Value = serde_json::from_str(session_text)
        .map_err(|error| format!("Session JSON 解析失败：{error}"))?;
    save_official_chatgpt_session(session, false)
}

#[tauri::command]
async fn gaoge_identify_official_chatgpt_session_text(request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_identify_official_chatgpt_session_text_inner(request)).await
}

fn chatgpt_cookie_header(window: &WebviewWindow) -> Result<String, String> {
    let url = url::Url::parse(CHATGPT_HOME_URL).map_err(|error| error.to_string())?;
    let cookies = window
        .cookies_for_url(url)
        .map_err(|error| format!("读取 ChatGPT 官方窗口登录态失败：{error}"))?;
    Ok(cookies
        .iter()
        .filter_map(|cookie| {
            let name = cookie.name().trim();
            if name.is_empty() {
                None
            } else {
                Some(format!("{}={}", name, cookie.value()))
            }
        })
        .collect::<Vec<_>>()
        .join("; "))
}

fn fetch_chatgpt_session_with_cookies(cookie_header: &str) -> Result<Option<Value>, String> {
    if cookie_header.trim().is_empty() {
        return Ok(None);
    }
    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(ACCOUNT_USAGE_TIMEOUT_SECS))
        .build()
        .map_err(|error| format!("创建官方 Session 请求失败：{error}"))?;
    let response = client
        .get(CHATGPT_SESSION_URL)
        .header(reqwest::header::ACCEPT, "application/json")
        .header(reqwest::header::USER_AGENT, GAOGE_USER_AGENT)
        .header(reqwest::header::COOKIE, cookie_header)
        .send()
        .map_err(|error| format!("读取官方 Session 页面失败：{error}"))?;
    if !response.status().is_success() {
        return Ok(None);
    }
    let session: Value = response
        .json()
        .map_err(|error| format!("官方 Session JSON 解析失败：{error}"))?;
    if is_full_chatgpt_session_json(&session) {
        Ok(Some(session))
    } else {
        Ok(None)
    }
}

fn read_official_chatgpt_session_from_window(
    window: &WebviewWindow,
) -> Result<Option<Value>, String> {
    let cookie_header = chatgpt_cookie_header(window)?;
    fetch_chatgpt_session_with_cookies(&cookie_header)
}

fn ensure_official_chatgpt_window(app: &AppHandle) -> Result<WebviewWindow, String> {
    if let Some(window) = app.get_webview_window(CHATGPT_OFFICIAL_WINDOW_LABEL) {
        return Ok(window);
    }
    let url = url::Url::parse(CHATGPT_HOME_URL).map_err(|error| error.to_string())?;
    WebviewWindowBuilder::new(
        app,
        CHATGPT_OFFICIAL_WINDOW_LABEL,
        WebviewUrl::External(url),
    )
    .title("ChatGPT 官方登录")
    .inner_size(1080.0, 760.0)
    .min_inner_size(760.0, 560.0)
    .resizable(true)
    .visible(false)
    .center()
    .build()
    .map_err(|error| format!("打开 ChatGPT 官方登录窗口失败：{error}"))
}

fn show_official_chatgpt_window(window: &WebviewWindow) {
    let _ = window.unminimize();
    let _ = window.show();
    let _ = window.center();
    let _ = window.set_focus();
}

#[tauri::command]
async fn gaoge_identify_official_chatgpt_session(app: AppHandle) -> Result<Value, String> {
    let window = ensure_official_chatgpt_window(&app)?;
    let deadline = Instant::now() + Duration::from_secs(CHATGPT_OFFICIAL_SESSION_TIMEOUT_SECS);
    let silent_deadline = Instant::now() + Duration::from_secs(3);
    let mut login_window_shown = true;
    if let Ok(home_url) = url::Url::parse(CHATGPT_HOME_URL) {
        let _ = window.navigate(home_url);
    }
    show_official_chatgpt_window(&window);

    loop {
        match read_official_chatgpt_session_from_window(&window) {
            Ok(Some(session)) => {
                let mut result = save_official_chatgpt_session(session, false)?;
                if let Some(object) = result.as_object_mut() {
                    object.insert(
                        "loginWindowShown".to_string(),
                        Value::Bool(login_window_shown),
                    );
                }
                let _ = window.close();
                return Ok(result);
            }
            Ok(None) => {
                if !login_window_shown && Instant::now() >= silent_deadline {
                    if let Ok(home_url) = url::Url::parse(CHATGPT_HOME_URL) {
                        let _ = window.navigate(home_url);
                    }
                    show_official_chatgpt_window(&window);
                    login_window_shown = true;
                }
            }
            Err(error) => {
                if !login_window_shown && Instant::now() < silent_deadline {
                    // Give WebView a brief chance to load the existing official cookie store silently.
                } else if !login_window_shown {
                    if let Ok(home_url) = url::Url::parse(CHATGPT_HOME_URL) {
                        let _ = window.navigate(home_url);
                    }
                    show_official_chatgpt_window(&window);
                    login_window_shown = true;
                } else if Instant::now() >= deadline {
                    let _ = window.close();
                    return Err(error);
                }
            }
        }

        if Instant::now() >= deadline {
            let _ = window.close();
            return Err("登录超时，请重新点击订阅并完成 ChatGPT 官方登录。".to_string());
        }
        thread::sleep(Duration::from_millis(CHATGPT_OFFICIAL_SESSION_POLL_MS));
    }
}

fn gaoge_import_codex_accounts_inner(request: Value) -> Result<Value, String> {
    if request
        .get("cancelled")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(
            json!({ "cancelled": true, "imported": [], "state": get_accounts_state_inner()? }),
        );
    }
    let file_path = request
        .get("filePath")
        .and_then(Value::as_str)
        .ok_or_else(|| "请选择要导入的账号文件。".to_string())?;
    let payload = read_json_if_exists(Path::new(file_path))?
        .ok_or_else(|| "账号文件不是有效 JSON。".to_string())?;
    let accounts = payload
        .get("accounts")
        .and_then(Value::as_array)
        .or_else(|| payload.get("items").and_then(Value::as_array))
        .cloned()
        .unwrap_or_default();
    let mut imported = Vec::new();
    for source in accounts {
        let auth = source.get("auth").unwrap_or(&source);
        if codex_auth_is_real_account_snapshot(auth) {
            if let Some(session) = exported_session_from_account_source(&source)? {
                let summary = account_summary_from_auth(auth, Some(&source));
                let account_key = summary
                    .get("accountKey")
                    .and_then(Value::as_str)
                    .unwrap_or("");
                if !account_key.is_empty() {
                    let _ = write_session_snapshot_for_key(account_key, &session)?;
                }
            }
            imported.push(upsert_account(auth, Some(&source), false)?);
        }
    }
    if imported.is_empty() {
        return Err("账号文件中没有有效的 Codex 登录凭据。".to_string());
    }
    Ok(json!({ "cancelled": false, "imported": imported, "state": get_accounts_state_inner()? }))
}

#[tauri::command]
async fn gaoge_import_codex_accounts(request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_import_codex_accounts_inner(request)).await
}

fn gaoge_export_codex_accounts_inner(request: Value) -> Result<Value, String> {
    if request
        .get("cancelled")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(json!({ "cancelled": true, "filePath": "", "count": 0 }));
    }
    let file_path = request
        .get("filePath")
        .and_then(Value::as_str)
        .ok_or_else(|| "请选择导出路径。".to_string())?;
    if let Some(auth) = read_json_if_exists(&codex_auth_path())? {
        if codex_auth_is_real_account_snapshot(&auth) {
            let _ = upsert_account(&auth, None, true);
        }
    }
    let selected_keys: Vec<String> = request
        .get("accountKeys")
        .and_then(Value::as_array)
        .map(|keys| {
            keys.iter()
                .filter_map(Value::as_str)
                .map(|key| key.to_string())
                .collect()
        })
        .unwrap_or_default();
    let registry = read_registry()?;
    let mut accounts = Vec::new();
    for item in registry
        .get("items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
    {
        if registry_item_is_gaoge_api_account(&item) {
            continue;
        }
        let item_key = item.get("accountKey").and_then(Value::as_str).unwrap_or("");
        if !selected_keys.is_empty() && !selected_keys.iter().any(|key| key == item_key) {
            continue;
        }
        let Some(snapshot_path) = item.get("snapshotPath").and_then(Value::as_str) else {
            continue;
        };
        if let Some(auth) = read_json_if_exists(Path::new(snapshot_path))? {
            if !codex_auth_is_real_account_snapshot(&auth) {
                continue;
            }
            let mut account = item.as_object().cloned().unwrap_or_default();
            account.remove("snapshotPath");
            account.remove("sessionSnapshotPath");
            if let Some(session) = read_session_snapshot_for_key(item_key)? {
                account.insert("session".to_string(), session);
                account.insert("hasFullSessionJson".to_string(), Value::Bool(true));
            }
            account.insert("auth".to_string(), auth);
            accounts.push(Value::Object(account));
        }
    }
    if accounts.is_empty() {
        return Err("没有可导出的账号快照，请先刷新账号或添加当前账号。".to_string());
    }
    write_json_pretty(
        Path::new(file_path),
        &json!({ "schemaVersion": 1, "kind": "Gaoge-accounts-export", "appVersion": env!("CARGO_PKG_VERSION"), "exportedAt": unix_now(), "exportedHostname": exported_hostname(), "accountCount": accounts.len(), "accounts": accounts }),
    )?;
    Ok(json!({ "cancelled": false, "filePath": file_path, "count": accounts.len() }))
}

