fn read_codex_account_snapshot_for_key(account_key: &str) -> Result<(Value, Value), String> {
    if account_key.trim().is_empty() {
        return Err("请选择要识别的 Codex 账号。".to_string());
    }

    let registry = read_registry()?;
    let item = registry
        .get("items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items
                .iter()
                .find(|item| item.get("accountKey").and_then(Value::as_str) == Some(account_key))
        })
        .cloned()
        .ok_or_else(|| "没有找到该账号，请先刷新账号列表。".to_string())?;
    let snapshot_path = item
        .get("snapshotPath")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| snapshot_path_for_key(account_key));
    let snapshot = read_json_if_exists(&snapshot_path)?
        .or_else(|| {
            recover_account_snapshot_from_current_auth(&item, account_key)
                .ok()
                .flatten()
        })
        .ok_or_else(|| {
            "账号 Session JSON 快照不存在或无法读取；请在账号管理中重新导入完整 Session JSON。"
                .to_string()
        })?;
    if !codex_auth_is_real_account_snapshot(&snapshot) {
        return Err(
            "该记录不是可用的真实 Codex 账号快照，请重新导入 ChatGPT Session。".to_string(),
        );
    }

    Ok((item, snapshot))
}

fn gaoge_identify_codex_account_session_inner(request: Value) -> Result<Value, String> {
    let account_key = request
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    let (item, snapshot) = read_codex_account_snapshot_for_key(account_key)?;
    let summary_key = account_summary_from_auth(&snapshot, Some(&item))
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim()
        .to_string();

    if summary_key.is_empty() {
        return Err(
            "已读取账号 Session JSON，但无法识别账号标识。请重新导入完整 Session JSON。"
                .to_string(),
        );
    }

    let raw_session = read_session_snapshot_for_key(&summary_key)?.ok_or_else(|| {
        "该账号只有 Codex 登录快照，没有保存完整 https://chatgpt.com/api/auth/session 返回值；请在账号管理中重新导入完整 Session JSON 后再订阅。"
            .to_string()
    })?;
    if !is_full_chatgpt_session_json(&raw_session) {
        return Err(
            "该账号保存的不是完整 ChatGPT Session JSON；请重新打开 https://chatgpt.com/api/auth/session 并导入完整返回值后再订阅。"
                .to_string(),
        );
    }

    let snapshot_path = item
        .get("snapshotPath")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .unwrap_or_else(|| snapshot_path_for_key(&summary_key));
    let fresh_snapshot = ensure_fresh_codex_auth(&snapshot, &snapshot_path).map_err(|error| {
        format!("实时刷新账号 Session 失败：{error}。请重新导入完整 Session JSON 后再订阅。")
    })?;
    let live_session = update_chatgpt_session_from_auth(&raw_session, &fresh_snapshot);
    if !is_full_chatgpt_session_json(&live_session) {
        return Err("实时获取到的 Session JSON 缺少 accessToken，请重新登录 ChatGPT 后再导入完整 Session JSON。".to_string());
    }
    let email = session_email(&live_session);
    if email.is_empty() {
        return Err("实时获取到完整 Session JSON，但没有识别到邮箱。请重新登录 ChatGPT 后再导入完整 Session JSON。".to_string());
    }
    let _ = write_session_snapshot_for_key(&summary_key, &live_session)?;
    let account = upsert_account(&fresh_snapshot, Some(&item), false)?;
    let public_account_key = account
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or(summary_key.as_str())
        .to_string();
    let summary = account_summary_from_auth(&fresh_snapshot, Some(&item));
    let session_json = serde_json::to_string(&live_session)
        .map_err(|error| format!("Session JSON 序列化失败：{error}"))?;

    Ok(json!({
      "accountKey": public_account_key,
      "email": email,
      "displayName": email,
      "sessionJson": session_json,
      "sessionSource": "live_chatgpt_session",
      "sessionUrl": CHATGPT_SESSION_URL,
      "isFullSessionJson": true,
      "tokenStatus": summary.get("tokenStatus").cloned().unwrap_or(Value::Null),
      "account": account
    }))
}

