#[allow(dead_code)]
fn gaoge_activate_codex_account_inner(request: Value) -> Result<Value, String> {
    let account_key = request
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    let prepared = prepare_codex_account_activation(account_key)?;
    let codex_closed = stop_codex_app();
    commit_codex_account_activation(&prepared)?;
    let mut state = get_accounts_state_inner()?;
    if let Some(object) = state.as_object_mut() {
        object.insert("codexClosed".to_string(), Value::Bool(codex_closed));
        object.insert("needsRestart".to_string(), Value::Bool(true));
    }
    Ok(state)
}

fn run_codex_official_account_switch_transaction(
    active_account: &ActiveCodexAccountSnapshot,
    codex_closed: bool,
    complete_route_state: impl FnOnce(RouterState) -> Result<(), String>,
) -> Result<Vec<Value>, String> {
    let targets = codex_route_targets();
    let route_snapshot = CodexRouteTransactionSnapshot::capture(&targets)
        .map_err(|error| format!("创建 Codex 账号切换事务快照失败：{error}"))?;
    let outer_snapshot = CodexDisableOuterStateSnapshot::capture()
        .map_err(|error| format!("创建 Codex 账号切换外层状态快照失败：{error}"))?;
    let transaction = (|| -> Result<Vec<Value>, String> {
        let mut router_state = load_router_state().unwrap_or_else(|_| default_router_state());
        // The route transaction writes the selected identity to every home.
        // Do not commit the primary identity before this rollback boundary.
        let codex_dirs = disable_codex_fuel_pack_all_route_targets(
            &router_state.relay_api_key,
            codex_closed,
            Some(active_account),
        )
        .map_err(|error| format!("恢复 Codex 官方路由失败：{error}"))?;
        router_state.enabled = false;
        router_state.mode = "official".to_string();
        complete_route_state(router_state)?;
        Ok(codex_dirs)
    })();
    match transaction {
        Ok(codex_dirs) => Ok(codex_dirs),
        Err(error) => {
            let rollback = restore_codex_route_and_outer_state(&route_snapshot, &outer_snapshot)
                .map(|rollback| format!("\n自动回滚失败：{rollback}"))
                .unwrap_or_default();
            Err(format!("{error}{rollback}"))
        }
    }
}

fn gaoge_activate_codex_account_and_restart_inner(
    app: AppHandle,
    request: Value,
) -> Result<Value, String> {
    let account_key = request
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    let _operation = lock_codex_foreground_operation()?;
    let prepared = prepare_codex_account_activation(account_key)?;
    let mut progress = CodexLoginProgress::new(&app);
    let active_account = prepared.active_snapshot();
    let preserve_relay = codex_account_switch_preserves_relay(&request);
    let running_app_dirs = list_running_codex_app_dirs();
    progress.stage("close", "正在关闭 Codex");
    let codex_closed = stop_codex_app_and_confirm_exit_before_config_write()?;
    progress.stage("configure", "正在恢复账号与登录配置");
    let (codex_dirs, relay_preserved, aggregate_state) = if preserve_relay {
        let codex_dirs = match sync_codex_auth_to_all_route_targets(&active_account) {
            Ok(value) => value,
            Err(error) => {
                return Err(core_failure_with_normal_launch(
                    running_app_dirs,
                    format!("保留 Codex 中转并切换账号失败：{error}"),
                ));
            }
        };
        let aggregate = aggregate_login_state_snapshot();
        let aggregate_state = aggregate.enabled.then(|| {
            let running = AGGREGATE_ROUTER_RUNTIME
                .lock()
                .ok()
                .and_then(|guard| guard.as_ref().cloned())
                .is_some_and(|runtime| !runtime.stop.load(Ordering::SeqCst));
            public_aggregate_login_state(&aggregate, running)
        });
        (codex_dirs, true, aggregate_state)
    } else {
        let codex_dirs = match run_codex_official_account_switch_transaction(
            &active_account,
            codex_closed,
            |router_state| {
                save_router_state(router_state)
                    .map_err(|error| format!("保存 Codex 官方路由状态失败：{error}"))?;
                deactivate_aggregate_login_state()
                    .map_err(|error| format!("关闭聚合登录状态失败：{error}"))
            },
        ) {
            Ok(value) => value,
            Err(error) => {
                return Err(core_failure_with_normal_launch(
                    running_app_dirs,
                    format!("切换 Codex 官方账号失败：{error}"),
                ));
            }
        };
        (codex_dirs, false, None)
    };

    progress.stage("sessions", "正在同步新增和变化的会话");
    let session_sync = if relay_preserved {
        sync_codex_route_targets_preserving_providers(true)
    } else {
        sync_codex_route_targets_resilient("openai", true)
    };
    if !relay_preserved {
        require_official_session_sync_completed(&session_sync)?;
    }
    progress.stage("enhancements", "正在准备模型面板与主题");
    let preparation = prepare_codex_enhancements(&app, false);
    progress.stage("launch", "正在启动 Codex");
    let launch = launch_prepared_codex(running_app_dirs, preparation);
    let primary = codex_dirs.first().cloned().unwrap_or_else(|| json!({}));
    let config_path = json_str(&primary, "configPath");
    let mut warnings = launch
        .get("warnings")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    warnings.extend(
        session_sync
            .get("warnings")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default(),
    );
    let codex_launched = json_bool(&launch, "launched");
    let codex_launch_queued = codex_launch_is_queued(&launch);
    let mut state = get_accounts_state_inner()?;
    if let Some(object) = state.as_object_mut() {
        object.insert("codexClosed".to_string(), Value::Bool(codex_closed));
        object.insert("codexLaunched".to_string(), Value::Bool(codex_launched));
        object.insert(
            "codexLaunchQueued".to_string(),
            Value::Bool(codex_launch_queued),
        );
        object.insert(
            "needsRestart".to_string(),
            Value::Bool(codex_launch_needs_restart(&launch)),
        );
        object.insert("codexDirs".to_string(), Value::Array(codex_dirs));
        object.insert("sessionSync".to_string(), session_sync);
        object.insert("launch".to_string(), launch.clone());
        object.insert(
            "enhancements".to_string(),
            json!({
              "plugin": json_field(&launch, "plugin"),
              "sessionDelete": json_field(&launch, "sessionDelete"),
              "theme": json_field(&launch, "theme"),
            }),
        );
        object.insert("warnings".to_string(), Value::Array(warnings));
        object.insert("relayPreserved".to_string(), Value::Bool(relay_preserved));
        if let Some(aggregate) = aggregate_state {
            object.insert("aggregate".to_string(), aggregate);
        }
        object.insert(
            "router".to_string(),
            public_router_state(json!({
              "running": false,
              "configUpdated": true,
              "configPath": config_path,
            })),
        );
    }
    Ok(state)
}

#[tauri::command]
async fn gaoge_activate_codex_account(app: AppHandle, request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_activate_codex_account_and_restart_inner(app, request)).await
}

fn gaoge_delete_codex_account_inner(request: Value) -> Result<Value, String> {
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK,
        "Codex 正在处理账号配置，请稍后删除账号。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let account_key = request
        .get("accountKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    if account_key.is_empty() {
        return Err("请选择要删除的 Codex 账号。".to_string());
    }
    let force = request
        .get("force")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let mut registry = read_registry()?;
    let registry_marks_active =
        registry.get("activeAccountKey").and_then(Value::as_str) == Some(account_key);
    let target_item = registry
        .get("items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items
                .iter()
                .find(|item| item.get("accountKey").and_then(Value::as_str) == Some(account_key))
        })
        .cloned();
    let live_auth = read_json_if_exists(&codex_auth_path())?;
    let live_auth_matches_target = live_auth.as_ref().is_some_and(|auth| {
        codex_auth_is_real_account_snapshot(auth)
            && target_item
                .as_ref()
                .is_some_and(|item| auth_matches_account_item(auth, item, account_key))
    });
    let is_active = registry_marks_active || live_auth_matches_target;
    if is_active && !force {
        return Err("正在启用的账号不能删除，请先切换到其他账号。".to_string());
    }
    if is_active && live_auth.is_some() && !live_auth_matches_target {
        return Err(
            "当前 Codex 登录与所选账号快照不一致，为防止误删其他账号，已取消强制删除。请刷新账号后重试。"
                .to_string(),
        );
    }

    let mut codex_was_running = false;
    let mut codex_closed = false;
    let mut live_auth_deleted = false;
    if is_active {
        codex_was_running = !list_running_codex_app_dirs().is_empty();
        let _ = stop_codex_app();
        wait_for_codex_app_exit(Duration::from_secs(CODEX_APP_EXIT_WAIT_SECS))?;
        codex_closed = true;

        if live_auth_matches_target {
            let item = target_item.as_ref().ok_or_else(|| {
                "当前账号快照记录不存在，为防止误删登录状态，已取消强制删除。".to_string()
            })?;
            live_auth_deleted = clear_live_codex_auth_if_matches_account(account_key, item)?;
            if !live_auth_deleted && codex_auth_path().exists() {
                return Err(
                    "关闭 Codex 后当前登录状态发生变化，为防止误删其他账号，已取消强制删除。"
                        .to_string(),
                );
            }
        }
        registry["activeAccountKey"] = Value::String(String::new());
    }

    let mut snapshot_deleted = false;
    let mut session_snapshot_deleted = false;
    if let Some(items) = registry.get_mut("items").and_then(Value::as_array_mut) {
        if let Some(item) = items
            .iter()
            .find(|item| item.get("accountKey").and_then(Value::as_str) == Some(account_key))
        {
            if let Some(snapshot_path) = item.get("snapshotPath").and_then(Value::as_str) {
                let path = PathBuf::from(snapshot_path);
                if path.starts_with(codex_snapshots_dir()) {
                    snapshot_deleted = fs::remove_file(path).is_ok();
                }
            }
            let session_path = item
                .get("sessionSnapshotPath")
                .and_then(Value::as_str)
                .map(PathBuf::from)
                .unwrap_or_else(|| session_snapshot_path_for_key(account_key));
            if session_path.starts_with(codex_session_snapshots_dir()) {
                session_snapshot_deleted = fs::remove_file(session_path).is_ok();
            }
        }
        items.retain(|item| item.get("accountKey").and_then(Value::as_str) != Some(account_key));
    }
    registry["updatedAt"] = Value::Number(unix_now().into());
    write_registry(&registry)?;
    Ok(json!({
      "deletedAccountKey": account_key,
      "snapshotDeleted": snapshot_deleted,
      "sessionSnapshotDeleted": session_snapshot_deleted,
      "forced": is_active,
      "codexWasRunning": codex_was_running,
      "codexClosed": codex_closed,
      "liveAuthDeleted": live_auth_deleted,
      "state": get_accounts_state_inner()?
    }))
}

#[tauri::command]
