fn configure_codex_all_route_targets_with_catalog(
    api_key: &str,
    base_url: &str,
    model: &str,
    model_catalog_plan: Option<&CodexModelCatalogPlan>,
    codex_closed: bool,
    active_account: Option<&ActiveCodexAccountSnapshot>,
    force_api_mode: bool,
) -> Result<Vec<Value>, String> {
    let targets = codex_route_targets();
    if let Some(plan) = model_catalog_plan {
        let resolved = resolve_codex_model_catalog(&targets, model, plan)?;
        return configure_codex_route_targets_with_resolved_catalog(
            &targets,
            api_key,
            base_url,
            &resolved.model,
            Some(&resolved.plan),
            Some(&resolved.catalog),
            codex_closed,
            active_account,
            force_api_mode,
        );
    }
    configure_codex_route_targets_with_resolved_catalog(
        &targets,
        api_key,
        base_url,
        model,
        None,
        None,
        codex_closed,
        active_account,
        force_api_mode,
    )
}

fn configure_codex_route_targets_with_resolved_catalog(
    targets: &[CodexDirTarget],
    api_key: &str,
    base_url: &str,
    model: &str,
    model_catalog_plan: Option<&CodexModelCatalogPlan>,
    resolved_model_catalog: Option<&Value>,
    codex_closed: bool,
    active_account: Option<&ActiveCodexAccountSnapshot>,
    force_api_mode: bool,
) -> Result<Vec<Value>, String> {
    let mut results = Vec::new();
    let mut primary_errors = Vec::new();
    let mut secondary_errors = Vec::new();
    for target in targets {
        match with_codex_dir(&target.dir, || {
            configure_codex_current_dir(
                &target,
                api_key,
                base_url,
                model,
                model_catalog_plan,
                resolved_model_catalog,
                codex_closed,
                active_account,
                force_api_mode,
            )
        }) {
            Ok(result) => results.push(result),
            Err(error) => {
                let message = format!("{}: {error}", target.dir.display());
                if target.primary {
                    primary_errors.push(message);
                } else {
                    secondary_errors.push(message);
                }
            }
        }
    }
    if !primary_errors.is_empty() || results.is_empty() {
        return Err(primary_errors.join("\n"));
    }
    if !secondary_errors.is_empty() {
        if let Some(primary) = results
            .iter_mut()
            .find(|result| result.get("primary").and_then(Value::as_bool) == Some(true))
            .and_then(Value::as_object_mut)
        {
            primary.insert(
                "routeWarning".to_string(),
                Value::String(format!(
                    "已跳过 {} 个异常的附加 Codex 配置目录，主目录登录不受影响。",
                    secondary_errors.len()
                )),
            );
            primary.insert("routeWarnings".to_string(), json!(secondary_errors));
        }
    }
    Ok(results)
}

fn codex_relay_close_snapshot_paths() -> Vec<PathBuf> {
    let mut paths = vec![
        codex_config_path(),
        codex_auth_path(),
        codex_registry_path(),
    ];
    paths.extend(codex_relay_restore::artifact_paths());
    if let Ok(Some(codex_relay_restore::ExplicitAuthBaseline::Account(key))) =
        codex_relay_restore::explicit_auth_baseline()
    {
        paths.push(snapshot_path_for_key(&key));
    }
    // Closing may refresh the saved copy from live OAuth credentials. Include
    // those exact snapshot paths so a later cleanup failure rolls it back too.
    if let Ok(registry) = read_registry() {
        for item in registry
            .get("items")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            if let Some(key) = item.get("accountKey").and_then(Value::as_str) {
                paths.push(snapshot_path_for_key(key));
            }
            if let Some(path) = item.get("snapshotPath").and_then(Value::as_str) {
                paths.push(PathBuf::from(path));
            }
        }
    }
    paths.sort();
    paths.dedup();
    paths
}

#[cfg(test)]
fn run_codex_relay_close_transaction(
    config_path: &Path,
    existing: &str,
    official_config: &str,
    relay_api_key: &str,
    active_account: Option<&ActiveCodexAccountSnapshot>,
    before_artifact_cleanup: impl FnOnce() -> Result<(), String>,
) -> Result<Value, String> {
    run_codex_relay_close_transaction_with_recovery(
        config_path,
        existing,
        official_config,
        relay_api_key,
        active_account,
        false,
        before_artifact_cleanup,
    )
}

fn run_codex_relay_close_transaction_with_recovery(
    config_path: &Path,
    existing: &str,
    official_config: &str,
    relay_api_key: &str,
    active_account: Option<&ActiveCodexAccountSnapshot>,
    untrusted_restore_state: bool,
    before_artifact_cleanup: impl FnOnce() -> Result<(), String>,
) -> Result<Value, String> {
    let snapshots = codex_relay_close_snapshot_paths()
        .into_iter()
        .map(OptionalFileSnapshot::capture)
        .collect::<Result<Vec<_>, _>>()?;
    let transaction = (|| -> Result<Value, String> {
        write_codex_config_atomic(config_path, Some(existing), official_config)?;
        let auth_cleanup = if untrusted_restore_state {
            cleanup_codex_auth_with_untrusted_restore_state()?
        } else if let Some(active_account) = active_account {
            let result = sync_codex_auth_from_active_snapshot(
                active_account,
                "codex-active-account-official",
            )?;
            set_registry_active_account(&active_account.account_key)?;
            result
        } else {
            cleanup_codex_gaoge_api_auth_for_official(relay_api_key, &existing)?
        };
        before_artifact_cleanup()?;
        // Validate writes while the client is stopped and rollback evidence still exists.
        codex_official_auth_verification::validate_written_identity(&auth_cleanup)?;
        codex_relay_restore::remove_artifacts()?;
        Ok(auth_cleanup)
    })();
    match transaction {
        Ok(auth_cleanup) => Ok(auth_cleanup),
        Err(error) => {
            let restore_result = restore_all_best_effort(snapshots.iter().rev(), |snapshot| {
                if snapshot.path == config_path {
                    restore_codex_config_snapshot_after_transaction_failure(
                        snapshot,
                        config_path,
                        official_config,
                    )
                } else {
                    snapshot.restore()
                }
            });
            if restore_result.is_ok() {
                Err(format!("{error} 已恢复本次关闭前的配置与登录状态。"))
            } else {
                Err(format!(
                    "{error}\n关闭失败后的自动回滚也未完整完成：{}",
                    restore_result.unwrap_err()
                ))
            }
        }
    }
}

fn disable_codex_fuel_pack_current_dir_with_recovery(
    target: &CodexDirTarget,
    relay_api_key: &str,
    _codex_closed: bool,
    active_account: Option<&ActiveCodexAccountSnapshot>,
    force_official: bool,
) -> Result<Value, String> {
    fs::create_dir_all(codex_dir()).map_err(|error| format!("create Codex dir failed: {error}"))?;
    let backup_path = backup_codex_config("codex-fuel-pack-disable")?;
    let config_path = codex_config_path();
    let existing = read_text_if_exists(&config_path)?;
    let recovery_backup = if force_official {
        codex_relay_restore::backup_corrupt_state_for_force_official()?
    } else {
        None
    };
    let restored_config = if recovery_backup.is_some() {
        codex_relay_restore::restore_config_without_saved_state(&existing)?
    } else {
        codex_relay_restore::restore_config(&existing)?
    };
    let restored_config = repair_known_codex_config_corruption(&restored_config);
    let official_config = remove_gaoge_image_mcp_config(&restored_config);
    let auth_cleanup = run_codex_relay_close_transaction_with_recovery(
        &config_path,
        &existing,
        &official_config,
        relay_api_key,
        active_account,
        recovery_backup.is_some(),
        || Ok(()),
    )?;
    // Preserve user-edited skill files and do not undo a successful account switch.
    if let Err(error) = gaoge_image_skill::sync(&target.dir, false) {
        log::warn!("Gaoge image skill cleanup skipped: {error}");
    }
    let session_sync = json!({
        "status": "pending",
        "provider": "openai",
        "background": true,
        "backupPath": Value::Null,
        "warnings": Vec::<String>::new(),
    });
    Ok(json!({
      "codexDir": codex_dir().to_string_lossy(),
      "codexDirSource": target.source,
      "primary": target.primary,
      "configPath": config_path.to_string_lossy(),
      "backupPath": backup_path.map(|p| p.to_string_lossy().to_string()),
      "recoveryBackupPath": recovery_backup.map(|p| p.to_string_lossy().to_string()),
      "authCleanup": auth_cleanup,
      "sessionSync": session_sync,
    }))
}

fn disable_codex_fuel_pack_all_route_targets(
    relay_api_key: &str,
    codex_closed: bool,
    active_account: Option<&ActiveCodexAccountSnapshot>,
) -> Result<Vec<Value>, String> {
    disable_codex_fuel_pack_all_route_targets_with_recovery(
        relay_api_key, codex_closed, active_account, false,
    )
}

fn disable_codex_fuel_pack_all_route_targets_with_recovery(
    relay_api_key: &str,
    codex_closed: bool,
    active_account: Option<&ActiveCodexAccountSnapshot>,
    force_official: bool,
) -> Result<Vec<Value>, String> {
    let mut targets = codex_route_targets();
    targets.sort_by_key(|target| !target.primary);
    let transaction = CodexRouteTransactionSnapshot::capture(&targets)?;
    let mut results = Vec::new();
    let mut errors = Vec::new();
    for target in &targets {
        match with_codex_dir(&target.dir, || {
            disable_codex_fuel_pack_current_dir_with_recovery(
                target, relay_api_key, codex_closed, active_account, force_official,
            )
        }) {
            Ok(result) => results.push(result),
            Err(error) => {
                errors.push(format!("{}: {error}", target.dir.display()));
                break;
            }
        }
    }
    if !errors.is_empty() {
        let error = errors.join("\n");
        return match transaction.restore() {
            Ok(()) => Err(format!(
                "{error}\n已恢复关闭前所有可恢复的 Codex 配置目录。"
            )),
            Err(rollback) => Err(format!(
                "{error}\n多目录关闭失败后的自动回滚也未完整完成：{rollback}"
            )),
        };
    }
    if results.is_empty() {
        return Err("没有成功恢复任何 Codex 配置目录。".to_string());
    }
    Ok(results)
}

fn json_field(value: &Value, key: &str) -> Value {
    value.get(key).cloned().unwrap_or(Value::Null)
}

fn any_json_bool(values: &[Value], key: &str) -> bool {
    values.iter().any(|value| json_bool(value, key))
}

