// This only establishes ownership of the catalog path. Callers must also
// verify the active provider credentials with codex_fuel_guard::status.
fn codex_managed_ultra_catalog_path(config_path: &Path, config: &str) -> Option<PathBuf> {
    if configured_provider(config) != CODEX_DIRECT_PROVIDER_ID
        || configured_root_value(config, "profile").is_some()
        || !model_provider_section_has_gaoge_route(config, CODEX_DIRECT_PROVIDER_ID)
        || config.parse::<toml_edit::Document>().is_err()
        || fs::symlink_metadata(config_path).ok()?.file_type().is_symlink()
    {
        return None;
    }
    let directory = config_path.parent()?;
    let configured = PathBuf::from(configured_root_value(config, "model_catalog_json")?);
    let catalog_path = if configured.is_absolute() {
        configured
    } else {
        directory.join(configured)
    };
    if catalog_path.file_name()? != OsStr::new(CODEX_MODEL_CATALOG_FILE)
        || fs::canonicalize(catalog_path.parent()?).ok()? != fs::canonicalize(directory).ok()?
        || fs::symlink_metadata(&catalog_path)
            .is_ok_and(|metadata| metadata.file_type().is_symlink())
    {
        return None;
    }
    Some(catalog_path)
}

fn repair_codex_managed_ultra_target(
    config_path: &Path,
    router: &RouterState,
    aggregate: &AggregateLoginState,
    aggregate_running: bool,
) -> Result<Option<Value>, String> {
    let existing = read_text_if_exists(config_path)?;
    if !json_bool(&codex_fuel_guard::status(&existing, router, aggregate, aggregate_running), "enabled") {
        return Ok(None);
    }
    let Some(catalog_path) = codex_managed_ultra_catalog_path(config_path, &existing) else {
        return Ok(None);
    };
    let original_catalog = fs::read(&catalog_path)
        .map_err(|error| format!("读取 Ultra 模型目录失败 {}：{error}", catalog_path.display()))?;
    let mut catalog: Value = serde_json::from_slice(&original_catalog)
        .map_err(|error| format!("Ultra 模型目录格式错误 {}：{error}", catalog_path.display()))?;
    let original_value = catalog.clone();
    let models = catalog.get_mut("models").and_then(Value::as_array_mut)
        .ok_or_else(|| "Ultra 模型目录缺少 models 数组。".to_string())?;
    for entry in models {
        let Some(slug) = entry.get("slug").and_then(Value::as_str).map(str::to_string) else {
            continue;
        };
        // Repair reasoning and explicitly managed speed capabilities only; never
        // rebuild unrelated model instructions, tools, or unknown capabilities.
        let model = canonical_codex_catalog_entry_model_name(entry, &slug, &aggregate.routes);
        if entry.get("gaogeModelCapabilities").is_some()
            || codex_model_supports_ultra_reasoning(&model)
            || codex_model_caps_reasoning_at_max(&model)
            || codex_model_caps_reasoning_at_xhigh(&model)
        {
            if let Some(object) = entry.as_object_mut() {
                object.entry("supported_reasoning_levels".to_string())
                    .or_insert_with(|| codex_native_responses_model_entry(&model, 0)["supported_reasoning_levels"].clone());
                reconcile_codex_reasoning_levels(object, &model);
                reconcile_codex_multi_agent_version(object, &model);
                reconcile_codex_speed_tiers(object, &model);
            }
        }
    }
    let repaired = ensure_codex_ultra_reasoning_controls(&existing);
    let repaired = desktop_model_support::reconcile_selected_capabilities(&repaired, &catalog)?;
    validate_codex_config_toml(&repaired)?;
    let desktop = repaired.parse::<toml_edit::Document>().map_err(|error| error.to_string())?;
    if desktop.get("desktop").and_then(|table| table.get(CODEX_DESKTOP_SHOW_ULTRA_KEY))
        .and_then(toml_edit::Item::as_bool) != Some(true)
        || !desktop.get("desktop").and_then(|table| table.get(CODEX_DESKTOP_EFFORTS_KEY))
            .and_then(toml_edit::Item::as_array)
            .is_some_and(|efforts| efforts.iter().any(|effort| effort.as_str() == Some("ultra")))
    {
        return Err("无法修复 Ultra 桌面设置，请检查 desktop 配置格式。".to_string());
    }
    let catalog_changed = catalog != original_value;
    let config_changed = repaired != existing;
    let serialized = serde_json::to_vec_pretty(&catalog)
        .map_err(|error| format!("编码 Ultra 模型目录失败：{error}"))?;
    if catalog_changed {
        write_bytes_atomic(&catalog_path, &serialized)?;
    }
    if config_changed {
        if let Err(error) = write_codex_config_atomic(config_path, Some(&existing), &repaired) {
            if catalog_changed && fs::read(&catalog_path).ok().as_deref() == Some(serialized.as_slice()) {
                if let Err(restore_error) = write_bytes_atomic(&catalog_path, &original_catalog) {
                    return Err(format!("{error}；恢复 Ultra 模型目录失败：{restore_error}"));
                }
            }
            return Err(error);
        }
    }
    Ok(Some(json!({
        "configPath": config_path.to_string_lossy(),
        "modelCatalogPath": catalog_path.to_string_lossy(),
        "changed": catalog_changed || config_changed,
        "catalogChanged": catalog_changed, "configChanged": config_changed,
    })))
}

fn prepare_codex_managed_ultra_configuration(targets: &[CodexDirTarget]) -> Value {
    let router = match load_router_state() {
        Ok(router) => router,
        Err(error) => return json!({"applied": false, "warnings": [format!("读取 Ultra 配置归属失败：{error}")]}),
    };
    let aggregate = aggregate_login_state_snapshot();
    let aggregate_running = AGGREGATE_ROUTER_RUNTIME.lock().ok()
        .and_then(|runtime| runtime.as_ref().cloned())
        .is_some_and(|runtime| !runtime.stop.load(Ordering::SeqCst)
            && runtime.port == aggregate.router_port && runtime.token == aggregate.router_token);
    let mut repaired = Vec::new();
    let mut warnings = Vec::new();
    for target in targets {
        match repair_codex_managed_ultra_target(&target.dir.join("config.toml"), &router, &aggregate, aggregate_running) {
            Ok(Some(result)) => repaired.push(result),
            Ok(None) => {},
            Err(error) => warnings.push(format!("Ultra 配置准备未完成：{error}")),
        }
    }
    json!({
        "applied": !repaired.is_empty() && warnings.is_empty(),
        "changed": repaired.iter().any(|result| json_bool(result, "changed")),
        "method": "managed-ultra-runtime", "modelPickerEnhanced": false,
        "ultraRuntimePending": !repaired.is_empty(), "ultraReady": false,
        "ready": false, "verified": false,
        "ultraVerified": false, "ultraReason": "awaiting-runtime-verification",
        "targets": repaired, "warnings": warnings,
    })
}

fn append_codex_result_warnings(result: &mut Value, additional: &Value) {
    let mut warnings = result.get("warnings").and_then(Value::as_array).cloned().unwrap_or_default();
    if let Some(extra) = additional.get("warnings").and_then(Value::as_array) {
        for warning in extra {
            if warning.as_str().is_some_and(|text| !text.is_empty()) && !warnings.contains(warning) {
                warnings.push(warning.clone());
            }
        }
    }
    result["warnings"] = Value::Array(warnings);
}

fn codex_model_patch_launch_target(patch: &Value) -> Option<PathBuf> {
    if json_str(patch, "method") == "asar-byte" && json_bool(patch, "applied") {
        if let Some(app_dir) = patch.get("resourcesDir").and_then(Value::as_str)
            .map(PathBuf::from).and_then(|resources| resources.parent().map(Path::to_path_buf))
            .filter(|app_dir| is_complete_codex_app_dir(app_dir))
        {
            return Some(app_dir);
        }
    }
    None
}

fn codex_enhancement_preparation_state() -> CodexEnhancementPreparation {
    let plugin_requested = codex_plugin_enhancement_enabled();
    let session_delete_requested = codex_session_delete_enabled();
    let theme_requested = codex_themes::theme_enabled();
    CodexEnhancementPreparation {
        plugin_requested,
        plugin_enabled: plugin_requested,
        plugin_applied: false,
        plugin_error: None,
        plugin_bootstrap: None,
        session_delete_requested,
        session_delete_enabled: session_delete_requested,
        session_delete_applied: false,
        session_delete_error: None,
        theme_requested,
        theme_enabled: theme_requested,
        theme_applied: false,
        theme_error: None,
        theme_payload: None,
    }
}

fn prepare_codex_enhancements(
    app: &AppHandle,
    allow_plugin_download: bool,
) -> CodexEnhancementPreparation {
    let mut preparation = codex_enhancement_preparation_state();

    if preparation.plugin_requested {
        match bootstrap_codex_plugin_marketplace(app, allow_plugin_download) {
            Ok(result) => preparation.plugin_bootstrap = Some(result),
            Err(error) => {
                preparation.plugin_enabled = false;
                preparation.plugin_error = Some(disable_codex_plugin_after_failure(format!(
                    "插件配置准备失败：{error}"
                )));
            }
        }
    }
    if preparation.theme_requested {
        match codex_themes::active_theme_runtime_payload() {
            Ok(Some(payload)) => preparation.theme_payload = Some(payload),
            Ok(None) => {
                preparation.theme_enabled = false;
                preparation.theme_error = Some(disable_codex_theme_after_failure(
                    "当前主题状态不存在，已恢复原生主题。",
                ));
            }
            Err(error) => {
                preparation.theme_enabled = false;
                preparation.theme_error = Some(disable_codex_theme_after_failure(format!(
                    "主题准备失败：{error}"
                )));
            }
        }
    }
    stop_codex_session_delete_bridge();
    preparation
}

#[allow(dead_code)]
fn launch_codex_cdp_target(app_dir: &Path, debug_port: u16) -> Result<CdpTarget, String> {
    launch_codex_with_cdp(app_dir, debug_port)?;
    match wait_for_cdp_target_with_timeout(
        debug_port,
        Duration::from_secs(CODEX_PACKAGED_CDP_FIRST_WAIT_SECS),
    ) {
        Ok(target) => Ok(target),
        #[cfg(target_os = "windows")]
        Err(first_error) if is_windows_apps_codex_dir(app_dir) => Err(format!(
            "Codex 商店版未开放调试端口：{first_error}；已保留通过系统应用标识启动的普通实例。"
        )),
        Err(error) => Err(error),
    }
}

fn codex_effective_launch_path(app_dir: &Path) -> PathBuf {
    if is_macos_app_bundle(app_dir) {
        app_dir.to_path_buf()
    } else {
        codex_direct_launch_exe_path(app_dir)
    }
}

#[allow(dead_code)]
fn fallback_to_normal_codex_launch(app_dir: &Path) -> Result<(), String> {
    let _ = stop_codex_app();
    wait_for_codex_app_exit(Duration::from_secs(CODEX_APP_EXIT_WAIT_SECS))?;
    thread::sleep(Duration::from_millis(350));
    launch_codex_normally_and_wait(app_dir)
}

fn core_failure_with_normal_launch(preferred: Vec<PathBuf>, error: impl Into<String>) -> String {
    let error = error.into();
    let launch_result = choose_launchable_codex_app_dir(preferred)
        .ok_or_else(|| "没有找到可启动的 Codex/ChatGPT，请在系统配置中检查启动路径。".to_string())
        .and_then(|app_dir| launch_codex_normally_and_wait(&app_dir));
    match launch_result {
        Ok(()) => format!("{error} Codex 已使用普通方式重新打开。"),
        Err(launch_error) => {
            format!("{error} 同时无法重新打开 Codex：{launch_error}")
        }
    }
}

fn disable_shared_codex_enhancements(preparation: &mut CodexEnhancementPreparation, error: &str) {
    if preparation.plugin_enabled {
        preparation.plugin_enabled = false;
        preparation.plugin_error = Some(disable_codex_plugin_after_failure(format!(
            "插件注入失败：{error}"
        )));
    }
    if preparation.session_delete_enabled {
        preparation.session_delete_enabled = false;
        preparation.session_delete_error = Some(disable_codex_session_delete_after_failure(
            format!("删除会话注入失败：{error}"),
        ));
    }
    if preparation.theme_enabled {
        preparation.theme_enabled = false;
        preparation.theme_payload = None;
        preparation.theme_error = Some(disable_codex_theme_after_failure(format!(
            "主题注入失败：{error}"
        )));
    }
}

fn codex_launch_result(
    preparation: &CodexEnhancementPreparation,
    launched: bool,
    method: &str,
    app_dir: Option<&Path>,
    debug_port: Option<u16>,
    warnings: Vec<String>,
    injection: Option<Value>,
) -> Value {
    json!({
      "launched": launched,
      "ready": launched,
      "launchAccepted": launched,
      "launchConfirmed": launched,
      "launchQueued": false,
      "needsRestart": !launched,
      "method": method,
      "appPath": app_dir.map(codex_effective_launch_path).map(|path| path.to_string_lossy().to_string()).unwrap_or_default(),
      "debugPort": debug_port,
      "warnings": warnings,
      "injection": injection,
      "plugin": codex_enhancement_feature_result(
          preparation.plugin_requested,
          preparation.plugin_applied,
          preparation.plugin_enabled,
          preparation.plugin_error.as_deref(),
      ),
      "sessionDelete": codex_enhancement_feature_result(
          preparation.session_delete_requested,
          preparation.session_delete_applied,
          preparation.session_delete_enabled,
          preparation.session_delete_error.as_deref(),
      ),
      "theme": codex_enhancement_feature_result(
          preparation.theme_requested,
          preparation.theme_applied,
          preparation.theme_enabled,
          preparation.theme_error.as_deref(),
      ),
      "activeThemeId": preparation.theme_payload.as_ref().map(|theme| theme.id.as_str()).unwrap_or(""),
      "pluginBootstrap": preparation.plugin_bootstrap,
      "ultra": codex_ultra_runtime::status(),
      "nativeFast": codex_native_fast_runtime::status(),
      "apiMode": codex_api_mode::status(codex_api_coding_mode_enabled(), current_codex_runtime_revision()),
    })
}

fn codex_launch_is_queued(launch: &Value) -> bool {
    json_bool(launch, "launchQueued")
        || (json_bool(launch, "launchAccepted") && !json_bool(launch, "launchConfirmed"))
}

fn codex_launch_needs_restart(launch: &Value) -> bool {
    !json_bool(launch, "launchConfirmed") && !codex_launch_is_queued(launch)
}

fn codex_enhancement_preparation_warnings(
    preparation: &CodexEnhancementPreparation,
) -> Vec<String> {
    preparation
        .plugin_error
        .iter()
        .chain(preparation.session_delete_error.iter())
        .chain(preparation.theme_error.iter())
        .cloned()
        .collect()
}

fn codex_background_runtime_launch_result(
    preparation: &CodexEnhancementPreparation,
    app_dir: &Path,
    debug_port: u16,
    launch_confirmed: bool,
    warnings: Vec<String>,
) -> Value {
    let mut result = codex_launch_result(
        preparation,
        launch_confirmed,
        "cdp-background",
        Some(app_dir),
        Some(debug_port),
        warnings,
        None,
    );
    if let Some(object) = result.as_object_mut() {
        object.insert("launchAccepted".to_string(), Value::Bool(true));
        object.insert("launchConfirmed".to_string(), Value::Bool(launch_confirmed));
        object.insert("launchQueued".to_string(), Value::Bool(!launch_confirmed));
        object.insert("needsRestart".to_string(), Value::Bool(false));
        object.insert("background".to_string(), Value::Bool(true));
        object.insert("runtimePending".to_string(), Value::Bool(true));
    }
    result
}

fn launch_prepared_codex(
    preferred: Vec<PathBuf>,
    preparation: CodexEnhancementPreparation,
) -> Value {
    launch_prepared_codex_with_target(preferred, preparation, None)
}

fn launch_prepared_codex_with_target(
    preferred: Vec<PathBuf>,
    mut preparation: CodexEnhancementPreparation,
    patched_app_dir: Option<PathBuf>,
) -> Value {
    // Every launch path (including aggregate login) starts a fresh verification
    // generation. A previous process must not validate the newly launched one.
    codex_ultra_runtime::reset();
    codex_native_fast_runtime::reset();
    codex_api_mode::reset();
    let aggregate_picker_requested = aggregate_model_picker_enabled();
    let model_transition_guard_requested = codex_model_transition_guard_required(&codex_fuel_runtime_state());
    let api_coding_mode_requested = codex_api_coding_mode_enabled();
    let runtime_requested = preparation.plugin_requested
        || preparation.session_delete_requested
        || preparation.theme_requested
        || aggregate_picker_requested
        || model_transition_guard_requested
        || api_coding_mode_requested
        || codex_account_balance_enabled();
    let selected_app_dir = if let Some(app_dir) = patched_app_dir {
        Some(app_dir)
    } else if runtime_requested {
        choose_runtime_enhancement_codex_app_dir(preferred)
    } else {
        choose_launchable_codex_app_dir(preferred)
    };
    let Some(app_dir) = selected_app_dir else {
        let error = "没有找到可启动的 Codex/ChatGPT，请在系统配置中选择启动路径。";
        disable_shared_codex_enhancements(&mut preparation, error);
        return codex_launch_result(
            &preparation,
            false,
            "none",
            None,
            None,
            vec![error.to_string()],
            None,
        );
    };

    // Normalize the saved native preference before any renderer can restore
    // Work. Runtime auth/policy checks still decide when Coding is verified.
    if api_coding_mode_requested {
        if let Err(error) = codex_api_mode::prepare_startup(&codex_fuel_runtime_config_path()) {
            return codex_launch_result(
                &preparation, false, "blocked-api-mode-configuration", Some(&app_dir),
                None, vec![error], None,
            );
        }
    }

    if !runtime_requested {
        return match launch_codex_normally_and_wait(&app_dir) {
            Ok(()) => codex_launch_result(
                &preparation,
                true,
                "normal",
                Some(&app_dir),
                None,
                Vec::new(),
                None,
            ),
            Err(error) => codex_launch_result(
                &preparation,
                false,
                "normal",
                Some(&app_dir),
                None,
                vec![error],
                None,
            ),
        };
    }

    let debug_port = match select_available_codex_cdp_port() {
        Ok(port) => port,
        Err(error) => {
            disable_shared_codex_enhancements(&mut preparation, &error);
            if model_transition_guard_requested || api_coding_mode_requested {
                let warnings = vec![
                    error,
                    "编码模式或模型切换保护未能启动，已停止自动打开 Codex；请检查调试启动权限后重试。"
                        .to_string(),
                ];
                return codex_launch_result(
                    &preparation,
                    false,
                    "cdp-required",
                    Some(&app_dir),
                    None,
                    warnings,
                    None,
                );
            }
            let fallback = launch_codex_normally_and_wait(&app_dir);
            let mut warnings = vec![error];
            if let Err(fallback_error) = &fallback {
                warnings.push(fallback_error.clone());
            }
            return codex_launch_result(
                &preparation,
                fallback.is_ok(),
                "fallback-normal",
                Some(&app_dir),
                None,
                warnings,
                None,
            );
        }
    };
    if preparation.plugin_requested {
        let _ = set_codex_plugin_enhancement_enabled(true, Some(debug_port));
    }
    if preparation.session_delete_requested {
        let _ = set_codex_session_delete_enabled(true, Some(debug_port));
    }
    if preparation.theme_requested {
        let _ = codex_themes::set_theme_applied(debug_port);
    }
    set_codex_runtime_debug_port(debug_port);
    invalidate_codex_runtime_injection_state();
    match launch_codex_with_cdp(&app_dir, debug_port) {
        Ok(()) => {
            // Login/configuration success must not wait for a renderer target or
            // a long Runtime.evaluate promise. The watcher discovers the page,
            // starts the local bridge, and verifies injection after this command
            // has returned to the UI.
            start_codex_runtime_watcher();
            let launch_confirmed = confirm_codex_launch_lightweight(&app_dir);
            codex_background_runtime_launch_result(
                &preparation,
                &app_dir,
                debug_port,
                launch_confirmed,
                codex_enhancement_preparation_warnings(&preparation),
            )
        }
        Err(error) if codex_app_is_running(&app_dir) => {
            // Windows packaged activation can report an argument/activation
            // error after the official client has already started. Preserve the
            // requested features and let the watcher probe the selected port.
            log::warn!("Codex CDP launch reported an error after startup; background retry scheduled: {error}");
            start_codex_runtime_watcher();
            codex_background_runtime_launch_result(
                &preparation,
                &app_dir,
                debug_port,
                true,
                codex_enhancement_preparation_warnings(&preparation),
            )
        }
        Err(error) => {
            disable_shared_codex_enhancements(&mut preparation, &error);
            if model_transition_guard_requested || api_coding_mode_requested {
                let warnings = vec![
                    error,
                    "编码模式或模型切换保护未能启动，已停止自动打开 Codex；请检查调试启动权限后重试。"
                        .to_string(),
                ];
                return codex_launch_result(
                    &preparation,
                    false,
                    "cdp-required",
                    Some(&app_dir),
                    Some(debug_port),
                    warnings,
                    None,
                );
            }
            let fallback = launch_codex_normally_and_wait(&app_dir);
            let mut warnings = vec![error];
            if let Err(fallback_error) = &fallback {
                warnings.push(fallback_error.clone());
            }
            codex_launch_result(
                &preparation,
                fallback.is_ok(),
                "fallback-normal",
                Some(&app_dir),
                Some(debug_port),
                warnings,
                None,
            )
        }
    }
}

fn stop_prepare_and_launch_codex_with_options(
    app: &AppHandle,
    allow_plugin_download: bool,
    retired_app_dirs: &[PathBuf],
) -> Value {
    let preferred = list_running_codex_app_dirs();
    codex_api_project_bridge::request_graceful_native_exit();
    let _ = stop_codex_app_with_additional_targets(retired_app_dirs);
    let close_result = wait_for_codex_app_exit_with_additional_targets(
        Duration::from_secs(CODEX_APP_EXIT_WAIT_SECS),
        retired_app_dirs,
    );
    if let Err(close_error) = close_result {
        let mut preparation = codex_enhancement_preparation_state();
        disable_shared_codex_enhancements(&mut preparation, &close_error);
        let selected_app_dir = choose_launchable_codex_app_dir(preferred);
        let mut blocked = codex_launch_result(
            &preparation,
            false,
            "blocked-unconfirmed-exit",
            selected_app_dir.as_deref(),
            None,
            vec![close_error],
            None,
        );
        if let Some(object) = blocked.as_object_mut() {
            object.insert("codexClosed".to_string(), Value::Bool(false));
        }
        return blocked;
    }
    if let Err(error) = codex_api_project_bridge::finalize_after_native_exit() {
        let mut preparation = codex_enhancement_preparation_state();
        disable_shared_codex_enhancements(&mut preparation, &error);
        let selected_app_dir = choose_launchable_codex_app_dir(preferred);
        let mut blocked = codex_launch_result(
            &preparation, false, "blocked-project-final-save",
            selected_app_dir.as_deref(), None, vec![error], None,
        );
        blocked["codexClosed"] = json!(true);
        return blocked;
    }
    let direct_route_migration = load_router_state().and_then(|router| {
        codex_direct_route_migration::restore_direct_after_exit(
            &router, &codex_route_targets(), true,
        )
    });
    if let Err(error) = direct_route_migration {
        let warning = format!("普通 API 域名直连恢复未完成，请重新执行 API 登录：{error}");
        let mut preparation = codex_enhancement_preparation_state();
        disable_shared_codex_enhancements(&mut preparation, &warning);
        let selected_app_dir = choose_launchable_codex_app_dir(preferred);
        let mut blocked = codex_launch_result(
            &preparation, false, "blocked-direct-route-migration",
            selected_app_dir.as_deref(), None, vec![warning], None,
        );
        if let Some(object) = blocked.as_object_mut() {
            object.insert("codexClosed".to_string(), Value::Bool(true));
        }
        return blocked;
    }
    // Native restart callers all pass here after confirmed exit. A failed
    // first policy read blocks launch instead of silently keeping a wider list.
    let model_policy_preparation = match desktop_model_support::refresh_managed_catalogs(&codex_route_targets()) {
        Ok(result) => result,
        Err(error) => {
            let mut preparation = codex_enhancement_preparation_state();
            disable_shared_codex_enhancements(&mut preparation, &error);
            let selected_app_dir = choose_launchable_codex_app_dir(preferred);
            let mut blocked = codex_launch_result(&preparation, false, "blocked-model-support-refresh",
                selected_app_dir.as_deref(), None, vec![error], None);
            blocked["codexClosed"] = json!(true);
            return blocked;
        }
    };
    let ultra_preparation = prepare_codex_managed_ultra_configuration(&codex_route_targets());
    codex_ultra_runtime::reset();
    codex_native_fast_runtime::reset();
    codex_api_mode::reset();
    let preparation = prepare_codex_enhancements(app, allow_plugin_download);
    let mut launch = launch_prepared_codex(preferred, preparation);
    append_codex_result_warnings(&mut launch, &ultra_preparation);
    append_codex_result_warnings(&mut launch, &model_policy_preparation);
    if let Some(object) = launch.as_object_mut() {
        object.insert("codexClosed".to_string(), Value::Bool(true));
        object.insert("appPatch".to_string(), ultra_preparation);
        object.insert("ultra".to_string(), codex_ultra_runtime::status());
        object.insert("nativeFast".to_string(), codex_native_fast_runtime::status());
    }
    launch
}

fn stop_prepare_and_launch_codex(app: &AppHandle) -> Value {
    stop_prepare_and_launch_codex_with_options(app, false, &[])
}

fn aggregate_provider_id(value: Option<&str>) -> Result<String, String> {
    let provider_id = value.unwrap_or_default().trim().to_ascii_lowercase();
    if provider_id.is_empty()
        || provider_id.len() > 32
        || !provider_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err("聚合模型供应商标识无效。".to_string());
    }
    Ok(provider_id)
}

fn aggregate_group_id(value: Option<&Value>) -> Result<String, String> {
    let group_id = value
        .and_then(|value| {
            value
                .as_u64()
                .map(|number| number.to_string())
                .or_else(|| value.as_i64().map(|number| number.to_string()))
                .or_else(|| value.as_str().map(|text| text.trim().to_string()))
        })
        .unwrap_or_else(|| "default".to_string());
    if group_id.is_empty()
        || group_id.len() > 40
        || !group_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err("聚合账号分组标识无效。".to_string());
    }
    Ok(group_id)
}

fn append_aggregate_group_routes(
    routes: &mut Vec<AggregateProviderRoute>,
    public_models: &mut HashSet<String>,
    source: aggregate_settings::AggregateSource,
    provider_id: &str,
    provider_name: &str,
    provider_base_url: Option<&str>,
    group: &Value,
) -> Result<(), String> {
    let group_id = aggregate_group_id(group.get("id").or_else(|| group.get("groupId")))?;
    let group_name = group
        .get("name")
        .or_else(|| group.get("groupName"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
        .unwrap_or_else(|| format!("分组 {group_id}"));
    if group_name.len() > 100 || group_name.chars().any(char::is_control) {
        return Err(format!("{provider_name} 的账号分组名称无效。"));
    }
    let upstream_platform = group
        .get("platform")
        .or_else(|| group.get("upstreamPlatform"))
        .and_then(Value::as_str)
        .unwrap_or(provider_id)
        .trim()
        .to_ascii_lowercase();
    if upstream_platform.is_empty()
        || upstream_platform.len() > 32
        || !upstream_platform
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err(format!(
            "{provider_name} / {group_name} 的上游平台标识无效。"
        ));
    }
    let group_rate_text = group
        .get("rateText")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim()
        .to_string();
    if group_rate_text.len() > 40 || group_rate_text.chars().any(char::is_control) {
        return Err(format!("{group_name} 的倍率说明无效。"));
    }
    let api_key = group
        .get("apiKey")
        .or_else(|| group.get("api_key"))
        .or_else(|| group.get("key"))
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    if api_key.is_empty() {
        return Err(format!(
            "请先为 {provider_name} / {group_name} 准备可用 Key。"
        ));
    }
    let base_url = normalize_base_url_strict(
        group
            .get("baseUrl")
            .and_then(Value::as_str)
            .or(provider_base_url),
        "",
    )?;
    let protocol = aggregate_protocol::Protocol::parse(group.get("protocol").and_then(Value::as_str).unwrap_or("responses"))?;
    aggregate_protocol::endpoint(protocol, &base_url, "/responses")?;
    let models = normalize_codex_model_names(group.get("models"));
    if models.is_empty() {
        return Err(format!("{provider_name} / {group_name} 没有可写入的模型。"));
    }
    let provider_prefix = format!("{provider_id}/");
    let public_prefix = format!("gaoge/{provider_id}/{group_id}/");
    for model in models {
        let upstream_model = model
            .strip_prefix(&public_prefix)
            .or_else(|| model.strip_prefix(&provider_prefix))
            .unwrap_or(model.as_str())
            .trim();
        if upstream_model.is_empty() || !is_codex_conversation_model(upstream_model) {
            continue;
        }
        let public_model = format!("{public_prefix}{upstream_model}");
        if public_model.len() > 240 || public_model.chars().any(char::is_control) {
            return Err(format!("聚合模型名称过长或无效：{public_model}"));
        }
        if !public_models.insert(format!("{source:?}/{public_model}")) {
            continue;
        }
        routes.push(AggregateProviderRoute {
            source,
            protocol,
            model_config: aggregate_settings::validate_model_config(&group["modelSettings"][upstream_model])?,
            provider_id: provider_id.to_string(),
            provider_name: provider_name.to_string(),
            upstream_platform: upstream_platform.clone(),
            group_id: group_id.clone(),
            group_name: group_name.clone(),
            group_rate_text: group_rate_text.clone(),
            public_model,
            upstream_model: upstream_model.to_string(),
            base_url: base_url.clone(),
            api_key: api_key.to_string(),
        });
        if routes.len() > 1000 {
            return Err("聚合模型总数不能超过 1000 个。".to_string());
        }
    }
    Ok(())
}

fn aggregate_login_state_from_request(request: &Value) -> Result<AggregateLoginState, String> {
    let providers = request
        .get("providers")
        .and_then(Value::as_array)
        .ok_or_else(|| "聚合登录缺少模型供应商。".to_string())?;
    if providers.is_empty() {
        return Err("聚合登录至少需要一个可用模型供应商。".to_string());
    }
    let mut routes = Vec::new();
    let mut provider_ids = HashSet::new();
    let mut public_models = HashSet::new();
    for provider in providers {
        if provider.get("enabled").and_then(Value::as_bool) == Some(false) {
            continue;
        }
        let provider_id = aggregate_provider_id(provider.get("id").and_then(Value::as_str))?;
        let source_value = provider.get("source").and_then(Value::as_str);
        if source_value.is_some_and(|value| !matches!(value, "builtin" | "custom")) {
            return Err("聚合来源必须是 builtin 或 custom。".into());
        }
        let legacy_custom = provider.get("groups").and_then(Value::as_array)
            .is_some_and(|groups| !groups.is_empty() && groups.iter().all(|group| group["id"] == "custom"));
        let source = aggregate_settings::AggregateSource::from_legacy(
            source_value, &provider_id, if legacy_custom { "custom" } else { "" },
        );
        if !provider_ids.insert((source, provider_id.clone())) {
            return Err(format!("聚合模型供应商 {provider_id} 重复。"));
        }
        let provider_name = provider
            .get("name")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(provider_id.as_str());
        if provider_name.len() > 80 || provider_name.chars().any(char::is_control) {
            return Err(format!("聚合模型供应商 {provider_id} 名称无效。"));
        }
        let provider_base_url = provider.get("baseUrl").and_then(Value::as_str);
        if let Some(groups) = provider.get("groups").and_then(Value::as_array) {
            if groups.is_empty() {
                return Err(format!("{provider_name} 没有可用账号分组。"));
            }
            for group in groups {
                append_aggregate_group_routes(
                    &mut routes,
                    &mut public_models,
                    source,
                    &provider_id,
                    provider_name,
                    provider_base_url,
                    group,
                )?;
            }
        } else {
            let legacy_group = json!({
              "id": provider.get("groupId").cloned().unwrap_or_else(|| json!("default")),
              "name": provider.get("groupName").cloned().unwrap_or_else(|| json!("默认分组")),
              "rateText": provider.get("rateText").cloned().unwrap_or_else(|| json!("")),
              "apiKey": provider.get("apiKey").cloned().unwrap_or_else(|| json!("")),
              "baseUrl": provider.get("baseUrl").cloned().unwrap_or_else(|| json!("")),
              "models": provider.get("models").cloned().unwrap_or_else(|| json!([])),
            });
            append_aggregate_group_routes(
                &mut routes,
                &mut public_models,
                source,
                &provider_id,
                provider_name,
                provider_base_url,
                &legacy_group,
            )?;
        }
    }
    if routes.is_empty() {
        return Err("聚合登录没有可用模型。".to_string());
    }
    // Keep existing route IDs unless the same full ID appears in both sources.
    // Resolve collisions after collecting all routes so input order is irrelevant.
    let builtin_ids: HashSet<String> = routes.iter()
        .filter(|route| route.source == aggregate_settings::AggregateSource::Builtin)
        .map(|route| route.public_model.clone()).collect();
    for route in &mut routes {
        if route.source == aggregate_settings::AggregateSource::Custom && builtin_ids.contains(&route.public_model) {
            route.public_model = format!("gaoge/custom/{}", route.public_model.strip_prefix("gaoge/").unwrap_or(&route.public_model));
        }
    }
    let mut unique_routes = HashSet::new();
    if routes.iter().any(|route| route.public_model.len() > 240 || !unique_routes.insert(route.public_model.clone())) {
        return Err("聚合模型完整路由标识冲突或过长，请修改接口或分组标识。".into());
    }
    let requested_default = request
        .get("defaultModel")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .trim();
    let requested_default_model = routes
        .iter()
        .find(|route| route.public_model == requested_default)
        .map(|route| route.public_model.clone());
    let default_model_origin = if requested_default_model.is_some() {
        CODEX_MODEL_SELECTION_ORIGIN_USER
    } else {
        CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC
    };
    let default_model = requested_default_model
        .or_else(|| {
            routes
                .iter()
                .find(|route| {
                    route.provider_id == "openai" && route.upstream_model == CODEX_DEFAULT_MODEL
                })
                .map(|route| route.public_model.clone())
        })
        .or_else(|| {
            routes
                .iter()
                .find(|route| route.provider_id == "openai")
                .map(|route| route.public_model.clone())
        })
        .unwrap_or_else(|| routes[0].public_model.clone());
    Ok(AggregateLoginState {
        enabled: true,
        router_port: 0,
        router_token: random_session_helper_token(),
        default_model,
        default_model_origin: default_model_origin.to_string(),
        speed_mode: request
            .get("speedMode")
            .and_then(Value::as_str)
            .and_then(normalize_aggregate_speed_mode)
            .unwrap_or(AGGREGATE_SPEED_MODE_STANDARD)
            .to_string(),
        official_account_key: String::new(),
        routes,
        recovery_models: Vec::new(),
        updated_at: unix_now(),
    })
}

/// A conversation retains its full model ID. Reapplying the catalog may remove
/// that ID, but must never assign it to a different source or billing group.
fn validate_aggregate_route_identity_transition(
    previous: &AggregateLoginState,
    next: &AggregateLoginState,
) -> Result<(), String> {
    let previous_routes: HashMap<&str, &AggregateProviderRoute> = previous.routes.iter()
        .map(|route| (route.public_model.as_str(), route)).collect();
    for route in &next.routes {
        let Some(old) = previous_routes.get(route.public_model.as_str()) else { continue };
        if old.source != route.source
            || old.provider_id != route.provider_id
            || old.group_id != route.group_id
            || old.upstream_model != route.upstream_model
        {
            return Err(format!(
                "聚合模型标识 {} 已属于其他来源、分组或模型。为避免旧会话切到其他线路，请新建自有接口以获取独立标识后重新写入。",
                route.public_model,
            ));
        }
    }
    Ok(())
}

fn aggregate_official_account_key_for_next_login(
    previous: &AggregateLoginState,
) -> Result<String, String> {
    if previous.enabled {
        // An empty key is an explicit signed-out baseline. Reconfiguring the
        // aggregate catalog must preserve it just as strictly as a real key.
        return Ok(previous.official_account_key.clone());
    }
    Ok(save_current_live_codex_auth_snapshot()?.unwrap_or_default())
}

fn gaoge_configure_codex_inner(app: AppHandle, request: Value) -> Result<Value, String> {
    let api_key = request
        .get("apiKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    if api_key.is_empty() {
        return Err("请先填写 Codex API Key。".to_string());
    }
    let _operation = lock_codex_foreground_operation()?;
    let require_current_account = json_bool(&request, "requireCurrentChatgptAccount");
    // Guard before credentials, saved-account activation or stopping Codex.
    let current_fuel_account = require_current_codex_fuel_account(&request)?;
    let replaces_aggregate_login =
        request.get("aggregateLogin").and_then(Value::as_bool) != Some(true);
    let mut progress = CodexLoginProgress::new(&app);
    let requested_model = normalize_model(request.get("model").and_then(Value::as_str));
    let base_url = normalize_base_url(
        request.get("baseUrl").and_then(Value::as_str),
        GAOGE_OPENAI_BASE_URL,
    )?;
    // Resolve at the native write boundary: frontend defaults or stale caches
    // must never widen the server-owned injection list.
    let desktop_model_policy = if replaces_aggregate_login {
        Some(desktop_model_support::refresh(&base_url, request.get("modelPolicyApiBaseUrl").and_then(Value::as_str))?)
    } else { None };
    let policy_request = desktop_model_policy.as_ref()
        .map(|policy| desktop_model_support::constrain_request(&request, policy))
        .unwrap_or_else(|| request.clone());
    let (planned_model, mut planned_model_catalog) =
        codex_model_catalog_plan(&policy_request,
            policy_request.get("model").and_then(Value::as_str).unwrap_or(&requested_model))?;
    if let Some(policy) = &desktop_model_policy {
        if !policy.warning.is_empty() {
            planned_model_catalog.warning = [planned_model_catalog.warning.as_str(), policy.warning.as_str()]
                .into_iter().filter(|part| !part.is_empty()).collect::<Vec<_>>().join(" ");
        }
    }
    let save_image_tools = || match save_codex_image_tool_credentials_from_request(&request) {
            Ok(status) => (status, String::new()),
            Err(error) => (
                json!({
                  "configured": false,
                  "updated": false,
                }),
                format!("Codex 生图工具凭据未更新：{error}"),
            ),
    };
    // Preserve the legacy timing, but fuel mode writes nothing until the
    // post-exit auth check has also passed.
    let early_image_tools = if require_current_account {
        None
    } else {
        Some(save_image_tools())
    };
    let force_api_mode = request
        .get("forceApiMode")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let enhance_model_picker_requested = request
        .get("enhanceModelPicker")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let requested_account_key = request
        .get("accountKey")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let prepared_account = if force_api_mode || require_current_account {
        None
    } else {
        requested_account_key
            .map(prepare_codex_account_activation)
            .transpose()?
    };
    let mut active_account = if require_current_account {
        current_fuel_account
    } else if force_api_mode {
        None
    } else if let Some(prepared) = prepared_account.as_ref() {
        Some(prepared.active_snapshot())
    } else {
        active_codex_account_snapshot()?
    };
    let targets = codex_route_targets();
    let resolved = resolve_codex_model_catalog(&targets, &planned_model, &planned_model_catalog)?;
    let model = resolved.model;
    let model_catalog_plan = resolved.plan;
    let mut model_catalog = resolved.catalog;
    if let Some(policy) = desktop_model_policy.as_ref().filter(|policy| policy.policy.enabled) {
        desktop_model_support::preserve_nonreasoning_declarations(&mut model_catalog, &targets);
        desktop_model_support::apply_catalog_capabilities(&mut model_catalog, &policy.policy);
        model_catalog["gaogeDesktopModelSupport"] = json!({"version":1,"revision":policy.policy.revision});
    }
    let locked_model_mode = model_catalog_plan.mode == CODEX_MODEL_SELECTION_LOCKED;
    let requested_model_origin = normalize_codex_model_selection_origin(
        request.get("modelSelectionOrigin").and_then(Value::as_str),
    );
    let model_origin = if requested_model_origin.is_empty() {
        if locked_model_mode {
            CODEX_MODEL_SELECTION_ORIGIN_USER.to_string()
        } else {
            CODEX_MODEL_SELECTION_ORIGIN_AUTOMATIC.to_string()
        }
    } else {
        requested_model_origin
    };
    let attempt_model_picker_enhancement = should_attempt_codex_model_picker_enhancement(
        codex_model_picker_platform_supported(std::env::consts::OS),
        enhance_model_picker_requested,
        &model_catalog_plan.mode,
        force_api_mode && model_catalog["models"].as_array().is_some_and(|models| {
            models.iter().any(|model| model["supported_reasoning_levels"].as_array()
                .is_some_and(|levels| levels.iter().any(|level| level["effort"] == "ultra")))
        }),
    );
    let running_app_dirs = list_running_codex_app_dirs();
    progress.stage("close", "正在关闭 Codex");
    let codex_closed = stop_codex_app_and_confirm_exit_before_config_write()?;
    if require_current_account {
        // Codex may rotate auth or sign out while closing. Use this latest
        // live material; never restore the pre-check or a saved snapshot.
        active_account = require_current_codex_fuel_account(&request)
            .map_err(|error| core_failure_with_normal_launch(running_app_dirs.clone(), error))?;
    }
    let api_project_source_was_official = read_json_if_exists(
        &codex_fuel_runtime_config_path().with_file_name("auth.json"),
    ).ok().flatten().as_ref().is_some_and(codex_auth_is_chatgpt_login);
    let (image_tools, image_tools_warning) = early_image_tools.unwrap_or_else(save_image_tools);
    progress.stage("configure", "正在写入登录配置与模型");
    let route_transaction = CodexRouteTransactionSnapshot::capture(&targets).map_err(|error| {
        core_failure_with_normal_launch(
            running_app_dirs.clone(),
            format!("创建 Codex 配置事务快照失败：{error}"),
        )
    })?;
    let outer_state = CodexDisableOuterStateSnapshot::capture().map_err(|error| {
        core_failure_with_normal_launch(
            running_app_dirs.clone(),
            format!("创建 Codex 外层状态事务快照失败：{error}"),
        )
    })?;
    if let Err(error) = capture_codex_relay_restore_for_targets(&targets, api_key, force_api_mode) {
        let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
        return Err(core_failure_with_normal_launch(
            running_app_dirs,
            if let Some(rollback) = rollback {
                format!("保存 Codex 登录前状态失败：{error}\n自动回滚失败：{rollback}")
            } else {
                format!("保存 Codex 登录前状态失败：{error}")
            },
        ));
    }
    if let Some(prepared) = prepared_account.as_ref() {
        if let Err(error) = commit_codex_account_activation(prepared) {
            let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
            return Err(core_failure_with_normal_launch(
                running_app_dirs,
                if let Some(rollback) = rollback {
                    format!("切换 Codex 账号失败：{error}\n自动回滚失败：{rollback}")
                } else {
                    format!("切换 Codex 账号失败：{error}")
                },
            ));
        }
    }
    // Write and verify the selected route/catalog first. Picker enhancement is
    // optional, so a slow or protected Store install must never erase the
    // requested 5.6 model or leave the client with only a native fallback.
    let codex_dirs = match configure_codex_route_targets_with_resolved_catalog(
        &targets,
        api_key,
        &base_url,
        &model,
        Some(&model_catalog_plan),
        Some(&model_catalog),
        codex_closed,
        active_account.as_ref(),
        force_api_mode,
    ) {
        Ok(value) => value,
        Err(error) => {
            let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
            return Err(core_failure_with_normal_launch(
                running_app_dirs,
                if let Some(rollback) = rollback {
                    format!("写入 Codex 中转路由失败：{error}\n自动回滚失败：{rollback}")
                } else {
                    format!("写入 Codex 中转路由失败：{error}")
                },
            ));
        }
    };
    let native_model_fallback = false;
    if json_bool(&request, "aggregateLogin") {
        let state = aggregate_login_state_snapshot();
        let speed_config = aggregate_route_for_model(&state, &model)
            .ok_or_else(|| "当前聚合模型不存在，无法保存速度配置。".to_string())
            .and_then(|route| sync_aggregate_model_config(&state, &route));
        if let Err(error) = speed_config {
            let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
            return Err(core_failure_with_normal_launch(
                running_app_dirs,
                if let Some(rollback) = rollback {
                    format!("写入 Codex 聚合速度配置失败：{error}\n自动回滚失败：{rollback}")
                } else {
                    format!("写入 Codex 聚合速度配置失败：{error}")
                },
            ));
        }
    }
    let mut app_patch = if attempt_model_picker_enhancement {
        match enhance_codex_model_picker(running_app_dirs.clone(), None) {
            Ok(value) => value,
            Err(error) => json!({
              "applied": false,
              "method": "model-catalog-only",
              "modelPickerEnhanced": false,
              "modelPickerDegraded": true,
              "catalogPreserved": true,
              "needsRestart": true,
              "warnings": [format!("模型下拉增强未完成：{error}")],
            }),
        }
    } else if locked_model_mode {
        json!({
            "applied": false,
            "method": "locked-model-direct",
            "modelPickerEnhanced": false,
            "lockedModelDirect": true,
            "needsRestart": true,
            "warnings": Vec::<&str>::new(),
        })
    } else {
        json!({
            "applied": false,
            "method": if enhance_model_picker_requested { "unsupported-platform" } else { "disabled" },
            "modelPickerEnhanced": false,
            "needsRestart": true,
            "warnings": if enhance_model_picker_requested {
                vec!["当前平台暂不支持自动增强 Codex 模型下拉框；模型目录仍会正常写入。"]
            } else {
                Vec::<&str>::new()
            },
        })
    };
    let mut state = load_router_state().unwrap_or_else(|_| default_router_state());
    state.enabled = false;
    state.mode = "relay".to_string();
    state.model = model.clone();
    state.model_origin = model_origin;
    state.relay_base_url = base_url.clone();
    state.relay_api_key = api_key.to_string();
    if let Err(error) = save_router_state(state) {
        let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
        return Err(core_failure_with_normal_launch(
            running_app_dirs,
            if let Some(rollback) = rollback {
                format!("保存 Codex 中转路由状态失败：{error}\n自动回滚失败：{rollback}")
            } else {
                format!("保存 Codex 中转路由状态失败：{error}")
            },
        ));
    }
    // Keep the previous aggregate login usable until the replacement route
    // and credentials have been written successfully. Validation or write
    // failures above must not erase the user's aggregate model catalog.
    if replaces_aggregate_login {
        if let Err(error) = deactivate_aggregate_login_state() {
            let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
            return Err(core_failure_with_normal_launch(
                running_app_dirs,
                if let Some(rollback) = rollback {
                    format!("切换为非聚合 Codex 配置失败：{error}\n自动回滚失败：{rollback}")
                } else {
                    format!("切换为非聚合 Codex 配置失败：{error}")
                },
            ));
        }
    }
    let primary = codex_dirs.first().cloned().unwrap_or_else(|| json!({}));
    let api_auth_created = any_json_bool(&codex_dirs, "apiAuthCreated");
    progress.stage("sessions", "正在同步新增和变化的会话");
    let session_sync = sync_codex_route_targets_resilient(CODEX_DIRECT_PROVIDER_ID, true);
    if codex_api_coding_mode_enabled() {
        // Seed the API catalog only after the offline native membership repair.
        if let Err(error) = codex_api_project_bridge::prepare_for_login(api_project_source_was_official) {
            append_codex_result_warnings(&mut app_patch, &json!({
                "warnings": [format!("本地项目恢复尚未就绪：{error}")]
            }));
        }
    }
    let config_path = json_str(&primary, "configPath");
    let backup_path = json_field(&primary, "backupPath");
    let model_catalog_path = json_field(&primary, "modelCatalogPath");
    let route_warning = json_str(&primary, "routeWarning");
    progress.stage("enhancements", "正在准备模型面板与主题");
    let ultra_preparation = prepare_codex_managed_ultra_configuration(&targets);
    append_codex_result_warnings(&mut app_patch, &ultra_preparation);
    app_patch["ultraConfiguration"] = ultra_preparation;
    codex_ultra_runtime::reset();
    codex_native_fast_runtime::reset();
    codex_api_mode::reset();
    let enhancement_preparation = prepare_codex_enhancements(&app, false);
    progress.stage("launch", "正在启动 Codex");
    let patched_app_dir = codex_model_patch_launch_target(&app_patch);
    let mut launch = launch_prepared_codex_with_target(running_app_dirs, enhancement_preparation, patched_app_dir);
    append_codex_result_warnings(&mut launch, &app_patch);
    launch["ultra"] = codex_ultra_runtime::status();
    launch["nativeFast"] = codex_native_fast_runtime::status();
    let codex_launched = json_bool(&launch, "launched");
    let codex_launch_queued = codex_launch_is_queued(&launch);
    if let Some(object) = app_patch.as_object_mut() {
        object.insert("launched".to_string(), Value::Bool(codex_launched));
        object.insert("launchQueued".to_string(), Value::Bool(codex_launch_queued));
        object.insert(
            "needsRestart".to_string(),
            Value::Bool(!codex_launched && !codex_launch_queued),
        );
    }
    let response_catalog_mode = Some(model_catalog_plan.mode.clone());
    let response_catalog_source = Some(model_catalog_plan.source.clone());
    let response_catalog_models = model_catalog_plan.models.clone();
    let response_catalog_warning = model_catalog_plan.warning.clone();
    Ok(
        json!({ "routeConfigured": true, "configPath": config_path, "backupPath": backup_path, "codexDirs": codex_dirs, "model": model, "displayModel": model, "provider": CODEX_DIRECT_PROVIDER_ID, "apiAuthCreated": api_auth_created, "forceApiMode": force_api_mode, "providerScopedToken": true, "nativeModelFallback": native_model_fallback, "modelCatalogPath": model_catalog_path, "modelCatalogMode": response_catalog_mode, "modelCatalogSource": response_catalog_source, "modelCatalogModels": response_catalog_models, "modelCatalogWarning": response_catalog_warning, "desktopModelSupportEnabled": desktop_model_policy.as_ref().is_some_and(|policy| policy.policy.enabled), "desktopModelSupportRevision": desktop_model_policy.as_ref().map(|policy| policy.policy.revision.as_str()).unwrap_or(""), "routeWarning": route_warning, "imageTools": image_tools, "imageToolsWarning": image_tools_warning, "router": public_router_state(json!({ "configUpdated": true, "configPath": config_path })), "sessionSync": session_sync, "appPatch": app_patch, "launch": launch.clone(), "enhancements": { "plugin": json_field(&launch, "plugin"), "sessionDelete": json_field(&launch, "sessionDelete"), "theme": json_field(&launch, "theme") }, "warnings": json_field(&launch, "warnings"), "codexClosed": codex_closed, "codexLaunched": codex_launched, "codexLaunchQueued": codex_launch_queued, "needsRestart": codex_launch_needs_restart(&launch) }),
    )
}

#[tauri::command]
async fn gaoge_configure_codex(app: AppHandle, request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_configure_codex_inner(app, request)).await
}

fn gaoge_configure_aggregate_login_inner(app: AppHandle, request: Value) -> Result<Value, String> {
    let previous = aggregate_login_state_snapshot();
    let aggregate_request = aggregate_settings::apply_to_request(&request)?;
    let mut next = aggregate_login_state_from_request(&aggregate_request)?;
    next.recovery_models = codex_aggregate_model_recovery::remembered_models(&previous);
    validate_aggregate_route_identity_transition(&previous, &next)?;
    if previous.enabled {
        next.speed_mode = normalize_aggregate_speed_mode(&previous.speed_mode)
            .unwrap_or(AGGREGATE_SPEED_MODE_STANDARD)
            .to_string();
    }
    next.official_account_key = aggregate_official_account_key_for_next_login(&previous)?;
    if previous.router_port > 0 {
        next.router_port = previous.router_port;
    }
    if !previous.router_token.is_empty() {
        next.router_token = previous.router_token.clone();
    }
    *AGGREGATE_LOGIN_STATE
        .lock()
        .map_err(|_| "聚合登录状态锁失败。".to_string())? = next.clone();
    let router_base_url = match ensure_aggregate_router_runtime(&mut next) {
        Ok(base_url) => base_url,
        Err(_) if next.router_port > 0 => {
            next.router_port = 0;
            ensure_aggregate_router_runtime(&mut next)?
        }
        Err(error) => return Err(error),
    };
    *AGGREGATE_LOGIN_STATE
        .lock()
        .map_err(|_| "聚合登录状态锁失败。".to_string())? = next.clone();
    save_aggregate_login_state(&next)?;
    bump_codex_runtime_revision();
    start_codex_runtime_watcher();

    let supported_models = next
        .routes
        .iter()
        .map(|route| route.public_model.clone())
        .collect::<Vec<_>>();
    let codex_request = json!({
      "apiKey": next.router_token,
      "baseUrl": router_base_url,
      "model": next.default_model,
      "modelSelectionOrigin": next.default_model_origin,
      "modelSelectionMode": CODEX_MODEL_SELECTION_UPSTREAM,
      "modelCatalogSource": CODEX_MODEL_CATALOG_SOURCE_UPSTREAM,
      "supportedModels": supported_models,
      "mode": "relay",
      "forceApiMode": true,
      "enhanceModelPicker": true,
      "aggregateLogin": true,
      "imageApiKey": request.get("imageApiKey").cloned().unwrap_or(Value::Null),
      "imageBaseUrl": request.get("imageBaseUrl").cloned().unwrap_or(Value::Null),
    });
    match gaoge_configure_codex_inner(app, codex_request) {
        Ok(mut result) => {
            if let Some(object) = result.as_object_mut() {
                object.insert(
                    "aggregate".to_string(),
                    public_aggregate_login_state(&next, true),
                );
            }
            Ok(result)
        }
        Err(error) => {
            stop_aggregate_router_runtime();
            let mut restored = previous;
            if restored.enabled {
                let _ = ensure_aggregate_router_runtime(&mut restored);
            }
            let _ = save_aggregate_login_state(&restored);
            bump_codex_runtime_revision();
            start_codex_runtime_watcher();
            Err(error)
        }
    }
}

#[tauri::command]
async fn gaoge_configure_aggregate_login(app: AppHandle, request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_configure_aggregate_login_inner(app, request)).await
}

#[tauri::command]
async fn gaoge_get_aggregate_model_settings() -> Result<Value, String> {
    run_blocking_task(aggregate_settings::snapshot).await
}

#[tauri::command]
async fn gaoge_save_aggregate_model_settings(request: Value) -> Result<Value, String> {
    run_blocking_task(move || {
        let _guard = try_lock_recover(&CODEX_CONFIGURE_LOCK, "Codex 正在处理其他配置，请稍后重试。")?;
        aggregate_settings::save(&request)
    }).await
}

#[tauri::command]
async fn gaoge_get_aggregate_login_status() -> Result<Value, String> {
    run_blocking_task(|| {
        let _configure_guard = try_lock_recover(
            &CODEX_CONFIGURE_LOCK,
            "Codex 正在处理其他配置，请稍后重试。",
        )?;
        let mut state = aggregate_login_state_snapshot();
        let running = if state.enabled {
            let previous_port = state.router_port;
            let previous_token = state.router_token.clone();
            match ensure_aggregate_router_runtime(&mut state) {
                Ok(_) => {
                    if state.router_port != previous_port || state.router_token != previous_token {
                        save_aggregate_login_state(&state)?;
                    } else {
                        *AGGREGATE_LOGIN_STATE
                            .lock()
                            .map_err(|_| "聚合登录状态锁失败。".to_string())? = state.clone();
                    }
                    true
                }
                Err(error) => {
                    log::warn!("Aggregate router restore failed: {error}");
                    false
                }
            }
        } else {
            stop_aggregate_router_runtime();
            false
        };
        Ok(public_aggregate_login_state(&state, running))
    })
    .await
}

fn gaoge_disable_aggregate_login_inner(app: AppHandle) -> Result<Value, String> {
    // Every route target owns an independent first-login restore baseline.
    // Never promote the primary directory's aggregate account into an
    // explicit override for all other CODEX_HOME locations.
    let mut result = gaoge_disable_codex_fuel_pack_inner_with_restore(app, None)?;
    let state = default_aggregate_login_state();
    if let Some(object) = result.as_object_mut() {
        object.insert(
            "aggregate".to_string(),
            public_aggregate_login_state(&state, false),
        );
    }
    Ok(result)
}

#[tauri::command]
async fn gaoge_disable_aggregate_login(app: AppHandle) -> Result<Value, String> {
    run_blocking_task(move || gaoge_disable_aggregate_login_inner(app)).await
}

fn codex_launch_target_status() -> Value {
    let saved = read_json_if_exists(&codex_launch_target_override_path())
        .ok()
        .flatten();
    let manual_path = saved
        .as_ref()
        .and_then(|value| value.get("selectedPath"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from);
    let manual_app_dir = manual_path
        .as_deref()
        .and_then(|path| validate_codex_launch_selection(path).ok());
    let auto_app_dir = choose_auto_launchable_codex_app_dir(list_running_codex_app_dirs());
    let (source, effective_app_dir) = if let Some(app_dir) = manual_app_dir.as_ref() {
        ("manual", Some(app_dir))
    } else if let Some(app_dir) = auto_app_dir.as_ref() {
        ("auto", Some(app_dir))
    } else {
        ("none", None)
    };
    let manual_valid = manual_path.is_some() && manual_app_dir.is_some();
    let warning = if manual_path.is_some() && !manual_valid {
        "手动设置的 Codex/ChatGPT 路径已经失效，当前已回退到自动识别路径。"
    } else {
        ""
    };
    json!({
      "source": source,
      "platform": std::env::consts::OS,
      "manualPath": manual_path.map(|path| path.to_string_lossy().to_string()).unwrap_or_default(),
      "manualValid": manual_valid,
      "autoDetectedPath": auto_app_dir.as_deref().map(codex_effective_launch_path).map(|path| path.to_string_lossy().to_string()).unwrap_or_default(),
      "effectivePath": effective_app_dir.map(|path| codex_effective_launch_path(path).to_string_lossy().to_string()).unwrap_or_default(),
      "appDir": effective_app_dir.map(|path| path.to_string_lossy().to_string()).unwrap_or_default(),
      "valid": effective_app_dir.is_some(),
      "warning": warning,
    })
}

fn merge_codex_launch_target_status(mut status: Value, restart: Option<Value>) -> Value {
    if let Some(object) = status.as_object_mut() {
        object.insert("restart".to_string(), restart.unwrap_or(Value::Null));
    }
    status
}

fn codex_process_transition_targets() -> Result<Vec<PathBuf>, String> {
    let mut targets = probe_running_codex_app_dirs()?;
    #[cfg(any(test, target_os = "windows", target_os = "macos"))]
    if let Some(persisted) = persisted_codex_process_app_dir() {
        targets.push(persisted);
    }
    if let Some(effective) = choose_launchable_codex_app_dir(Vec::new()) {
        targets.push(effective);
    }
    let mut seen = HashSet::new();
    targets.retain(|path| seen.insert(codex_path_identity(path)));
    Ok(targets)
}

