fn gaoge_set_codex_launch_target_inner(app: AppHandle, request: Value) -> Result<Value, String> {
    let selected_path = request
        .get("path")
        .or_else(|| request.get("selectedPath"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .ok_or_else(|| "请选择 Codex/ChatGPT 启动程序。".to_string())?;
    let app_dir = validate_codex_launch_selection(&selected_path)?;
    let _operation = lock_codex_foreground_operation()?;
    let retired_app_dirs = codex_process_transition_targets()?;
    stop_codex_app_and_confirm_exit_before_config_write()?;
    persist_codex_launch_target_override(&selected_path, &app_dir)?;
    let restart = stop_prepare_and_launch_codex_with_options(&app, false, &retired_app_dirs);
    Ok(merge_codex_launch_target_status(
        codex_launch_target_status(),
        Some(restart),
    ))
}

