fn gaoge_restart_codex_inner(app: AppHandle, request: Option<Value>) -> Result<Value, String> {
    let _operation = lock_codex_foreground_operation()?;
    if let Some(request) = request {
        let router = load_router_state()?;
        if let Some(control) = request.get("modelPolicyApiBaseUrl").and_then(Value::as_str) {
            let relay = request.get("relayBaseUrl").and_then(Value::as_str).unwrap_or_default();
            if relay.trim_end_matches('/') == router.relay_base_url.trim_end_matches('/') {
                desktop_model_support::remember_pair(relay, control)?;
            }
        }
    }
    let launch = stop_prepare_and_launch_codex(&app);
    Ok(json!({
      "routeConfigured": codex_fuel_pack_active(),
      "launch": launch.clone(),
      "enhancements": {
        "plugin": json_field(&launch, "plugin"),
        "sessionDelete": json_field(&launch, "sessionDelete"),
        "theme": json_field(&launch, "theme"),
      },
      "warnings": json_field(&launch, "warnings"),
      "codexClosed": json_bool(&launch, "codexClosed"),
      "appPatch": json_field(&launch, "appPatch"),
      "ultra": json_field(&launch, "ultra"),
      "codexLaunched": json_bool(&launch, "launched"),
      "codexLaunchQueued": codex_launch_is_queued(&launch),
      "appPath": json_str(&launch, "appPath"),
      "needsRestart": codex_launch_needs_restart(&launch),
    }))
}

