fn codex_theme_runtime_state(update: bool) -> Value {
    let theme = match codex_themes::active_theme_runtime_payload() {
        Ok(theme) => theme,
        Err(error) => {
            let mut status = codex_theme_status::response(None, json!({"error": error}));
            status["selectedThemeId"] = json!(codex_themes::active_theme_id().unwrap_or_default());
            return status;
        }
    };
    let debug_port = codex_plugin_active_debug_port();
    let runtime = query_cdp_targets(debug_port).and_then(pick_cdp_page_target)
        .ok().and_then(|target| target.web_socket_debugger_url)
        .and_then(|websocket_url| {
            let expected_version = codex_theme_status::RUNTIME_VERSION;
            let script = if update {
                let payload = serde_json::to_string(&theme).ok()?;
                format!(r#"(async () => {{
                  const controller = window.__gaogeCodexThemeController;
                  if (controller?.version !== {expected_version} || typeof controller.apply !== 'function' || typeof controller.status !== 'function') return null;
                  window.__GAOGE_CODEX_THEME__ = {payload};
                  try {{
                    const outcome = await controller.apply(window.__GAOGE_CODEX_THEME__);
                    const status = controller.status();
                    if (outcome?.error && !status?.error) return {{...status, ready: false, applied: false, error: outcome.error}};
                    window.__GAOGE_THEME_RUNTIME_READY__ = status?.ready === true;
                    return status;
                  }} catch (error) {{ return {{version: {expected_version}, ready: false, applied: false, error: String(error?.message || error)}}; }}
                }})()"#)
            } else {
                format!("(() => {{ const c = window.__gaogeCodexThemeController; return c?.version === {expected_version} && typeof c.status === 'function' ? c.status() : null; }})()")
            };
            cdp_evaluate_script(&websocket_url, &script).ok()
        }).unwrap_or(Value::Null);
    let status = codex_theme_status::response(theme.as_ref(), runtime);
    if update && theme.is_some() && json_bool(&status, "runtimeReady") {
        let _ = codex_themes::set_theme_applied(debug_port);
    }
    status
}

fn codex_theme_mutation_response(mut result: Value, update: bool) -> Value {
    let runtime = codex_theme_runtime_state(update);
    if result["status"]["themes"].is_array() {
        codex_theme_status::decorate_catalog(&mut result["status"], &runtime);
    }
    if let Some(object) = result.as_object_mut() {
        object.insert("applied".into(), runtime["runtimeReady"].clone());
        object.insert("needsRestart".into(), runtime["needsRestart"].clone());
        object.insert("runtime".into(), runtime);
    }
    result
}

