fn gaoge_deactivate_codex_theme_inner() -> Result<Value, String> {
    let _configure_guard = try_lock_recover(&CODEX_CONFIGURE_LOCK, "Codex 正在处理其他配置，请稍后重试。")?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let _configure_activity = CodexConfigureActivityGuard::start();
    // Preserve the active connection before clearing the selected theme's saved port.
    set_codex_runtime_debug_port(codex_plugin_active_debug_port());
    let status = codex_themes::deactivate_theme()?;
    bump_codex_runtime_revision();
    start_codex_runtime_watcher();
    let mut result = codex_theme_mutation_response(json!({
        "status": status, "warnings": Vec::<String>::new(),
        "codexClosed": false, "codexLaunched": false,
    }), true);
    let applied = json_bool(&result, "applied");
    result["theme"] = codex_enhancement_feature_result(false, applied, false, None);
    result["message"] = json!(if applied { "已恢复 Codex 默认主题。" } else { "已选择默认主题，等待 Codex 恢复。" });
    Ok(result)
}

