fn gaoge_disable_codex_fuel_pack_inner_with_restore(
    app: AppHandle,
    restore_account_key: Option<&str>,
) -> Result<Value, String> {
    gaoge_disable_codex_fuel_pack_inner_with_recovery(app, restore_account_key, false)
}

fn codex_secondary_auth_restore_warnings(targets: &[Value]) -> Vec<Value> {
    targets
        .iter()
        .filter(|target| !json_bool(target, "primary"))
        .filter_map(|target| {
            let reason = target.get("authCleanup")?.get("reason")?.as_str()?;
            let notice = match reason {
                "native_signed_out_after_missing_official_auth" => {
                    "原账号登录凭据缺失，已恢复官方未登录状态，请重新登录。"
                }
                "native_signed_out_after_invalid_official_auth" => {
                    "原账号登录已失效，已恢复官方未登录状态，请重新登录。"
                }
                "preserved_current_auth_after_missing_official_auth" => {
                    "原账号登录凭据缺失，无法恢复原账号，已保留当前登录状态。"
                }
                "preserved_current_auth_after_invalid_official_auth" => {
                    "原账号登录已失效，无法恢复原账号，已保留当前登录状态。"
                }
                _ => return None,
            };
            Some(Value::String(format!(
                "{}：{notice}",
                json_str(target, "codexDir")
            )))
        })
        .collect()
}

fn gaoge_disable_codex_fuel_pack_inner_with_recovery(
    app: AppHandle,
    restore_account_key: Option<&str>,
    force_official: bool,
) -> Result<Value, String> {
    let _operation = lock_codex_foreground_operation()?;
    let mut progress = CodexLoginProgress::new(&app);
    let running_app_dirs = list_running_codex_app_dirs();
    progress.stage("close", "正在关闭 Codex");
    let codex_closed = stop_codex_app_and_confirm_exit_before_config_write()?;
    progress.stage("configure", "正在恢复官方登录配置");
    let route_targets = codex_route_targets();
    let route_transaction =
        CodexRouteTransactionSnapshot::capture(&route_targets).map_err(|error| {
            core_failure_with_normal_launch(
                running_app_dirs.clone(),
                format!("创建 Codex 关闭事务快照失败：{error}"),
            )
        })?;
    let outer_state = CodexDisableOuterStateSnapshot::capture().map_err(|error| {
        core_failure_with_normal_launch(
            running_app_dirs.clone(),
            format!("创建 Codex 外层状态快照失败：{error}"),
        )
    })?;
    // Preparing an account can refresh its snapshot and update registry
    // metadata, so it belongs inside the transaction boundary.
    let prepared_restore = match restore_account_key
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(prepare_codex_account_activation)
        .transpose()
    {
        Ok(prepared) => prepared,
        Err(error) => {
            let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state);
            return Err(core_failure_with_normal_launch(
                running_app_dirs,
                if let Some(rollback) = rollback {
                    format!("准备 Codex 恢复账号失败：{error}\n自动回滚失败：{rollback}")
                } else {
                    format!("准备 Codex 恢复账号失败：{error}")
                },
            ));
        }
    };
    // A normal close must restore each route target's own first-login
    // baseline. Only a genuinely explicit caller-selected account may
    // override those saved states.
    let active_account = prepared_restore
        .as_ref()
        .map(PreparedCodexAccountActivation::active_snapshot);
    let mut state = load_router_state().unwrap_or_else(|_| default_router_state());
    let relay_api_key = state.relay_api_key.clone();
    let mut codex_dirs = match disable_codex_fuel_pack_all_route_targets_with_recovery(
        &relay_api_key,
        codex_closed,
        active_account.as_ref(),
        force_official,
    ) {
        Ok(value) => value,
        Err(error) => {
            let rollback = restore_codex_route_and_outer_state(&route_transaction, &outer_state)
                .map(|rollback| format!("\n自动回滚失败：{rollback}"))
                .unwrap_or_default();
            return Err(core_failure_with_normal_launch(
                running_app_dirs,
                format!("恢复 Codex 官方路由失败：{error}{rollback}"),
            ));
        }
    };
    state.enabled = false;
    state.mode = "official".to_string();
    if let Err(error) = save_router_state(state) {
        let mut rollback_errors = Vec::new();
        if let Err(rollback) = route_transaction.restore() {
            rollback_errors.push(rollback);
        }
        if let Err(rollback) = outer_state.restore() {
            rollback_errors.push(rollback);
        }
        return Err(core_failure_with_normal_launch(
            running_app_dirs,
            if rollback_errors.is_empty() {
                format!("保存 Codex 官方路由状态失败：{error}")
            } else {
                format!(
                    "保存 Codex 官方路由状态失败：{error}\n自动回滚失败：{}",
                    rollback_errors.join("\n")
                )
            },
        ));
    }
    if let Err(error) = deactivate_aggregate_login_state() {
        let mut rollback_errors = Vec::new();
        if let Err(rollback) = route_transaction.restore() {
            rollback_errors.push(rollback);
        }
        if let Err(rollback) = outer_state.restore() {
            rollback_errors.push(rollback);
        }
        return Err(core_failure_with_normal_launch(
            running_app_dirs,
            if rollback_errors.is_empty() {
                format!("关闭聚合登录状态失败：{error}")
            } else {
                format!(
                    "关闭聚合登录状态失败：{error}\n自动回滚失败：{}",
                    rollback_errors.join("\n")
                )
            },
        ));
    }
    let primary = codex_dirs.first().cloned().unwrap_or_else(|| json!({}));
    let auth_cleanup = json_field(&primary, "authCleanup");
    progress.stage("sessions", "正在同步新增和变化的会话");
    let session_sync = sync_codex_route_targets_resilient("openai", true);
    require_official_session_sync_completed(&session_sync)?;
    let config_path = json_str(&primary, "configPath");
    let backup_path = json_field(&primary, "backupPath");
    progress.stage("enhancements", "正在准备模型面板与主题");
    let enhancement_preparation = prepare_codex_enhancements(&app, false);
    progress.stage("launch", "正在启动 Codex");
    let launch = launch_prepared_codex(running_app_dirs, enhancement_preparation);
    // Read only after launch: never overwrite a newly selected account or roll
    // back a running client merely because verification is pending or failed.
    let auth_verification = codex_official_auth_verification::verify_targets(&mut codex_dirs, &launch);
    let mut warnings = launch
        .get("warnings")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    for target in &codex_dirs {
        if let Some(path) = target.get("recoveryBackupPath").and_then(Value::as_str) {
            let login_notice = if target
                .get("authCleanup")
                .and_then(|cleanup| cleanup.get("reason"))
                .and_then(Value::as_str)
                == Some("native_signed_out_after_corrupt_restore")
            {
                "未找到可确认的官方登录，已恢复官方未登录状态，请在 Codex 中重新登录。"
            } else {
                "已保留当前可识别的官方账号。"
            };
            warnings.push(Value::String(format!(
                "中转恢复记录已损坏，原记录已保留至 {path}。{login_notice}"
            )));
        }
    }
    warnings.extend(codex_secondary_auth_restore_warnings(&codex_dirs));
    if matches!(json_str(&auth_verification, "status").as_str(), "failed" | "pending") {
        warnings.push(Value::String("官方线路已恢复，但原账号本机登录凭据尚未完成一致性核验；请检查账号状态，勿将其视为已登录成功。".to_string()));
    }
    warnings.extend(
        session_sync
            .get("warnings")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default(),
    );
    let codex_launched = json_bool(&launch, "launched");
    let codex_launch_queued = codex_launch_is_queued(&launch);
    Ok(
        json!({ "configPath": config_path, "backupPath": backup_path, "codexDirs": codex_dirs, "authCleanup": auth_cleanup, "authVerification": auth_verification, "router": public_router_state(json!({ "running": false, "configUpdated": true, "configPath": config_path })), "sessionSync": session_sync, "launch": launch.clone(), "enhancements": { "plugin": json_field(&launch, "plugin"), "sessionDelete": json_field(&launch, "sessionDelete"), "theme": json_field(&launch, "theme") }, "warnings": warnings, "codexClosed": codex_closed, "codexLaunched": codex_launched, "codexLaunchQueued": codex_launch_queued, "needsRestart": codex_launch_needs_restart(&launch) }),
    )
}

