fn gaoge_configure_claude_inner(_app: AppHandle, request: Value) -> Result<Value, String> {
    let api_key = request
        .get("apiKey")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    if api_key.is_empty() {
        return Err("请先填写 Claude API Key。".to_string());
    }
    let model = request
        .get("model")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .ok_or_else(|| "请先获取 Claude 模型列表。".to_string())?;
    let base_url = normalize_base_url(
        request.get("baseUrl").and_then(Value::as_str),
        GAOGE_ANTHROPIC_BASE_URL,
    )?;
    let claude_closed = stop_claude_app();
    let (backup_path, cli_had_account, cli_api_auth_created) =
        write_claude_code_settings(api_key, &base_url, model, &request)?;
    let desktop = configure_claude_desktop(api_key, &base_url, model, &request)?;
    Ok(
        json!({ "settingsPath": claude_settings_path().to_string_lossy(), "backupPath": backup_path.map(|p| p.to_string_lossy().to_string()), "model": model, "baseUrl": base_url, "cliHadAccount": cli_had_account, "cliApiAuthCreated": cli_api_auth_created, "desktop": desktop, "claudeClosed": claude_closed, "needsRestart": true }),
    )
}

