fn cleanup_claude_code_settings_for_relay_disable() -> Result<ClaudeSettingsCleanup, String> {
    let backup_path = backup_claude_settings("claude-relay-disable")?;
    let settings_path = claude_settings_path();
    let mut removed_keys: Vec<String> = Vec::new();
    let mut restored_keys: Vec<String> = Vec::new();
    let mut config_updated = false;
    if let Some(Value::Object(mut settings)) = read_json_if_exists(&settings_path)? {
        let should_remove_env = if let Some(Value::Object(env)) = settings.get_mut("env") {
            let remove_gaoge_api_key = is_gaoge_managed_claude_api_key(env);
            let remove_gaoge_auth_token = is_gaoge_managed_claude_auth_token(env);
            let remove_legacy_auth_token = is_legacy_gaoge_managed_claude_auth_token(env);
            let previous_auth_token = env
                .remove(CLAUDE_GAOGE_PREVIOUS_AUTH_TOKEN_ENV_KEY)
                .and_then(|value| value.as_str().map(str::to_string));
            if previous_auth_token.is_some() {
                removed_keys.push(CLAUDE_GAOGE_PREVIOUS_AUTH_TOKEN_ENV_KEY.to_string());
            }
            for key in CLAUDE_RELAY_ENV_KEYS {
                if env.remove(key).is_some() {
                    removed_keys.push(key.to_string());
                }
            }
            if env
                .remove(CLAUDE_GAOGE_AUTH_TOKEN_MANAGED_ENV_KEY)
                .is_some()
            {
                removed_keys.push(CLAUDE_GAOGE_AUTH_TOKEN_MANAGED_ENV_KEY.to_string());
            }
            if remove_gaoge_api_key && env.remove("ANTHROPIC_API_KEY").is_some() {
                removed_keys.push("ANTHROPIC_API_KEY".to_string());
            }
            if (remove_gaoge_auth_token || remove_legacy_auth_token)
                && env.remove("ANTHROPIC_AUTH_TOKEN").is_some()
            {
                removed_keys.push("ANTHROPIC_AUTH_TOKEN".to_string());
            }
            if let Some(previous_auth_token) = previous_auth_token {
                env.insert(
                    "ANTHROPIC_AUTH_TOKEN".to_string(),
                    Value::String(previous_auth_token),
                );
                restored_keys.push("ANTHROPIC_AUTH_TOKEN".to_string());
            }
            env.is_empty()
        } else {
            false
        };
        if should_remove_env {
            settings.remove("env");
        }

        config_updated = !removed_keys.is_empty();
        if config_updated {
            write_json_pretty(&settings_path, &Value::Object(settings))?;
        }
    }
    Ok((
        settings_path,
        backup_path,
        config_updated,
        removed_keys,
        restored_keys,
    ))
}

fn gaoge_disable_claude_relay_inner() -> Result<Value, String> {
    let claude_closed = stop_claude_app();
    let (settings_path, backup_path, mut config_updated, removed_keys, restored_keys) =
        cleanup_claude_code_settings_for_relay_disable()?;
    let desktop = restore_claude_desktop_official()?;
    config_updated |= desktop
        .get("configUpdated")
        .and_then(Value::as_bool)
        .unwrap_or(false);

    Ok(json!({
        "settingsPath": settings_path.to_string_lossy(),
        "backupPath": backup_path.map(|p| p.to_string_lossy().to_string()),
        "configUpdated": config_updated,
        "removedKeys": removed_keys,
        "restoredKeys": restored_keys,
        "desktop": desktop,
        "claudeClosed": claude_closed,
        "needsRestart": true,
    }))
}

