fn gaoge_sync_codex_sessions_inner() -> Result<Value, String> {
    let _operation = lock_codex_foreground_operation()?;
    gaoge_sync_codex_sessions_locked()
}

// The caller owns the foreground configure/launch lock. Keep this separate so
// startup can check running clients after acquiring the lock without recursion.
fn gaoge_sync_codex_sessions_locked() -> Result<Value, String> {
    let config = read_text_if_exists(&codex_config_path())?;
    let provider = match configured_provider(&config).as_str() {
        CODEX_DIRECT_PROVIDER_ID => CODEX_DIRECT_PROVIDER_ID,
        "openai" => "openai",
        "" => "openai",
        _ => "openai",
    };
    sync_codex_route_targets(provider, false)
}

fn should_run_startup_codex_session_sync(running_app_dirs: &[PathBuf]) -> bool {
    running_app_dirs.is_empty()
}

fn gaoge_sync_codex_sessions_on_startup_inner() -> Result<Value, String> {
    // Serialize the observation and sync with foreground configuration/restart.
    // Do not reuse a pre-lock process snapshot and never treat probe errors as
    // proof of exit. Startup must not close a client launched while it waited.
    let _operation = lock_codex_foreground_operation()?;
    let running_app_dirs = match probe_native_project_recovery_client() {
        Ok(running) => running,
        Err(error) => return Ok(json!({
            "skipped": true,
            "reason": "codex_process_state_unknown",
            "message": format!("无法确认 Codex 运行状态，已跳过启动会话同步，未关闭客户端：{error}")
        })),
    };
    if !should_run_startup_codex_session_sync(&running_app_dirs) {
        return Ok(json!({
          "skipped": true,
          "reason": "codex_running",
          "runningCodexCount": running_app_dirs.len(),
          "message": "Codex 正在运行，已跳过启动会话同步，未关闭 Codex。"
        }));
    }
    gaoge_sync_codex_sessions_locked()
}

#[tauri::command]
async fn gaoge_sync_codex_sessions() -> Result<Value, String> {
    run_blocking_task(gaoge_sync_codex_sessions_inner).await
}

fn bootstrap_codex_plugin_marketplace(
    _app: &AppHandle,
    allow_download: bool,
) -> Result<Value, String> {
    if cfg!(test) {
        return Ok(json!({
            "configured": false,
            "pluginCount": 0,
            "testSkipped": true,
            "codexDirs": [],
        }));
    }
    let _bootstrap_guard = CODEX_PLUGIN_BOOTSTRAP_LOCK
        .lock()
        .map_err(|_| "Codex 插件市场初始化锁失败。".to_string())?;
    let codex_dirs = set_codex_plugins_all_route_targets_with_download(true, allow_download)?;
    let primary = codex_dirs.first().cloned().unwrap_or_else(|| json!({}));
    let plugin_count = primary
        .get("pluginMarketplace")
        .and_then(|value| value.get("pluginCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if plugin_count == 0 {
        let warning = primary
            .get("pluginMarketplace")
            .and_then(|value| value.get("warning"))
            .and_then(Value::as_str)
            .unwrap_or("官方插件市场为空");
        return Err(format!("官方插件市场下载或校验失败：{warning}"));
    }
    Ok(json!({
        "configured": true,
        "pluginCount": plugin_count,
        "codexDirs": codex_dirs,
    }))
}

fn set_codex_plugins_current_dir_with_download(
    target: &CodexDirTarget,
    enabled: bool,
    allow_download: bool,
) -> Result<Value, String> {
    fs::create_dir_all(codex_dir()).map_err(|error| format!("创建 Codex 目录失败：{error}"))?;
    let backup_path = backup_codex_config("plugins")?;
    let config_snapshot = read_text_if_exists(&codex_config_path())?;
    config_snapshot.parse::<toml_edit::Document>()
        .map_err(|_| "插件市场配置格式无效，已保留原文件。".to_string())?;
    let (next_config, plugins) = set_codex_plugin_config(&config_snapshot, enabled);
    let (next_config, plugin_marketplace) = if enabled {
        ensure_codex_marketplace_config(&next_config, allow_download)
    } else {
        (next_config, codex_marketplace_disabled_status())
    };
    if next_config != config_snapshot {
        write_codex_config_atomic(&codex_config_path(), Some(&config_snapshot), &next_config)
            .map_err(|error| format!("写入插件配置失败：{error}"))?;
    }
    Ok(json!({
      "codexDir": codex_dir().to_string_lossy(),
      "codexDirSource": target.source,
      "primary": target.primary,
      "enabled": enabled,
      "configPath": codex_config_path().to_string_lossy(),
      "backupPath": backup_path.map(|p| p.to_string_lossy().to_string()),
      "plugins": plugins,
      "pluginMarketplace": plugin_marketplace,
    }))
}

#[cfg_attr(not(test), allow(dead_code))]
fn set_codex_plugins_current_dir(target: &CodexDirTarget, enabled: bool) -> Result<Value, String> {
    set_codex_plugins_current_dir_with_download(target, enabled, true)
}

fn set_codex_plugins_all_route_targets_with_download(
    enabled: bool,
    allow_download: bool,
) -> Result<Vec<Value>, String> {
    let mut results = Vec::new();
    let mut errors = Vec::new();
    for target in codex_route_targets() {
        match with_codex_dir(&target.dir, || {
            set_codex_plugins_current_dir_with_download(&target, enabled, allow_download)
        }) {
            Ok(result) => results.push(result),
            Err(error) => errors.push(format!("{}: {error}", target.dir.display())),
        }
    }
    if errors.is_empty() {
        Ok(results)
    } else {
        Err(errors.join("\n"))
    }
}

fn set_codex_plugins_all_route_targets(enabled: bool) -> Result<Vec<Value>, String> {
    set_codex_plugins_all_route_targets_with_download(enabled, true)
}

#[allow(dead_code)]
fn repair_enabled_codex_plugin_configs() -> Result<Value, String> {
    if !codex_plugin_enhancement_enabled() {
        return Ok(json!({
          "enabled": false,
          "repaired": 0,
          "pluginCount": 0,
        }));
    }
    let marketplace_root = local_openai_curated_marketplace_root()?
        .ok_or_else(|| "已开启官方插件，但本地精选插件市场不存在。".to_string())?;
    let plugin_count = codex_marketplace_plugin_count(&marketplace_root);
    if plugin_count == 0 {
        return Err("已开启官方插件，但本地精选插件市场为空。".to_string());
    }

    let mut repaired = 0usize;
    let mut codex_dirs = Vec::new();
    let mut errors = Vec::new();
    for target in codex_route_targets() {
        let target_dir = target.dir.clone();
        match with_codex_dir(&target.dir, || -> Result<bool, String> {
            fs::create_dir_all(codex_dir())
                .map_err(|error| format!("创建 Codex 目录失败：{error}"))?;
            let config_snapshot = read_text_if_exists(&codex_config_path())?;
            config_snapshot.parse::<toml_edit::Document>()
                .map_err(|_| "插件市场配置格式无效，已保留原文件。".to_string())?;
            let next_config = set_codex_marketplace_config(&config_snapshot, &marketplace_root);
            if next_config != config_snapshot {
                write_codex_config_atomic(
                    &codex_config_path(),
                    Some(&config_snapshot),
                    &next_config,
                )
                .map_err(|error| format!("恢复插件配置失败：{error}"))?;
                Ok(true)
            } else {
                Ok(false)
            }
        }) {
            Ok(changed) => {
                repaired += usize::from(changed);
                codex_dirs.push(target_dir.to_string_lossy().to_string());
            }
            Err(error) => errors.push(format!("{}: {error}", target_dir.display())),
        }
    }
    if !errors.is_empty() {
        return Err(errors.join("\n"));
    }
    Ok(json!({
      "enabled": true,
      "repaired": repaired,
      "pluginCount": plugin_count,
      "codexDirs": codex_dirs,
    }))
}

#[allow(dead_code)]
fn gaoge_set_codex_plugins_inner(app: AppHandle, request: Value) -> Result<Value, String> {
    let enabled = request
        .get("enabled")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let auth_status = codex_plugin_auth_status();
    let plugin_bootstrap = if enabled {
        match bootstrap_codex_plugin_marketplace(&app, true) {
            Ok(value) => Some(value),
            Err(error) => {
                let _ = set_codex_plugin_enhancement_enabled(false, None);
                let _ = set_codex_plugins_all_route_targets(false);
                return Err(error);
            }
        }
    } else {
        None
    };
    let codex_dirs = if let Some(codex_dirs) = plugin_bootstrap
        .as_ref()
        .and_then(|value| value.get("codexDirs"))
        .and_then(Value::as_array)
    {
        codex_dirs.clone()
    } else {
        set_codex_plugins_all_route_targets(enabled)?
    };
    let primary = codex_dirs.first().cloned().unwrap_or_else(|| json!({}));
    let running_dirs = list_running_codex_app_dirs();
    let codex_closed = stop_codex_app();
    set_codex_plugin_enhancement_enabled(enabled, None)?;
    let app_patch = run_plugin_patch_best_effort(&app, enabled, &request, running_dirs);
    if enabled && !json_bool(&app_patch, "injectionVerified") {
        let error = json_str(&app_patch, "error");
        let _ = set_codex_plugin_enhancement_enabled(false, None);
        let _ = set_codex_plugins_all_route_targets(false);
        return Err(if error.is_empty() {
            "官方插件启用失败：未能确认插件市场和 Codex 运行时已经加载。".to_string()
        } else {
            format!("官方插件启用失败：{error}")
        });
    }
    let needs_restart = app_patch
        .get("needsRestart")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    Ok(
        json!({ "enabled": enabled, "configEnabled": true, "configPath": json_str(&primary, "configPath"), "backupPath": json_field(&primary, "backupPath"), "codexDirs": codex_dirs, "plugins": json_field(&primary, "plugins"), "pluginMarketplace": json_field(&primary, "pluginMarketplace"), "pluginBootstrap": plugin_bootstrap, "authStatus": auth_status, "appPatch": app_patch, "codexClosed": codex_closed, "needsRestart": needs_restart }),
    )
}

fn gaoge_set_codex_plugins_inner_v2(app: AppHandle, request: Value) -> Result<Value, String> {
    let enabled = request.get("enabled").and_then(Value::as_bool)
        .ok_or_else(|| "插件开启状态必须是布尔值。".to_string())?;
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK, "Codex 正在处理其他配置，请稍后重试。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let _configure_activity = CodexConfigureActivityGuard::start();

    // Register the catalog only. Never install/enable every plugin or restart
    // Codex as a side effect of changing this compatibility preference.
    let bootstrap = if enabled {
        Some(bootstrap_codex_plugin_marketplace(&app, true)?)
    } else { None };
    let debug_port = codex_plugin_active_debug_port();
    set_codex_plugin_enhancement_enabled(enabled, Some(debug_port))?;
    set_codex_runtime_debug_port(debug_port);
    invalidate_codex_runtime_injection_state();
    // A connected new runtime can switch immediately; the watcher installs it
    // otherwise. A legacy runtime explicitly reports that a restart is needed.
    if let Ok(target) = query_cdp_targets(debug_port).and_then(pick_cdp_page_target) {
        if let Some(websocket_url) = target.web_socket_debugger_url.as_deref() {
            let markets = local_plugin_marketplaces().to_string();
            let script = format!(r#"(() => {{
              window.__GAOGE_PLUGIN_ENHANCEMENTS_ENABLED__ = {enabled};
              window.__GAOGE_PLUGIN_MARKETPLACES__ = {markets};
              const runtime = window.__gaogeCodexPluginRuntime;
              if (runtime?.configure) runtime.configure({{ enabled: {enabled}, localMarketplaces: () => window.__GAOGE_PLUGIN_MARKETPLACES__ || [] }});
              if (!{enabled} && window.__gaogeCodexPluginFallbackTimer) {{
                clearInterval(window.__gaogeCodexPluginFallbackTimer);
                window.__gaogeCodexPluginFallbackTimer = 0;
              }}
              return {{ configured: !!runtime?.configure }};
            }})()"#);
            let _ = cdp_evaluate_script(websocket_url, &script);
        }
    }
    start_codex_runtime_watcher();
    let status = gaoge_get_codex_plugins_status_inner();
    let ready = json_bool(&status, "runtimeReady");
    let needs_restart = json_bool(&status, "needsRestart");
    let targets = bootstrap.as_ref().map(|value| json_field(value, "codexDirs"))
        .unwrap_or_else(|| json!([]));
    let primary = targets.as_array().and_then(|items| items.first()).cloned()
        .unwrap_or_else(|| json!({}));
    Ok(json!({
      "enabled": enabled, "configEnabled": enabled, "status": status,
      "configPath": json_str(&primary, "configPath"), "backupPath": json_field(&primary, "backupPath"),
      "codexDirs": targets, "plugins": json_field(&primary, "plugins"),
      "pluginMarketplace": json_field(&primary, "pluginMarketplace"), "pluginBootstrap": bootstrap,
      "appPatch": { "applied": ready, "method": "cdp-hot", "degraded": false,
        "injectionVerified": ready, "needsRestart": needs_restart, "debugPort": debug_port },
      "codexClosed": false, "codexLaunched": false, "codexLaunchQueued": false,
      "needsRestart": needs_restart,
    }))
}

fn codex_plugin_active_debug_port() -> u16 {
    if codex_session_delete_enabled() { codex_session_delete_debug_port() }
    else if codex_plugin_enhancement_enabled() { codex_plugin_debug_port() }
    else if let Some(port) = codex_themes::theme_debug_port() { port }
    else { codex_runtime_debug_port() }
}

