async fn gaoge_set_codex_plugins(app: AppHandle, request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_set_codex_plugins_inner_v2(app, request)).await
}

fn codex_plugin_runtime_status(debug_port: u16) -> Value {
    let enabled = codex_plugin_enhancement_enabled();
    let unavailable = || {
        let running = !list_running_codex_app_dirs().is_empty();
        json!({ "runtimeReady": false, "runtimeInjected": false,
          "nativeEntryReady": false, "listVerified": false, "searchReady": false,
          "pluginEnhancementsEnabled": false, "requestPatchReady": false,
          "debugPort": debug_port, "needsRestart": running,
          "pending": enabled && !running,
          "reason": if running { "runtime-unavailable" } else if enabled { "codex-not-running" } else { "disabled" } })
    };
    let target = match query_cdp_targets(debug_port).and_then(pick_cdp_page_target) {
        Ok(target) => target, Err(_) => return unavailable(),
    };
    let Some(websocket_url) = target.web_socket_debugger_url.as_deref() else { return unavailable(); };
    let script = r#"(() => {
      const runtime = window.__gaogeCodexPluginRuntime;
      const legacy = !!(window.__gaogeCodexPluginCdpFallbackV2 || window.__gaogePluginMarketplaceRequestPatch
        || window.__gaogeCodexPluginMarketplaceRuntimeV5 || window.__gaogePluginMarketplaceFetchPatch
        || Array.prototype.__gaogePluginOriginalFilter || window.__gaogePluginMarketplaceRuntimeTimer
        || window.fetch?.__gaogePluginMarketplacePatch || window.fetch?.__gaogeCodexPluginFetchPatch
        || window.__gaogeCodexPluginFetchPatchInstalled || window.__gaogePluginMarketplaceBridgePatch
        || window.__gaogePluginMarketplaceResponseListenerInstalled || window.__gaogePluginMarketplaceWindowEventPatch
        || Array.prototype.filter.__gaogePluginMarketplacePatch
        || window.electronBridge?.__gaogePluginMarketplaceOriginalSendMessageFromView
        || window.__gaogeCodexAppServerClient?.__gaogePluginMarketplacePatch
        || document.querySelector?.('[data-gaoge-plugin-click-spoofed], [data-gaoge-force-plugin-unlocked]'));
      const expected = window.__GAOGE_PLUGIN_ENHANCEMENTS_ENABLED__ === true;
      const current = runtime?.version === __GAOGE_PLUGIN_RUNTIME_VERSION__ && runtime?.disposed === false
        && typeof runtime?.status === "function";
      if (!current) return { ready: false, applied: false, runtimeReady: false, runtimeInjected: false,
        nativeEntryReady: false, entryReady: false, listVerified: false, nativeListVerified: false,
        searchReady: false, requestPatchReady: false, indexedPlugins: 0, pluginCount: 0,
        pluginEnhancementsEnabled: false, needsRestart: legacy, pending: (expected || !!runtime) && !legacy,
        reason: legacy ? "legacy-runtime-restart-required" : expected || runtime ? "runtime-pending" : "disabled" };
      const state = runtime.status();
      const valid = state.version === runtime.version && state.disposed === false;
      const injected = valid && state.runtimeInjected === true;
      const entry = valid && (state.nativeEntryReady === true || state.entryReady === true);
      const listed = valid && (state.listVerified === true || state.nativeListVerified === true);
      const ready = expected && state.enabled === true && injected && entry && listed
        && state.runtimeReady === true && !legacy && !state.needsRestart && !state.error;
      return { ...state, ready, runtimeReady: ready, runtimeInjected: injected,
        applied: valid && !legacy && state.applied === true, nativeEntryReady: entry, entryReady: entry,
        listVerified: listed, nativeListVerified: listed, searchReady: valid && state.searchReady === true,
        needsRestart: legacy || state.needsRestart === true,
        pending: legacy ? false : !valid || state.pending === true,
        reason: legacy ? "legacy-runtime-restart-required" : !valid ? "runtime-pending" : state.reason,
        pluginEnhancementsEnabled: state.enabled === true,
        requestPatchReady: valid && state.requestPatchReady === true,
        pluginCount: valid ? Number(state.pluginCount || 0) : 0,
        indexedPlugins: valid ? Number(state.pluginCount || 0) : 0 };
    })()"#.replace("__GAOGE_PLUGIN_RUNTIME_VERSION__", &CODEX_PLUGIN_RUNTIME_VERSION.to_string());
    match cdp_evaluate_script(websocket_url, &script) {
        Ok(mut status) => {
            if let Some(object) = status.as_object_mut() {
                object.insert("debugPort".to_string(), json!(debug_port));
                if object.get("pluginEnhancementsEnabled").and_then(Value::as_bool) != Some(enabled) {
                    object.insert("runtimeReady".to_string(), json!(false));
                    if !object.get("needsRestart").and_then(Value::as_bool).unwrap_or(false) {
                        object.insert("pending".to_string(), json!(true));
                        object.insert("reason".to_string(), json!("runtime-pending"));
                    }
                }
            }
            status
        },
        Err(_) => unavailable(),
    }
}

fn gaoge_get_codex_plugins_status_inner() -> Value {
    let enabled = codex_plugin_enhancement_enabled();
    let debug_port = codex_plugin_active_debug_port();
    let marketplaces = local_plugin_marketplaces();
    let local_marketplace_count = marketplaces.as_array().map(Vec::len).unwrap_or(0);
    let available_plugin_count = marketplaces
        .as_array()
        .map(|marketplaces| plugin_marketplace_unique_plugin_count(marketplaces))
        .unwrap_or(0);
    let marketplace_root = local_openai_curated_marketplace_root()
        .ok()
        .flatten()
        .map(|path| path.to_string_lossy().to_string());
    let mut status = codex_plugin_runtime_status(debug_port);
    if let Some(object) = status.as_object_mut() {
        object.insert("enabled".to_string(), json!(enabled));
        object.insert("configEnabled".to_string(), json!(enabled));
        object.insert("platform".to_string(), json!(std::env::consts::OS));
        object.insert(
            "localMarketplaceCount".to_string(),
            json!(local_marketplace_count),
        );
        object.insert(
            "availablePluginCount".to_string(),
            json!(available_plugin_count),
        );
        object.insert("marketplaceRoot".to_string(), json!(marketplace_root));
        if let Ok(image_status) = GAOGE_IMAGE_INTEGRATION_STATUS.lock() {
            object.insert("imageToolsMigration".to_string(), image_status.clone());
        }
    }
    status
}

#[tauri::command]
async fn gaoge_get_codex_plugins_status() -> Result<Value, String> {
    run_blocking_task(|| Ok(gaoge_get_codex_plugins_status_inner())).await
}

fn codex_session_delete_runtime_status(debug_port: u16) -> Value {
    let target = match query_cdp_targets(debug_port).and_then(pick_cdp_page_target) {
        Ok(target) => target,
        Err(error) => {
            return json!({
              "runtimeReady": false,
              "active": false,
              "debugPort": debug_port,
              "message": "Codex 当前未通过删除会话运行模式启动。",
              "runtimeError": error,
            });
        }
    };
    let Some(websocket_url) = target.web_socket_debugger_url.as_deref() else {
        return json!({
          "runtimeReady": false,
          "active": false,
          "debugPort": debug_port,
          "targetTitle": target.title,
          "targetUrl": target.url,
          "message": "Codex 页面缺少本机调试连接。",
        });
    };
    let script = r#"
(() => {
  const runtime = window.__gaogeSessionDeleteRuntime;
  return {
    runtimeReady: !!(runtime?.enabled && runtime?.active),
    active: !!runtime?.active,
    bridgeReady: typeof window.__gaogeSessionDeleteBridge === "function"
      && window.__gaogeSessionDeleteBridgeReady === true,
    sessionRows: document.querySelectorAll("[data-app-action-sidebar-thread-id]").length,
    buttonsAttached: document.querySelectorAll(".gaoge-codex-session-delete").length,
  };
})()
"#;
    match cdp_evaluate_script(websocket_url, script) {
        Ok(mut status) => {
            if let Some(object) = status.as_object_mut() {
                object.insert("debugPort".to_string(), json!(debug_port));
                object.insert("targetTitle".to_string(), json!(target.title));
                object.insert("targetUrl".to_string(), json!(target.url));
            }
            status
        }
        Err(error) => json!({
          "runtimeReady": false,
          "active": false,
          "debugPort": debug_port,
          "targetTitle": target.title,
          "targetUrl": target.url,
          "message": "无法读取删除会话运行状态。",
          "runtimeError": error,
        }),
    }
}

fn gaoge_get_codex_session_delete_status_inner() -> Value {
    let enabled = codex_session_delete_enabled();
    let debug_port = codex_session_delete_debug_port();
    let mut status = if enabled {
        codex_session_delete_runtime_status(debug_port)
    } else {
        json!({
          "runtimeReady": false,
          "active": false,
          "debugPort": debug_port,
        })
    };
    if let Some(object) = status.as_object_mut() {
        object.insert("enabled".to_string(), json!(enabled));
        object.insert("platform".to_string(), json!(std::env::consts::OS));
    }
    status
}

