#[allow(dead_code)]
fn gaoge_set_codex_session_delete_inner(request: Value) -> Result<Value, String> {
    let enabled = request
        .get("enabled")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let _session_delete_guard = try_lock_recover(
        &CODEX_SESSION_DELETE_LOCK,
        "删除会话设置正在处理中，请勿重复点击。",
    )?;
    let _configure_activity = CodexConfigureActivityGuard::start();
    let plugin_enhancements_enabled = codex_fuel_pack_active() || codex_plugins_enabled_anywhere();

    if !enabled {
        let debug_port = codex_session_delete_debug_port();
        stop_codex_session_delete_bridge();
        set_codex_session_delete_enabled(false, None)?;
        let mut runtime_removed = false;
        if let Ok(target) = query_cdp_targets(debug_port).and_then(pick_cdp_page_target) {
            if let Some(websocket_url) = target.web_socket_debugger_url.as_deref() {
                let app_dir = list_running_codex_app_dirs()
                    .into_iter()
                    .next()
                    .or_else(|| choose_launchable_codex_app_dir(Vec::new()));
                let app_version = app_dir
                    .as_deref()
                    .map(codex_app_version_string)
                    .unwrap_or_default();
                let helper = ensure_codex_session_helper().ok();
                let theme = codex_themes::active_theme_runtime_payload().ok().flatten();
                let script = codex_plugin_cdp_script(
                    &app_version,
                    helper.as_ref(),
                    plugin_enhancements_enabled,
                    false,
                    theme.as_ref(),
                );
                runtime_removed = cdp_evaluate_script(websocket_url, &script).is_ok();
            }
        }
        return Ok(json!({
          "enabled": false,
          "runtimeReady": false,
          "active": false,
          "runtimeRemoved": runtime_removed,
          "debugPort": debug_port,
          "platform": std::env::consts::OS,
          "message": "删除会话功能已关闭。",
        }));
    }

    stop_codex_session_delete_bridge();
    set_codex_session_delete_enabled(false, None)?;
    let preferred = list_running_codex_app_dirs();
    let app_dir = choose_launchable_codex_app_dir(preferred)
        .ok_or_else(|| "没有找到可启动的 Codex 官方应用。".to_string())?;
    let codex_closed = stop_codex_app();
    wait_for_codex_app_exit(Duration::from_secs(CODEX_APP_EXIT_WAIT_SECS))?;
    thread::sleep(Duration::from_millis(600));
    let debug_port = select_available_codex_cdp_port()?;
    launch_codex_with_cdp(&app_dir, debug_port)?;
    let target = match wait_for_cdp_target_with_timeout(
        debug_port,
        Duration::from_secs(CODEX_PACKAGED_CDP_FIRST_WAIT_SECS),
    ) {
        Ok(target) => target,
        #[cfg(target_os = "windows")]
        Err(first_error) if is_windows_apps_codex_dir(&app_dir) => {
            let _ = stop_codex_app();
            wait_for_codex_app_exit(Duration::from_secs(CODEX_APP_EXIT_WAIT_SECS))?;
            thread::sleep(Duration::from_millis(600));
            if let Err(direct_error) = launch_codex_executable_with_cdp(&app_dir, debug_port) {
                let _ = activate_windows_packaged_codex(&app_dir, &[]);
                return Err(format!(
                    "Codex 商店版调试启动失败：{first_error}；直接重试也失败：{direct_error}"
                ));
            }
            wait_for_cdp_target_with_timeout(
                debug_port,
                Duration::from_secs(
                    CODEX_PLUGIN_CDP_MAX_WAIT_SECS - CODEX_PACKAGED_CDP_FIRST_WAIT_SECS,
                ),
            )
            .map_err(|second_error| {
                format!(
                    "Codex 已重新启动，但删除会话连接仍未建立：{first_error}；重试结果：{second_error}"
                )
            })?
        }
        Err(error) => return Err(error),
    };
    let websocket_url = target
        .web_socket_debugger_url
        .as_deref()
        .ok_or_else(|| "Codex 页面缺少本机调试连接。".to_string())?;
    ensure_codex_session_delete_bridge(websocket_url)?;
    let app_version = codex_app_version_string(&app_dir);
    let theme = match codex_themes::active_theme_runtime_payload() {
        Ok(payload) => payload,
        Err(error) => {
            let _ = disable_codex_theme_after_failure(format!("主题准备失败：{error}"));
            None
        }
    };
    let script = codex_plugin_cdp_script(
        &app_version,
        None,
        plugin_enhancements_enabled,
        true,
        theme.as_ref(),
    );
    let injection = cdp_evaluate_script(websocket_url, &script).map_err(|error| {
        stop_codex_session_delete_bridge();
        error
    })?;
    if !codex_session_delete_injection_verified(&injection) {
        stop_codex_session_delete_bridge();
        let _ = set_codex_session_delete_enabled(false, None);
        return Err(format!(
            "删除会话按钮加载失败，请确认 Codex 已完成启动后重试：{injection}"
        ));
    }
    if let Err(error) = set_codex_session_delete_enabled(true, Some(debug_port)) {
        stop_codex_session_delete_bridge();
        return Err(error);
    }
    if let Some(active_theme) = theme.as_ref() {
        if codex_theme_injection_verified(&injection, Some(active_theme)) {
            let _ = codex_themes::set_theme_applied(debug_port);
        } else {
            let _ = disable_codex_theme_after_failure(format!("主题注入结果校验失败：{injection}"));
        }
    }

    Ok(json!({
      "enabled": true,
      "runtimeReady": true,
      "active": true,
      "debugPort": debug_port,
      "platform": std::env::consts::OS,
      "appPath": codex_exe_path(&app_dir).to_string_lossy(),
      "targetTitle": target.title,
      "targetUrl": target.url,
      "sessionRows": injection.get("sessionRows").cloned().unwrap_or(json!(0)),
      "buttonsAttached": injection.get("sessionDeleteButtons").cloned().unwrap_or(json!(0)),
      "codexClosed": codex_closed,
      "codexLaunched": true,
      "message": "删除会话功能已开启，Codex 已重新启动。",
    }))
}

fn gaoge_set_codex_session_delete_inner_v2(
    app: AppHandle,
    request: Value,
) -> Result<Value, String> {
    let enabled = request
        .get("enabled")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let _configure_guard = try_lock_recover(
        &CODEX_CONFIGURE_LOCK,
        "Codex 正在处理其他配置，请稍后重试。",
    )?;
    let _configure_file_lock = acquire_codex_lock("configure")?;
    let _session_delete_guard = try_lock_recover(
        &CODEX_SESSION_DELETE_LOCK,
        "删除会话设置正在处理中，请勿重复点击。",
    )?;
    let _configure_activity = CodexConfigureActivityGuard::start();
    stop_codex_session_delete_bridge();
    set_codex_session_delete_enabled(enabled, enabled.then_some(CODEX_PLUGIN_CDP_DEBUG_PORT))?;
    let launch = stop_prepare_and_launch_codex(&app);
    let feature = json_field(&launch, "sessionDelete");
    let final_enabled = json_bool(&feature, "enabled");
    let applied = json_bool(&feature, "applied");
    let error = json_str(&feature, "error");
    Ok(json!({
      "enabled": final_enabled,
      "runtimeReady": applied,
      "active": applied,
      "platform": std::env::consts::OS,
      "debugPort": json_field(&launch, "debugPort"),
      "appPath": json_str(&launch, "appPath"),
      "codexClosed": json_bool(&launch, "codexClosed"),
      "codexLaunched": json_bool(&launch, "launched"),
      "codexLaunchQueued": codex_launch_is_queued(&launch),
      "launch": launch.clone(),
      "enhancements": {
        "plugin": json_field(&launch, "plugin"),
        "sessionDelete": feature,
        "theme": json_field(&launch, "theme"),
      },
      "warnings": json_field(&launch, "warnings"),
      "message": if final_enabled && applied {
          "删除会话功能已开启，Codex 已重新启动。".to_string()
      } else if final_enabled {
          format!("删除会话已保持开启，本次运行时加载未完成，后台会自动重试。{error}")
      } else {
          "删除会话功能已关闭，Codex 已重新启动。".to_string()
      },
      "error": error,
    }))
}

#[tauri::command]
async fn gaoge_set_codex_session_delete(app: AppHandle, request: Value) -> Result<Value, String> {
    run_blocking_task(move || gaoge_set_codex_session_delete_inner_v2(app, request)).await
}

fn codex_language_runtime_status(update: bool) -> Value {
    let target = match query_cdp_targets(codex_runtime_debug_port()).and_then(pick_cdp_page_target) {
        Ok(target) => target,
        Err(_) => return Value::Null,
    };
    let Some(websocket_url) = target.web_socket_debugger_url.as_deref() else {
        return Value::Null;
    };
    let config = json!({
        "enabled": codex_chinese_locale_enabled(),
        "revision": codex_runtime_revision_token(current_codex_runtime_revision()),
    });
    let script = format!(
        "(() => {{ const r = window.__gaogeCodexLocaleRuntime; if (!r || r.disposed) return null; if ({update}) r.update({config}); return r.status(); }})()"
    );
    cdp_evaluate_script(websocket_url, &script).unwrap_or(Value::Null)
}

fn codex_language_response(enabled: bool, runtime: Value) -> Value {
    let matches = runtime.get("version").and_then(Value::as_u64) == Some(codex_locale::VERSION)
        && !json_bool(&runtime, "disposed")
        && runtime.get("enabled").and_then(Value::as_bool) == Some(enabled);
    let needs_restart = !matches || !json_bool(&runtime, "ready") || json_bool(&runtime, "needsRestart");
    let applied = matches && json_bool(&runtime, "ready") && !needs_restart;
    let message = if enabled {
        if applied { "已开启强制中文。" } else { "已开启强制中文，重启 Codex 后生效。" }
    } else if needs_restart {
        "已关闭强制中文，重启 Codex 后生效。"
    } else {
        "已关闭强制中文。"
    };
    json!({ "enabled": enabled, "language": CODEX_FORCED_LANGUAGE, "applied": applied,
        "needsRestart": needs_restart, "message": message, "runtime": runtime,
        "codexClosed": false, "warnings": [] })
}

#[tauri::command]
async fn gaoge_get_codex_language_settings(request: Option<Value>) -> Result<Value, String> {
    run_blocking_task(move || {
        let (enabled, initialized) = {
            let _guard = CODEX_LANGUAGE_SETTINGS_LOCK.lock()
                .map_err(|_| "中文设置正在处理中。".to_string())?;
            codex_locale::initialize(&codex_language_settings_path(),
                request.as_ref().and_then(|v| v.get("legacyEnabled")).and_then(Value::as_bool))?
        };
        if initialized { bump_codex_runtime_revision(); }
        start_codex_runtime_watcher();
        Ok(codex_language_response(enabled, codex_language_runtime_status(initialized)))
    }).await
}

fn gaoge_set_codex_language_inner(request: Value) -> Result<Value, String> {
    let enabled = request.get("enabled").and_then(Value::as_bool)
        .ok_or_else(|| "缺少中文开关状态。".to_string())?;
    {
        let _guard = CODEX_LANGUAGE_SETTINGS_LOCK.lock()
            .map_err(|_| "中文设置正在处理中。".to_string())?;
        codex_locale::save(&codex_language_settings_path(), enabled)?;
        bump_codex_runtime_revision();
    }
    start_codex_runtime_watcher();
    Ok(codex_language_response(enabled, codex_language_runtime_status(true)))
}

