async fn gaoge_get_codex_install_status() -> Result<Value, String> {
    Ok(INSTALL_STATUS
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_else(|_| default_install_status()))
}

#[tauri::command]
async fn gaoge_install_codex_app(app: AppHandle, request: Option<Value>) -> Result<Value, String> {
    run_blocking_task(move || {
        let result = install_codex_inner_v2(&app, request.unwrap_or_else(|| json!({})));
        if let Ok(mut guard) = INSTALL_CANCEL.lock() {
            *guard = None;
        }
        match result {
            Ok(status) => Ok(status),
            Err(error) => {
                let _ = fs::remove_file(active_install_part_path());
                set_active_install_part(None);
                if let Some(work_dir) = take_active_install_work_dir() {
                    let _ = remove_dir_retry(&work_dir);
                }
                Ok(publish_install_status(
                    &app,
                    json!({ "state": "error", "message": error, "error": error, "canInstall": true }),
                ))
            }
        }
    }).await
}

#[tauri::command]
async fn gaoge_cancel_codex_install(app: AppHandle) -> Result<Value, String> {
    if let Ok(guard) = INSTALL_CANCEL.lock() {
        if let Some(flag) = guard.as_ref() {
            flag.store(true, Ordering::Relaxed);
        }
    }
    let _ = fs::remove_file(active_install_part_path());
    set_active_install_part(None);
    if let Some(work_dir) = take_active_install_work_dir() {
        let _ = remove_dir_retry(&work_dir);
    }
    Ok(publish_install_status(
        &app,
        json!({ "state": "cancelled", "message": "已取消 Codex 安装。", "canInstall": true }),
    ))
}

#[tauri::command]
async fn gaoge_open_payment_window(request: Value) -> Result<Value, String> {
    let pay_url = request
        .get("payUrl")
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim();
    let parsed = url::Url::parse(pay_url).map_err(|_| "Invalid payment URL".to_string())?;
    if !matches!(
        parsed.scheme(),
        "http" | "https" | "alipay" | "alipays" | "alipayqr"
    ) {
        return Err("Invalid payment URL".to_string());
    }
    let mut command = if cfg!(target_os = "windows") {
        let mut command = hidden_command("rundll32.exe");
        command.args(["url.dll,FileProtocolHandler", pay_url]);
        command
    } else if cfg!(target_os = "macos") {
        let mut command = hidden_command("open");
        command.arg(pay_url);
        command
    } else if cfg!(target_os = "linux") {
        let mut command = hidden_command("xdg-open");
        command.arg(pay_url);
        command
    } else {
        return Err(format!("Unsupported platform: {}", std::env::consts::OS));
    };
    command
        .spawn()
        .map_err(|error| format!("打开支付窗口失败：{error}"))?;
    Ok(json!({ "opened": true }))
}

#[tauri::command]
async fn gaoge_get_update_status(request: Option<Value>) -> Result<Value, String> {
    let mut status = current_update_status();
    if let Some(update_base_url) = update_feed_base_from_request(request.as_ref()) {
        if let Some(object) = status.as_object_mut() {
            object.insert(
                "feedUrl".to_string(),
                json!(update_feed_url_with_base(Some(update_base_url.as_str()))),
            );
        }
    }
    Ok(status)
}

#[tauri::command]
async fn gaoge_check_for_updates(app: AppHandle, request: Option<Value>) -> Result<Value, String> {
    let update_base_url = update_feed_base_from_request(request.as_ref());
    let feed_url = update_feed_url_with_base(update_base_url.as_deref());

    if feed_url.trim().is_empty() {
        let message = "缺少更新地址，请先刷新或选择服务器。";
        return Ok(publish_update_status(
            &app,
            json!({
              "state": "error",
              "message": message,
              "latestVersion": "",
              "minimumVersion": "",
              "forceUpdate": false,
              "progress": 0,
              "downloaded": false,
              "feedUrl": "",
              "error": message
            }),
        ));
    }

    if cfg!(debug_assertions) {
        return Ok(publish_update_status(
            &app,
            json!({
              "state": "disabled",
              "message": "开发模式不启用自动更新，打包安装后生效。",
              "latestVersion": "",
              "minimumVersion": "",
              "forceUpdate": false,
              "progress": 0,
              "downloaded": false,
              "feedUrl": feed_url,
              "error": ""
            }),
        ));
    }

    if let Some(message) = macos_update_blocker_message() {
        reset_downloaded_update();
        return Ok(publish_update_status(
            &app,
            json!({
              "state": "error",
              "message": message,
              "latestVersion": "",
              "minimumVersion": "",
              "forceUpdate": false,
              "progress": 0,
              "downloaded": false,
              "feedUrl": feed_url,
              "error": message
            }),
        ));
    }

    if UPDATE_IN_PROGRESS.swap(true, Ordering::SeqCst) {
        return Ok(current_update_status());
    }

    reset_downloaded_update();
    let checking_status = publish_update_status(
        &app,
        json!({
          "state": "checking",
          "message": "正在检查更新...",
          "latestVersion": "",
          "minimumVersion": "",
          "forceUpdate": false,
          "progress": 0,
          "downloaded": false,
          "feedUrl": feed_url,
          "error": ""
        }),
    );

    let result: Result<Value, String> = async {
        let update_endpoint =
            url::Url::parse(&feed_url).map_err(|error| format!("更新地址无效：{error}"))?;
        let updater = app
            .updater_builder()
            .endpoints(vec![update_endpoint])
            .map_err(|error| format!("设置更新地址失败：{error}"))?
            .build()
            .map_err(|error| format!("初始化更新器失败：{error}"))?;
        let metadata = match fetch_update_manifest_metadata(&feed_url).await {
            Ok(metadata) => metadata,
            Err(error) => {
                eprintln!("{error}");
                UpdateManifestMetadata::default()
            }
        };
        let manifest_latest_version = normalize_manifest_version(metadata.version.as_deref());
        let minimum_version = normalize_manifest_version(metadata.minimum_version.as_deref());
        let force_update =
            is_version_below_minimum(env!("CARGO_PKG_VERSION"), minimum_version.as_str());
        publish_update_status(
            &app,
            json!({
              "minimumVersion": minimum_version.clone(),
              "forceUpdate": force_update
            }),
        );
        let update = updater
            .check()
            .await
            .map_err(|error| format!("检查更新失败：{error}"))?;

        let Some(update) = update else {
            reset_downloaded_update();
            if force_update {
                return Ok(publish_update_status(
                    &app,
                    json!({
                      "state": "error",
                      "message": "当前版本低于最低要求，但更新服务器没有返回可安装版本。",
                      "latestVersion": if manifest_latest_version.is_empty() { env!("CARGO_PKG_VERSION") } else { manifest_latest_version.as_str() },
                      "minimumVersion": minimum_version,
                      "forceUpdate": true,
                      "progress": 0,
                      "downloaded": false,
                      "error": "当前版本低于最低要求，但更新服务器没有返回可安装版本，请联系客服处理。"
                    }),
                ));
            }
            return Ok(publish_update_status(
                &app,
                json!({
                  "state": "not-available",
                  "message": "当前已经是最新版本。",
                  "latestVersion": if manifest_latest_version.is_empty() { env!("CARGO_PKG_VERSION") } else { manifest_latest_version.as_str() },
                  "minimumVersion": minimum_version,
                  "forceUpdate": force_update,
                  "progress": 100,
                  "downloaded": false,
                  "error": ""
                }),
            ));
        };

        let latest_version = update.version.clone();
        let latest_version_for_status = if latest_version.trim().is_empty() {
            manifest_latest_version
        } else {
            latest_version.clone()
        };
        let download_message = update
            .body
            .clone()
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| {
                if force_update {
                    format!("当前版本低于最低要求，正在下载必须更新的版本 {latest_version_for_status}...")
                } else {
                    format!("发现新版本 {latest_version_for_status}，正在下载更新...")
                }
            });
        publish_update_status(
            &app,
            json!({
              "state": "downloading",
              "message": download_message,
              "latestVersion": latest_version_for_status,
              "minimumVersion": minimum_version.clone(),
              "forceUpdate": force_update,
              "progress": 0,
              "downloaded": false,
              "error": ""
            }),
        );

        let downloaded_bytes = Arc::new(AtomicU64::new(0));
        let progress_bytes = downloaded_bytes.clone();
        let progress_app = app.clone();
        let progress_version = update.version.clone();
        let progress_minimum_version = minimum_version.clone();
        let bytes = update
            .download(
                move |chunk_length, total_length| {
                    let downloaded = progress_bytes
                        .fetch_add(chunk_length as u64, Ordering::SeqCst)
                        + chunk_length as u64;
                    let progress = total_length
                        .filter(|total| *total > 0)
                        .map(|total| ((downloaded as f64 / total as f64) * 100.0).round())
                        .unwrap_or(0.0)
                        .clamp(0.0, 100.0);
                    publish_update_status(
                        &progress_app,
                        json!({
                          "state": "downloading",
                          "message": format!("正在下载更新 {progress_version}..."),
                          "latestVersion": progress_version.clone(),
                          "minimumVersion": progress_minimum_version.clone(),
                          "forceUpdate": force_update,
                          "progress": progress,
                          "downloaded": false,
                          "error": ""
                        }),
                    );
                },
                || {},
            )
            .await
            .map_err(|error| format!("下载更新失败：{error}"))?;

        if let Ok(mut guard) = DOWNLOADED_UPDATE.lock() {
            *guard = Some(DownloadedUpdate { update, bytes });
        }

        Ok(publish_update_status(
            &app,
            json!({
              "state": "downloaded",
              "message": format!("新版本 {} 已下载完成，点击立即安装。", latest_version),
              "latestVersion": latest_version,
              "minimumVersion": minimum_version,
              "forceUpdate": force_update,
              "progress": 100,
              "downloaded": true,
              "error": ""
            }),
        ))
    }
    .await;

    UPDATE_IN_PROGRESS.store(false, Ordering::SeqCst);

    match result {
        Ok(status) => Ok(status),
        Err(error) => Ok(publish_update_status(
            &app,
            json!({
              "state": "error",
              "message": "检测更新失败。",
              "progress": checking_status.get("progress").and_then(Value::as_i64).unwrap_or(0),
              "downloaded": false,
              "error": error
            }),
        )),
    }
}

#[tauri::command]
async fn gaoge_install_update(app: AppHandle) -> Result<Value, String> {
    let downloaded = DOWNLOADED_UPDATE
        .lock()
        .map_err(|_| "读取已下载更新状态失败。".to_string())?
        .take();

    let Some(downloaded) = downloaded else {
        return Ok(json!({ "installing": false }));
    };

    if let Some(message) = macos_update_blocker_message() {
        publish_update_status(
            &app,
            json!({
              "state": "error",
              "message": message,
              "latestVersion": downloaded.update.version,
              "progress": 100,
              "downloaded": false,
              "error": message
            }),
        );
        return Err(message.to_string());
    }

    publish_update_status(
        &app,
        json!({
          "state": "downloaded",
          "message": format!("正在启动 {} 的安装程序...", downloaded.update.version),
          "latestVersion": downloaded.update.version,
          "progress": 100,
          "downloaded": true,
          "error": ""
        }),
    );

    downloaded
        .update
        .install(&downloaded.bytes)
        .map_err(format_update_install_error)?;
    if cfg!(target_os = "macos") {
        publish_update_status(
            &app,
            json!({
              "state": "restarting",
              "message": format!("新版本 {} 已安装完成，正在重启应用。", downloaded.update.version),
              "latestVersion": downloaded.update.version,
              "progress": 100,
              "downloaded": false,
              "error": ""
            }),
        );
        app.request_restart();
        return Ok(json!({ "installing": true, "restarting": true }));
    }

    Ok(json!({ "installing": true, "restarting": false }))
}

fn local_image_request_text(request: &Value, key: &str, fallback: &str) -> String {
    request
        .get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(fallback)
        .to_string()
}

fn local_image_request_count(request: &Value) -> u32 {
    let count = request
        .get("imageCount")
        .and_then(Value::as_u64)
        .unwrap_or(1)
        .clamp(1, IMAGE_GENERATION_MAX_COUNT as u64);
    count as u32
}

fn local_image_mode(request: &Value) -> String {
    let mode = local_image_request_text(request, "mode", "text")
        .to_ascii_lowercase()
        .replace('-', "_");
    if matches!(mode.as_str(), "image" | "image_to_image" | "edit" | "edits") {
        "image".to_string()
    } else {
        "text".to_string()
    }
}

fn local_image_size(request: &Value) -> String {
    let fallback = if local_image_request_text(request, "outputFormat", "png") == "gif" {
        "auto"
    } else {
        "1024x1024"
    };
    local_image_request_text(request, "size", fallback).replace(' ', "")
}

fn local_image_quality(request: &Value) -> String {
    match local_image_request_text(request, "quality", "medium")
        .to_ascii_lowercase()
        .as_str()
    {
        "auto" => "auto".to_string(),
        "low" | "fast" => "low".to_string(),
        "high" | "hd" => "high".to_string(),
        "medium" | "standard" | "normal" => "medium".to_string(),
        _ => "medium".to_string(),
    }
}

fn local_image_is_26(model: &str) -> bool {
    matches!(model, GAOGE_IMAGE_MODEL_2_6_FLARE | GAOGE_IMAGE_MODEL_2_6_SUNBURST)
}

fn local_image_bounded_integer(
    request: &Value,
    key: &str,
    fallback: u32,
    minimum: u32,
    maximum: u32,
    step: u32,
) -> Result<u32, String> {
    match request.get(key) {
        None | Some(Value::Null) => Ok(fallback),
        Some(value) => value
            .as_u64()
            .filter(|value| *value >= u64::from(minimum) && *value <= u64::from(maximum)
                && *value % u64::from(step) == 0)
            .map(|value| value as u32)
            .ok_or_else(|| format!("参数 {key} 必须为 {minimum} 到 {maximum} 的整数，步长 {step}。")),
    }
}

fn local_image_media_options(
    request: &Value,
    model: &str,
    mode: &str,
    size: &str,
    image_count: u32,
    reference_paths: &[PathBuf],
) -> Result<LocalImageMediaOptions, String> {
    let output_format = match request.get("outputFormat") {
        None | Some(Value::Null) => "png".to_string(),
        Some(Value::String(value)) if matches!(value.as_str(), "png" | "gif") => value.clone(),
        _ => return Err("输出格式仅支持 png 或 gif。".to_string()),
    };
    let is_26 = local_image_is_26(model);
    let complexity = if is_26 {
        let complexity = match request.get("complexity") {
            None | Some(Value::Null) => "high",
            Some(Value::String(value)) => value.as_str(),
            _ => return Err("complexity 必须是 low、medium 或 high。".to_string()),
        };
        if !matches!(complexity, "low" | "medium" | "high") {
            return Err("complexity 必须是 low、medium 或 high。".to_string());
        }
        Some(complexity.to_string())
    } else {
        if request.get("complexity").is_some_and(|value| !value.is_null()) {
            return Err("complexity 仅适用于 GPT Image 2.6，不会自动更换模型。".to_string());
        }
        None
    };
    let (frame_count, frame_duration_ms) = if output_format == "gif" {
        if !is_26 {
            return Err("GIF 仅支持 GPT Image 2.6 Flare / Sunburst，请明确选择支持的模型。".to_string());
        }
        if mode != "text" || !reference_paths.is_empty() {
            return Err("当前 GIF 仅支持文生动图，不能上传参考图或使用图片编辑。".to_string());
        }
        if size != "auto" {
            return Err("当前 GIF 尺寸需设为 auto。".to_string());
        }
        if image_count != 1 || request.get("imageCount").is_some_and(|value| !value.is_null() && value.as_u64() != Some(1)) {
            return Err("当前 GIF 每次生成 1 个动画；帧数请使用 frameCount。".to_string());
        }
        (
            Some(local_image_bounded_integer(request, "frameCount", 9, 2, 16, 1)?),
            Some(local_image_bounded_integer(request, "frameDurationMs", 200, 20, 2000, 10)?),
        )
    } else {
        if ["frameCount", "frameDurationMs"].iter().any(|key| request.get(*key).is_some_and(|value| !value.is_null())) {
            return Err("帧数和每帧时长仅适用于 GIF，静态图片请移除动画参数。".to_string());
        }
        (None, None)
    };
    Ok(LocalImageMediaOptions { output_format, complexity, frame_count, frame_duration_ms })
}

fn local_image_reference_paths(request: &Value) -> Vec<PathBuf> {
    request
        .get("referenceImagePaths")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .filter_map(|value| value.as_str().map(str::trim).map(ToString::to_string))
        .filter(|value| !value.is_empty())
        .take(IMAGE_GENERATION_MAX_REFERENCES)
        .map(PathBuf::from)
        .collect()
}

fn ensure_local_image_output_dir(request: &Value) -> Result<PathBuf, String> {
    let output_dir = local_image_request_text(request, "outputDir", "");
    if output_dir.is_empty() {
        return Err("请先选择图片保存位置。".to_string());
    }
    let path = PathBuf::from(output_dir);
    fs::create_dir_all(&path).map_err(|error| format!("创建图片保存目录失败：{error}"))?;
    let metadata = fs::metadata(&path).map_err(|error| format!("读取图片保存目录失败：{error}"))?;
    if !metadata.is_dir() {
        return Err("请选择文件夹作为图片保存位置。".to_string());
    }
    Ok(path)
}

fn local_image_endpoint(base_url: &str, mode: &str) -> Result<String, String> {
    append_url_path(
        base_url,
        if mode == "image" {
            "images/edits"
        } else {
            "images/generations"
        },
    )
}

fn local_image_mime_from_path(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(OsStr::to_str)
        .unwrap_or("")
        .to_ascii_lowercase()
        .as_str()
    {
        "jpg" | "jpeg" => "image/jpeg",
        "webp" => "image/webp",
        "gif" => "image/gif",
        _ => "image/png",
    }
}

fn local_image_extension_from_mime(mime_type: &str, bytes: &[u8]) -> &'static str {
    if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        return "gif";
    }
    let mime = mime_type.to_ascii_lowercase();
    if mime.contains("gif") {
        return "gif";
    }
    if mime.contains("jpeg") || mime.contains("jpg") {
        return "jpg";
    }
    if mime.contains("webp") {
        return "webp";
    }
    if bytes.starts_with(&[0xff, 0xd8, 0xff]) {
        return "jpg";
    }
    if bytes.len() >= 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        return "webp";
    }
    "png"
}

fn local_image_mime_from_bytes(mime_type: &str, bytes: &[u8]) -> String {
    if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        return "image/gif".to_string();
    }
    let mime = mime_type.trim();
    if mime.starts_with("image/") {
        return mime.to_string();
    }
    match local_image_extension_from_mime(mime, bytes) {
        "jpg" => "image/jpeg".to_string(),
        "webp" => "image/webp".to_string(),
        "gif" => "image/gif".to_string(),
        _ => "image/png".to_string(),
    }
}

fn strip_data_url_prefix(value: &str) -> (&str, Option<String>) {
    if !value.starts_with("data:image/") {
        return (value, None);
    }
    let Some((head, body)) = value.split_once(',') else {
        return (value, None);
    };
    let mime = head
        .trim_start_matches("data:")
        .split(';')
        .next()
        .filter(|value| value.starts_with("image/"))
        .map(ToString::to_string);
    (body, mime)
}

fn local_image_decode_base64(value: &str) -> Result<(Vec<u8>, Option<String>), String> {
    let (body, mime_type) = strip_data_url_prefix(value.trim());
    general_purpose::STANDARD
        .decode(body)
        .or_else(|_| general_purpose::STANDARD_NO_PAD.decode(body))
        .map(|bytes| (bytes, mime_type))
        .map_err(|_| "图片数据解析失败。".to_string())
}

fn local_image_provider_error_text(value: &str) -> String {
    let sanitized = value
        .replace('\n', " ")
        .replace('\r', " ")
        .chars()
        .collect::<String>();
    let compact = sanitized.split_whitespace().collect::<Vec<_>>().join(" ");
    compact.chars().take(1000).collect()
}

fn local_image_upstream_error(context: &str, detail: &str) -> String {
    let detail = local_image_provider_error_text(detail);
    if detail.is_empty() {
        log::warn!("Image generation upstream error: {context}");
    } else {
        log::warn!("Image generation upstream error: {context}: {detail}");
    }
    if context.contains("timed out") {
        IMAGE_GENERATION_TIMEOUT_MESSAGE.to_string()
    } else {
        IMAGE_GENERATION_BUSY_MESSAGE.to_string()
    }
}

fn local_image_http_error(status: u16, payload: Option<&Value>) -> String {
    // Classify provider errors, but never echo untrusted response text or credentials.
    let detail = payload.map(|value| {
        let error = value.get("error").unwrap_or(value);
        ["code", "type", "message"].iter().filter_map(|key| error.get(*key).and_then(Value::as_str))
            .collect::<Vec<_>>().join(" ").to_ascii_lowercase()
    }).unwrap_or_default();
    if detail.contains("gif") && (detail.contains("preview") || detail.contains("access") || detail.contains("permission") || detail.contains("not enabled")) {
        return "当前账号或线路尚未开通所选模型的 GIF 预览权限，请联系服务方确认。".to_string();
    }
    match status {
        401 => "生图凭证无效或已过期，请重新配置 Image2 Key。".to_string(),
        403 => "当前账号或线路没有所选生图模型的访问权限，请确认服务方已开通。".to_string(),
        404 => "当前线路未提供所选生图模型或接口，请确认模型映射已开通。".to_string(),
        400 | 422 => "生图参数被当前线路拒绝，请检查模型、格式、尺寸和动画参数是否受支持。".to_string(),
        429 => "生图请求已达到当前线路的额度或速率限制，请稍后重试或检查额度。".to_string(),
        408 | 504 => IMAGE_GENERATION_TIMEOUT_MESSAGE.to_string(),
        _ => IMAGE_GENERATION_BUSY_MESSAGE.to_string(),
    }
}

fn local_image_unexpected_response_text(value: &str) -> String {
    local_image_upstream_error("invalid response format", value)
}

fn append_local_provider_image(
    images: &mut Vec<LocalImageProviderImage>,
    image_url: Option<String>,
    image_base64: Option<String>,
) {
    if image_url
        .as_deref()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty())
        || image_base64
            .as_deref()
            .map(str::trim)
            .is_some_and(|value| !value.is_empty())
    {
        images.push(LocalImageProviderImage {
            image_url: image_url.map(|value| value.trim().to_string()),
            image_base64: image_base64.map(|value| value.trim().to_string()),
        });
    }
}

fn append_local_provider_images(
    images: &mut Vec<LocalImageProviderImage>,
    value: &Value,
    context: &str,
) {
    match value {
        Value::String(text) => {
            let trimmed = text.trim();
            if trimmed.is_empty() {
                return;
            }
            if context == "base64" || trimmed.starts_with("data:image/") {
                append_local_provider_image(images, None, Some(trimmed.to_string()));
            } else if context == "url"
                || trimmed.starts_with("http://")
                || trimmed.starts_with("https://")
            {
                append_local_provider_image(images, Some(trimmed.to_string()), None);
            }
        }
        Value::Array(items) => {
            for item in items {
                append_local_provider_images(images, item, context);
            }
        }
        Value::Object(object) => {
            append_local_provider_image(
                images,
                object
                    .get("url")
                    .and_then(Value::as_str)
                    .or_else(|| object.get("image_url").and_then(Value::as_str))
                    .or_else(|| object.get("imageUrl").and_then(Value::as_str))
                    .or_else(|| object.get("signed_url").and_then(Value::as_str))
                    .or_else(|| object.get("download_url").and_then(Value::as_str))
                    .map(ToString::to_string),
                object
                    .get("b64_json")
                    .and_then(Value::as_str)
                    .or_else(|| object.get("base64").and_then(Value::as_str))
                    .or_else(|| object.get("image_base64").and_then(Value::as_str))
                    .or_else(|| object.get("imageBase64").and_then(Value::as_str))
                    .map(ToString::to_string),
            );
            for key in [
                "data", "images", "output", "outputs", "result", "results", "content",
            ] {
                if let Some(next) = object.get(key) {
                    append_local_provider_images(images, next, "auto");
                }
            }
            for key in ["image_urls", "imageUrls", "urls"] {
                if let Some(next) = object.get(key) {
                    append_local_provider_images(images, next, "url");
                }
            }
            if let Some(next) = object.get("b64_json") {
                append_local_provider_images(images, next, "base64");
            }
        }
        _ => {}
    }
}

fn collect_local_provider_images(payload: &Value) -> Vec<LocalImageProviderImage> {
    let mut images = Vec::new();
    append_local_provider_images(&mut images, payload, "auto");
    let mut seen = HashSet::new();
    images
        .into_iter()
        .filter(|image| {
            let key = image
                .image_url
                .as_deref()
                .or(image.image_base64.as_deref())
                .unwrap_or("")
                .to_string();
            !key.is_empty() && seen.insert(key)
        })
        .collect()
}

async fn local_image_download_url(
    client: &reqwest::Client,
    base_url: &str,
    image_url: &str,
    timings: &ImageTimings,
) -> Result<(Vec<u8>, String), String> {
    let timer = timings.stage(ImageTimingStage::ImageDownload);
    let url = url::Url::parse(image_url)
        .or_else(|_| url::Url::parse(base_url).and_then(|base| base.join(image_url)))
        .map_err(|error| {
            local_image_upstream_error("invalid generated image URL", &error.to_string())
        })?;
    if !matches!(url.scheme(), "http" | "https") {
        return Err(local_image_upstream_error(
            "unsupported generated image URL scheme",
            url.scheme(),
        ));
    }
    let response = client
        .get(url)
        .header(reqwest::header::USER_AGENT, GAOGE_USER_AGENT)
        .send()
        .await
        .map_err(|error| {
            local_image_upstream_error("generated image download failed", &error.to_string())
        })?;
    let status = response.status();
    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .unwrap_or("image/png")
        .to_string();
    if !status.is_success() {
        return Err(local_image_upstream_error(
            "generated image download returned an error",
            &format!("HTTP {}", status.as_u16()),
        ));
    }
    let bytes = response
        .bytes()
        .await
        .map_err(|error| {
            local_image_upstream_error("generated image body read failed", &error.to_string())
        })?
        .to_vec();
    timer.finish(true);
    Ok((bytes, content_type))
}

async fn local_image_bytes_from_provider_image(
    client: &reqwest::Client,
    base_url: &str,
    image: &LocalImageProviderImage,
    timings: &ImageTimings,
) -> Result<(Vec<u8>, String), String> {
    if let Some(base64) = image.image_base64.as_deref() {
        let timer = timings.stage(ImageTimingStage::ImageDecode);
        let (bytes, mime_type) = local_image_decode_base64(base64)
            .map_err(|error| local_image_upstream_error("invalid generated image data", &error))?;
        let mime_type = local_image_mime_from_bytes(mime_type.as_deref().unwrap_or(""), &bytes);
        timer.finish(true);
        return Ok((bytes, mime_type));
    }
    if let Some(image_url) = image.image_url.as_deref() {
        return local_image_download_url(client, base_url, image_url, timings).await;
    }
    Err(local_image_upstream_error(
        "generated image payload contained no image data",
        "missing image URL and base64 data",
    ))
}

fn save_local_image_result(
    output_dir: &Path,
    bytes: &[u8],
    mime_type: &str,
    index: usize,
    timings: &ImageTimings,
) -> Result<Value, String> {
    let timer = timings.stage(ImageTimingStage::ImageSave);
    let mime_type = local_image_mime_from_bytes(mime_type, bytes);
    let extension = local_image_extension_from_mime(&mime_type, bytes);
    let sequence = LOCAL_IMAGE_SAVE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
    let file_name = format!(
        "gaoge-image2-{}-{}-{}.{}",
        timestamp_for_path(),
        sequence,
        index + 1,
        extension
    );
    let path = output_dir.join(&file_name);
    fs::write(&path, bytes).map_err(|error| format!("保存生成图片失败：{error}"))?;
    let preview_data_url = format!(
        "data:{};base64,{}",
        mime_type,
        general_purpose::STANDARD.encode(bytes)
    );
    timer.finish(true);
    Ok(json!({
      "path": path.to_string_lossy(),
      "fileName": file_name,
      "mimeType": mime_type,
      "bytes": bytes.len(),
      "previewDataUrl": preview_data_url,
      "previewWarning": if bytes.len() > GAOGE_IMAGE_MCP_MAX_VIEW_BYTES {
          Some("文件已保存；超过 20 MB，Codex 内嵌预览不可用，请打开本地文件。")
      } else { None },
    }))
}

fn validate_local_image_output(bytes: &[u8], expected_format: &str) -> Result<(), String> {
    if expected_format == "gif" && !(bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a")) {
        return Err("当前线路没有返回请求的 GIF 动图，请确认 GIF 权限及 output_format 参数透传；未按静态图片冒充成功。".to_string());
    }
    Ok(())
}

async fn parse_and_save_local_image_response(
    client: &reqwest::Client,
    base_url: &str,
    response: reqwest::Response,
    output_dir: &Path,
    expected_count: u32,
    start_index: usize,
    expected_format: &str,
    timings: &ImageTimings,
) -> Result<Value, String> {
    let status = response.status();
    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .unwrap_or("")
        .to_string();

    if !status.is_success() {
        let status_code = status.as_u16();
        let body_timer = timings.stage(ImageTimingStage::ResponseBody);
        let body_result = response.text().await;
        body_timer.finish(body_result.is_ok());
        let text = body_result.unwrap_or_default();
        let parse_timer = timings.stage(ImageTimingStage::ResponseParse);
        let payload = serde_json::from_str::<Value>(&text).ok();
        parse_timer.finish(false);
        log::warn!("Image generation request rejected: HTTP {status_code}");
        return Err(local_image_http_error(status_code, payload.as_ref()));
    }

    let mut saved_images = Vec::new();
    let mut failed_images = Vec::new();
    if content_type.to_ascii_lowercase().starts_with("image/") {
        let body_timer = timings.stage(ImageTimingStage::ResponseBody);
        let bytes = response
            .bytes()
            .await
            .map_err(|error| {
                local_image_upstream_error("image response body read failed", &error.to_string())
            })?
            .to_vec();
        body_timer.finish(true);
        validate_local_image_output(&bytes, expected_format)?;
        saved_images.push(save_local_image_result(
            output_dir,
            &bytes,
            &content_type,
            start_index,
            timings,
        )?);
    } else {
        let body_timer = timings.stage(ImageTimingStage::ResponseBody);
        let text = response.text().await.map_err(|error| {
            local_image_upstream_error("image response body read failed", &error.to_string())
        })?;
        body_timer.finish(true);
        let parse_timer = timings.stage(ImageTimingStage::ResponseParse);
        let payload: Value =
            serde_json::from_str(&text).map_err(|_| local_image_unexpected_response_text(&text))?;
        let images = collect_local_provider_images(&payload);
        if images.is_empty() {
            return Err(local_image_upstream_error(
                "image response contained no usable images",
                &payload.to_string(),
            ));
        }
        parse_timer.finish(true);
        for (index, image) in images.iter().enumerate() {
            let image_index = start_index + index;
            match local_image_bytes_from_provider_image(client, base_url, image, timings).await {
                Ok((bytes, mime_type)) => {
                    match validate_local_image_output(&bytes, expected_format).and_then(|()| save_local_image_result(
                        output_dir, &bytes, &mime_type, image_index, timings,
                    )) {
                        Ok(saved) => saved_images.push(saved),
                        Err(error) => failed_images.push(json!({
                            "index": image_index + 1,
                            "message": local_image_provider_error_text(&error),
                        })),
                    }
                }
                Err(error) => failed_images.push(json!({
                    "index": image_index + 1,
                    "message": local_image_provider_error_text(&error),
                })),
            }
        }
    }

    let expected_count = usize::try_from(expected_count.max(1)).unwrap_or(1);
    let handled_count = saved_images.len() + failed_images.len();
    if expected_count > handled_count {
        for index in handled_count..expected_count {
            log::warn!(
                "Image generation upstream returned fewer images than requested: missing index {}",
                index + 1
            );
            failed_images.push(json!({
                "index": index + 1,
                "message": IMAGE_GENERATION_BUSY_MESSAGE,
            }));
        }
    }

    if saved_images.is_empty() && !failed_images.is_empty() {
        let first_message = failed_images
            .first()
            .and_then(|item| item.get("message"))
            .and_then(Value::as_str)
            .unwrap_or(IMAGE_GENERATION_BUSY_MESSAGE);
        return Err(first_message.to_string());
    }

    Ok(json!({
      "outputDir": output_dir.to_string_lossy(),
      "count": saved_images.len(),
      "failedCount": failed_images.len(),
      "failedImages": failed_images,
      "images": saved_images,
    }))
}

fn local_image_generation_parameters(parts: &LocalImageGenerationRequestParts, image_count: u32) -> Value {
    let mut body = json!({
        "model": parts.model,
        "prompt": parts.prompt,
        "n": image_count,
        "size": parts.size,
        "quality": parts.quality,
        "background": "auto",
        "output_format": parts.media.output_format,
    });
    if !local_image_is_26(&parts.model) {
        body["response_format"] = json!("b64_json");
    }
    if let Some(complexity) = &parts.media.complexity {
        body["complexity"] = json!(complexity);
    }
    if parts.media.output_format == "gif" {
        body["frame_count"] = json!(parts.media.frame_count);
        body["frame_duration_ms"] = json!(parts.media.frame_duration_ms);
    }
    body
}

async fn send_local_image_generation_request(
    client: reqwest::Client,
    parts: LocalImageGenerationRequestParts,
    image_count: u32,
    timings: &ImageTimings,
) -> Result<reqwest::Response, String> {
    let timer = timings.stage(ImageTimingStage::HttpRequest);
    let body = local_image_generation_parameters(&parts, image_count);
    let response = if parts.mode == "image" {
        let mut form = reqwest::multipart::Form::new();
        for (name, value) in body.as_object().expect("image parameters object") {
            let text = value.as_str().map(ToString::to_string).unwrap_or_else(|| value.to_string());
            form = form.text(name.clone(), text);
        }
        for (index, path) in parts.reference_paths.iter().enumerate() {
            let bytes = fs::read(path).map_err(|error| {
                format!("failed to read reference image {}: {error}", path.display())
            })?;
            let file_name = path.file_name().and_then(OsStr::to_str).map(ToString::to_string)
                .unwrap_or_else(|| format!("reference-{}.png", index + 1));
            let part = reqwest::multipart::Part::bytes(bytes).file_name(file_name)
                .mime_str(local_image_mime_from_path(path))
                .map_err(|error| format!("invalid reference image mime type: {error}"))?;
            form = form.part("image", part);
        }
        client.post(parts.endpoint).bearer_auth(parts.api_key).multipart(form).send().await
    } else {
        client.post(parts.endpoint).bearer_auth(parts.api_key).json(&body).send().await
    };
    timer.finish(response.as_ref().is_ok_and(|response| response.status().is_success()));
    response.map_err(|error| {
        let context = if error.is_timeout() { "image generation request timed out" } else { "image generation request failed" };
        local_image_upstream_error(context, &error.to_string())
    })
}

fn local_image_result_array(result: &Value, key: &str) -> Vec<Value> {
    result
        .get(key)
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
}

async fn generate_local_images_parallel(
    client: reqwest::Client,
    base_url: String,
    parts: LocalImageGenerationRequestParts,
    output_dir: PathBuf,
    image_count: u32,
    timings: &ImageTimings,
) -> Result<Value, String> {
    let total = usize::try_from(image_count.max(1)).unwrap_or(1);
    let mut handles = Vec::with_capacity(total);

    for index in 0..total {
        let task_client = client.clone();
        let task_parse_client = client.clone();
        let task_parts = parts.clone();
        let task_base_url = base_url.clone();
        let task_output_dir = output_dir.clone();
        let task_timings = timings.clone();
        let expected_format = task_parts.media.output_format.clone();
        handles.push(tauri::async_runtime::spawn(async move {
            let response =
                send_local_image_generation_request(task_client, task_parts, 1, &task_timings).await?;
            parse_and_save_local_image_response(
                &task_parse_client,
                &task_base_url,
                response,
                &task_output_dir,
                1,
                index,
                &expected_format,
                &task_timings,
            )
            .await
        }));
    }

    let mut saved_images = Vec::new();
    let mut failed_images = Vec::new();
    for (index, handle) in handles.into_iter().enumerate() {
        match handle.await {
            Ok(Ok(result)) => {
                saved_images.extend(local_image_result_array(&result, "images"));
                failed_images.extend(local_image_result_array(&result, "failedImages"));
            }
            Ok(Err(error)) => failed_images.push(json!({
                "index": index + 1,
                "message": local_image_provider_error_text(&error),
            })),
            Err(error) => {
                let message =
                    local_image_upstream_error("image generation task failed", &error.to_string());
                failed_images.push(json!({
                    "index": index + 1,
                    "message": message,
                }));
            }
        }
    }

    if saved_images.is_empty() && !failed_images.is_empty() {
        let first_message = failed_images
            .first()
            .and_then(|item| item.get("message"))
            .and_then(Value::as_str)
            .unwrap_or(IMAGE_GENERATION_BUSY_MESSAGE);
        return Err(first_message.to_string());
    }

    Ok(json!({
      "outputDir": output_dir.to_string_lossy(),
      "count": saved_images.len(),
      "failedCount": failed_images.len(),
      "failedImages": failed_images,
      "images": saved_images,
    }))
}

async fn gaoge_generate_local_image_inner(request: Value) -> Result<Value, String> {
    let timings = ImageTimings::new();
    let mut result = gaoge_generate_local_image_timed(request, &timings).await;
    timings.finish(result.is_ok());
    if let Ok(value) = &mut result {
        value["timingsMs"] = timings.snapshot();
    }
    result
}

async fn gaoge_generate_local_image_timed(
    request: Value,
    timings: &ImageTimings,
) -> Result<Value, String> {
    let preparation_timer = timings.stage(ImageTimingStage::Preparation);
    let api_key = provider_api_key(&request, "image2")
        .map_err(|_| "未读取到 Image2 生图 Key，请先登录并确保账号有 Image2 分组。".to_string())?;
    let output_dir = ensure_local_image_output_dir(&request)?;
    let prompt = local_image_request_text(&request, "prompt", "");
    if prompt.is_empty() {
        return Err("请输入提示词。".to_string());
    }
    let mode = local_image_mode(&request);
    let reference_paths = local_image_reference_paths(&request);
    if mode == "image" && reference_paths.is_empty() {
        return Err("图片编辑需要先上传参考图。".to_string());
    }

    let base_url = normalize_base_url(
        request.get("baseUrl").and_then(Value::as_str),
        GAOGE_OPENAI_BASE_URL,
    )?;
    let endpoint = local_image_endpoint(&base_url, &mode)?;
    let model = local_image_request_text(&request, "model", GAOGE_IMAGE_MODEL_2_6_FLARE);
    let image_count = local_image_request_count(&request);
    let size = local_image_size(&request);
    let quality = local_image_quality(&request);
    let media = local_image_media_options(&request, &model, &mode, &size, image_count, &reference_paths)?;
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(IMAGE_GENERATION_TIMEOUT_SECS))
        .user_agent(GAOGE_USER_AGENT)
        .build()
        .map_err(|error| format!("创建生图请求失败：{error}"))?;

    let parts = LocalImageGenerationRequestParts {
        api_key: api_key.clone(),
        endpoint: endpoint.clone(),
        mode: mode.clone(),
        prompt: prompt.clone(),
        model: model.clone(),
        size: size.clone(),
        quality: quality.clone(),
        reference_paths: reference_paths.clone(),
        media,
    };

    preparation_timer.finish(true);
    if image_count > 1 {
        return generate_local_images_parallel(
            client,
            base_url.clone(),
            parts,
            output_dir.clone(),
            image_count,
            timings,
        )
        .await;
    }

    let expected_format = parts.media.output_format.clone();
    let response = send_local_image_generation_request(client.clone(), parts, 1, timings).await?;
    return parse_and_save_local_image_response(&client, &base_url, response, &output_dir, 1, 0, &expected_format, timings)
        .await;
}

fn gaoge_image_tool_model(tool_name: &str) -> Option<&'static str> {
    match tool_name {
        GAOGE_IMAGE_TOOL_2 => Some(GAOGE_IMAGE_MODEL_2),
        GAOGE_IMAGE_TOOL_2_5_FLARE => Some(GAOGE_IMAGE_MODEL_2_5_FLARE),
        GAOGE_IMAGE_TOOL_2_5_SUNBURST => Some(GAOGE_IMAGE_MODEL_2_5_SUNBURST),
        GAOGE_IMAGE_TOOL_2_6_FLARE => Some(GAOGE_IMAGE_MODEL_2_6_FLARE),
        GAOGE_IMAGE_TOOL_2_6_SUNBURST => Some(GAOGE_IMAGE_MODEL_2_6_SUNBURST),
        _ => None,
    }
}

fn gaoge_image_mcp_input_schema() -> Value {
    json!({
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "prompt": {
          "type": "string",
          "description": "必填。描述要生成的图片，或说明如何编辑参考图。"
        },
        "size": {
          "type": "string",
          "description": "可选。输出尺寸，默认 1024x1024。",
          "enum": [
            "auto",
            "1024x1024",
            "1536x1024",
            "1024x1536",
            "2048x2048",
            "2048x1152",
            "1152x2048",
            "2880x2880",
            "3840x2160",
            "2160x3840"
          ],
          "default": "1024x1024"
        },
        "quality": {
          "type": "string",
          "description": "可选。生成质量，默认 medium。",
          "enum": ["auto", "low", "medium", "high"],
          "default": "medium"
        },
        "image_count": {
          "type": "integer",
          "description": "可选。生成张数，范围 1 到 4，默认 1。",
          "minimum": 1,
          "maximum": 4,
          "default": 1
        },
        "output_dir": {
          "type": "string",
          "description": "可选。图片保存目录，建议传当前工作区内的绝对路径；省略时保存到当前工作目录的 generated_images。"
        },
        "reference_image_paths": {
          "type": "array",
          "description": "可选。当前对话里官方 ImageView.path、local_image.path 或其他本地参考图路径；支持绝对路径和 file URI，传入后自动使用图片编辑接口，最多 6 张。",
          "maxItems": 6,
          "items": { "type": "string" }
        },
        "reference_image_resource_uris": {
          "type": "array",
          "description": "可选。上一条 Gaoge 生图工具返回的 resourceUri；传入后自动读取对应生成图片作为编辑参考图，最多 6 张。优先使用此字段引用本工具之前生成的图片。",
          "maxItems": 6,
          "items": { "type": "string" }
        }
      },
      "required": ["prompt"]
    })
}

fn gaoge_image_mcp_26_input_schema() -> Value {
    let mut schema = gaoge_image_mcp_input_schema();
    let properties = schema["properties"].as_object_mut().expect("image schema properties");
    properties.insert("complexity".to_string(), json!({
        "type": "string", "enum": ["low", "medium", "high"], "default": "high",
        "description": "可选。生成前规划复杂度，与 quality 渲染质量独立；默认 high。"
    }));
    properties.insert("output_format".to_string(), json!({
        "type": "string", "enum": ["png", "gif"], "default": "png",
        "description": "可选。png 静态图片或 gif 动图。GIF 仅文生，需所选模型的 GIF 预览权限；不能传参考图，size=auto、image_count=1。"
    }));
    properties.insert("frame_count".to_string(), json!({
        "type": "integer", "minimum": 2, "maximum": 16, "default": 9,
        "description": "仅 GIF。帧数 2–16，默认 9；静态图片不传。"
    }));
    properties.insert("frame_duration_ms".to_string(), json!({
        "type": "integer", "minimum": 20, "maximum": 2000, "multipleOf": 10, "default": 200,
        "description": "仅 GIF。每帧 20–2000 毫秒、步长 10，默认 200；静态图片不传。"
    }));
    properties.get_mut("size").expect("image size schema")["description"] = json!("可选。静态图片默认 1024x1024；GIF 必须为 auto，GIF 未传尺寸时自动取 auto。");
    schema
}

fn gaoge_image_mcp_view_input_schema() -> Value {
    json!({
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "resource_uri": {
          "type": "string",
          "description": "可选。用户所指图片对应的 resourceUri，通常取自当前对话上一条 Gaoge 生图工具结果的 structuredContent.imageContext.latestResourceUri。与 image_path 至少提供一个。"
        },
        "image_path": {
          "type": "string",
          "description": "可选。当前对话中官方 ImageView.path、local_image.path 或生成图片的本地绝对路径/file URI。工具会安全校验并注册为持久资源；与 resource_uri 至少提供一个。"
        },
        "question": {
          "type": "string",
          "description": "可选。用户希望模型重点查看、分析、识别、比较或检查的内容。"
        }
      },
      "anyOf": [
        { "required": ["resource_uri"] },
        { "required": ["image_path"] }
      ]
    })
}

