    #[cfg(test)]
    {
        if let Some(path) = CODEX_DIR_OVERRIDE.with(|override_dir| override_dir.borrow().clone()) {
            return path;
        }
        return std::env::temp_dir().join(format!("gaoge-image-mcp-tests-{}", std::process::id()));
    }
