fn gaoge_image_mcp_resource_index_path() -> PathBuf {
    gaoge_image_mcp_codex_home().join(GAOGE_IMAGE_MCP_RESOURCE_INDEX_FILE)
}

fn gaoge_image_mcp_acquire_resource_index_lock(
    index_path: &Path,
) -> Result<GaogeImageMcpResourceIndexLock, String> {
    ensure_parent(index_path)?;
    let lock_path = index_path.with_extension("lock");
    for _ in 0..GAOGE_IMAGE_MCP_RESOURCE_LOCK_RETRIES {
        match fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lock_path)
        {
            Ok(mut file) => {
                let _ = writeln!(file, "{} {}", std::process::id(), unix_now());
                let _ = file.sync_all();
                return Ok(GaogeImageMcpResourceIndexLock {
                    path: lock_path,
                    file: Some(file),
                });
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                let stale = fs::metadata(&lock_path)
                    .and_then(|metadata| metadata.modified())
                    .ok()
                    .and_then(|modified| modified.elapsed().ok())
                    .is_some_and(|elapsed| {
                        elapsed.as_secs() >= GAOGE_IMAGE_MCP_RESOURCE_LOCK_STALE_SECS
                    });
                if stale {
                    let _ = fs::remove_file(&lock_path);
                    continue;
                }
                thread::sleep(Duration::from_millis(20));
            }
            Err(error) => {
                return Err(format!(
                    "创建图片资源索引锁失败 {}：{error}",
                    lock_path.display()
                ));
            }
        }
    }
    Err("图片资源索引正忙，请稍后重试。".to_string())
}

fn gaoge_image_mcp_normalize_canonical_path(path: PathBuf) -> PathBuf {
    #[cfg(target_os = "windows")]
    {
        let text = path.to_string_lossy();
        if let Some(rest) = text.strip_prefix(r"\\?\UNC\") {
            return PathBuf::from(format!(r"\\{rest}"));
        }
        if let Some(rest) = text.strip_prefix(r"\\?\") {
            return PathBuf::from(rest);
        }
    }
    path
}

fn gaoge_image_mcp_path_from_argument(raw_path: &str, cwd: &Path) -> Result<PathBuf, String> {
    let raw_path = raw_path.trim();
    if raw_path.is_empty() {
        return Err("图片路径不能为空。".to_string());
    }
    let path = if raw_path.to_ascii_lowercase().starts_with("file:") {
        let url = url::Url::parse(raw_path).map_err(|_| "图片 file URI 无效。".to_string())?;
        if url.scheme() != "file" {
            return Err("图片地址必须是本地 file URI。".to_string());
        }
        url.to_file_path()
            .map_err(|_| "图片 file URI 无法转换成本地路径。".to_string())?
    } else {
        if raw_path.contains("://") {
            return Err("只支持本地图片路径或 file URI。".to_string());
        }
        let path = PathBuf::from(raw_path);
        if path.is_absolute() {
            path
        } else {
            cwd.join(path)
        }
    };
    fs::canonicalize(&path)
        .map(gaoge_image_mcp_normalize_canonical_path)
        .map_err(|error| format!("无法读取本地图片 {}：{error}", path.display()))
}

fn gaoge_image_mcp_detect_mime(path: &Path) -> Result<String, String> {
    let metadata = fs::metadata(path)
        .map_err(|error| format!("读取图片信息失败 {}：{error}", path.display()))?;
    if !metadata.is_file() {
        return Err(format!("图片路径不是文件：{}", path.display()));
    }
    if metadata.len() == 0 {
        return Err(format!("图片文件为空：{}", path.display()));
    }
    if metadata.len() > GAOGE_IMAGE_MCP_MAX_VIEW_BYTES as u64 {
        return Err(format!(
            "图片过大，超过查看限制 {} MB：{}",
            GAOGE_IMAGE_MCP_MAX_VIEW_BYTES / (1024 * 1024),
            path.display()
        ));
    }
    let mut file = fs::File::open(path)
        .map_err(|error| format!("打开图片失败 {}：{error}", path.display()))?;
    let mut header = [0u8; 16];
    let count = file
        .read(&mut header)
        .map_err(|error| format!("读取图片头失败 {}：{error}", path.display()))?;
    let header = &header[..count];
    let mime_type = if header.starts_with(&[137, 80, 78, 71, 13, 10, 26, 10]) {
        "image/png"
    } else if header.starts_with(&[0xff, 0xd8, 0xff]) {
        "image/jpeg"
    } else if header.len() >= 12 && &header[..4] == b"RIFF" && &header[8..12] == b"WEBP" {
        "image/webp"
    } else if header.starts_with(b"GIF87a") || header.starts_with(b"GIF89a") {
        "image/gif"
    } else if header.starts_with(b"BM") {
        "image/bmp"
    } else {
        return Err(format!(
            "不支持或无法识别的图片格式：{}。仅支持 PNG、JPEG、WebP、GIF 和 BMP。",
            path.display()
        ));
    };
    Ok(mime_type.to_string())
}

fn gaoge_image_mcp_resource_uri_for_path(path: &Path) -> String {
    let digest = Sha256::digest(codex_path_identity(path).as_bytes());
    format!(
        "{GAOGE_IMAGE_MCP_IMAGE_RESOURCE_PREFIX}{}",
        general_purpose::URL_SAFE_NO_PAD.encode(&digest[..18])
    )
}

fn gaoge_image_mcp_load_resource_index(
    index_path: &Path,
) -> HashMap<String, GaogeImageMcpImageResource> {
    let Some(value) = read_json_if_exists(index_path).ok().flatten() else {
        return HashMap::new();
    };
    let Some(entries) = value.get("resources").and_then(Value::as_array) else {
        return HashMap::new();
    };
    let cwd = index_path.parent().unwrap_or_else(|| Path::new("."));
    let mut resources = HashMap::new();
    for entry in entries {
        let Some(uri) = entry
            .get("uri")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|uri| uri.starts_with(GAOGE_IMAGE_MCP_IMAGE_RESOURCE_PREFIX))
        else {
            continue;
        };
        let Some(raw_path) = entry.get("path").and_then(Value::as_str) else {
            continue;
        };
        let Ok(path) = gaoge_image_mcp_path_from_argument(raw_path, cwd) else {
            continue;
        };
        let Ok(mime_type) = gaoge_image_mcp_detect_mime(&path) else {
            continue;
        };
        resources.insert(
            uri.to_string(),
            GaogeImageMcpImageResource {
                path,
                mime_type,
                updated_at: entry.get("updatedAt").and_then(Value::as_i64).unwrap_or(0),
                source: entry
                    .get("source")
                    .and_then(Value::as_str)
                    .unwrap_or("persisted")
                    .to_string(),
            },
        );
    }
    resources
}

fn gaoge_image_mcp_merge_resource_maps(
    target: &mut HashMap<String, GaogeImageMcpImageResource>,
    incoming: HashMap<String, GaogeImageMcpImageResource>,
) {
    for (uri, resource) in incoming {
        let replace = target
            .get(&uri)
            .map(|current| resource.updated_at >= current.updated_at)
            .unwrap_or(true);
        if replace {
            target.insert(uri, resource);
        }
    }
}

fn gaoge_image_mcp_prune_resources(resources: &mut HashMap<String, GaogeImageMcpImageResource>) {
    if resources.len() <= GAOGE_IMAGE_MCP_MAX_REGISTERED_RESOURCES {
        return;
    }
    let mut ordered = resources
        .iter()
        .map(|(uri, resource)| (resource.updated_at, uri.clone()))
        .collect::<Vec<_>>();
    ordered.sort();
    let remove_count = resources
        .len()
        .saturating_sub(GAOGE_IMAGE_MCP_MAX_REGISTERED_RESOURCES);
    for (_, uri) in ordered.into_iter().take(remove_count) {
        resources.remove(&uri);
    }
}

fn gaoge_image_mcp_persist_resource_index(
    index_path: &Path,
    resources: &HashMap<String, GaogeImageMcpImageResource>,
) -> Result<(), String> {
    let mut entries = resources
        .iter()
        .map(|(uri, resource)| {
            json!({
              "uri": uri,
              "path": resource.path.to_string_lossy(),
              "mimeType": resource.mime_type,
              "updatedAt": resource.updated_at,
              "source": resource.source,
            })
        })
        .collect::<Vec<_>>();
    entries.sort_by(|left, right| {
        right["updatedAt"]
            .as_i64()
            .cmp(&left["updatedAt"].as_i64())
            .then_with(|| left["uri"].as_str().cmp(&right["uri"].as_str()))
    });
    write_json_pretty_atomic(
        index_path,
        &json!({
          "version": GAOGE_IMAGE_MCP_RESOURCE_INDEX_VERSION,
          "updatedAt": unix_now(),
          "resources": entries,
        }),
    )
}

fn gaoge_image_mcp_ensure_registry_loaded(
    registry: &mut GaogeImageMcpImageResourceRegistry,
    index_path: &Path,
) {
    if registry.index_path.as_deref() == Some(index_path) {
        return;
    }
    registry.resources = gaoge_image_mcp_load_resource_index(index_path);
    registry.index_path = Some(index_path.to_path_buf());
}

fn gaoge_image_mcp_prepare_image_resource(
    raw_path: &str,
    source: &str,
    cwd: &Path,
) -> Result<(String, GaogeImageMcpImageResource), String> {
    let path = gaoge_image_mcp_path_from_argument(raw_path, cwd)?;
    let mime_type = gaoge_image_mcp_detect_mime(&path)?;
    let uri = gaoge_image_mcp_resource_uri_for_path(&path);
    Ok((
        uri,
        GaogeImageMcpImageResource {
            path,
            mime_type,
            updated_at: unix_now(),
            source: source.to_string(),
        },
    ))
}

fn gaoge_image_mcp_store_prepared_resources(
    prepared: Vec<(String, GaogeImageMcpImageResource)>,
) -> Result<Vec<String>, String> {
    if prepared.is_empty() {
        return Ok(Vec::new());
    }
    let index_path = gaoge_image_mcp_resource_index_path();
    let _index_lock = gaoge_image_mcp_acquire_resource_index_lock(&index_path)?;
    let mut registry = GAOGE_IMAGE_MCP_IMAGE_RESOURCES
        .lock()
        .map_err(|_| "图片资源注册表不可用。".to_string())?;
    gaoge_image_mcp_ensure_registry_loaded(&mut registry, &index_path);
    gaoge_image_mcp_merge_resource_maps(
        &mut registry.resources,
        gaoge_image_mcp_load_resource_index(&index_path),
    );
    let mut uris = Vec::with_capacity(prepared.len());
    for (uri, resource) in prepared {
        registry.resources.insert(uri.clone(), resource);
        uris.push(uri);
    }
    gaoge_image_mcp_prune_resources(&mut registry.resources);
    gaoge_image_mcp_persist_resource_index(&index_path, &registry.resources)?;
    Ok(uris)
}

fn gaoge_image_mcp_register_image_resource_with_source(
    path: &str,
    source: &str,
) -> Result<String, String> {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let prepared = gaoge_image_mcp_prepare_image_resource(path, source, &cwd)?;
    gaoge_image_mcp_store_prepared_resources(vec![prepared])?
        .into_iter()
        .next()
        .ok_or_else(|| "图片资源注册失败。".to_string())
}

fn gaoge_image_mcp_register_image_resource(path: &str, _mime_type: &str) -> Option<String> {
    gaoge_image_mcp_register_image_resource_with_source(path, "gaoge-generated").ok()
}

fn gaoge_image_mcp_resolve_registered_resource(
    resource_uri: Option<&str>,
) -> Result<(String, GaogeImageMcpImageResource), String> {
    let index_path = gaoge_image_mcp_resource_index_path();
    let mut registry = GAOGE_IMAGE_MCP_IMAGE_RESOURCES
        .lock()
        .map_err(|_| "图片资源注册表不可用。".to_string())?;
    gaoge_image_mcp_ensure_registry_loaded(&mut registry, &index_path);
    let resource_uri = resource_uri
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "必须指定当前对话中图片的资源地址。".to_string())?;
    if !resource_uri.starts_with(GAOGE_IMAGE_MCP_IMAGE_RESOURCE_PREFIX) {
        return Err("图片资源地址不是 Gaoge 生图资源。".to_string());
    }
    if !registry.resources.contains_key(resource_uri) {
        gaoge_image_mcp_merge_resource_maps(
            &mut registry.resources,
            gaoge_image_mcp_load_resource_index(&index_path),
        );
    }
    registry
        .resources
        .get(resource_uri)
        .cloned()
        .map(|resource| (resource_uri.to_string(), resource))
        .ok_or_else(|| {
            "图片资源不存在或本地文件已失效；可把当前对话中的 ImageView.path 或 local_image.path 传给 image_path 重新注册。"
                .to_string()
        })
}

fn gaoge_image_mcp_read_registered_image(
    resource_uri: Option<&str>,
) -> Result<(String, GaogeImageMcpImageResource, Vec<u8>), String> {
    let (resource_uri, resource) = gaoge_image_mcp_resolve_registered_resource(resource_uri)?;
    let metadata =
        fs::metadata(&resource.path).map_err(|error| format!("读取生成图片信息失败：{error}"))?;
    if !metadata.is_file() {
        return Err("生成图片资源不再是文件。".to_string());
    }
    if metadata.len() > GAOGE_IMAGE_MCP_MAX_VIEW_BYTES as u64 {
        return Err(format!(
            "生成图片过大，超过查看限制 {} MB。",
            GAOGE_IMAGE_MCP_MAX_VIEW_BYTES / (1024 * 1024)
        ));
    }
    let bytes = fs::read(&resource.path).map_err(|error| format!("读取生成图片失败：{error}"))?;
    if bytes.len() > GAOGE_IMAGE_MCP_MAX_VIEW_BYTES {
        return Err(format!(
            "生成图片过大，超过查看限制 {} MB。",
            GAOGE_IMAGE_MCP_MAX_VIEW_BYTES / (1024 * 1024)
        ));
    }
    let mut resource = resource;
    resource.mime_type = gaoge_image_mcp_detect_mime(&resource.path)?;
    Ok((resource_uri, resource, bytes))
}

fn gaoge_image_mcp_read_resource(uri: &str) -> Result<Value, String> {
    if uri == GAOGE_IMAGE_MCP_UI_RESOURCE_URI {
        return Ok(json!({
          "contents": [{
            "uri": GAOGE_IMAGE_MCP_UI_RESOURCE_URI,
            "mimeType": GAOGE_IMAGE_MCP_UI_MIME_TYPE,
            "text": include_str!("gaoge_image_mcp_ui.html"),
            "_meta": {
              "ui": {
                "prefersBorder": true
              }
            }
          }]
        }));
    }

    let (resource_uri, resource, bytes) = gaoge_image_mcp_read_registered_image(Some(uri))?;
    Ok(json!({
      "contents": [{
        "uri": resource_uri,
        "mimeType": resource.mime_type,
        "blob": general_purpose::STANDARD.encode(bytes),
      }]
    }))
}

fn gaoge_image_mcp_string_argument(
    arguments: &Map<String, Value>,
    key: &str,
    fallback: &str,
) -> Result<String, String> {
    match arguments.get(key) {
        Some(Value::String(value)) => {
            let value = value.trim();
            if value.is_empty() {
                Ok(fallback.to_string())
            } else {
                Ok(value.to_string())
            }
        }
        Some(Value::Null) | None => Ok(fallback.to_string()),
        Some(_) => Err(format!("参数 {key} 必须是字符串。")),
    }
}

fn gaoge_image_mcp_resolve_path(path: &str, cwd: &Path) -> PathBuf {
    let path = PathBuf::from(path);
    if path.is_absolute() {
        lexical_normalize_path(&path)
    } else {
        lexical_normalize_path(&cwd.join(path))
    }
}

fn gaoge_image_mcp_generation_request(
    tool_name: &str,
    arguments: &Value,
    credentials: &CodexImageToolCredentials,
    cwd: &Path,
) -> Result<Value, String> {
    let model = gaoge_image_tool_model(tool_name)
        .ok_or_else(|| format!("未知的 Gaoge 生图工具：{tool_name}"))?;
    let arguments = arguments
        .as_object()
        .ok_or_else(|| "生图工具参数必须是对象。".to_string())?;
    let prompt = gaoge_image_mcp_string_argument(arguments, "prompt", "")?;
    if prompt.is_empty() {
        return Err("参数 prompt 不能为空。".to_string());
    }
    let output_format = gaoge_image_mcp_string_argument(arguments, "output_format", "png")?;
    let size = gaoge_image_mcp_string_argument(arguments, "size", if output_format == "gif" { "auto" } else { "1024x1024" })?;
    if !matches!(
        size.as_str(),
        "auto"
            | "1024x1024"
            | "1536x1024"
            | "1024x1536"
            | "2048x2048"
            | "2048x1152"
            | "1152x2048"
            | "2880x2880"
            | "3840x2160"
            | "2160x3840"
    ) {
        return Err(format!("不支持的图片尺寸：{size}"));
    }
    let quality = gaoge_image_mcp_string_argument(arguments, "quality", "medium")?;
    if !matches!(quality.as_str(), "auto" | "low" | "medium" | "high") {
        return Err(format!("不支持的图片质量：{quality}"));
    }
    let image_count = match arguments.get("image_count") {
        Some(Value::Number(value)) => value
            .as_u64()
            .filter(|value| (1..=IMAGE_GENERATION_MAX_COUNT as u64).contains(value))
            .ok_or_else(|| {
                format!("参数 image_count 必须是 1 到 {IMAGE_GENERATION_MAX_COUNT} 的整数。")
            })?,
        Some(Value::Null) | None => 1,
        Some(_) => {
            return Err(format!(
                "参数 image_count 必须是 1 到 {IMAGE_GENERATION_MAX_COUNT} 的整数。"
            ));
        }
    };
    let output_dir = gaoge_image_mcp_string_argument(arguments, "output_dir", "")?;
    let output_dir = if output_dir.is_empty() {
        lexical_normalize_path(&cwd.join("generated_images"))
    } else {
        gaoge_image_mcp_resolve_path(&output_dir, cwd)
    };
    let reference_values = match arguments.get("reference_image_paths") {
        Some(Value::Array(values)) => values,
        Some(Value::Null) | None => &Vec::new(),
        Some(_) => return Err("参数 reference_image_paths 必须是路径数组。".to_string()),
    };
    let reference_resource_values = match arguments.get("reference_image_resource_uris") {
        Some(Value::Array(values)) => values,
        Some(Value::Null) | None => &Vec::new(),
        Some(_) => {
            return Err("参数 reference_image_resource_uris 必须是资源地址数组。".to_string())
        }
    };
    if reference_values.len() + reference_resource_values.len() > IMAGE_GENERATION_MAX_REFERENCES {
        return Err(format!(
            "参考图最多只能传 {IMAGE_GENERATION_MAX_REFERENCES} 张。"
        ));
    }
    let mut reference_paths = Vec::with_capacity(reference_values.len());
    for value in reference_values {
        let raw_path = value
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| "参考图路径不能为空。".to_string())?;
        let path = gaoge_image_mcp_path_from_argument(raw_path, cwd)?;
        gaoge_image_mcp_detect_mime(&path)?;
        reference_paths.push(path.to_string_lossy().to_string());
    }
    for value in reference_resource_values {
        let raw_uri = value
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| "参考图片资源地址不能为空。".to_string())?;
        let (_, resource) = gaoge_image_mcp_resolve_registered_resource(Some(raw_uri))?;
        gaoge_image_mcp_detect_mime(&resource.path)?;
        reference_paths.push(resource.path.to_string_lossy().to_string());
    }
    let mut request = json!({
      "apiKey": credentials.api_key,
      "baseUrl": credentials.base_url,
      "mode": if reference_paths.is_empty() { "text" } else { "image" },
      "prompt": prompt,
      "model": model,
      "size": size,
      "quality": quality,
      "imageCount": image_count,
      "outputDir": output_dir.to_string_lossy(),
      "referenceImagePaths": reference_paths,
      "outputFormat": output_format,
    });
    for (source, target) in [("complexity", "complexity"), ("frame_count", "frameCount"), ("frame_duration_ms", "frameDurationMs")] {
        if let Some(value) = arguments.get(source) {
            request[target] = value.clone();
        }
    }
    let references = local_image_reference_paths(&request);
    local_image_media_options(&request, model, &local_image_mode(&request), &size, image_count as u32, &references)?;
    Ok(request)
}

fn gaoge_image_mcp_view_image(arguments: &Value) -> Value {
    let result = (|| {
        let arguments = arguments
            .as_object()
            .ok_or_else(|| "查看图片工具参数必须是对象。".to_string())?;
        let resource_uri = gaoge_image_mcp_string_argument(arguments, "resource_uri", "")?;
        let image_path = gaoge_image_mcp_string_argument(arguments, "image_path", "")?;
        let question = gaoge_image_mcp_string_argument(arguments, "question", "")?;
        if resource_uri.is_empty() && image_path.is_empty() {
            return Err(
                "必须提供当前对话图片的 resource_uri，或 ImageView/local_image 的 image_path。"
                    .to_string(),
            );
        }
        let mut registered_from_path = resource_uri.is_empty() && !image_path.is_empty();
        let selected_uri = if !resource_uri.is_empty() {
            resource_uri.clone()
        } else {
            gaoge_image_mcp_register_image_resource_with_source(&image_path, "codex-history")?
        };
        let (resource_uri, resource, bytes) =
            match gaoge_image_mcp_read_registered_image(Some(&selected_uri)) {
                Ok(result) => result,
                Err(_) if !image_path.is_empty() && !resource_uri.is_empty() => {
                    registered_from_path = true;
                    let fallback_uri = gaoge_image_mcp_register_image_resource_with_source(
                        &image_path,
                        "codex-history",
                    )?;
                    gaoge_image_mcp_read_registered_image(Some(&fallback_uri))?
                }
                Err(error) => return Err(error),
            };
        let mime_type = local_image_mime_from_bytes(&resource.mime_type, &bytes);
        let file_name = resource
            .path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("生成图片");
        let mut text = format!(
            "已读取图片 {file_name}，以下 MCP image 内容供客户端转交为视觉输入。资源地址：{resource_uri}"
        );
        if !question.is_empty() {
            text.push_str(&format!("\n重点查看：{question}"));
        }
        Ok::<Value, String>(json!({
          "content": [
            {
              "type": "text",
              "text": text,
            },
            {
              "type": "image",
              "data": general_purpose::STANDARD.encode(&bytes),
              "mimeType": mime_type,
            }
          ],
          // Keep metadata out of structuredContent: some clients prioritize it
          // over the image-bearing content array when building model input.
          // This response includes image bytes; delivery is the client's responsibility.
          "_meta": {
            "resourceUri": resource_uri,
            "fileName": file_name,
            "mimeType": mime_type,
            "bytes": bytes.len(),
            "registeredFromPath": registered_from_path,
          },
          "isError": false,
        }))
    })();
    result.unwrap_or_else(gaoge_image_mcp_tool_error)
}

fn gaoge_image_mcp_tool_success(model: &str, result: Value) -> Value {
    let output_dir = result
        .get("outputDir")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let images = result
        .get("images")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let failed_images = result
        .get("failedImages")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut paths = Vec::new();
    let mut safe_images = Vec::new();
    let mut ui_images = Vec::new();
    let mut resource_links = Vec::new();
    let mut preview_warnings = Vec::new();
    for image in &images {
        let path = image
            .get("path")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        if !path.is_empty() {
            paths.push(path.clone());
        }
        let mime_type = image
            .get("mimeType")
            .and_then(Value::as_str)
            .unwrap_or("image/png");
        let file_name = image.get("fileName").cloned().unwrap_or(Value::Null);
        let resource_uri = if path.is_empty() {
            None
        } else {
            gaoge_image_mcp_register_image_resource(&path, mime_type)
        };
        let mut safe_image = json!({
          "path": path,
          "fileName": file_name,
          "mimeType": mime_type,
          "bytes": image.get("bytes").cloned().unwrap_or(Value::Null),
        });
        if resource_uri.is_none() && !path.is_empty() {
            let warning = if image.get("bytes").and_then(Value::as_u64).unwrap_or(0) > GAOGE_IMAGE_MCP_MAX_VIEW_BYTES as u64 {
                "文件已保存；超过 20 MB，Codex 内嵌预览不可用，请打开本地文件。"
            } else {
                "文件已保存；预览资源未注册，请通过本地文件查看。"
            };
            safe_image["previewWarning"] = json!(warning);
            ui_images.push(json!({
                "path": path,
                "fileName": file_name,
                "mimeType": mime_type,
                "bytes": image.get("bytes").cloned().unwrap_or(Value::Null),
                "previewUnavailableReason": warning,
            }));
            preview_warnings.push(warning.to_string());
        }
        if let Some(resource_uri) = resource_uri {
            safe_image["resourceUri"] = Value::String(resource_uri.clone());
            ui_images.push(json!({
              "resourceUri": resource_uri.clone(),
              "fileName": image.get("fileName").cloned().unwrap_or(Value::Null),
              "mimeType": mime_type,
              "bytes": image.get("bytes").cloned().unwrap_or(Value::Null),
            }));
            resource_links.push(json!({
              "type": "resource_link",
              "uri": resource_uri,
              "name": image.get("fileName").and_then(Value::as_str).unwrap_or("生成图片"),
              "mimeType": mime_type,
              "description": "生成图片预览资源",
            }));
        }
        safe_images.push(safe_image);
    }
    let latest_resource_uri = safe_images
        .iter()
        .rev()
        .find_map(|image| image.get("resourceUri").and_then(Value::as_str))
        .map(ToString::to_string);
    let path_lines = if paths.is_empty() {
        "没有可用的输出文件。".to_string()
    } else {
        paths
            .iter()
            .map(|path| format!("- {}", path.replace('\\', "/")))
            .collect::<Vec<_>>()
            .join("\n")
    };
    let failed_count = failed_images.len();
    let mut text = format!(
        "已使用 {model} 生成 {} 张图片，文件已保存到本地：\n{path_lines}",
        images.len()
    );
    if failed_count > 0 {
        text.push_str(&format!("\n另有 {failed_count} 张生成失败。"));
    }
    preview_warnings.sort();
    preview_warnings.dedup();
    for warning in &preview_warnings {
        text.push_str(&format!("\n{warning}"));
    }
    if let Some(resource_uri) = latest_resource_uri.as_deref() {
        text.push_str(&format!(
            "\n图片已可通过卡片或上面的绝对路径直接交付；普通生图无需调用查看工具。后续直接编辑可将 resourceUri {resource_uri} 作为 reference_image_resource_uris；仅在用户要求分析或检查、或复杂交付确需验收时使用 {GAOGE_IMAGE_VIEW_TOOL} 获取一次视觉输入。"
        ));
    }
    let mut content = vec![json!({
      "type": "text",
      "text": text,
    })];
    content.extend(resource_links);
    json!({
      "content": content,
      "structuredContent": {
        "model": model,
        "outputDir": output_dir,
        "count": images.len(),
        "failedCount": failed_count,
        "images": safe_images,
        "failedImages": failed_images,
        "previewWarnings": preview_warnings,
        "imageContext": {
          "latestResourceUri": latest_resource_uri,
          "deliveryHint": "成功生成可直接展示卡片或 images[].path；普通交付无需看图，仅按用户要求或复杂验收获取视觉输入。",
          "viewTool": GAOGE_IMAGE_VIEW_TOOL,
          "editReferenceField": "reference_image_resource_uris"
        },
      },
      "_meta": {
        GAOGE_IMAGE_MCP_RESULT_META_KEY: {
          "version": 1,
          "images": ui_images,
        }
      },
      "isError": false,
    })
}

fn gaoge_image_mcp_public_error_text(message: &str) -> String {
    let trimmed = message.trim();
    let lower = trimmed.to_ascii_lowercase();
    if trimmed == IMAGE_GENERATION_BUSY_MESSAGE
        || trimmed.starts_with('<')
        || lower.contains("<!doctype html")
        || lower.contains("<html")
    {
        IMAGE_GENERATION_BUSY_MESSAGE.to_string()
    } else {
        format!("Gaoge 图片工具失败：{trimmed}")
    }
}

fn gaoge_image_mcp_tool_error(message: impl Into<String>) -> Value {
    let message = message.into();
    json!({
      "content": [{
        "type": "text",
        "text": gaoge_image_mcp_public_error_text(&message),
      }],
      "isError": true,
    })
}

async fn gaoge_image_mcp_call_tool(tool_name: &str, arguments: &Value) -> Value {
    let timings = ImageTimings::new();
    let mut output = if tool_name == GAOGE_IMAGE_VIEW_TOOL {
        let timer = timings.stage(ImageTimingStage::ImageView);
        let output = gaoge_image_mcp_view_image(arguments);
        timer.finish(output.get("isError").and_then(Value::as_bool) == Some(false));
        output
    } else {
        let result = async {
            let credential_timer = timings.stage(ImageTimingStage::Credentials);
            let credentials = run_blocking_task(load_codex_image_tool_credentials).await?;
            credential_timer.finish(true);
            let argument_timer = timings.stage(ImageTimingStage::Arguments);
            let cwd =
                std::env::current_dir().map_err(|error| format!("读取当前工作目录失败：{error}"))?;
            let request = gaoge_image_mcp_generation_request(tool_name, arguments, &credentials, &cwd)?;
            let model = gaoge_image_tool_model(tool_name)
                .ok_or_else(|| format!("未知的 Gaoge 生图工具：{tool_name}"))?;
            argument_timer.finish(true);
            let result = gaoge_generate_local_image_timed(request, &timings).await?;
            let registration_timer = timings.stage(ImageTimingStage::ResourceRegistration);
            let output = gaoge_image_mcp_tool_success(model, result);
            registration_timer.finish(true);
            Ok::<Value, String>(output)
        }
        .await;
        result.unwrap_or_else(gaoge_image_mcp_tool_error)
    };
    timings.finish(output.get("isError").and_then(Value::as_bool) == Some(false));
    // Stage values sum work across concurrent images; total is tool wall-clock time.
    // No timing values contain image content, credentials, prompts or filesystem paths.
    attach_gaoge_image_mcp_timings(&mut output, timings.snapshot());
    output
}

// Only successful generation already has structured metadata. Never create it
// for image/error content: affected clients would discard that content entirely.
fn attach_gaoge_image_mcp_timings(output: &mut Value, timings: Value) {
    let metadata_key = if output.get("isError").and_then(Value::as_bool) != Some(true)
        && output.get("structuredContent").is_some_and(Value::is_object)
    {
        "structuredContent"
    } else {
        "_meta"
    };
    if !output.get(metadata_key).is_some_and(Value::is_object) {
        output[metadata_key] = json!({});
    }
    output[metadata_key]["timingsMs"] = timings;
}

fn gaoge_image_mcp_jsonrpc_result(id: Value, result: Value) -> Value {
    json!({
      "jsonrpc": "2.0",
      "id": id,
      "result": result,
    })
}

fn gaoge_image_mcp_jsonrpc_error(id: Value, code: i64, message: impl Into<String>) -> Value {
    json!({
      "jsonrpc": "2.0",
      "id": id,
      "error": {
        "code": code,
        "message": message.into(),
      },
    })
}

async fn gaoge_image_mcp_handle_message(message: Value) -> Option<Value> {
    let Some(object) = message.as_object() else {
        return Some(gaoge_image_mcp_jsonrpc_error(
            Value::Null,
            -32600,
            "Invalid Request",
        ));
    };
    let id = object.get("id").cloned();
    let method = object
        .get("method")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if method.starts_with("notifications/") {
        return None;
    }
    let Some(id) = id else {
        return None;
    };
    match method {
        "initialize" => {
            let protocol_version = object
                .get("params")
                .and_then(|params| params.get("protocolVersion"))
                .and_then(Value::as_str)
                .filter(|value| !value.trim().is_empty())
                .unwrap_or(GAOGE_IMAGE_MCP_PROTOCOL_VERSION);
            Some(gaoge_image_mcp_jsonrpc_result(
                id,
                json!({
                  "protocolVersion": protocol_version,
                  "capabilities": {
                    "tools": {
                      "listChanged": false
                    },
                    "resources": {
                      "listChanged": false,
                      "subscribe": false
                    }
                  },
                  "serverInfo": {
                    "name": "gaoge-image",
                    "title": "Gaoge Image Tools",
                    "version": env!("CARGO_PKG_VERSION")
                  },
                  "instructions": format!("{GAOGE_IMAGE_FAST_PATH_INSTRUCTIONS} 提供五个固定模型生图工具和一个查看/分析图片工具。用户未指定型号时优先使用 2.6F；明确指定 2、2.5F、2.5S、2.6F 或 2.6S 时必须调用对应工具，禁止静默换模型。只有2.6工具支持complexity和GIF；GIF仅文生，output_format=gif、size=auto、image_count=1，默认9帧/每帧200ms，不传参考图；静态图不传帧参数。GIF需要当前线路预览权限，权限错误不能宣称已生成。用户自然地提到这张图、刚才的图片、这个图片并要求描述、识别、比较、检查或修改时，不要要求固定话术：Gaoge 生图从当前对话结果读取 structuredContent.imageContext.latestResourceUri；官方历史图片从当前对话的 ImageView.path 或 local_image.path 读取。分析时传给查看工具的 resource_uri 或 image_path；编辑时传给生图工具的 reference_image_resource_uris 或 reference_image_paths。不得猜测其他对话或全局最近图片。")
                }),
            ))
        }
        "ping" => Some(gaoge_image_mcp_jsonrpc_result(id, json!({}))),
        "tools/list" => Some(gaoge_image_mcp_jsonrpc_result(
            id,
            json!({ "tools": gaoge_image_mcp_tools() }),
        )),
        "resources/list" => Some(gaoge_image_mcp_jsonrpc_result(
            id,
            json!({
              "resources": [{
                "uri": GAOGE_IMAGE_MCP_UI_RESOURCE_URI,
                "name": "Gaoge 图片预览",
                "description": "在 Codex 对话中显示生图结果的 MCP App UI。",
                "mimeType": GAOGE_IMAGE_MCP_UI_MIME_TYPE
              }]
            }),
        )),
        "resources/read" => {
            let params = object.get("params").cloned().unwrap_or_else(|| json!({}));
            let Some(uri) = params.get("uri").and_then(Value::as_str) else {
                return Some(gaoge_image_mcp_jsonrpc_error(
                    id,
                    -32602,
                    "Missing resource URI",
                ));
            };
            match gaoge_image_mcp_read_resource(uri) {
                Ok(result) => Some(gaoge_image_mcp_jsonrpc_result(id, result)),
                Err(error) => Some(gaoge_image_mcp_jsonrpc_error(id, -32002, error)),
            }
        }
        "tools/call" => {
            let params = object.get("params").cloned().unwrap_or_else(|| json!({}));
            let Some(tool_name) = params.get("name").and_then(Value::as_str) else {
                return Some(gaoge_image_mcp_jsonrpc_error(
                    id,
                    -32602,
                    "Missing tool name",
                ));
            };
            let arguments = params
                .get("arguments")
                .cloned()
                .unwrap_or_else(|| json!({}));
            Some(gaoge_image_mcp_jsonrpc_result(
                id,
                gaoge_image_mcp_call_tool(tool_name, &arguments).await,
            ))
        }
        _ => Some(gaoge_image_mcp_jsonrpc_error(
            id,
            -32601,
            format!("Method not found: {method}"),
        )),
    }
}

pub fn run_gaoge_image_mcp() -> Result<(), String> {
    start_gaoge_image_mcp_skill_refresh();
    if let Ok(mut registry) = GAOGE_IMAGE_MCP_IMAGE_RESOURCES.lock() {
        let index_path = gaoge_image_mcp_resource_index_path();
        gaoge_image_mcp_ensure_registry_loaded(&mut registry, &index_path);
    }
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let mut output = BufWriter::new(stdout.lock());
    for line in stdin.lock().lines() {
        let line = line.map_err(|error| format!("读取 MCP 请求失败：{error}"))?;
        if line.trim().is_empty() {
            continue;
        }
        let response = match serde_json::from_str::<Value>(&line) {
            Ok(message) => tauri::async_runtime::block_on(gaoge_image_mcp_handle_message(message)),
            Err(error) => Some(gaoge_image_mcp_jsonrpc_error(
                Value::Null,
                -32700,
                format!("Parse error: {error}"),
            )),
        };
        let Some(response) = response else {
            continue;
        };
        serde_json::to_writer(&mut output, &response)
            .map_err(|error| format!("写入 MCP 响应失败：{error}"))?;
        output
            .write_all(b"\n")
            .map_err(|error| format!("写入 MCP 响应失败：{error}"))?;
        output
            .flush()
            .map_err(|error| format!("刷新 MCP 响应失败：{error}"))?;
    }
    Ok(())
}

#[tauri::command]
async fn gaoge_generate_local_image(request: Value) -> Result<Value, String> {
    gaoge_generate_local_image_inner(request).await
}

#[tauri::command]
async fn gaoge_set_window_layout(app: AppHandle, request: Value) -> Result<Value, String> {
    let mode = request.get("mode").and_then(Value::as_str).unwrap_or("app");
    let normalized_mode = match mode {
        "login" => "login",
        "server" => "server",
        _ => "app",
    };
    let (width, height, min_width, min_height) = (1250.0, 800.0, 1250.0, 700.0);

    let window = app
        .get_webview_window("main")
        .ok_or_else(|| "未找到主窗口".to_string())?;

    if window.is_maximized().unwrap_or(false) {
        let _ = window.unmaximize();
    }

    window
        .set_min_size(Some(Size::Logical(LogicalSize {
            width: min_width,
            height: min_height,
        })))
        .map_err(|error| format!("设置窗口最小尺寸失败：{error}"))?;
    window
        .set_max_size::<Size>(None)
        .map_err(|error| format!("set window max size failed: {error}"))?;
    window
        .set_size(Size::Logical(LogicalSize { width, height }))
        .map_err(|error| format!("设置窗口尺寸失败：{error}"))?;
    let _ = window.center();

    Ok(json!({
      "applied": true,
      "mode": normalized_mode,
      "width": width,
      "height": height
    }))
}

