    #[test]
    fn fuel_runtime_health_uses_the_embedded_script_version() {
        let version = codex_fuel_runtime_version();
        assert!(version > 0, "the runtime must declare one readable version");
        let mut result = json!({
            "fuelRuntimeEnabled": true,
            "fuelRuntimeReady": true,
            "fuelRuntimeVersion": version,
            "fuelRuntimeHealth": { "healthy": true, "needsReinstall": false },
            "fuelRuntimeError": ""
        });
        assert!(codex_fuel_injection_verified(&result, true));
        result["fuelRuntimeVersion"] = json!(version + 1);
        assert!(!codex_fuel_injection_verified(&result, true));
        result["fuelRuntimeVersion"] = json!(version);
        result["fuelRuntimeReady"] = json!(false);
        assert!(!codex_fuel_injection_verified(&result, true));
        result["fuelRuntimeReady"] = json!(true);
        result["fuelRuntimeError"] = json!("adapter unavailable");
        assert!(!codex_fuel_injection_verified(&result, true));
        assert!(codex_fuel_injection_verified(&json!({}), false));
    }

    #[test]
    fn fuel_runtime_health_rejects_broken_adaptation_even_when_installation_is_ready() {
        let mut snapshot = json!({
            "matches": true,
            "fuel": {
                "fuelRuntimePresent": true,
                "fuelRuntimeEnabled": true,
                "fuelRuntimeReady": true,
                "fuelRuntimeVersion": codex_fuel_runtime_version(),
                "fuelRuntimeError": "",
                "fuelRuntimeHealth": { "healthy": true, "needsReinstall": false },
                "fuelRuntimeUsageCache": { "installed": false, "supported": 0, "unlocked": 0 }
            }
        });
        // A native adapter can be healthy before the account usage query loads.
        assert!(codex_runtime_healthcheck_verified(&snapshot, true));
        snapshot["fuel"]["fuelRuntimeReady"] = json!(false);
        snapshot["fuel"]["fuelRuntimeHealth"]["reason"] = json!("awaiting-usage-query");
        snapshot["fuel"]["fuelRuntimeHealth"]["monitoring"] = json!(true);
        snapshot["fuel"]["fuelRuntimeUsageCache"]["installed"] = json!(true);
        assert!(codex_runtime_healthcheck_verified(&snapshot, true));
        assert!(!codex_fuel_injection_verified(&snapshot["fuel"], true));
        snapshot["fuel"]["fuelRuntimeUsageCache"]["installed"] = json!(false);
        assert!(!codex_runtime_healthcheck_verified(&snapshot, true));
        snapshot["fuel"]["fuelRuntimeReady"] = json!(true);
        snapshot["fuel"]["fuelRuntimeHealth"]["healthy"] = json!(false);
        snapshot["fuel"]["fuelRuntimeHealth"]["needsReinstall"] = json!(true);
        assert!(!codex_runtime_healthcheck_verified(&snapshot, true));
        assert!(!codex_fuel_injection_verified(&snapshot["fuel"], true));
        snapshot["fuel"]["fuelRuntimeHealth"] = Value::Null;
        assert!(!codex_runtime_healthcheck_verified(&snapshot, true));
        // Official routing does not require the relay adapter to be active.
        snapshot["fuel"]["fuelRuntimeEnabled"] = json!(false);
        assert!(codex_runtime_healthcheck_verified(&snapshot, false));
        snapshot["matches"] = json!(false);
        assert!(!codex_runtime_healthcheck_verified(&snapshot, false));
    }

