    fn write_test_plugin_marketplace(
        root: &Path,
        file_name: &str,
        marketplace_name: &str,
        plugin_names: &[&str],
    ) {
        let manifest_dir = root.join(".agents").join("plugins");
        fs::create_dir_all(&manifest_dir).unwrap();
        let plugins = plugin_names
            .iter()
            .map(|name| {
                fs::create_dir_all(root.join("plugins").join(name)).unwrap();
                json!({
                    "name": name,
                    "path": format!("./plugins/{name}"),
                })
            })
            .collect::<Vec<_>>();
        fs::write(
            manifest_dir.join(file_name),
            serde_json::to_vec_pretty(&json!({
                "name": marketplace_name,
                "plugins": plugins,
            }))
            .unwrap(),
        )
        .unwrap();
    }

