    fn image_request_parts_for_test(model: &str, request: &Value) -> Result<LocalImageGenerationRequestParts, String> {
        let mode = local_image_mode(request);
        let size = local_image_size(request);
        let references = local_image_reference_paths(request);
        let media = local_image_media_options(request, model, &mode, &size, local_image_request_count(request), &references)?;
        Ok(LocalImageGenerationRequestParts {
            api_key: "offline-test-key".to_string(),
            endpoint: "http://127.0.0.1/unused".to_string(),
            mode, prompt: "test animation".to_string(), model: model.to_string(), size,
            quality: local_image_quality(request), reference_paths: references, media,
        })
    }

    #[test]
    fn image26_payloads_keep_complexity_separate_and_isolate_gif_parameters() {
        for model in [GAOGE_IMAGE_MODEL_2_6_FLARE, GAOGE_IMAGE_MODEL_2_6_SUNBURST] {
            let static_parts = image_request_parts_for_test(model, &json!({"quality":"low", "complexity":"high"})).unwrap();
            let body = local_image_generation_parameters(&static_parts, 1);
            assert_eq!(body["model"], model);
            assert_eq!(body["quality"], "low");
            assert_eq!(body["complexity"], "high");
            assert_eq!(body["output_format"], "png");
            for key in ["response_format", "frame_count", "frame_duration_ms"] { assert!(body.get(key).is_none(), "{key}"); }
            let gif_parts = image_request_parts_for_test(model, &json!({"outputFormat":"gif"})).unwrap();
            let gif = local_image_generation_parameters(&gif_parts, 1);
            assert_eq!(gif["size"], "auto");
            assert_eq!(gif["n"], 1);
            assert_eq!(gif["output_format"], "gif");
            assert_eq!(gif["frame_count"], 9);
            assert_eq!(gif["frame_duration_ms"], 200);
            for key in ["response_format", "stream", "partial_images", "output_compression", "prompt_rewriter", "image", "mask"] {
                assert!(gif.get(key).is_none(), "{key}");
            }
        }
        for model in [GAOGE_IMAGE_MODEL_2, GAOGE_IMAGE_MODEL_2_5_FLARE, GAOGE_IMAGE_MODEL_2_5_SUNBURST] {
            let old = image_request_parts_for_test(model, &json!({"mode":"image","referenceImagePaths":["reference.png"],"quality":"high","size":"3840x2160"})).unwrap();
            let body = local_image_generation_parameters(&old, 1);
            assert_eq!(body["response_format"], "b64_json");
            assert_eq!(body["size"], "3840x2160");
            assert!(body.get("complexity").is_none());
            assert!(body.get("frame_count").is_none());
        }
    }

    #[test]
    fn image26_gif_validation_rejects_incompatible_requests_without_model_fallback() {
        for request in [
            json!({"outputFormat":"gif","mode":"image","referenceImagePaths":["x.png"]}),
            json!({"outputFormat":"gif","referenceImagePaths":["x.png"]}),
            json!({"outputFormat":"gif","imageCount":2}),
            json!({"outputFormat":"gif","imageCount":0}),
            json!({"outputFormat":"gif","size":"1024x1024"}),
            json!({"outputFormat":"gif","frameCount":1}),
            json!({"outputFormat":"gif","frameCount":17}),
            json!({"outputFormat":"gif","frameCount":"9"}),
            json!({"outputFormat":"gif","frameDurationMs":19}),
            json!({"outputFormat":"gif","frameDurationMs":205}),
            json!({"outputFormat":"gif","frameDurationMs":2010}),
            json!({"outputFormat":"png","frameCount":9}),
            json!({"complexity":"maximum"}),
        ] {
            assert!(image_request_parts_for_test(GAOGE_IMAGE_MODEL_2_6_FLARE, &request).is_err(), "{request}");
        }
        assert!(image_request_parts_for_test(GAOGE_IMAGE_MODEL_2_5_FLARE, &json!({"outputFormat":"gif"})).is_err());
        assert!(image_request_parts_for_test(GAOGE_IMAGE_MODEL_2, &json!({"complexity":"low"})).is_err());
        for (frames, duration) in [(2, 20), (16, 2000)] {
            assert!(image_request_parts_for_test(GAOGE_IMAGE_MODEL_2_6_SUNBURST, &json!({"outputFormat":"gif","frameCount":frames,"frameDurationMs":duration})).is_ok());
        }
    }

