    const IMAGE26_ANIMATED_GIF_FIXTURE: &str = "";

    #[test]
    fn image26_gif_base64_and_mislabeled_mime_save_original_animation_bytes() {
        let dir = tempfile::tempdir().unwrap();
        let (bytes, mime) = local_image_decode_base64(IMAGE26_ANIMATED_GIF_FIXTURE).unwrap();
        assert!(mime.is_none());
        assert!(validate_local_image_output(&bytes, "gif").is_ok());
        assert_eq!(local_image_mime_from_bytes("image/png", &bytes), "image/gif");
        let saved = save_local_image_result(dir.path(), &bytes, "", 0, &ImageTimings::new()).unwrap();
        let path = Path::new(saved["path"].as_str().unwrap());
        assert_eq!(path.extension().and_then(OsStr::to_str), Some("gif"));
        assert_eq!(fs::read(path).unwrap(), bytes);
        assert_eq!(saved["mimeType"], "image/gif");
        assert!(saved["previewDataUrl"].as_str().unwrap().starts_with("data:image/gif;base64,"));
        assert_eq!(gaoge_image_mcp_detect_mime(path).unwrap(), "image/gif");
        assert!(validate_local_image_output(b"\x89PNG\r\n\x1a\n", "gif").unwrap_err().contains("没有返回请求的 GIF"));
    }

    #[test]
    fn image26_gif_response_rejects_silent_static_fallback() {
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut request = [0u8; 2048];
            let _ = stream.read(&mut request);
            let body = json!({"data":[{"b64_json":general_purpose::STANDARD.encode(b"\x89PNG\r\n\x1a\n") }]}).to_string();
            write!(stream,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();
        });
        let client = reqwest::Client::new();
        let dir = tempfile::tempdir().unwrap();
        let result = tauri::async_runtime::block_on(async {
            let response = client.get(format!("http://{address}")).send().await.unwrap();
            parse_and_save_local_image_response(&client, &format!("http://{address}"), response, dir.path(), 1, 0, "gif", &ImageTimings::new()).await
        });
        server.join().unwrap();
        assert!(result.unwrap_err().contains("没有返回请求的 GIF"));
        assert_eq!(fs::read_dir(dir.path()).unwrap().count(), 0);
    }

