    #[test]
    fn image26_provider_errors_are_actionable_and_never_echo_provider_secrets() {
        let payload = json!({"error":{"message":"GIF preview access denied; secret-token-123"}});
        let denied = local_image_http_error(403, Some(&payload));
        assert!(denied.contains("GIF") && denied.contains("权限"));
        assert!(!denied.contains("secret-token-123"));
        assert!(local_image_http_error(401, None).contains("凭证"));
        assert!(local_image_http_error(400, None).contains("参数"));
        assert!(local_image_http_error(429, None).contains("额度或速率"));
        assert_eq!(local_image_http_error(504, None), IMAGE_GENERATION_TIMEOUT_MESSAGE);
        assert_eq!(local_image_upstream_error("image generation request timed out", "secret-token-123"), IMAGE_GENERATION_TIMEOUT_MESSAGE);
    }

    #[test]
    fn image26_startup_migration_only_updates_existing_enabled_managed_integrations() {
        let workspace = tempfile::tempdir().unwrap();
        let integrated = workspace.path().join("integrated");
        let untouched = workspace.path().join("official");
        let disabled = workspace.path().join("disabled");
        let custom = workspace.path().join("custom");
        let wrapper = workspace.path().join("wrapper");
        for path in [&integrated, &untouched, &disabled, &custom, &wrapper] { fs::create_dir(path).unwrap(); }
        let installed = "[mcp_servers.gaoge_image]\ncommand = \"old-directory/gaoge-free.exe\"\nargs = [\"--gaoge-image-mcp\"]\ntool_timeout_sec = 900\nenabled = true\ncustom_setting = \"keep\"\n[mcp_servers.other]\ncommand = \"other\"\n";
        fs::write(integrated.join("config.toml"), installed).unwrap();
        fs::write(untouched.join("config.toml"), "model = \"gpt-6\"\n").unwrap();
        let disabled_config = installed.replace("enabled = true", "enabled = false");
        fs::write(disabled.join("config.toml"), &disabled_config).unwrap();
        let custom_config = installed.replace("--gaoge-image-mcp", "--custom");
        fs::write(custom.join("config.toml"), &custom_config).unwrap();
        let wrapper_config = installed.replace("old-directory/gaoge-free.exe", "custom-wrapper.exe");
        fs::write(wrapper.join("config.toml"), &wrapper_config).unwrap();
        let targets = [&integrated, &untouched, &disabled, &custom, &wrapper].into_iter().map(|dir| CodexDirTarget { dir: dir.clone(), source: "test", primary: false }).collect::<Vec<_>>();
        let executable = workspace.path().join("gaoge-free.exe");
        let first = migrate_existing_gaoge_image_integrations(&targets, &executable);
        assert_eq!(first["targets"].as_array().unwrap().len(), 3);
        let updated = fs::read_to_string(integrated.join("config.toml")).unwrap();
        assert!(updated.contains("gaoge-free.exe"));
        assert!(!updated.contains("old-directory/"));
        assert!(updated.contains("tool_timeout_sec = 900"));
        assert!(updated.contains("custom_setting = \"keep\""));
        assert!(updated.contains("[mcp_servers.other]"));
        assert!(integrated.join("skills/gaoge-image/SKILL.md").exists());
        for dir in [&untouched, &disabled] { assert!(!dir.join("skills").exists()); }
        assert!(custom.join("skills/gaoge-image/SKILL.md").exists());
        assert!(wrapper.join("skills/gaoge-image/SKILL.md").exists());
        assert_eq!(fs::read_to_string(disabled.join("config.toml")).unwrap(), disabled_config);
        assert_eq!(fs::read_to_string(custom.join("config.toml")).unwrap(), custom_config);
        assert_eq!(first["targets"][1]["status"], "preserved_custom");
        assert_eq!(first["targets"][2]["status"], "preserved_custom");
        assert_eq!(fs::read_to_string(wrapper.join("config.toml")).unwrap(), wrapper_config);
        let second = migrate_existing_gaoge_image_integrations(&targets, &executable);
        assert_eq!(second["targets"][0]["configUpdated"], false);
        assert_eq!(second["targets"][0]["imageSkill"]["status"], "current");
    }

