    #[test]
    fn gaoge_image_upstream_errors_never_expose_raw_response_bodies() {
        let raw_html =
            "<!DOCTYPE html><html><head><title>524: A timeout occurred</title></head></html>";
        let public_error = local_image_unexpected_response_text(raw_html);
        assert_eq!(public_error, IMAGE_GENERATION_BUSY_MESSAGE);

        let result = gaoge_image_mcp_tool_error(public_error);
        assert_eq!(result["content"][0]["text"], IMAGE_GENERATION_BUSY_MESSAGE);
        let serialized = serde_json::to_string(&result).unwrap();
        assert!(!serialized.contains("DOCTYPE"));
        assert!(!serialized.contains("524"));

        let defensive_result = gaoge_image_mcp_tool_error(raw_html);
        assert_eq!(
            defensive_result["content"][0]["text"],
            IMAGE_GENERATION_BUSY_MESSAGE
        );
    }

    #[test]
    fn local_image_http_error_returns_busy_message_without_html() {
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let address = listener.local_addr().unwrap();
        let raw_html =
            "<!DOCTYPE html><html><head><title>524: A timeout occurred</title></head></html>";
        let response_body = raw_html.as_bytes().to_vec();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut request = [0u8; 1024];
            let _ = stream.read(&mut request);
            let response = format!(
                "HTTP/1.1 524 A Timeout Occurred\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                response_body.len()
            );
            stream.write_all(response.as_bytes()).unwrap();
            stream.write_all(&response_body).unwrap();
            stream.flush().unwrap();
        });

        let client = reqwest::Client::new();
        let response = tauri::async_runtime::block_on(
            client
                .get(format!("http://{address}/images/generations"))
                .send(),
        )
        .unwrap();
        let output_dir = std::env::temp_dir().join(format!(
            "gaoge-image-upstream-error-test-{}",
            timestamp_for_path()
        ));
        fs::create_dir_all(&output_dir).unwrap();
        let error = tauri::async_runtime::block_on(parse_and_save_local_image_response(
            &client,
            &format!("http://{address}"),
            response,
            &output_dir,
            1,
            0,
            "png",
            &ImageTimings::new(),
        ))
        .unwrap_err();
        server.join().unwrap();

        assert_eq!(error, IMAGE_GENERATION_BUSY_MESSAGE);
        assert!(!error.contains("DOCTYPE"));
        assert!(!error.contains("524"));
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn gaoge_image_mcp_result_keeps_image_bytes_out_of_tool_context() {
        let path = std::env::temp_dir().join(format!(
            "gaoge-image-mcp-resource-test-{}.png",
            timestamp_for_path()
        ));
        let bytes = vec![137, 80, 78, 71, 13, 10, 26, 10, 1, 2, 3, 4];
        fs::write(&path, &bytes).unwrap();

        let result = gaoge_image_mcp_tool_success(
            GAOGE_IMAGE_MODEL_2,
            json!({
              "outputDir": path.parent().unwrap().to_string_lossy(),
              "count": 1,
              "failedCount": 0,
              "failedImages": [],
              "images": [{
                "path": path.to_string_lossy(),
                "fileName": "generated.png",
                "mimeType": "image/png",
                "bytes": bytes.len(),
                "previewDataUrl": "data:image/png;base64,AQIDBAUG",
              }]
            }),
        );
        let serialized = serde_json::to_string(&result).unwrap();

        assert!(!serialized.contains("previewDataUrl"));
        assert!(!serialized.contains("AQIDBAUG"));
        assert!(result["structuredContent"]["imageContext"]["deliveryHint"].as_str().unwrap().contains("普通交付无需看图"));
        assert!(result["content"][0]["text"].as_str().unwrap().contains("普通生图无需调用查看工具"));
        assert!(!result["content"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["type"] == "image"));
        assert_eq!(result["content"][1]["type"], "resource_link");
        assert!(result["_meta"][GAOGE_IMAGE_MCP_RESULT_META_KEY]["images"].is_array());

        let resource_uri = result["structuredContent"]["images"][0]["resourceUri"]
            .as_str()
            .unwrap();
        assert_eq!(
            result["structuredContent"]["imageContext"]["latestResourceUri"],
            resource_uri
        );
        assert!(result["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains(GAOGE_IMAGE_VIEW_TOOL));
        assert!(resource_uri.starts_with(GAOGE_IMAGE_MCP_IMAGE_RESOURCE_PREFIX));
        let resource = gaoge_image_mcp_read_resource(resource_uri).unwrap();
        assert_eq!(
            resource["contents"][0]["blob"],
            general_purpose::STANDARD.encode(&bytes)
        );
        assert_eq!(resource["contents"][0]["mimeType"], "image/png");

        let _ = fs::remove_file(&path);
        GAOGE_IMAGE_MCP_IMAGE_RESOURCES
            .lock()
            .unwrap()
            .resources
            .remove(resource_uri);
    }

    #[test]
    fn gaoge_image_mcp_view_tool_returns_image_content_without_structured_override() {
        let path = std::env::temp_dir().join(format!(
            "gaoge-image-mcp-view-test-{}.png",
            timestamp_for_path()
        ));
        let bytes = general_purpose::STANDARD
            .decode("iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAGklEQVR4nGMIWHDnPyWYYdSAUQNGDRguBgAAjJXLH15wN5kAAAAASUVORK5CYII=")
            .unwrap();
        fs::write(&path, &bytes).unwrap();
        let resource_uri =
            gaoge_image_mcp_register_image_resource(path.to_str().unwrap(), "image/png").unwrap();

        let viewed = gaoge_image_mcp_view_image(&json!({
          "resource_uri": resource_uri,
          "question": "检查主体和背景"
        }));
        assert_eq!(viewed["isError"], false);
        assert!(viewed.get("structuredContent").is_none());
        assert_eq!(viewed["_meta"]["resourceUri"], resource_uri);
        assert_eq!(viewed["_meta"]["registeredFromPath"], false);
        assert!(viewed["_meta"].get("imageProvidedToModel").is_none());
        assert!(!viewed["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("已作为视觉输入提供给模型"));
        assert_eq!(viewed["content"][0]["type"], "text");
        assert!(viewed["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("检查主体和背景"));
        assert_eq!(viewed["content"][1]["type"], "image");
        assert_eq!(
            viewed["content"][1]["data"],
            general_purpose::STANDARD.encode(&bytes)
        );
        assert_eq!(viewed["content"][1]["mimeType"], "image/png");

        let invalid = gaoge_image_mcp_view_image(&json!({
          "resource_uri": "ui://other-app/image"
        }));
        assert_eq!(invalid["isError"], true);
        assert!(invalid["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("不是 Gaoge 生图资源"));

        let _ = fs::remove_file(&path);
        GAOGE_IMAGE_MCP_IMAGE_RESOURCES
            .lock()
            .unwrap()
            .resources
            .remove(&resource_uri);
    }

    #[test]
    fn gaoge_image_mcp_view_tool_accepts_official_image_view_file_uri() {
        let root = std::env::temp_dir().join(format!(
            "gaoge-image-mcp-official-history-test-{}",
            timestamp_for_path()
        ));
        let path = root
            .join("剑与她")
            .join("generated_images")
            .join("official-history.png");
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        let bytes = general_purpose::STANDARD
            .decode("iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAGklEQVR4nGMIWHDnPyWYYdSAUQNGDRguBgAAjJXLH15wN5kAAAAASUVORK5CYII=")
            .unwrap();
        fs::write(&path, &bytes).unwrap();
        let file_uri = url::Url::from_file_path(&path).unwrap().to_string();

        let viewed = gaoge_image_mcp_view_image(&json!({
          "image_path": file_uri,
          "question": "继续处理官方历史图片"
        }));
        assert_eq!(viewed["isError"], false);
        assert!(viewed.get("structuredContent").is_none());
        assert_eq!(viewed["_meta"]["registeredFromPath"], true);
        assert!(viewed["_meta"].get("imageProvidedToModel").is_none());
        let resource_uri = viewed["_meta"]["resourceUri"]
            .as_str()
            .unwrap()
            .to_string();
        assert!(resource_uri.starts_with(GAOGE_IMAGE_MCP_IMAGE_RESOURCE_PREFIX));
        let selected = gaoge_image_mcp_view_image(&json!({
          "resource_uri": resource_uri,
          "image_path": file_uri,
        }));
        assert_eq!(selected["isError"], false);
        assert_eq!(selected["_meta"]["registeredFromPath"], false);
        assert!(selected.get("structuredContent").is_none());
        let fallback = gaoge_image_mcp_view_image(&json!({
          "resource_uri": "ui://gaoge-image/generated/missing-resource",
          "image_path": file_uri,
        }));
        assert_eq!(fallback["isError"], false);
        assert_eq!(fallback["_meta"]["registeredFromPath"], true);
        assert_eq!(fallback["content"][1]["data"], general_purpose::STANDARD.encode(&bytes));
        assert_eq!(
            viewed["content"][1]["data"],
            general_purpose::STANDARD.encode(&bytes)
        );
        assert!(gaoge_image_mcp_resource_index_path().exists());
        let persisted = gaoge_image_mcp_load_resource_index(&gaoge_image_mcp_resource_index_path());
        assert_eq!(
            persisted.get(&resource_uri).unwrap().path,
            gaoge_image_mcp_normalize_canonical_path(fs::canonicalize(&path).unwrap())
        );

        let _ = fs::remove_dir_all(&root);
        GAOGE_IMAGE_MCP_IMAGE_RESOURCES
            .lock()
            .unwrap()
            .resources
            .remove(&resource_uri);
    }

