    #[test]
    fn gaoge_image_mcp_validates_arguments_and_pins_requested_model() {
        let cwd = std::env::temp_dir().join("gaoge-image-mcp-request");
        let credentials = CodexImageToolCredentials {
            api_key: "image-secret".to_string(),
            base_url: "https://relay.example.invalid/v1".to_string(),
        };
        let request = gaoge_image_mcp_generation_request(
            GAOGE_IMAGE_TOOL_2_5_FLARE,
            &json!({
              "prompt": "女孩在操场跑步",
              "size": "1536x1024",
              "quality": "high",
              "image_count": 2,
            }),
            &credentials,
            &cwd,
        )
        .unwrap();

        assert_eq!(request["model"], "gpt-image-2.5-flare");
        assert_eq!(request["apiKey"], "image-secret");
        assert_eq!(request["mode"], "text");
        assert_eq!(request["imageCount"], 2);
        assert_eq!(
            request["outputDir"].as_str(),
            Some(
                lexical_normalize_path(&cwd.join("generated_images"))
                    .to_string_lossy()
                    .as_ref()
            )
        );
        for (tool, expected_model) in [
            (GAOGE_IMAGE_TOOL_2, "gpt-image-2"),
            (GAOGE_IMAGE_TOOL_2_5_FLARE, "gpt-image-2.5-flare"),
            (GAOGE_IMAGE_TOOL_2_5_SUNBURST, "gpt-image-2.5-sunburst"),
            (GAOGE_IMAGE_TOOL_2_6_FLARE, "gpt-image-2.6-flare"),
            (GAOGE_IMAGE_TOOL_2_6_SUNBURST, "gpt-image-2.6-sunburst"),
        ] {
            let request = gaoge_image_mcp_generation_request(
                tool,
                &json!({ "prompt": "女孩在操场跑步" }),
                &credentials,
                &cwd,
            )
            .unwrap();
            assert_eq!(request["model"], expected_model);
        }

        let missing_prompt =
            gaoge_image_mcp_generation_request(GAOGE_IMAGE_TOOL_2, &json!({}), &credentials, &cwd)
                .unwrap_err();
        assert!(missing_prompt.contains("prompt"));

        let invalid_count = gaoge_image_mcp_generation_request(
            GAOGE_IMAGE_TOOL_2,
            &json!({ "prompt": "test", "image_count": 5 }),
            &credentials,
            &cwd,
        )
        .unwrap_err();
        assert!(invalid_count.contains("image_count"));
    }

