    #[test]
    fn gaoge_image_mcp_config_is_idempotent_and_preserves_other_servers() {
        let executable = Path::new(r"C:\Program Files\Gaoge Free\gaoge-free.exe");
        let existing = r#"
model = "gpt-5.5"

[mcp_servers.keep_me]
command = "keep-me"
args = ["--safe"]

[features]
fast_mode = true
"#;

        let first = upsert_gaoge_image_mcp_config(existing, executable);
        let second = upsert_gaoge_image_mcp_config(&first, executable);

        assert_eq!(first, second);
        assert_eq!(
            second
                .matches(&format!("[mcp_servers.{GAOGE_IMAGE_MCP_SERVER_ID}]"))
                .count(),
            1
        );
        assert!(second.contains("[mcp_servers.keep_me]"));
        assert!(second.contains("command = \"keep-me\""));
        assert!(second.contains("[features]"));
        assert!(second.contains("fast_mode = true"));
        assert!(second.contains(GAOGE_IMAGE_MCP_ARG));
        assert!(second.contains("tool_timeout_sec = 240"));
        assert!(!second.contains("image-secret"));
        assert!(gaoge_image_mcp_config_verified(&second, executable));

        let removed = remove_gaoge_image_mcp_config(&second);
        assert!(!removed.contains(GAOGE_IMAGE_MCP_SERVER_ID));
        assert!(removed.contains("[mcp_servers.keep_me]"));
    }

