    #[test]
    fn codex_capabilities_aggregate_preserves_explicit_native_limits_and_restrictions() {
        let fixture: Value = serde_json::from_str(include_str!(
            "../../scripts/fixtures/codex-models-26.901.json"
        ))
        .unwrap();
        let mut native = fixture["models"][0].clone();
        native["context_window"] = json!(120_000);
        native["max_context_window"] = json!(640_000);
        native["effective_context_window_percent"] = json!(92);
        native["auto_compact_token_limit"] = json!(100_000);
        native["input_modalities"] = json!(["text"]);
        native["supports_image_detail_original"] = json!(false);
        let metadata = HashMap::from([("gpt-6-astra".to_string(), native.clone())]);
        let entry =
            aggregate_model_entry(&aggregate_test_route("openai", "gpt-6-astra"), 0, &metadata);
        for field in [
            "context_window",
            "max_context_window",
            "effective_context_window_percent",
            "auto_compact_token_limit",
            "input_modalities",
            "supports_image_detail_original",
            "model_messages",
        ] {
            assert_eq!(
                entry[field], native[field],
                "{field} must survive route renaming"
            );
        }
        assert_eq!(entry["slug"], "gaoge/openai/1/gpt-6-astra");
        let mut incomplete = native.clone();
        incomplete.as_object_mut().unwrap().remove("model_messages");
        assert!(sanitize_codex_model_metadata(incomplete, "gpt-6-astra").is_none());
        let mut missing_image = native;
        missing_image
            .as_object_mut()
            .unwrap()
            .remove("input_modalities");
        let repaired = sanitize_codex_model_metadata(missing_image, "gpt-6-astra").unwrap();
        assert_eq!(repaired["input_modalities"], json!(["text", "image"]));
        assert_eq!(repaired["supports_image_detail_original"], false);
    }

    #[test]
    fn codex_capabilities_picker_and_native_catalog_agree_across_models() {
        let fixture: Value = serde_json::from_str(include_str!(
            "../../scripts/fixtures/codex-models-26.901.json"
        ))
        .unwrap();
        let metadata = HashMap::from([("gpt-6-astra".to_string(), fixture["models"][0].clone())]);
        let routes = vec![
            aggregate_test_route("openai", "gpt-6-astra"),
            aggregate_test_route("openai", "gpt-5.3-codex-spark"),
            aggregate_test_route("kimi", "k3"),
            aggregate_test_route("glm", "glm-5.2"),
            aggregate_test_route("deepseek", "deepseek-v4-flash-vision-exp"),
        ];
        let state = AggregateLoginState {
            enabled: true,
            default_model: routes[0].public_model.clone(),
            default_model_origin: CODEX_MODEL_SELECTION_ORIGIN_USER.to_string(),
            routes,
            router_port: 0,
            router_token: String::new(),
            speed_mode: "standard".to_string(),
            official_account_key: String::new(),
            recovery_models: Vec::new(),
            updated_at: 0,
        };
        let picker = aggregate_model_picker_catalog_for_state(&state, &metadata);
        let ui_models: Vec<&Value> = picker["providers"]
            .as_array()
            .unwrap()
            .iter()
            .flat_map(|p| p["groups"].as_array().unwrap())
            .flat_map(|g| g["models"].as_array().unwrap())
            .collect();
        for route in &state.routes {
            let native = aggregate_model_entry(route, 0, &metadata);
            let ui = ui_models
                .iter()
                .find(|m| m["publicModel"] == route.public_model)
                .unwrap();
            assert_eq!(ui["contextWindow"], native["context_window"]);
            assert_eq!(ui["maxContextWindow"], native["max_context_window"]);
            assert_eq!(ui["inputModalities"], native["input_modalities"]);
            assert_eq!(
                ui["supportsImageDetailOriginal"],
                native["supports_image_detail_original"]
            );
        }
        assert_eq!(ui_models[0]["contextSource"], "codex");
        assert_eq!(ui_models[0]["maxContextLabel"], "872K");
        assert_eq!(ui_models[2]["contextWindow"], 1_048_576);
    }

    #[test]
    fn codex_capabilities_native_cache_fixture_and_optional_installed_cache() {
        let path = std::env::var_os("CODEX_NATIVE_MODELS_FIXTURE");
        let text = path
            .map(|path| fs::read_to_string(path).unwrap())
            .unwrap_or_else(|| {
                include_str!("../../scripts/fixtures/codex-models-26.901.json").to_string()
            });
        let source: Value = serde_json::from_str(&text).unwrap();
        let mut metadata = HashMap::new();
        for entry in source["models"].as_array().unwrap() {
            let slug = entry["slug"].as_str().unwrap();
            let accepted = sanitize_codex_model_metadata(entry.clone(), slug)
                .unwrap_or_else(|| panic!("current model metadata was discarded: {slug}"));
            metadata.insert(slug.to_string(), accepted);
        }
        assert!(metadata.contains_key("gpt-6-astra"));
        let mut models = Vec::new();
        for entry in source["models"].as_array().unwrap() {
            let model = entry["slug"].as_str().unwrap();
            let route = aggregate_test_route("openai", model);
            let mapped = aggregate_model_entry(&route, 0, &metadata);
            for field in [
                "context_window",
                "max_context_window",
                "input_modalities",
                "model_messages",
                "supported_reasoning_levels",
            ] {
                assert_eq!(mapped[field], entry[field], "{model}: {field}");
            }
            models.push(mapped);
        }
        // A second consumer can use this output to verify the installed Codex
        // app-server parser. It contains model metadata only, never account data.
        if let Some(output) = std::env::var_os("CODEX_COMPAT_CATALOG_OUTPUT") {
            for (provider, model) in [
                ("kimi", "k3"),
                ("glm", "glm-5.2"),
                ("deepseek", "deepseek-v4-flash-vision-exp"),
            ] {
                models.push(aggregate_model_entry(
                    &aggregate_test_route(provider, model),
                    0,
                    &metadata,
                ));
            }
            write_json_pretty(Path::new(&output), &json!({"models": models})).unwrap();
        }
    }

