            let route = aggregate_test_route("openai", "gpt-6-sol");
            let unknown = aggregate_test_route("custom", "unknown-fixture-model");
            write_json_pretty(&dir.join("models_cache.json"), &json!({"models": [
                {"slug":"gpt-6-sol", "context_window": 48_000,
                 "input_modalities":["text"], "service_tiers":[],
                 "supported_reasoning_levels":[]},
                {"slug":unknown.public_model,"context_window":262_144}
            ]})).unwrap();
            let targets = vec![CodexDirTarget { dir, source: "test", primary: true }];
            let native = aggregate_local_model_metadata(&targets);
            assert!(native.contains_key("gpt-6-sol"));
            assert!(!native.contains_key(&unknown.public_model));
            let entry = aggregate_model_entry(&route, 0, &native);
            assert_eq!(entry["context_window"], 48_000);
            assert_eq!(entry["input_modalities"], json!(["text"]));
            assert_eq!(entry["supported_reasoning_levels"], json!([]));
