    #[test]
    fn aggregate_final_catalog_preserves_resolved_capabilities_without_resanitizing() {
        with_temp_user_home("aggregate-final-catalog", |root| {
            let unknown = aggregate_test_route("custom", "unknown-fixture-model");
            let restricted = aggregate_test_route("openai", "gpt-6-sol");
            let mut configured = aggregate_test_route("custom", "configured-fixture-model");
            configured.model_config = json!({
                "contextWindow": 98_304, "autoCompactPercent": 75, "fast": "supported"
            });
            let mut disabled = aggregate_test_route("openai", "gpt-6-astra");
            disabled.model_config = json!({"fast": "unsupported"});
            let mut native = codex_native_responses_model_entry("gpt-6-sol", 0);
            native["context_window"] = json!(160_000);
            native["model_messages"] = json!({"instructions_template": "Preserve native instructions."});
            native["service_tiers"] = json!([]);
            native["input_modalities"] = json!(["text"]);
            for key in ["additional_speed_tiers", "max_context_window", "auto_compact_token_limit", "supports_image_detail_original"] {
                native.as_object_mut().unwrap().remove(key);
            }
            let native_metadata = HashMap::from([("gpt-6-sol".to_owned(), native.clone())]);
            let routes = [unknown, restricted, configured, disabled];
            let models = routes.iter().map(|route| route.public_model.clone()).collect::<Vec<_>>();
            let entries = routes.iter().enumerate().map(|(index, route)| {
                aggregate_model_entry(route, index, &native_metadata)
            }).collect::<Vec<_>>();
            let metadata = models.iter().cloned().zip(entries.iter().cloned()).collect();
            let catalog = build_codex_native_responses_catalog_with_metadata(&models, &metadata).unwrap();
            assert_eq!(catalog["models"], json!(entries));
            assert!(catalog["models"][0]["context_window"].is_null());
            assert!(catalog["models"][0]["max_context_window"].is_null());
            assert!(catalog["models"][0]["auto_compact_token_limit"].is_null());
            assert!(!aggregate_entry_supports_fast(&catalog["models"][0]));
            assert_eq!(catalog["models"][1]["context_window"], 160_000);
            assert_eq!(catalog["models"][1]["model_messages"], native["model_messages"]);
            assert_eq!(catalog["models"][1]["input_modalities"], json!(["text"]));
            assert!(!aggregate_entry_supports_fast(&catalog["models"][1]));
            assert_eq!(catalog["models"][2]["context_window"], 98_304);
            assert_eq!(catalog["models"][2]["auto_compact_token_limit"], 73_728);
            assert!(aggregate_entry_supports_fast(&catalog["models"][2]));
            assert!(!aggregate_entry_supports_fast(&catalog["models"][3]));
            let written = write_codex_model_catalog_value(&root.join(".codex"), &catalog, &models).unwrap();
            assert_eq!(read_json_if_exists(&written.path).unwrap().unwrap(), catalog);
            assert!(build_codex_native_responses_catalog(&models).is_err(), "unresolved aggregate models must not silently use generic capabilities");
        });
    }

    #[test]
    fn aggregate_speed_native_task_tiers_never_fall_back_to_saved_choice() {
        let route = aggregate_test_route("openai", "gpt-6-astra");
        for tier in ["fast", "priority"] {
            let mut payload = json!({"model": route.public_model, "service_tier": tier});
            let routing = prepare_aggregate_speed_request(&route, &mut payload);
            assert_eq!(payload["service_tier"], "priority");
            assert_eq!(routing.upstream_model, "gpt-6-astra");
        }
        // Standard is represented by null/default and may be omitted by the
        // native transport. None of these values requests acceleration.
        for (provider, model) in [
            ("openai", "gpt-6-astra"),
            ("anthropic", "claude-opus-4-8"),
            ("kimi", "kimi-k2.7-code"),
        ] {
            let route = aggregate_test_route(provider, model);
            for tier in [None, Some(Value::Null), Some(json!("default")), Some(json!("auto")),
                Some(json!("standard")), Some(json!(false)), Some(json!(1)), Some(json!({}))] {
                let mut payload = json!({});
                if let Some(tier) = tier {
                    payload["service_tier"] = tier;
                }
                let routing = prepare_aggregate_speed_request(&route, &mut payload);
                assert!(payload.get("service_tier").is_none());
                assert_eq!(routing.upstream_model, model);
                assert!(!routing.anthropic_fast_beta);
            }
        }
    }

