    #[test]
    fn aggregate_claude_payload_removes_server_search_and_preserves_vision_and_client_tools() {
        let input = json!([{
          "type": "message",
          "role": "user",
          "content": [
            { "type": "input_image", "image_url": "data:image/png;base64,aGVsbG8=" },
            { "type": "input_text", "text": "describe this image" }
          ]
        }, {
          "type": "function_call",
          "call_id": "call_read",
          "name": "read_file",
          "arguments": "{\"path\":\"README.md\"}"
        }, {
          "type": "function_call_output",
          "call_id": "call_read",
          "output": "project readme"
        }]);
        let mut payload = json!({
          "model": "claude-sonnet-4-6",
          "input": input.clone(),
          "tools": [
            { "type": "web_search" },
            { "type": "web_search_preview" },
            { "type": "function", "name": "read_file", "parameters": { "type": "object" } },
            { "type": "custom", "name": "apply_patch", "format": { "type": "grammar" } },
            { "type": "tool_search" },
            { "type": "namespace", "name": "mcp", "tools": [] }
          ],
          "tool_choice": { "type": "web_search" },
          "web_search_options": { "search_context_size": "low" },
          "include": ["reasoning.encrypted_content", "web_search_call.action.sources"]
        });

        let removed = sanitize_aggregate_claude_response_payload(&mut payload);

        assert_eq!(removed, 2);
        assert_eq!(payload["input"], input);
        assert_eq!(payload["tool_choice"], json!("auto"));
        assert!(payload.get("web_search_options").is_none());
        assert_eq!(payload["include"], json!(["reasoning.encrypted_content"]));
        let tool_types = payload["tools"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|tool| tool.get("type").and_then(Value::as_str))
            .collect::<Vec<_>>();
        assert_eq!(
            tool_types,
            vec!["function", "custom", "tool_search", "namespace"]
        );
    }

