    #[test]
    fn aggregate_claude_payload_enforces_safe_output_floor_and_renames_legacy_field() {
        let mut payload = json!({
          "model": "claude-sonnet-4-6",
          "input": "hello",
          "max_tokens": 1024
        });

        let route = AggregateProviderRoute {
            source: Default::default(),
            protocol: Default::default(),
            model_config: Value::Null,
            provider_id: "anthropic".to_string(),
            provider_name: "Anthropic / Claude".to_string(),
            upstream_platform: "anthropic".to_string(),
            group_id: "31".to_string(),
            group_name: "Claude-Max".to_string(),
            group_rate_text: "3.5x 倍率".to_string(),
            public_model: "gaoge/anthropic/31/claude-sonnet-4-6".to_string(),
            upstream_model: "claude-sonnet-4-6".to_string(),
            base_url: "https://relay.example.invalid".to_string(),
            api_key: "secret".to_string(),
        };

        let state = AggregateLoginState {
            enabled: true,
            router_port: 0,
            router_token: String::new(),
            default_model: route.public_model.clone(),
            default_model_origin: CODEX_MODEL_SELECTION_ORIGIN_USER.to_string(),
            speed_mode: "standard".to_string(),
            official_account_key: String::new(),
            routes: vec![route.clone()],
            recovery_models: Vec::new(),
            updated_at: 0,
        };
        // enforce_claude_max_output_tokens should: remove max_tokens, set max_output_tokens to
        // max(requested, model_floor). sonnet-4-6 floor is 131_072. payload has max_tokens:1024
        // so safe value = max(1024, 131_072) = 131_072.
        let object = payload.as_object_mut().unwrap();
        let returned = enforce_claude_max_output_tokens(object, &route.upstream_model);

        assert!(
            object.get("max_tokens").is_none(),
            "max_tokens must be removed"
        );
        assert_eq!(returned, 131_072, "floor for sonnet-4-6 is 131_072");
        assert_eq!(
            object.get("max_output_tokens").and_then(Value::as_u64),
            Some(131_072),
            "max_output_tokens must equal the safe floor"
        );

        // also verify that a value ABOVE the floor is preserved
        let mut payload2 = json!({ "max_output_tokens": 200_000_u64 });
        let obj2 = payload2.as_object_mut().unwrap();
        let returned2 = enforce_claude_max_output_tokens(obj2, &route.upstream_model);
        assert_eq!(returned2, 200_000, "value above floor must be kept");

        let _ = state.enabled; // suppress unused warning
    }

    #[test]
    fn aggregate_grok_payload_removes_only_nonportable_reasoning_history() {
        let original = json!({
          "model": "grok-4.5",
          "input": [
            {
              "type": "message",
              "role": "developer",
              "content": [{ "type": "input_text", "text": "instructions" }]
            },
            {
              "type": "message",
              "role": "user",
              "content": [
                { "type": "input_image", "image_url": "data:image/png;base64,aGVsbG8=" },
                { "type": "input_text", "text": "first question" }
              ]
            },
            {
              "type": "reasoning",
              "id": "rs_previous_turn",
              "encrypted_content": "provider-private-state",
              "summary": [{ "type": "summary_text", "text": "private summary" }]
            },
            {
              "type": "message",
              "role": "assistant",
              "content": [{ "type": "output_text", "text": "first answer" }]
            },
            {
              "type": "function_call",
              "call_id": "call_read",
              "name": "read_file",
              "arguments": "{\"path\":\"README.md\"}"
            },
            {
              "type": "function_call_output",
              "call_id": "call_read",
              "output": "project readme"
            },
            {
              "type": "message",
              "role": "user",
              "content": [{ "type": "input_text", "text": "second question" }]
            }
          ],
          "include": ["reasoning.encrypted_content", "file_search_call.results"],
          "reasoning": { "effort": "xhigh", "summary": "detailed" },
          "tools": [{ "type": "function", "name": "read_file" }],
          "stream": true,
          "store": false
        });
        let mut payload = original.clone();

        assert_eq!(
            sanitize_aggregate_response_payload("grok", "openai", &mut payload),
            2
        );

        let input = payload["input"].as_array().unwrap();
        assert_eq!(input.len(), 6);
        assert!(!input.iter().any(|item| {
            item.get("type")
                .and_then(Value::as_str)
                .is_some_and(|item_type| item_type == "reasoning")
        }));
        assert!(input
            .iter()
            .any(|item| { item.get("role").and_then(Value::as_str) == Some("assistant") }));
        assert!(input
            .iter()
            .any(|item| { item.get("type").and_then(Value::as_str) == Some("function_call") }));
        assert!(input.iter().any(|item| {
            item.get("type").and_then(Value::as_str) == Some("function_call_output")
        }));
        assert!(input.iter().any(|item| {
            item.get("content")
                .and_then(Value::as_array)
                .is_some_and(|content| {
                    content
                        .iter()
                        .any(|part| part.get("type").and_then(Value::as_str) == Some("input_image"))
                })
        }));
        assert_eq!(payload["include"], json!(["file_search_call.results"]));
        assert_eq!(payload["reasoning"], original["reasoning"]);
        assert_eq!(payload["tools"], original["tools"]);
        assert_eq!(original["input"].as_array().unwrap().len(), 7);
        assert_eq!(
            original["include"],
            json!(["reasoning.encrypted_content", "file_search_call.results"])
        );
    }

    #[test]
    fn aggregate_glm_payload_caps_unsupported_effort_and_preserves_codex_request_fields() {
        let original = json!({
          "model": "glm-5.2",
          "instructions": "Keep using the Codex tools.",
          "input": [
            { "type": "message", "role": "user", "content": [{ "type": "input_text", "text": "continue" }] },
            { "type": "function_call_output", "call_id": "call_read", "output": "result" }
          ],
          "tools": [
            { "type": "function", "name": "read_file", "parameters": { "type": "object" } },
            { "type": "namespace", "name": "codex_app", "tools": [] },
            { "type": "web_search" }
          ],
          "reasoning": { "effort": "xhigh", "summary": "detailed" },
          "stream": true,
          "store": false,
          "client_metadata": { "originator": "codex" }
        });

        for effort in ["xhigh", "XHIGH", "low", "medium"] {
            let mut payload = original.clone();
            payload["reasoning"]["effort"] = Value::String(effort.to_string());
            assert_eq!(
                sanitize_aggregate_response_payload("glm", "openai", &mut payload),
                1
            );
            assert_eq!(payload["reasoning"]["effort"], json!("high"));
            assert_eq!(payload["reasoning"]["summary"], json!("detailed"));
            assert_eq!(payload["input"], original["input"]);
            assert_eq!(payload["tools"], original["tools"]);
            assert_eq!(payload["client_metadata"], original["client_metadata"]);
        }

        for effort in ["high", "max"] {
            let mut payload = original.clone();
            payload["reasoning"]["effort"] = Value::String(effort.to_string());
            let expected = payload.clone();
            assert_eq!(
                sanitize_aggregate_response_payload("glm", "openai", &mut payload),
                0
            );
            assert_eq!(payload, expected);
        }

        let mut openai_payload = original.clone();
        assert_eq!(
            sanitize_aggregate_response_payload("openai", "openai", &mut openai_payload),
            0
        );
        assert_eq!(openai_payload, original);
    }

