    #[test]
    fn aggregate_openai_payload_normalizes_claude_history_without_breaking_tool_links() {
        let mut payload = json!({
          "model": "gpt-5.6-sol",
          "input": [
            {
              "type": "message",
              "role": "assistant",
              "id": "item_032bff3f2465ff0ac13b529b",
              "content": [{ "type": "output_text", "text": "checking" }]
            },
            {
              "type": "function_call",
              "id": "item_e83a121bb2e3bf007f5e68e8",
              "call_id": "toolu_018mG3jYnUdJq6UYKicFaQUP",
              "name": "shell_command",
              "arguments": "{\"command\":\"cargo check\"}"
            },
            {
              "type": "function_call_output",
              "id": "fco_019ff41021c57d21b0268d3a",
              "call_id": "toolu_018mG3jYnUdJq6UYKicFaQUP",
              "output": "Finished"
            },
            {
              "type": "reasoning",
              "id": "item_9cff5b119661c55a72cb0626",
              "summary": [{ "type": "summary_text", "text": "Claude private reasoning" }],
              "encrypted_content": null
            },
            {
              "type": "reasoning",
              "id": "rs_native_openai_reasoning",
              "encrypted_content": "openai-state"
            },
            {
              "type": "function_call",
              "id": "fc_native_openai_call",
              "call_id": "call_native",
              "name": "read_file",
              "arguments": "{}"
            }
          ],
          "include": ["reasoning.encrypted_content"]
        });

        assert_eq!(
            sanitize_aggregate_response_payload("openai", "openai", &mut payload),
            3
        );

        let input = payload["input"].as_array().unwrap();
        assert_eq!(input.len(), 5);
        assert!(input.iter().any(|item| {
            item.get("id").and_then(Value::as_str) == Some("msg_032bff3f2465ff0ac13b529b")
        }));
        let repaired_call = input
            .iter()
            .find(|item| {
                item.get("call_id").and_then(Value::as_str)
                    == Some("toolu_018mG3jYnUdJq6UYKicFaQUP")
                    && item.get("type").and_then(Value::as_str) == Some("function_call")
            })
            .unwrap();
        assert_eq!(
            repaired_call.get("id").and_then(Value::as_str),
            Some("fc_e83a121bb2e3bf007f5e68e8")
        );
        assert_eq!(
            repaired_call.get("call_id").and_then(Value::as_str),
            Some("toolu_018mG3jYnUdJq6UYKicFaQUP")
        );
        assert!(input.iter().any(|item| {
            item.get("type").and_then(Value::as_str) == Some("function_call_output")
                && item.get("call_id").and_then(Value::as_str)
                    == Some("toolu_018mG3jYnUdJq6UYKicFaQUP")
        }));
        assert!(!input.iter().any(|item| {
            item.get("id").and_then(Value::as_str) == Some("item_9cff5b119661c55a72cb0626")
        }));
        assert!(input.iter().any(|item| {
            item.get("id").and_then(Value::as_str) == Some("rs_native_openai_reasoning")
        }));
        assert!(input.iter().any(|item| {
            item.get("id").and_then(Value::as_str) == Some("fc_native_openai_call")
        }));
        assert_eq!(payload["include"], json!(["reasoning.encrypted_content"]));
    }

