    #[test]
    fn aggregate_compaction_detection_and_sanitizer_keep_history_but_disable_tools() {
        let headers = HashMap::from([(
            "x-codex-turn-metadata".to_string(),
            r#"{"request_kind":"compaction","compaction":{"reason":"auto"}}"#.to_string(),
        )]);
        let mut payload = json!({
          "instructions": "Summarize the conversation.",
          "input": [
            { "role": "user", "content": [{ "type": "input_text", "text": "old request" }] },
            { "role": "assistant", "content": [{ "type": "output_text", "text": "old answer" }] }
          ],
          "tools": [{ "type": "function", "name": "exec" }],
          "tool_choice": "auto",
          "parallel_tool_calls": true,
          "reasoning": { "effort": "xhigh" },
          "include": ["reasoning.encrypted_content"],
          "service_tier": "priority"
        });
        assert!(aggregate_request_is_compaction(&headers, &payload));
        let original_input = payload["input"].clone();
        let changed = sanitize_aggregate_response_payload_for_request(
            "anthropic",
            "anthropic",
            &mut payload,
            true,
        );
        assert!(changed >= 6);
        assert_eq!(payload["input"], original_input);
        for removed in [
            "tools",
            "tool_choice",
            "parallel_tool_calls",
            "reasoning",
            "include",
            "service_tier",
        ] {
            assert!(payload.get(removed).is_none(), "{removed} must be removed");
        }
        let instructions = payload["instructions"].as_str().unwrap();
        assert!(instructions.contains("Summarize the conversation"));
        assert!(instructions.contains("never return a placeholder or an empty response"));

        let payload_metadata = json!({
          "client_metadata": {
            "x-codex-turn-metadata": "{\"request_kind\":\"compaction\"}"
          }
        });
        assert!(aggregate_request_is_compaction(
            &HashMap::new(),
            &payload_metadata
        ));
        assert!(!aggregate_request_is_compaction(
            &HashMap::new(),
            &json!({ "client_metadata": { "request_kind": "turn" } })
        ));
    }

    #[test]
    fn aggregate_http_reader_handles_expect_continue_and_segmented_image_body() {
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let address = listener.local_addr().unwrap();
        let body = json!({
          "model": "gaoge/deepseek/61/deepseek-v4-pro",
          "input": [{
            "type": "message",
            "role": "user",
            "content": [{
              "type": "input_image",
              "image_url": format!("data:image/png;base64,{}", "A".repeat(48 * 1024))
            }]
          }]
        })
        .to_string()
        .into_bytes();
        assert!(body.len() > 16 * 1024);
        let expected_body = body.clone();

        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            stream.set_nonblocking(true).unwrap();
            read_aggregate_http_request(&mut stream)
        });

        let mut client = TcpStream::connect(address).unwrap();
        client
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let header = format!(
            "POST /v1/responses HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/json\r\nContent-Length: {}\r\nExpect: 100-continue\r\n\r\n",
            body.len()
        );
        client.write_all(header.as_bytes()).unwrap();
        client.flush().unwrap();

        let expected_continue = b"HTTP/1.1 100 Continue\r\n\r\n";
        let mut actual_continue = vec![0u8; expected_continue.len()];
        client.read_exact(&mut actual_continue).unwrap();
        assert_eq!(actual_continue, expected_continue);

        let split = 17 * 1024;
        client.write_all(&body[..split]).unwrap();
        client.flush().unwrap();
        thread::sleep(Duration::from_millis(25));
        client.write_all(&body[split..]).unwrap();
        client.flush().unwrap();

        let (method, path, headers, received_body) = server.join().unwrap().unwrap();
        assert_eq!(method, "POST");
        assert_eq!(path, "/v1/responses");
        assert_eq!(
            headers.get("expect").map(String::as_str),
            Some("100-continue")
        );
        assert_eq!(received_body, expected_body);
    }

