    #[test]
    fn canonical_rollout_choice_is_order_independent_and_stable() {
        let id = "01980e4f-4a31-7000-8000-000000000180";
        let mut earlier = test_rollout(id, PathBuf::from("sessions/earlier.jsonl"), "Earlier");
        earlier.timestamp_ms = 1_783_526_400_000;
        earlier.line_count = 500;
        let mut later = test_rollout(id, PathBuf::from("sessions/later.jsonl"), "Later");
        later.timestamp_ms = 1_783_612_800_000;
        later.line_count = 20;
        let unrelated = test_rollout(
            "01980e4f-4a31-7000-8000-000000000181",
            PathBuf::from("sessions/unrelated.jsonl"),
            "Unrelated",
        );

        let forward =
            canonical_rollout_summaries(&[earlier.clone(), unrelated.clone(), later.clone()]);
        let reverse = canonical_rollout_summaries(&[later.clone(), unrelated, earlier.clone()]);
        let repeated = canonical_rollout_summaries(&forward);

        assert_eq!(forward.len(), 2);
        assert_eq!(
            forward
                .iter()
                .find(|rollout| rollout.id == id)
                .map(|rollout| rollout.path.as_path()),
            Some(later.path.as_path())
        );
        assert_eq!(
            forward
                .iter()
                .map(|rollout| (&rollout.id, codex_path_identity(&rollout.path)))
                .collect::<Vec<_>>(),
            reverse
                .iter()
                .map(|rollout| (&rollout.id, codex_path_identity(&rollout.path)))
                .collect::<Vec<_>>()
        );
        assert_eq!(
            repeated
                .iter()
                .map(|rollout| (&rollout.id, codex_path_identity(&rollout.path)))
                .collect::<Vec<_>>(),
            forward
                .iter()
                .map(|rollout| (&rollout.id, codex_path_identity(&rollout.path)))
                .collect::<Vec<_>>()
        );
    }

