    #[test]
    fn codex_api_key_service_tier_legacy_detection_is_exact_and_fail_closed() {
        let fixture = include_bytes!("../../scripts/fixtures/codex-service-tier-gate-26.915.js");
        assert_eq!(CODEX_APIKEY_SERVICE_TIER_GATE_ORIGINAL.len(), CODEX_APIKEY_SERVICE_TIER_GATE_PATCHED.len());
        let (offset, patched) = codex_api_key_service_tier_gate_match(fixture).unwrap().unwrap();
        assert!(!patched);
        let mut known_legacy = fixture.to_vec();
        known_legacy[offset..offset + CODEX_APIKEY_SERVICE_TIER_GATE_PATCHED.len()]
            .copy_from_slice(CODEX_APIKEY_SERVICE_TIER_GATE_PATCHED);
        assert_eq!(codex_api_key_service_tier_gate_match(&known_legacy).unwrap(), Some((offset, true)));
        let ambiguous = [fixture.as_slice(), b"\n", fixture.as_slice()].concat();
        assert!(codex_api_key_service_tier_gate_match(&ambiguous).is_err());
        let changed = String::from_utf8_lossy(fixture)
            .replace("isServiceTierAllowed:d", "isServiceTierAllowed:a").into_bytes();
        assert!(codex_api_key_service_tier_gate_match(&changed).unwrap_err().contains("结构已变化"));
    }

