    #[test]
    fn codex_model_picker_asar_patch_refreshes_file_integrity() {
        with_temp_user_home("codex-model-picker-asar-patch", |root| {
            let asset = b"function r({authMethod:e,availableModels:n,defaultModel:r,enabledReasoningEfforts:i,includeUltraReasoningEffort:a,models:o,useHiddenModels:s}){let u=s&&e!==`amazonBedrock`;o.forEach(r=>{if(u?n.has(r.model):!r.hidden){}})}";
            let original_hash = format!("{:x}", Sha256::digest(asset));
            let header = json!({
                "files": {
                    "webview": { "files": {
                        "assets": { "files": {
                            "model-list-filter-test.js": {
                                "size": asset.len(),
                                "offset": "0",
                                "integrity": {
                                    "algorithm": "SHA256",
                                    "hash": original_hash,
                                    "blockSize": 4_194_304,
                                    "blocks": [original_hash]
                                }
                            }
                        }}
                    }}
                }
            });
            let header_json = serde_json::to_vec(&header).unwrap();
            let pickle_payload = 4 + header_json.len();
            let padded_payload = (pickle_payload + 3) & !3;
            let header_size = 4 + padded_payload;
            let mut archive = Vec::new();
            archive.extend_from_slice(&4u32.to_le_bytes());
            archive.extend_from_slice(&(header_size as u32).to_le_bytes());
            archive.extend_from_slice(&((header_size - 4) as u32).to_le_bytes());
            archive.extend_from_slice(&(header_json.len() as u32).to_le_bytes());
            archive.extend_from_slice(&header_json);
            archive.resize(8 + header_size, 0);
            archive.extend_from_slice(asset);

            let path = root.join("app.asar");
            let backup = root.join(CODEX_MODEL_PICKER_PATCH_BACKUP_FILE);
            fs::write(&path, &archive).unwrap();

            let first = patch_codex_model_picker_file(&path, &backup).unwrap();
            assert_eq!(first.get("changed").and_then(Value::as_bool), Some(true));
            assert_eq!(
                first.get("modelPickerAsset").and_then(Value::as_str),
                Some("webview/assets/model-list-filter-test.js")
            );
            assert_eq!(fs::read(&backup).unwrap(), archive);

            let patched = fs::read(&path).unwrap();
            let (header_range, data_start) = asar_header_layout(&patched).unwrap();
            let patched_asset = &patched[data_start..data_start + asset.len()];
            assert!(byte_slice_contains(
                patched_asset,
                CODEX_MODEL_PICKER_FILTER_PATCHED
            ));
            let expected_hash = format!("{:x}", Sha256::digest(patched_asset));
            let patched_header: Value = serde_json::from_slice(&patched[header_range]).unwrap();
            let integrity = &patched_header["files"]["webview"]["files"]["assets"]["files"]
                ["model-list-filter-test.js"]["integrity"];
            assert_eq!(integrity["hash"].as_str(), Some(expected_hash.as_str()));
            assert_eq!(
                integrity["blocks"][0].as_str(),
                Some(expected_hash.as_str())
            );

            let second = patch_codex_model_picker_file(&path, &backup).unwrap();
            assert_eq!(second.get("changed").and_then(Value::as_bool), Some(false));
            assert_eq!(fs::read(&backup).unwrap(), archive);
        });
    }

    #[test]
    fn codex_model_picker_asar_preserves_service_tier_gate_and_multi_block_integrity() {
        let fixture = include_bytes!("../../scripts/fixtures/codex-service-tier-gate-26.915.js");
        let block_size = 128usize;
        let native = include_bytes!("../../scripts/fixtures/codex-model-filter-26.901.js");
        let mut asset = native.to_vec();
        asset.extend_from_slice(b"\n");
        asset.extend_from_slice(fixture);
        asset.extend(std::iter::repeat_n(b';', block_size + 29));
        let original_hash = format!("{:x}", Sha256::digest(&asset));
        let original_blocks = asset
            .chunks(block_size)
            .map(|block| format!("{:x}", Sha256::digest(block)))
            .collect::<Vec<_>>();
        let header = json!({
            "files": {
                "webview": { "files": {
                    "assets": { "files": {
                        "app-initial-test.js": {
                            "size": asset.len(),
                            "offset": "0",
                            "integrity": {
                                "algorithm": "SHA256",
                                "hash": original_hash,
                                "blockSize": block_size,
                                "blocks": original_blocks
                            }
                        }
                    }}
                }}
            }
        });
        let header_json = serde_json::to_vec(&header).unwrap();
        let pickle_payload = 4 + header_json.len();
        let padded_payload = (pickle_payload + 3) & !3;
        let header_size = 4 + padded_payload;
        let mut archive = Vec::new();
        archive.extend_from_slice(&4u32.to_le_bytes());
        archive.extend_from_slice(&(header_size as u32).to_le_bytes());
        archive.extend_from_slice(&((header_size - 4) as u32).to_le_bytes());
        archive.extend_from_slice(&(header_json.len() as u32).to_le_bytes());
        archive.extend_from_slice(&header_json);
        archive.resize(8 + header_size, 0);
        archive.extend_from_slice(&asset);
        let original = archive.clone();
        for _ in 0..2 {
            let patch = patch_codex_model_picker_bytes(&mut archive).unwrap();
            assert!(patch.native_model_catalog);
            assert!(!patch.api_key_service_tier_patched);
            assert!(!patch.changed);
            assert_eq!(archive, original, "ASAR bytes, file integrity and block hashes must remain unchanged");
        }
        let (header_range, data_start) = asar_header_layout(&archive).unwrap();
        assert_eq!(&archive[data_start..], asset.as_slice());
        let verified_header: Value = serde_json::from_slice(&archive[header_range]).unwrap();
        assert_eq!(verified_header, header);
    }

    #[test]
    fn codex_model_picker_real_asar_fixture_is_patchable_when_provided() {
        let Ok(path) = std::env::var("CODEX_REAL_ASAR_FIXTURE") else {
            return;
        };
        let mut content = fs::read(&path).unwrap();
        let original_len = content.len();

        let (changed, code_changed, asset) = patch_codex_model_picker_asar_content(&mut content)
            .unwrap()
            .expect("expected a real ASAR archive");
        assert!(changed);
        assert!(code_changed);
        assert!(asset.contains("model-list-filter"));
        assert_eq!(content.len(), original_len);

        let (changed_again, code_changed_again, same_asset) =
            patch_codex_model_picker_asar_content(&mut content)
                .unwrap()
                .expect("expected the patched ASAR archive");
        assert!(!changed_again);
        assert!(!code_changed_again);
        assert_eq!(same_asset, asset);
        assert_eq!(content.len(), original_len);
    }

