    #[test]
    fn codex_model_catalog_plan_distinguishes_upstream_locked_and_fallback() {
        let (upstream_model, upstream) = codex_model_catalog_plan(
            &json!({
                "modelSelectionMode": "upstream",
                "modelCatalogSource": "upstream",
                "supportedModels": ["gpt-5.6-sol", "gpt-5.6-terra", "gpt-5.6-sol"]
            }),
            "gpt-5.6-terra",
        )
        .unwrap();
        assert_eq!(upstream_model, "gpt-5.6-terra");
        assert_eq!(
            upstream.models,
            vec!["gpt-5.6-sol".to_string(), "gpt-5.6-terra".to_string()]
        );
        assert_eq!(upstream.mode, CODEX_MODEL_SELECTION_UPSTREAM);
        assert_eq!(upstream.source, CODEX_MODEL_CATALOG_SOURCE_UPSTREAM);

        let (fallback_model, fallback) = codex_model_catalog_plan(
            &json!({
                "modelSelectionMode": "upstream",
                "modelCatalogSource": "fallback",
                "supportedModels": ["not-used"]
            }),
            "gpt-5.6-sol",
        )
        .unwrap();
        assert_eq!(fallback_model, CODEX_DEFAULT_MODEL);
        assert_eq!(fallback.models, codex_fallback_models());
        assert_eq!(fallback.source, CODEX_MODEL_CATALOG_SOURCE_FALLBACK);
        assert!(!fallback.warning.is_empty());

        let (locked_model, locked) =
            codex_model_catalog_plan(&json!({ "model": "gpt-5.6-luna" }), "gpt-5.6-luna").unwrap();
        assert_eq!(locked_model, "gpt-5.6-luna");
        assert_eq!(locked.models, vec!["gpt-5.6-luna".to_string()]);
        assert_eq!(locked.mode, CODEX_MODEL_SELECTION_LOCKED);

        let removed = codex_model_catalog_plan(
            &json!({
                "modelSelectionMode": "locked",
                "modelCatalogSource": "upstream",
                "supportedModels": ["gpt-5.5"]
            }),
            "gpt-6-removed",
        )
        .unwrap_err();
        assert!(removed.contains("gpt-6-removed"));
    }

