    #[test]
    fn checked_codex_config_write_rejects_invalid_and_stale_candidates() {
        let suffix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "gaoge-codex-config-write-{}-{suffix}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        let path = root.join("config.toml");
        let original = "model = \"gpt-5.6-sol\"\n";
        fs::write(&path, original).unwrap();

        let invalid = "[desktop]\n\"low\",\n]\n";
        assert!(write_codex_config_atomic(&path, Some(original), invalid).is_err());
        assert_eq!(fs::read_to_string(&path).unwrap(), original);

        let externally_updated = "model = \"gpt-6-sol\"\n";
        fs::write(&path, externally_updated).unwrap();
        let candidate = "model = \"gpt-6-astra\"\n";
        assert!(write_codex_config_atomic(&path, Some(original), candidate).is_err());
        assert_eq!(fs::read_to_string(&path).unwrap(), externally_updated);

        write_codex_config_atomic(&path, Some(externally_updated), candidate).unwrap();
        assert_eq!(fs::read_to_string(&path).unwrap(), candidate);
        assert!(validate_codex_config_toml(candidate).is_ok());

        let missing = root.join("missing.toml");
        assert!(write_codex_config_atomic(&missing, Some(""), invalid).is_err());
        assert!(!missing.exists());

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_config_write_rollback_restores_only_our_candidate() {
        let suffix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "gaoge-codex-config-rollback-{}-{suffix}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        let path = root.join("config.toml");
        let original = "model = \"gpt-5.5\"\n";
        let candidate = "model = \"gpt-5.6-sol\"\n";
        fs::write(&path, original).unwrap();
        let snapshot = OptionalFileSnapshot::capture(path.clone()).unwrap();

        fs::write(&path, candidate).unwrap();
        rollback_codex_config_if_candidate(&snapshot, &path, candidate).unwrap();
        assert_eq!(fs::read_to_string(&path).unwrap(), original);

        fs::write(&path, "model = \"gpt-6-astra\"\n").unwrap();
        let error = rollback_codex_config_if_candidate(&snapshot, &path, candidate).unwrap_err();
        assert!(error.contains("其他程序修改"));
        assert_eq!(
            fs::read_to_string(&path).unwrap(),
            "model = \"gpt-6-astra\"\n"
        );

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn api_speed_config_round_trips_without_changing_models_auth_or_sessions() {
        let original = "model = \"gpt-5.6-terra\"\nservice_tier = \"priority\"\nnotify = [\"keep\"]\n\n[features]\nfast_mode = false\nother = true\n\n[mcp_servers.example]\ncommand = \"keep-command\"\n";
        let fast = codex_api_speed_config(original, "fast");
        assert_eq!(
            configured_root_value(&fast, "service_tier").as_deref(),
            Some("priority")
        );
        assert_eq!(codex_api_speed_config(&fast, "fast"), fast);
        let standard = codex_api_speed_config(&fast, "standard");
        assert_eq!(
            configured_root_value(&standard, "service_tier").as_deref(),
            Some("default")
        );
        assert_eq!(standard.matches("service_tier").count(), 1);
        assert_eq!(standard.matches("fast_mode = true").count(), 1);
        for preserved in [
            "model = \"gpt-5.6-terra\"",
            "notify = [\"keep\"]",
            "other = true",
            "command = \"keep-command\"",
        ] {
            assert!(standard.contains(preserved));
        }
        assert_eq!(codex_api_speed_config(&standard, "fast"), fast);
    }

    #[test]
    fn api_speed_bridge_persists_only_the_active_managed_api_home_and_rejects_stale_routes() {
        with_temp_user_home("api-speed-bridge", |root| {
            let old_router = ROUTER_STATE.lock().unwrap().clone();
            let old_aggregate = aggregate_login_state_snapshot();
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let active_home = root.join("active-home");
                fs::create_dir_all(&active_home).unwrap();
                std::env::set_var("CODEX_HOME", &active_home);
                let mut router = default_router_state();
                router.mode = "relay".to_string();
                router.relay_api_key = "synthetic-api-speed-key".to_string();
                router.relay_base_url = "https://relay.example.invalid/v1".to_string();
                *ROUTER_STATE.lock().unwrap() = router.clone();
                *AGGREGATE_LOGIN_STATE.lock().unwrap() = default_aggregate_login_state();
                let config_path = active_home.join("config.toml");
                let auth_path = active_home.join("auth.json");
                fs::write(
                    &config_path,
                    build_codex_direct_config(
                        &router.relay_api_key,
                        &router.relay_base_url,
                        "gpt-5.6-terra",
                    ),
                )
                .unwrap();
                write_json_pretty(&auth_path, &build_codex_api_auth(&router.relay_api_key))
                    .unwrap();
                let auth_before = fs::read(&auth_path).unwrap();
                let revision = current_codex_runtime_revision();
                for speed in ["fast", "standard", "fast"] {
                    let result = handle_codex_session_delete_bridge_request(
                        "/speed/select",
                        &json!({
                            "speedMode": speed, "model": "gpt-5.6-terra", "baseUrl": router.relay_base_url,
                        }),
                    );
                    assert_eq!(result["ok"], true, "{result}");
                    assert_eq!(result["apiSpeedEnabled"], true);
                    assert_eq!(result["speedMode"], speed);
                    assert_eq!(codex_fuel_runtime_state()["speedMode"], speed);
                    assert!(!result.to_string().contains(&router.relay_api_key));
                }
                assert_eq!(current_codex_runtime_revision(), revision);
                assert_eq!(fs::read(&auth_path).unwrap(), auth_before);
                assert!(!root.join(".codex/config.toml").exists());
                let saved = fs::read(&config_path).unwrap();
                for request in [
                    json!({"speedMode":"fast","model":"gpt-image-2","baseUrl":router.relay_base_url}),
                    json!({"speedMode":"fast","model":"gpt-5.6-terra","baseUrl":"https://previous.invalid/v1"}),
                    json!({"speedMode":"invalid","model":"gpt-5.6-terra","baseUrl":router.relay_base_url}),
                ] {
                    assert_eq!(
                        handle_codex_session_delete_bridge_request("/speed/select", &request)["ok"],
                        false
                    );
                    assert_eq!(fs::read(&config_path).unwrap(), saved);
                }
                write_json_pretty(
                    &auth_path,
                    &test_codex_chatgpt_auth("synthetic@example.invalid", "synthetic", "synthetic"),
                )
                .unwrap();
                assert_eq!(codex_fuel_runtime_state()["apiSpeedEnabled"], false);
                assert!(select_codex_api_speed(&json!({"speedMode":"standard","model":"gpt-5.6-terra","baseUrl":router.relay_base_url})).is_err());
                assert_eq!(fs::read(&config_path).unwrap(), saved);
                let mut mixed_auth = build_codex_api_auth(&router.relay_api_key);
                mixed_auth["auth_mode"] = json!("chatgpt");
                write_json_pretty(&auth_path, &mixed_auth).unwrap();
                assert_eq!(codex_fuel_runtime_state()["apiSpeedEnabled"], false);
                fs::remove_file(&auth_path).unwrap();
                assert_eq!(codex_fuel_runtime_state()["apiSpeedEnabled"], false);
                write_json_pretty(&auth_path, &build_codex_api_auth(&router.relay_api_key))
                    .unwrap();
                assert_eq!(codex_fuel_runtime_state()["apiSpeedEnabled"], true);
            }));
            *ROUTER_STATE.lock().unwrap() = old_router;
            *AGGREGATE_LOGIN_STATE.lock().unwrap() = old_aggregate;
            if let Err(panic) = outcome {
                std::panic::resume_unwind(panic);
            }
        });
    }

    #[test]
