    #[test]
    fn native_responses_catalog_accepts_exact_upstream_slugs_without_local_cache() {
        with_temp_user_home("codex-native-responses-catalog", |root| {
            let codex_dir = root.join(".codex");
            let models = vec!["gpt-5.6-terra".to_string(), "vendor-model-live".to_string()];
            let written = write_codex_model_catalog(&codex_dir, &models).unwrap();

            assert!(written.path.is_absolute());
            assert_eq!(written.models, models);
            let catalog_text = fs::read_to_string(&written.path).unwrap();
            assert!(!catalog_text.contains("api_key"));
            let catalog: Value = serde_json::from_str(&catalog_text).unwrap();
            assert_eq!(codex_catalog_model_names(&catalog), models);
            let entries = catalog.get("models").and_then(Value::as_array).unwrap();
            for entry in entries {
                assert_eq!(
                    entry.get("visibility").and_then(Value::as_str),
                    Some("list")
                );
                assert_eq!(
                    entry.get("supported_in_api").and_then(Value::as_bool),
                    Some(true)
                );
                assert!(entry.get("tool_mode").is_none());
                if entry["slug"] == "gpt-5.6-terra" {
                    assert_eq!(entry["multi_agent_version"], "v2");
                } else {
                    assert!(entry.get("multi_agent_version").is_none());
                }
                assert!(entry.get("use_responses_lite").is_none());
            }
            assert_eq!(entries[0]["input_modalities"], json!(["text", "image"]));
            assert_eq!(entries[1]["input_modalities"], json!(["text", "image"]));
            assert_eq!(
                entries[1]
                    .get("supports_image_detail_original")
                    .and_then(Value::as_bool),
                Some(false)
            );
        });
    }

