    #[test]
    fn locked_catalog_switch_from_56_to_55_keeps_image_inputs_enabled() {
        with_temp_user_home("codex-image-model-switch", |root| {
            let codex_dir = root.join(".codex");
            fs::create_dir_all(&codex_dir).unwrap();

            for (model, original_detail) in [("gpt-5.6-sol", false), ("gpt-5.5", true)] {
                let plan = CodexModelCatalogPlan {
                    mode: CODEX_MODEL_SELECTION_LOCKED.to_string(),
                    source: CODEX_MODEL_CATALOG_SOURCE_UPSTREAM.to_string(),
                    models: vec![model.to_string()],
                    warning: String::new(),
                };
                let resolved =
                    resolve_codex_model_catalog(&codex_route_targets(), model, &plan).unwrap();
                let written = write_codex_model_catalog_value(
                    &codex_dir,
                    &resolved.catalog,
                    &resolved.plan.models,
                )
                .unwrap();
                let persisted: Value = serde_json::from_str(
                    &fs::read_to_string(written.path).expect("read persisted model catalog"),
                )
                .unwrap();
                let entry = &persisted["models"][0];

                assert_eq!(entry["slug"].as_str(), Some(model));
                assert_eq!(entry["input_modalities"], json!(["text", "image"]));
                assert_eq!(
                    entry["supports_image_detail_original"].as_bool(),
                    Some(original_detail),
                    "{model}: image input must not fabricate original-detail support"
                );
            }
        });
    }

