    #[test]
    fn account_switch_defaults_to_live_relay_but_honors_explicit_official_request() {
        with_temp_user_home("codex-account-switch-live-route-default", |_root| {
            fs::create_dir_all(codex_dir()).unwrap();
            // The OAuth immediate-activation caller sends only accountKey.
            let oauth_request = json!({ "accountKey": "new-oauth-account" });
            fs::write(codex_config_path(), "model = \"gpt-5.5\"\n").unwrap();
            assert!(!codex_account_switch_preserves_relay(&oauth_request));
            assert!(!codex_account_switch_preserves_relay(&json!({ "preserveRelay": true })));

            let relay = build_codex_direct_config("relay-key", GAOGE_OPENAI_BASE_URL, "gpt-5.5");
            fs::write(codex_config_path(), &relay).unwrap();
            assert!(codex_account_switch_preserves_relay(&oauth_request));
            assert!(codex_account_switch_preserves_relay(&json!({ "preserveRelay": true })));
            assert!(!codex_account_switch_preserves_relay(&json!({ "preserveRelay": false })));

            let inactive_relay = relay.replacen(
                "model_provider = \"custom\"",
                "model_provider = \"openai\"",
                1,
            );
            fs::write(codex_config_path(), &inactive_relay).unwrap();
            assert!(!codex_account_switch_preserves_relay(&oauth_request));
            let profile_relay = format!(
                "{inactive_relay}\n[profiles.relay]\nmodel_provider = \"custom\"\n"
            );
            fs::write(codex_config_path(), format!("profile = \"relay\"\n{profile_relay}")).unwrap();
            assert!(codex_account_switch_preserves_relay(&oauth_request));
        });
    }

