    #[test]
    fn usage_auth_refresh_waits_for_account_configuration_before_commit() {
        with_temp_user_home("codex-usage-refresh-configure-lock", |_root| {
            let original =
                test_codex_chatgpt_auth("usage@example.com", "usage-user", "usage-account");
            let item = upsert_account(&original, None, false).unwrap();
            let path = snapshot_path_for_key(item["accountKey"].as_str().unwrap());
            let mut refreshed = original.clone();
            refreshed["tokens"]["refresh_token"] = json!("rotated-usage-refresh");
            let guard = CODEX_CONFIGURE_LOCK.lock().unwrap();
            let (sender, receiver) = mpsc::channel();
            let worker_path = path.clone();
            let expected = refreshed.clone();
            let worker = thread::spawn(move || {
                let result =
                    commit_codex_usage_auth_refresh(&original, &refreshed, &worker_path);
                sender.send(result).unwrap();
            });
            let blocked = receiver.recv_timeout(Duration::from_millis(50)).is_err();
            drop(guard);
            let result = receiver.recv_timeout(Duration::from_secs(5)).unwrap().unwrap();
            worker.join().unwrap();
            assert!(blocked);
            assert_eq!(result, expected);
            assert_eq!(read_json_if_exists(&path).unwrap(), Some(expected));
        });
    }

