    #[test]
    fn current_relay_detection_requires_current_gaoge_host() {
        let legacy =
            build_codex_direct_config("relay-key", "https://legacy.example.invalid/v1", "gpt-5.5");
        assert!(provider_has_gaoge_route(&legacy, CODEX_DIRECT_PROVIDER_ID));
        assert!(!provider_has_current_gaoge_route(
            &legacy,
            CODEX_DIRECT_PROVIDER_ID,
            GAOGE_OPENAI_BASE_URL
        ));
        assert!(!is_gaoge_custom_provider_config(
            &legacy,
            GAOGE_OPENAI_BASE_URL
        ));

        let current = build_codex_direct_config("relay-key", GAOGE_OPENAI_BASE_URL, "gpt-5.5");
        assert!(provider_has_gaoge_route(&current, CODEX_DIRECT_PROVIDER_ID));
        assert!(provider_has_current_gaoge_route(
            &current,
            CODEX_DIRECT_PROVIDER_ID,
            GAOGE_OPENAI_BASE_URL
        ));
        assert!(is_gaoge_custom_provider_config(
            &current,
            GAOGE_OPENAI_BASE_URL
        ));

        let main_base_url = "https://region-a.example.invalid/v1";
        let main = build_codex_direct_config("relay-key", main_base_url, "gpt-5.5");
        assert!(provider_has_current_gaoge_route(
            &main,
            CODEX_DIRECT_PROVIDER_ID,
            main_base_url
        ));
        assert!(is_gaoge_custom_provider_config(&main, main_base_url));
        assert!(!provider_has_current_gaoge_route(
            &main,
            CODEX_DIRECT_PROVIDER_ID,
            GAOGE_OPENAI_BASE_URL
        ));
    }

