    fn test_codex_chatgpt_auth_with_token_exps(
        email: &str,
        user_id: &str,
        account_id: &str,
        access_exp: i64,
        id_exp: i64,
        include_refresh_token: bool,
    ) -> Value {
        let auth_info = json!({
            "chatgpt_account_id": account_id,
            "chatgpt_user_id": user_id,
            "chatgpt_plan_type": "prolite",
            "chatgpt_subscription_active_until": "2026-06-30T11:39:08+00:00"
        });
        let profile_info = json!({
            "email": email,
            "name": "Saved User"
        });
        let id_token = test_jwt(json!({
            "sub": user_id,
            "email": email,
            "name": "Saved User",
            "exp": id_exp,
            "https://api.openai.com/auth": auth_info,
            "https://api.openai.com/profile": profile_info
        }));
        let access_token = test_jwt(json!({
            "sub": user_id,
            "exp": access_exp,
            "https://api.openai.com/auth": auth_info
        }));
        let mut tokens = Map::new();
        tokens.insert("access_token".to_string(), Value::String(access_token));
        tokens.insert("id_token".to_string(), Value::String(id_token));
        tokens.insert(
            "account_id".to_string(),
            Value::String(account_id.to_string()),
        );
        if include_refresh_token {
            tokens.insert(
                "refresh_token".to_string(),
                Value::String(format!("refresh-{account_id}")),
            );
        }
        json!({
          "auth_mode": "chatgpt",
          "tokens": Value::Object(tokens)
        })
    }

    pub(super) fn with_temp_user_home<T>(label: &str, test: impl FnOnce(&Path) -> T) -> T {
        let _guard = TEST_ENV_LOCK.lock().unwrap();
        let root = std::env::temp_dir().join(format!(
            "gaoge-{label}-{}-{}",
            std::process::id(),
            timestamp_for_path()
        ));
        let env_paths = [
            ("USERPROFILE", root.clone()),
            ("HOME", root.clone()),
            ("APPDATA", root.join("appdata")),
            ("LOCALAPPDATA", root.join("localappdata")),
            ("XDG_CONFIG_HOME", root.join("xdg-config")),
            ("XDG_DATA_HOME", root.join("xdg-data")),
        ];
        let previous: Vec<(&str, Option<std::ffi::OsString>)> = env_paths
            .iter()
            .map(|(key, _)| (*key, std::env::var_os(key)))
            .collect();
        let previous_codex_home = std::env::var_os("CODEX_HOME");

        fs::create_dir_all(&root).unwrap();
        for (key, path) in env_paths {
            std::env::set_var(key, path);
        }
        std::env::remove_var("CODEX_HOME");

        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| test(&root)));

        for (key, value) in previous {
            if let Some(value) = value {
                std::env::set_var(key, value);
            } else {
                std::env::remove_var(key);
            }
        }
        if let Some(value) = previous_codex_home {
            std::env::set_var("CODEX_HOME", value);
        } else {
            std::env::remove_var("CODEX_HOME");
        }
        let _ = fs::remove_dir_all(&root);
        drop(_guard);

        match result {
            Ok(value) => value,
            Err(payload) => std::panic::resume_unwind(payload),
        }
    }

    fn write_managed_test_rollout(
        codex_home: &Path,
        archived: bool,
        session_id: &str,
        title: &str,
        cwd: &Path,
        parent_thread_id: Option<&str>,
    ) -> PathBuf {
        let root = if archived {
            codex_home.join("archived_sessions")
        } else {
            codex_home.join("sessions").join("2026").join("08")
        };
        fs::create_dir_all(&root).unwrap();
        let path = root.join(format!("rollout-{session_id}.jsonl"));
        let source = parent_thread_id.map_or_else(
            || json!("cli"),
            |parent_id| {
                json!({
                    "subagent": {
                        "thread_spawn": {
                            "parent_thread_id": parent_id,
                            "agent_nickname": "test-worker",
                            "depth": 1
                        }
                    }
                })
            },
        );
        fs::write(
            &path,
            [
                json!({
                    "timestamp": "2026-08-10T04:00:00.000Z",
                    "type": "session_meta",
                    "payload": {
                        "id": session_id,
                        "title": title,
                        "timestamp": "2026-08-10T04:00:00.000Z",
                        "cwd": cwd.to_string_lossy(),
                        "model_provider": "openai",
                        "model": "gpt-5.6-sol",
                        "model_reasoning_effort": "high",
                        "source": source
                    }
                })
                .to_string(),
                json!({
                    "timestamp": "2026-08-10T04:01:00.000Z",
                    "type": "response_item",
                    "payload": {
                        "type": "message",
                        "role": "user",
                        "content": [{"type": "input_text", "text": format!("用户问题：{title}")}]
                    }
                })
                .to_string(),
                json!({
                    "timestamp": "2026-08-10T04:02:00.000Z",
                    "type": "response_item",
                    "payload": {
                        "type": "message",
                        "role": "assistant",
                        "content": [{"type": "output_text", "text": format!("助手回答：{title}")}]
                    }
                })
                .to_string(),
            ]
            .join("\n")
                + "\n",
        )
        .unwrap();
        path
    }

