    #[test]
    fn claude_desktop_writes_fable_model_without_legacy_alias() {
        let request = json!({
            "desktopModels": [
                CLAUDE_FABLE_MODEL,
                "claude-opus-4-6",
                "claude-opus-4-7",
                "claude-opus-4-8",
                "claude-opus-fable-5[1m]",
                "claude-sonnet-4-6",
                "claude-sonnet-5"
            ]
        });
        let profile = build_claude_desktop_profile(
            "relay-key",
            GAOGE_ANTHROPIC_BASE_URL,
            &request,
            CLAUDE_FABLE_MODEL,
        );
        let models = profile
            .get("inferenceModels")
            .and_then(Value::as_array)
            .unwrap();
        assert_eq!(models.len(), 6);
        assert!(models
            .iter()
            .any(|item| { item.get("name").and_then(Value::as_str) == Some(CLAUDE_FABLE_MODEL) }));
        assert!(!models.iter().any(|item| {
            item.get("name").and_then(Value::as_str)
                == Some(CLAUDE_DESKTOP_LEGACY_FABLE_ALIAS_MODEL)
        }));

        let fable = models
            .iter()
            .find(|item| item.get("name").and_then(Value::as_str) == Some(CLAUDE_FABLE_MODEL))
            .unwrap();
        assert_eq!(
            fable.get("labelOverride").and_then(Value::as_str),
            Some(CLAUDE_DESKTOP_FABLE_LABEL)
        );
        assert_eq!(fable.get("supports1m").and_then(Value::as_bool), Some(true));
        assert_eq!(
            models
                .iter()
                .filter(|item| {
                    item.get("name").and_then(Value::as_str) == Some(CLAUDE_FABLE_MODEL)
                })
                .count(),
            1
        );
        assert!(models
            .iter()
            .filter(|item| { item.get("name").and_then(Value::as_str) != Some(CLAUDE_FABLE_MODEL) })
            .all(|item| item.get("supports1m").and_then(Value::as_bool) == Some(false)));
    }

