    #[test]
    fn claude_disable_restores_previous_user_auth_token() {
        with_temp_user_home("claude-cli-token-restore", |_root| {
            write_json_pretty(
                &claude_settings_path(),
                &json!({
                    "env": {
                        "ANTHROPIC_AUTH_TOKEN": "user-token",
                        "ANTHROPIC_API_KEY": "user-api-key"
                    }
                }),
            )
            .unwrap();

            let request = json!({});
            write_claude_code_settings(
                "relay-key",
                GAOGE_ANTHROPIC_BASE_URL,
                "claude-sonnet-4-5",
                &request,
            )
            .unwrap();

            let configured = read_json_if_exists(&claude_settings_path())
                .unwrap()
                .unwrap();
            let configured_env = configured.get("env").and_then(Value::as_object).unwrap();
            assert_eq!(
                configured_env
                    .get("ANTHROPIC_AUTH_TOKEN")
                    .and_then(Value::as_str),
                Some("relay-key")
            );
            assert_eq!(
                configured_env
                    .get(CLAUDE_GAOGE_PREVIOUS_AUTH_TOKEN_ENV_KEY)
                    .and_then(Value::as_str),
                Some("user-token")
            );

            let (_settings_path, _backup, updated, removed, restored) =
                cleanup_claude_code_settings_for_relay_disable().unwrap();

            assert!(updated);
            assert!(removed.contains(&"ANTHROPIC_AUTH_TOKEN".to_string()));
            assert!(restored.contains(&"ANTHROPIC_AUTH_TOKEN".to_string()));

            let restored_settings = read_json_if_exists(&claude_settings_path())
                .unwrap()
                .unwrap();
            let restored_env = restored_settings
                .get("env")
                .and_then(Value::as_object)
                .unwrap();
            assert_eq!(
                restored_env
                    .get("ANTHROPIC_AUTH_TOKEN")
                    .and_then(Value::as_str),
                Some("user-token")
            );
            assert_eq!(
                restored_env
                    .get("ANTHROPIC_API_KEY")
                    .and_then(Value::as_str),
                Some("user-api-key")
            );
            assert!(restored_env
                .get(CLAUDE_GAOGE_AUTH_TOKEN_MANAGED_ENV_KEY)
                .is_none());
            assert!(restored_env
                .get(CLAUDE_GAOGE_PREVIOUS_AUTH_TOKEN_ENV_KEY)
                .is_none());
        });
    }

