    #[test]
    fn persisted_route_fingerprint_cleans_legacy_gaoge_config_without_name_only_guess() {
        with_temp_user_home("persisted-route-fingerprint", |_root| {
            let old_router = ROUTER_STATE.lock().unwrap().clone();
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let mut router = default_router_state();
                router.mode = "relay".to_string();
                router.relay_base_url = "https://legacy.example.invalid/v1".to_string();
                router.relay_api_key = "legacy-relay-key".to_string();
                save_router_state(router).unwrap();

                let legacy = r#"
model_provider = "custom"

[model_providers.custom]
name = "Gaoge"
base_url = "https://legacy.example.invalid/v1"
wire_api = "responses"
experimental_bearer_token = "legacy-relay-key"
"#;
                assert!(provider_has_gaoge_route(legacy, CODEX_DIRECT_PROVIDER_ID));
                assert!(has_gaoge_managed_provider_config(legacy));
                let cleaned = merge_codex_config(legacy, &build_codex_official_config("gpt-5.5"));
                assert!(!cleaned.contains("[model_providers.custom]"));
                assert!(!cleaned.contains("legacy-relay-key"));

                let personal = legacy
                    .replace("legacy.example.invalid", "personal.example.invalid")
                    .replace("legacy-relay-key", "personal-key");
                assert!(!provider_has_gaoge_route(
                    &personal,
                    CODEX_DIRECT_PROVIDER_ID
                ));
                assert!(!has_gaoge_managed_provider_config(&personal));
                let preserved = merge_codex_config(&personal, "");
                assert!(preserved.contains("[model_providers.custom]"));
                assert!(preserved.contains("personal.example.invalid"));
                assert!(preserved.contains("personal-key"));
            }));
            *ROUTER_STATE.lock().unwrap() = old_router;
            if let Err(panic) = outcome {
                std::panic::resume_unwind(panic);
            }
        });
    }

