    #[test]
    fn fuel_runtime_config_home_uses_effective_home_instead_of_default_relay() {
        with_temp_user_home("fuel-runtime-home-scope", |root| {
            let default_config = root.join(".codex").join("config.toml");
            let effective_home = root.join("effective-codex-home");
            let effective_config = effective_home.join("config.toml");
            fs::create_dir_all(default_config.parent().unwrap()).unwrap();
            fs::create_dir_all(&effective_home).unwrap();
            let mut router = default_router_state();
            router.relay_base_url = "https://relay.example.invalid/v1".to_string();
            router.relay_api_key = "fixture-home-key".to_string();
            let relay =
                build_codex_direct_config(&router.relay_api_key, &router.relay_base_url, "gpt-5.5");
            let aggregate = default_aggregate_login_state();
            let enabled = || {
                let config = read_text_if_exists(&codex_fuel_runtime_config_path()).unwrap();
                json_bool(
                    &codex_fuel_guard::status(&config, &router, &aggregate, false),
                    "enabled",
                )
            };

            fs::write(&default_config, &relay).unwrap();
            fs::write(&effective_config, "model_provider = \"openai\"\n").unwrap();
            std::env::set_var("CODEX_HOME", &effective_home);
            assert_eq!(codex_fuel_runtime_config_path(), effective_config);
            assert_eq!(codex_config_path(), default_config);
            assert!(
                !enabled(),
                "A relay in an inactive home must not enable the guard"
            );

            fs::write(&default_config, "model_provider = \"openai\"\n").unwrap();
            fs::write(&effective_config, &relay).unwrap();
            assert!(
                enabled(),
                "The inherited CODEX_HOME contains the active relay"
            );
            fs::write(&effective_config, "").unwrap();
            assert!(
                !enabled(),
                "Removing the active relay must immediately disable it"
            );
        });
    }

