    #[test]
    fn configure_and_disable_codex_targets_cover_codex_home() {
        with_temp_user_home("codex-route-write-targets", |root| {
            let default_dir = root.join(".codex");
            let codex_home = root.join("external-codex").join(".codex");
            std::env::set_var("CODEX_HOME", &codex_home);

            let configured = configure_codex_all_route_targets(
                "relay-key",
                GAOGE_OPENAI_BASE_URL,
                "gpt-5.5",
                true,
                None,
                false,
            )
            .unwrap();

            assert_eq!(configured.len(), 2);
            for dir in [&default_dir, &codex_home] {
                let config = fs::read_to_string(dir.join("config.toml")).unwrap();
                assert!(config.contains("model_provider = \"custom\""));
                assert!(config.contains("[model_providers.custom]"));
                assert!(config.contains(GAOGE_OPENAI_BASE_URL));
            }

            let disabled =
                disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();

            assert_eq!(disabled.len(), 2);
            for dir in [&default_dir, &codex_home] {
                let config = fs::read_to_string(dir.join("config.toml")).unwrap();
                assert!(configured_root_value(&config, "model_provider").is_none());
                assert!(!config.contains("[model_providers.custom]"));
                assert!(!config.contains(GAOGE_OPENAI_BASE_URL));
            }
        });
    }

    #[test]
    fn repeated_codex_login_synchronizes_sessions_without_backups() {
        with_temp_user_home("codex-login-preserves-sessions", |root| {
            let codex_home = root.join(".codex");
            let session_dir = codex_home.join("sessions").join("2026").join("07");
            fs::create_dir_all(&session_dir).unwrap();
            let session_id = "019f0000-1111-7000-8000-000000000001";
            let rollout_path = session_dir.join(format!("rollout-{session_id}.jsonl"));
            let rollout = [
                json!({
                    "type": "session_meta",
                    "payload": {
                        "id": session_id,
                        "title": "Keep this conversation",
                        "timestamp": "2026-07-12T00:00:00Z",
                        "model_provider": "openai"
                    }
                })
                .to_string(),
                json!({
                    "type": "event_msg",
                    "payload": { "role": "user", "content": "keep me" }
                })
                .to_string(),
            ]
            .join("\n")
                + "\n";
            fs::write(&rollout_path, rollout).unwrap();

            let second_session_id = "019f0000-2222-7000-8000-000000000002";
            let second_rollout_path =
                session_dir.join(format!("rollout-{second_session_id}.jsonl"));
            for login_round in 0..2 {
                let configured = configure_codex_all_route_targets(
                    "relay-key",
                    GAOGE_OPENAI_BASE_URL,
                    "gpt-5.6-sol",
                    true,
                    None,
                    true,
                )
                .unwrap();
                assert_eq!(configured.len(), 1);
                assert_eq!(
                    configured[0]["sessionSync"]["status"].as_str(),
                    Some("pending")
                );
                assert_eq!(
                    configured[0]["sessionSync"]["provider"].as_str(),
                    Some(CODEX_DIRECT_PROVIDER_ID)
                );
                assert!(rollout_path.exists());
                if login_round == 0 {
                    assert!(fs::read_to_string(&rollout_path)
                        .unwrap()
                        .contains("\"model_provider\":\"openai\""));
                }

                let synced = sync_codex_route_targets(CODEX_DIRECT_PROVIDER_ID, true).unwrap();
                assert_eq!(synced["status"].as_str(), Some("completed"));
                assert_eq!(synced["background"].as_bool(), Some(false));
                assert_eq!(
                    synced["configuredProvider"].as_str(),
                    Some(CODEX_DIRECT_PROVIDER_ID)
                );
                assert!(fs::read_to_string(&rollout_path)
                    .unwrap()
                    .contains("\"model_provider\":\"custom\""));
                assert!(fs::read_to_string(codex_home.join("session_index.jsonl"))
                    .unwrap()
                    .contains(session_id));

                if login_round == 0 {
                    fs::write(
                        &second_rollout_path,
                        format!(
                            "{}\n",
                            json!({
                                "type": "session_meta",
                                "payload": {
                                    "id": second_session_id,
                                    "title": "Created between two logins",
                                    "timestamp": "2026-07-12T00:01:00Z",
                                    "model_provider": CODEX_DIRECT_PROVIDER_ID
                                }
                            })
                        ),
                    )
                    .unwrap();
                }
            }

            assert!(second_rollout_path.exists());
            assert!(fs::read_to_string(codex_home.join("session_index.jsonl"))
                .unwrap()
                .contains(second_session_id));
            assert_eq!(rollout_files().len(), 2);
            assert!(!codex_home.join("backups").join("gaogeaii").exists());
        });
    }

