    #[test]
    fn relay_close_restores_user_settings_and_keeps_personal_identity() {
        with_temp_user_home("relay-close-personal", |_root| {
            let auth = test_codex_chatgpt_auth("personal@example.com", "personal", "personal");
            write_json_pretty(&codex_auth_path(), &auth).unwrap();
            let original = "model = \"gpt-5.6-terra\"\nmodel_reasoning_effort = \"high\"\ndisable_response_storage = true\nservice_tier = \"priority\"\n\n[features]\nfast_mode = false\n\n[mcp_servers.personal]\ncommand = \"keep-me\"\n";
            fs::write(codex_config_path(), original).unwrap();
            for key in ["first-key", "second-key"] {
                configure_codex_all_route_targets(
                    key,
                    GAOGE_OPENAI_BASE_URL,
                    "gpt-5.5",
                    true,
                    None,
                    false,
                )
                .unwrap();
                assert_eq!(
                    read_json_if_exists(&codex_auth_path()).unwrap().unwrap(),
                    auth
                );
            }
            let mut relay = read_text_if_exists(&codex_config_path()).unwrap();
            relay = relay
                .replace("service_tier = \"priority\"", "service_tier = \"fast\"")
                .replace("fast_mode = false", "fast_mode = true");
            relay.push_str("\n[plugins.\"personal@marketplace\"]\nenabled = true\n");
            fs::write(codex_config_path(), relay).unwrap();
            disable_codex_fuel_pack_all_route_targets("second-key", true, None).unwrap();
            let restored = read_text_if_exists(&codex_config_path()).unwrap();
            assert_eq!(
                configured_root_value(&restored, "model").as_deref(),
                Some("gpt-5.6-terra")
            );
            assert_eq!(
                configured_root_value(&restored, "model_reasoning_effort").as_deref(),
                Some("high")
            );
            assert!(restored.contains("service_tier = \"priority\""));
            assert!(restored.contains("fast_mode = false"));
            assert!(restored.contains("command = \"keep-me\""));
            assert!(restored.contains("[plugins.\"personal@marketplace\"]"));
            assert!(!restored.contains("disable_response_storage"));
            assert_eq!(
                read_json_if_exists(&codex_auth_path()).unwrap().unwrap(),
                auth
            );
        });
    }

