    #[test]
    fn relay_close_missing_official_auth_returns_to_login_without_selecting_saved_accounts() {
        for missing_kind in ["deleted", "non-official", "no-live-auth"] {
            with_temp_user_home("relay-close-missing-official-auth", |_root| {
                let original =
                    test_codex_chatgpt_auth("original@example.com", "original", "original");
                write_json_pretty(&codex_auth_path(), &original).unwrap();
                let other = test_codex_chatgpt_auth("other@example.com", "other", "other");
                upsert_account(&other, None, false).unwrap();
                configure_codex_all_route_targets(
                    "relay-key",
                    GAOGE_OPENAI_BASE_URL,
                    "gpt-5.5",
                    true,
                    None,
                    true,
                )
                .unwrap();
                let key = auth_account_key(&original);
                let snapshot_path = snapshot_path_for_key(&key);
                if missing_kind == "non-official" {
                    write_json_pretty(&snapshot_path, &json!({})).unwrap();
                } else {
                    fs::remove_file(&snapshot_path).unwrap();
                }
                if missing_kind == "no-live-auth" {
                    fs::remove_file(codex_auth_path()).unwrap();
                }
                let result =
                    disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();
                assert_eq!(
                    result[0]["authCleanup"]["reason"],
                    "native_signed_out_after_missing_official_auth"
                );
                assert_eq!(result[0]["authCleanup"]["restored"], false);
                assert!(!codex_auth_path().exists());
                assert!(configured_root_value(
                    &read_text_if_exists(&codex_config_path()).unwrap(), "model_provider"
                ).is_none());
                for path in codex_relay_restore::artifact_paths() {
                    assert!(!path.exists(), "{}", path.display());
                }
                let registry = read_registry().unwrap();
                assert_eq!(registry["activeAccountKey"], "");
                let account = codex_registry_item_for_key(&registry, &key).unwrap();
                assert_eq!(account["requiresReauth"], true);
                assert_eq!(account["canSwitch"], false);
                assert_eq!(
                    read_json_if_exists(&snapshot_path_for_key(&auth_account_key(&other))).unwrap(),
                    Some(other)
                );
                // Closing again must not activate some other saved account.
                disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();
                assert!(!codex_auth_path().exists());
                assert_eq!(read_registry().unwrap()["activeAccountKey"], "");
            });
        }
    }

