    #[test]
    fn relay_close_unavailable_baseline_preserves_unrelated_live_auth() {
        for missing in [true, false] {
            for personal_api in [true, false] {
                with_temp_user_home("relay-close-unavailable-preserves-current", |_root| {
                    let original =
                        test_codex_chatgpt_auth("original@example.com", "original", "original");
                    write_json_pretty(&codex_auth_path(), &original).unwrap();
                    configure_codex_all_route_targets(
                        "relay-key",
                        GAOGE_OPENAI_BASE_URL,
                        "gpt-5.5",
                        true,
                        None,
                        true,
                    )
                    .unwrap();
                    let key = auth_account_key(&original);
                    if missing {
                        fs::remove_file(snapshot_path_for_key(&key)).unwrap();
                    } else {
                        let expired = test_codex_chatgpt_auth_with_exp(
                            "original@example.com",
                            "original",
                            "original",
                            unix_now() - 60,
                            false,
                        );
                        write_json_pretty(&snapshot_path_for_key(&key), &expired).unwrap();
                    }
                    let current = if personal_api {
                        build_codex_api_auth("unrelated-personal-api-key")
                    } else {
                        test_codex_chatgpt_auth("other@example.com", "other", "other")
                    };
                    write_json_pretty(&codex_auth_path(), &current).unwrap();
                    let result =
                        disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();
                    assert_eq!(
                        read_json_if_exists(&codex_auth_path()).unwrap(),
                        Some(current.clone())
                    );
                    assert_eq!(result[0]["authCleanup"]["removed"], false);
                    assert_eq!(
                        result[0]["authCleanup"]["reason"],
                        if missing {
                            "preserved_current_auth_after_missing_official_auth"
                        } else {
                            "preserved_current_auth_after_invalid_official_auth"
                        }
                    );
                    assert_eq!(
                        read_registry().unwrap()["activeAccountKey"],
                        if personal_api {
                            String::new()
                        } else {
                            auth_account_key(&current)
                        }
                    );
                    assert!(configured_root_value(
                        &read_text_if_exists(&codex_config_path()).unwrap(), "model_provider"
                    ).is_none());
                });
            }
        }
    }

    #[test]
    fn relay_close_expired_unrefreshable_official_auth_returns_to_login() {
        for force_api in [true, false] {
            for missing_snapshot in [true, false] {
                with_temp_user_home("relay-close-unrefreshable-official-auth", |_root| {
                    let original =
                        test_codex_chatgpt_auth("original@example.com", "original", "original");
                    write_json_pretty(&codex_auth_path(), &original).unwrap();
                    configure_codex_all_route_targets(
                        "relay-key",
                        GAOGE_OPENAI_BASE_URL,
                        "gpt-5.5",
                        true,
                        None,
                        force_api,
                    )
                    .unwrap();
                    let expired = test_codex_chatgpt_auth_with_exp(
                        "original@example.com",
                        "original",
                        "original",
                        unix_now() - 60,
                        false,
                    );
                    let key = auth_account_key(&original);
                    let snapshot_path = snapshot_path_for_key(&key);
                    if missing_snapshot {
                        fs::remove_file(&snapshot_path).unwrap();
                    } else {
                        write_json_pretty(&snapshot_path, &expired).unwrap();
                    }
                    if !force_api {
                        write_json_pretty(&codex_auth_path(), &expired).unwrap();
                    }
                    let result =
                        disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();
                    assert_eq!(
                        result[0]["authCleanup"]["reason"],
                        if missing_snapshot && force_api {
                            "native_signed_out_after_missing_official_auth"
                        } else {
                            "native_signed_out_after_invalid_official_auth"
                        }
                    );
                    assert!(!codex_auth_path().exists());
                    let registry = read_registry().unwrap();
                    assert_eq!(registry["activeAccountKey"], "");
                    assert_eq!(
                        codex_registry_item_for_key(&registry, &key).unwrap()["requiresReauth"],
                        true
                    );
                    // Invalid saved credentials remain available for account management.
                    if !missing_snapshot {
                        assert_eq!(read_json_if_exists(&snapshot_path).unwrap(), Some(expired));
                    }
                });
            }
        }
    }

    #[test]
    fn relay_close_does_not_discard_refreshable_near_expiry_or_opaque_auth() {
        for kind in ["refreshable", "near-expiry", "opaque"] {
            with_temp_user_home("relay-close-usable-saved-auth", |_root| {
                let original =
                    test_codex_chatgpt_auth("original@example.com", "original", "original");
                write_json_pretty(&codex_auth_path(), &original).unwrap();
                configure_codex_all_route_targets(
                    "relay-key",
                    GAOGE_OPENAI_BASE_URL,
                    "gpt-5.5",
                    true,
                    None,
                    true,
                )
                .unwrap();
                let mut saved = test_codex_chatgpt_auth_with_exp(
                    "original@example.com",
                    "original",
                    "original",
                    if kind == "refreshable" {
                        unix_now() - 60
                    } else {
                        unix_now() + 90
                    },
                    kind == "refreshable",
                );
                if kind == "opaque" {
                    saved["tokens"]["access_token"] = json!("opaque-token-with-no-local-expiry");
                }
                write_json_pretty(&snapshot_path_for_key(&auth_account_key(&original)), &saved)
                    .unwrap();
                // A prior transient validation failure is not proof of expiry.
                mark_codex_account_requires_reauth(
                    &auth_account_key(&original),
                    "temporary network failure",
                )
                .unwrap();
                let result =
                    disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();
                assert_eq!(result[0]["authCleanup"]["restored"], true);
                assert_eq!(
                    read_json_if_exists(&codex_auth_path()).unwrap(),
                    Some(saved)
                );
            });
        }
    }

