    #[test]
    fn relay_close_missing_secondary_snapshot_does_not_block_other_directories() {
        with_temp_user_home("relay-close-missing-secondary-snapshot", |root| {
            let primary_dir = root.join(".codex");
            let secondary_dir = root.join("external-codex").join(".codex");
            std::env::set_var("CODEX_HOME", &secondary_dir);
            let primary_auth = test_codex_chatgpt_auth("primary@example.com", "primary", "primary");
            let secondary_auth =
                test_codex_chatgpt_auth("secondary@example.com", "secondary", "secondary");
            for (dir, auth) in [
                (&primary_dir, &primary_auth),
                (&secondary_dir, &secondary_auth),
            ] {
                with_codex_dir(dir, || {
                    fs::create_dir_all(codex_dir()).unwrap();
                    fs::write(codex_config_path(), "model = \"original-model\"\n").unwrap();
                    write_json_pretty(&codex_auth_path(), auth).unwrap();
                });
            }
            configure_codex_all_route_targets(
                "relay-key",
                GAOGE_OPENAI_BASE_URL,
                "gpt-5.5",
                true,
                None,
                true,
            )
            .unwrap();
            with_codex_dir(&secondary_dir, || {
                fs::remove_file(snapshot_path_for_key(&auth_account_key(&secondary_auth))).unwrap();
            });
            let result =
                disable_codex_fuel_pack_all_route_targets("relay-key", true, None).unwrap();
            assert_eq!(result.len(), 2);
            with_codex_dir(&primary_dir, || {
                assert_eq!(
                    read_json_if_exists(&codex_auth_path()).unwrap(),
                    Some(primary_auth)
                );
            });
            with_codex_dir(&secondary_dir, || {
                assert!(!codex_auth_path().exists());
                assert_eq!(read_registry().unwrap()["activeAccountKey"], "");
            });
            for dir in [&primary_dir, &secondary_dir] {
                with_codex_dir(dir, || {
                    let config = read_text_if_exists(&codex_config_path()).unwrap();
                    assert_eq!(
                        configured_root_value(&config, "model").as_deref(),
                        Some("original-model")
                    );
                    assert!(configured_root_value(&config, "model_provider").is_none());
                    assert!(codex_relay_restore::artifact_paths()
                        .iter()
                        .all(|path| !path.exists()));
                });
            }
            let warnings = codex_secondary_auth_restore_warnings(&result);
            assert_eq!(warnings.len(), 1);
            let warning = warnings[0].as_str().unwrap();
            assert!(warning.contains(secondary_dir.to_str().unwrap()));
            assert!(warning.contains("原账号登录凭据缺失"));
            assert!(warning.contains("重新登录"));
        });
    }

