    #[test]
    fn codex_route_transaction_restores_model_catalog_without_deleting_new_account_files() {
        with_temp_user_home("codex-route-transaction-catalog", |_root| {
            fs::create_dir_all(codex_dir()).unwrap();
            let catalog_path = codex_dir().join(CODEX_MODEL_CATALOG_FILE);
            let original_catalog = br#"{"models":["gpt-5.5"]}"#;
            fs::write(&catalog_path, original_catalog).unwrap();

            let accounts_dir = codex_accounts_dir();
            fs::create_dir_all(&accounts_dir).unwrap();
            let preexisting_account = accounts_dir.join("preexisting.json");
            let new_account = accounts_dir.join("created-during-transaction.json");
            fs::write(&preexisting_account, b"before").unwrap();

            let snapshot = CodexRouteTransactionSnapshot::capture(&codex_route_targets()).unwrap();
            fs::write(&catalog_path, br#"{"models":["gpt-5.6-sol"]}"#).unwrap();
            fs::write(&new_account, b"external").unwrap();

            snapshot.restore().unwrap();
            assert_eq!(fs::read(&catalog_path).unwrap(), original_catalog);
            assert_eq!(fs::read(&preexisting_account).unwrap(), b"before");
            assert_eq!(fs::read(&new_account).unwrap(), b"external");

            fs::remove_file(&catalog_path).unwrap();
            let absent_snapshot =
                CodexRouteTransactionSnapshot::capture(&codex_route_targets()).unwrap();
            fs::write(&catalog_path, br#"{"models":["gpt-6-sol"]}"#).unwrap();
            absent_snapshot.restore().unwrap();
            assert!(!catalog_path.exists());
        });
    }

