    #[test]
    fn relay_login_migrates_legacy_auth_backup() {
        if !secure_storage_available() {
            return;
        }
        with_temp_user_home("relay-login-migrate-auth", |_root| {
            let original = build_codex_api_auth("legacy-personal-api-secret");
            write_json_pretty(&codex_auth_path(), &build_codex_api_auth("old-relay-key")).unwrap();
            let restore_path = codex_relay_restore::artifact_paths()[1].clone();
            write_json_pretty(&restore_path, &json!({
                "root_lines": [],
                "fast_mode_lines": [],
                "official_account_key": null,
                "legacy": false,
                "api_key_hashes": [],
                "auth_baseline_captured": true,
                "preserved_auth": original,
                "preserved_active_account_key": "personal-before-relay",
            })).unwrap();
            configure_codex_all_route_targets(
                "new-relay-key", GAOGE_OPENAI_BASE_URL, "gpt-5.5", true, None, true,
            ).unwrap();
            let saved = fs::read_to_string(&restore_path).unwrap();
            assert!(!saved.contains("legacy-personal-api-secret"));
            assert!(!saved.contains("\"preserved_auth\""));
            let state: Value = serde_json::from_str(&saved).unwrap();
            let encrypted = state["encrypted_preserved_auth"].as_str().unwrap();
            assert!(!encrypted.is_empty());
            let restored: Value = serde_json::from_str(&decrypt_secret(encrypted).unwrap().unwrap()).unwrap();
            assert_eq!(restored, original);
            disable_codex_fuel_pack_all_route_targets("new-relay-key", true, None).unwrap();
            assert_eq!(read_json_if_exists(&codex_auth_path()).unwrap().unwrap(), original);
            assert_eq!(read_registry().unwrap()["activeAccountKey"], "personal-before-relay");
        });
    }

