    fn with_official_account_switch_fixture(
        label: &str,
        scenario: impl FnOnce(&[PathBuf], &ActiveCodexAccountSnapshot),
    ) {
        with_temp_user_home(label, |root| {
            let original_router = ROUTER_STATE.lock().unwrap().clone();
            let original_aggregate = AGGREGATE_LOGIN_STATE.lock().unwrap().clone();
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let homes = vec![root.join(".codex"), root.join("external-codex")];
                std::env::set_var("CODEX_HOME", &homes[1]);
                let original =
                    test_codex_chatgpt_auth("original@example.com", "original-user", "original");
                let selected =
                    test_codex_chatgpt_auth("selected@example.com", "selected-user", "selected");
                for home in &homes {
                    with_codex_dir(home, || {
                        write_json_pretty(&codex_auth_path(), &original).unwrap();
                        upsert_account(&original, None, true).unwrap();
                        upsert_account(&selected, None, false).unwrap();
                        fs::write(codex_config_path(), "model = \"gpt-5.5\"\n").unwrap();
                    });
                }
                configure_codex_all_route_targets(
                    "relay-key", GAOGE_OPENAI_BASE_URL, "gpt-5.5", true, None, false,
                )
                .unwrap();
                let mut router = default_router_state();
                router.mode = "relay".to_string();
                router.relay_api_key = "relay-key".to_string();
                router.relay_base_url = GAOGE_OPENAI_BASE_URL.to_string();
                save_router_state(router).unwrap();
                let mut aggregate = default_aggregate_login_state();
                aggregate.enabled = true;
                aggregate.official_account_key = auth_account_key(&original);
                aggregate.router_token = "fixture-aggregate-token".to_string();
                aggregate.routes.push(AggregateProviderRoute {
                    source: Default::default(),
                    protocol: Default::default(),
                    model_config: Value::Null,
                    provider_id: "openai".to_string(),
                    provider_name: "Fixture".to_string(),
                    upstream_platform: "openai".to_string(),
                    group_id: "fixture".to_string(),
                    group_name: "Fixture".to_string(),
                    group_rate_text: String::new(),
                    public_model: "gpt-5.5".to_string(),
                    upstream_model: "gpt-5.5".to_string(),
                    base_url: "https://fixture.example.invalid/v1".to_string(),
                    api_key: "fixture-route-key".to_string(),
                });
                save_aggregate_login_state(&aggregate).unwrap();
                let selected_key = auth_account_key(&selected);
                let selected = ActiveCodexAccountSnapshot {
                    snapshot_path: snapshot_path_for_key(&selected_key),
                    account_key: selected_key,
                    auth: selected,
                };
                scenario(&homes, &selected);
            }));
            *ROUTER_STATE.lock().unwrap() = original_router;
            *AGGREGATE_LOGIN_STATE.lock().unwrap() = original_aggregate;
            if let Err(panic) = outcome {
                std::panic::resume_unwind(panic);
            }
        });
    }

    fn assert_official_account_switch_rollback(failure_stage: &str) {
        with_official_account_switch_fixture(failure_stage, |homes, selected| {
            if failure_stage == "secondary-home" {
                with_codex_dir(&homes[1], || {
                    let restore_path = codex_relay_restore::artifact_paths()[1].clone();
                    fs::write(restore_path, b"{broken-restore").unwrap();
                });
            }
            let routes_before =
                CodexRouteTransactionSnapshot::capture(&codex_route_targets()).unwrap();
            let outer_before = CodexDisableOuterStateSnapshot::capture().unwrap();
            let mut reached_outer_state = false;
            let error = run_codex_official_account_switch_transaction(
                selected,
                true,
                |router| {
                    reached_outer_state = true;
                    for home in homes {
                        with_codex_dir(home, || {
                            assert_eq!(
                                read_json_if_exists(&codex_auth_path()).unwrap(),
                                Some(selected.auth.clone()),
                            );
                            assert_eq!(
                                read_registry().unwrap()["activeAccountKey"],
                                selected.account_key,
                            );
                        });
                    }
                    // Inject a failure after a state write, so rollback must
                    // restore persisted bytes as well as in-memory state.
                    save_router_state(router)?;
                    if failure_stage == "aggregate-save" {
                        save_aggregate_login_state(&default_aggregate_login_state())?;
                    }
                    Err(format!("injected-{failure_stage}-failure"))
                },
            )
            .unwrap_err();
            if failure_stage == "secondary-home" {
                assert!(!reached_outer_state);
                assert!(error.contains("恢复 Codex 官方路由失败"));
            } else {
                assert!(reached_outer_state);
                assert!(error.contains(&format!("injected-{failure_stage}-failure")));
            }
            assert!(!error.contains("自动回滚失败"), "{error}");
            for snapshot in routes_before.files.iter().chain([
                &outer_before.router_file,
                &outer_before.aggregate_file,
            ]) {
                assert_eq!(
                    fs::read(&snapshot.path).ok(),
                    snapshot.contents,
                    "{}",
                    snapshot.path.display(),
                );
            }
            assert_eq!(
                serde_json::to_value(ROUTER_STATE.lock().unwrap().clone()).unwrap(),
                serde_json::to_value(outer_before.router_state).unwrap(),
            );
            assert_eq!(
                serde_json::to_value(aggregate_login_state_snapshot()).unwrap(),
                serde_json::to_value(outer_before.aggregate_state).unwrap(),
            );
        });
    }

    #[test]
    fn official_account_switch_rolls_back_secondary_home_failure() {
        assert_official_account_switch_rollback("secondary-home");
    }

    #[test]
    fn official_account_switch_rolls_back_router_save_failure() {
        assert_official_account_switch_rollback("router-save");
    }

    #[test]
    fn official_account_switch_rolls_back_aggregate_save_failure() {
        assert_official_account_switch_rollback("aggregate-save");
    }

