    #[test]
    fn force_deleting_current_codex_account_closes_login_and_removes_all_snapshots() {
        with_temp_user_home("codex-force-delete-current-account", |_root| {
            let auth = test_codex_chatgpt_auth(
                "force-delete@example.com",
                "user-force-delete",
                "account-force-delete",
            );
            write_json_pretty(&codex_auth_path(), &auth).unwrap();
            let account = upsert_account(&auth, None, true).unwrap();
            let account_key = account
                .get("accountKey")
                .and_then(Value::as_str)
                .unwrap()
                .to_string();
            let registry = read_registry().unwrap();
            let snapshot_path = registry
                .get("items")
                .and_then(Value::as_array)
                .and_then(|items| {
                    items.iter().find(|item| {
                        item.get("accountKey").and_then(Value::as_str) == Some(account_key.as_str())
                    })
                })
                .and_then(|item| item.get("snapshotPath"))
                .and_then(Value::as_str)
                .map(PathBuf::from)
                .unwrap();
            let session_path = write_session_snapshot_for_key(
                &account_key,
                &json!({ "access_token": "session-token" }),
            )
            .unwrap();

            let error = gaoge_delete_codex_account_inner(json!({
              "accountKey": account_key
            }))
            .unwrap_err();
            assert!(error.contains("不能删除"));
            assert!(codex_auth_path().exists());
            assert!(snapshot_path.exists());
            assert!(session_path.exists());

            let result = gaoge_delete_codex_account_inner(json!({
              "accountKey": account_key,
              "force": true
            }))
            .unwrap();

            assert_eq!(result.get("forced").and_then(Value::as_bool), Some(true));
            assert_eq!(
                result.get("codexClosed").and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                result.get("liveAuthDeleted").and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                result.get("snapshotDeleted").and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                result
                    .get("sessionSnapshotDeleted")
                    .and_then(Value::as_bool),
                Some(true)
            );
            assert!(read_json_if_exists(&codex_auth_path()).unwrap().is_none());
            assert!(!snapshot_path.exists());
            assert!(!session_path.exists());

            let registry = read_registry().unwrap();
            assert_eq!(
                registry.get("activeAccountKey").and_then(Value::as_str),
                Some("")
            );
            assert!(!registry
                .get("items")
                .and_then(Value::as_array)
                .unwrap()
                .iter()
                .any(|item| {
                    item.get("accountKey").and_then(Value::as_str) == Some(account_key.as_str())
                }));
            assert!(!result
                .get("state")
                .and_then(|state| state.get("accounts"))
                .and_then(Value::as_array)
                .unwrap()
                .iter()
                .any(|item| {
                    item.get("accountKey").and_then(Value::as_str) == Some(account_key.as_str())
                }));
        });
    }

