    #[test]
    fn codex_session_manager_exports_manifest_markdown_and_raw_jsonl() {
        with_temp_user_home("codex-session-manager-export", |root| {
            let codex_home = root.join(".codex");
            let project = root.join("workspaces").join("export-project");
            let session_id = "01980e4f-4a31-7000-8000-000000000221";
            write_managed_test_rollout(
                &codex_home,
                false,
                session_id,
                "Export conversation",
                &project,
                None,
            );
            let export_path = root.join("exports").join("sessions.zip");

            let result = gaoge_export_codex_sessions_inner(json!({
                "filePath": export_path.to_string_lossy(),
                "sessionIds": [session_id]
            }))
            .unwrap();

            assert_eq!(result["exportedCount"].as_u64(), Some(1));
            assert!(export_path.exists());
            let mut archive = ZipArchive::new(fs::File::open(&export_path).unwrap()).unwrap();
            let names = (0..archive.len())
                .map(|index| archive.by_index(index).unwrap().name().to_string())
                .collect::<Vec<_>>();
            let prefix = format!("sessions/0001-{session_id}");
            assert!(names.contains(&"manifest.json".to_string()));
            assert!(names.contains(&format!("{prefix}/metadata.json")));
            assert!(names.contains(&format!("{prefix}/conversation.md")));
            assert!(names.contains(&format!("{prefix}/conversation.jsonl")));

            let manifest = {
                let mut text = String::new();
                archive
                    .by_name("manifest.json")
                    .unwrap()
                    .read_to_string(&mut text)
                    .unwrap();
                serde_json::from_str::<Value>(&text).unwrap()
            };
            assert_eq!(manifest["sessionCount"].as_u64(), Some(1));
            assert_eq!(manifest["sessions"][0]["id"], session_id);

            let markdown = {
                let mut text = String::new();
                archive
                    .by_name(&format!("{prefix}/conversation.md"))
                    .unwrap()
                    .read_to_string(&mut text)
                    .unwrap();
                text
            };
            assert!(markdown.contains("# Export conversation"));
            assert!(markdown.contains("## 用户"));
            assert!(markdown.contains("用户问题：Export conversation"));
            assert!(markdown.contains("## 助手"));
            assert!(markdown.contains("助手回答：Export conversation"));

            let raw = {
                let mut text = String::new();
                archive
                    .by_name(&format!("{prefix}/conversation.jsonl"))
                    .unwrap()
                    .read_to_string(&mut text)
                    .unwrap();
                text
            };
            assert!(raw.contains("session_meta"));
            assert!(raw.contains(session_id));
        });
    }

