    #[test]
    fn official_rollout_sync_normalizes_legacy_message_and_function_ids() {
        let suffix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "gaoge-rollout-official-message-id-{}-{suffix}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        let file = root.join("rollout-official.jsonl");
        let header = json!({
            "type": "session_meta",
            "payload": { "id": "session-official", "model_provider": "openai" }
        })
        .to_string();
        let legacy_message = json!({
            "type": "response_item",
            "payload": {
                "type": "message",
                "id": "item_aaaaaaaaaaaaaaaaaaaaaaaa",
                "role": "assistant",
                "content": [{ "type": "output_text", "text": "legacy aggregate text" }]
            }
        })
        .to_string();
        let official_message = json!({
            "type": "response_item",
            "payload": {
                "type": "message",
                "id": "msg_keep_official",
                "role": "assistant",
                "content": [{ "type": "output_text", "text": "official text" }]
            }
        })
        .to_string();
        let function_call = json!({
            "type": "response_item",
            "payload": {
                "type": "function_call",
                "id": "item_bbbbbbbbbbbbbbbbbbbbbbbb",
                "call_id": "call_keep",
                "name": "exec",
                "arguments": "{}"
            }
        })
        .to_string();
        let reasoning = json!({
            "type": "response_item",
            "payload": {
                "type": "reasoning",
                "id": "item_cccccccccccccccccccccccc",
                "summary": []
            }
        })
        .to_string();
        let user_message = json!({
            "type": "response_item",
            "payload": {
                "type": "message",
                "id": "item_dddddddddddddddddddddddd",
                "role": "user",
                "content": [{ "type": "input_text", "text": "leave user history alone" }]
            }
        })
        .to_string();
        // Current local Codex rollout files contain no structured item_reference
        // records; item_id only appeared inside opaque tool-output strings in the
        // schema audit. Keep unknown reference shapes byte-for-byte until Codex
        // persists a documented relationship that can be updated safely.
        let unknown_item_reference = json!({
            "type": "response_item",
            "payload": {
                "type": "item_reference",
                "id": "item_ffffffffffffffffffffffff"
            }
        })
        .to_string();
        let uppercase_legacy_message = json!({
            "type": "response_item",
            "payload": {
                "type": "message",
                "id": "item_AAAAAAAAAAAAAAAAAAAAAAAA",
                "role": "assistant",
                "content": [{ "type": "output_text", "text": "leave unknown ID shapes alone" }]
            }
        })
        .to_string();
        let malformed = r#"{"type":"response_item","payload":{"type":"message","id":"item_eeeeeeeeeeeeeeeeeeeeeeee""#;
        let original = [
            header.clone(),
            legacy_message,
            official_message.clone(),
            function_call.clone(),
            reasoning.clone(),
            user_message.clone(),
            unknown_item_reference.clone(),
            uppercase_legacy_message.clone(),
            malformed.to_string(),
        ]
        .join("\r\n")
            + "\r\n";
        fs::write(&file, original).unwrap();

        let (provider_changed, _, normalized, warning) =
            sync_rollout_for_target_provider(&file, "openai", true).unwrap();

        assert!(!provider_changed);
        assert_eq!(normalized, 2);
        assert!(warning.is_none());
        let repaired = fs::read_to_string(&file).unwrap();
        let rows = repaired.lines().collect::<Vec<_>>();
        assert_eq!(rows[0], header);
        assert_eq!(
            serde_json::from_str::<Value>(rows[1]).unwrap()["payload"]["id"],
            "msg_aaaaaaaaaaaaaaaaaaaaaaaa"
        );
        assert_eq!(rows[2], official_message);
        let mut expected_call = serde_json::from_str::<Value>(&function_call).unwrap();
        expected_call["payload"]["id"] = json!("fc_bbbbbbbbbbbbbbbbbbbbbbbb");
        assert_eq!(
            serde_json::from_str::<Value>(rows[3]).unwrap(),
            expected_call
        );
        assert_eq!(rows[4], reasoning);
        assert_eq!(rows[5], user_message);
        assert_eq!(rows[6], unknown_item_reference);
        assert_eq!(rows[7], uppercase_legacy_message);
        assert_eq!(rows[8], malformed);
        assert!(repaired.ends_with("\r\n"));

        let before_second_run = fs::read(&file).unwrap();
        let (provider_changed, _, normalized, warning) =
            sync_rollout_for_target_provider(&file, "openai", true).unwrap();
        assert!(!provider_changed);
        assert_eq!(normalized, 0);
        assert!(warning.is_none());
        assert_eq!(fs::read(&file).unwrap(), before_second_run);

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn official_rollout_sync_repairs_ids_after_same_length_provider_fast_path() {
        let suffix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "gaoge-rollout-official-message-id-fast-path-{}-{suffix}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        let file = root.join("rollout-custom.jsonl");
        let header = r#"{ "type": "session_meta", "payload": { "id": "session-fast", "model_provider": "custom" } }"#;
        let message = r#"{"type":"response_item","payload":{"type":"message","id":"item_1234567890abcdef12345678","role":"assistant","content":[{"type":"output_text","text":"repair me"}]}}"#;
        fs::write(&file, format!("{header}\n{message}\n")).unwrap();

        let (provider_changed, _, normalized, warning) =
            sync_rollout_for_target_provider(&file, "openai", true).unwrap();

        assert!(provider_changed);
        assert_eq!(normalized, 1);
        assert!(warning.is_none());
        let repaired = fs::read_to_string(&file).unwrap();
        let rows = repaired.lines().collect::<Vec<_>>();
        assert_eq!(
            serde_json::from_str::<Value>(rows[0]).unwrap()["payload"]["model_provider"],
            "openai"
        );
        assert_eq!(
            serde_json::from_str::<Value>(rows[1]).unwrap()["payload"]["id"],
            "msg_1234567890abcdef12345678"
        );

        let relay_file = root.join("rollout-relay.jsonl");
        fs::write(&relay_file, format!("{header}\n{message}\n")).unwrap();
        let (provider_changed, _, normalized, warning) =
            sync_rollout_for_target_provider(&relay_file, "custom", true).unwrap();
        assert!(!provider_changed);
        assert_eq!(normalized, 1);
        assert!(warning.is_none());
        assert!(fs::read_to_string(&relay_file)
            .unwrap()
            .contains("\"id\":\"msg_1234567890abcdef12345678\""));

        let _ = fs::remove_dir_all(root);
    }

