    #[test]
    fn config_write_gate_fails_closed_when_process_exit_is_unconfirmed() {
        let mut stop_called = false;
        let mut wait_called = false;
        let result = require_codex_exit_before_config_write(
            || {
                stop_called = true;
                true
            },
            || {
                wait_called = true;
                Err("simulated running writer".to_string())
            },
        );
        let mut downstream_write_performed = false;
        if result.is_ok() {
            downstream_write_performed = true;
        }

        assert!(stop_called);
        assert!(wait_called);
        assert!(result.is_err());
        assert!(!downstream_write_performed);

        let already_stopped = require_codex_exit_before_config_write(|| false, || Ok(()));
        assert_eq!(already_stopped, Ok(true));
    }

    #[test]
    fn codex_exit_probe_requires_two_consecutive_empty_snapshots() {
        let mut consecutive_stopped_checks = 0;
        assert!(!observe_codex_exit_probe(&mut consecutive_stopped_checks, Ok(true)).unwrap());
        assert_eq!(consecutive_stopped_checks, 1);
        assert!(!observe_codex_exit_probe(&mut consecutive_stopped_checks, Ok(false)).unwrap());
        assert_eq!(consecutive_stopped_checks, 0);
        assert!(!observe_codex_exit_probe(&mut consecutive_stopped_checks, Ok(true)).unwrap());
        assert!(observe_codex_exit_probe(&mut consecutive_stopped_checks, Ok(true)).unwrap());
    }

    #[test]
    fn codex_exit_probe_errors_fail_closed() {
        let mut consecutive_stopped_checks = 1;
        let result = observe_codex_exit_probe(
            &mut consecutive_stopped_checks,
            Err("process scan failed".to_string()),
        );
        assert!(result.is_err());
        assert_eq!(consecutive_stopped_checks, 1);
    }

    #[test]
    fn codex_exit_wait_retries_survivors_until_two_clean_snapshots() {
        let survivor = RunningCodexProcess {
            pid: 4242,
            executable_path: PathBuf::from(
                r"C:\Program Files\WindowsApps\OpenAI.Codex\app\resources\codex.exe",
            ),
            app_dir: PathBuf::from(r"C:\Program Files\WindowsApps\OpenAI.Codex\app"),
        };
        let mut snapshots = vec![vec![survivor], Vec::new(), Vec::new()].into_iter();
        let mut retried_pids = Vec::new();

        let result = wait_for_codex_process_exit_with_probe(
            Duration::from_secs(1),
            Duration::ZERO,
            || Ok(snapshots.next().unwrap_or_default()),
            |running| retried_pids.extend(running.iter().map(|process| process.pid)),
        );

        assert_eq!(result, Ok(()));
        assert_eq!(retried_pids, vec![4242]);
    }

    #[test]
    fn codex_exit_wait_reports_the_process_that_remains() {
        let survivor = RunningCodexProcess {
            pid: 7331,
            executable_path: PathBuf::from(r"C:\Codex\resources\codex.exe"),
            app_dir: PathBuf::from(r"C:\Codex"),
        };
        let mut retry_count = 0;

        let error = wait_for_codex_process_exit_with_probe(
            Duration::ZERO,
            Duration::ZERO,
            || Ok(vec![survivor.clone()]),
            |_| retry_count += 1,
        )
        .unwrap_err();

        assert_eq!(retry_count, 1);
        assert!(error.contains("PID 7331"));
        assert!(error.contains(r"C:\Codex\resources\codex.exe"));
    }

    #[test]
    fn official_rollout_atomic_rewrite_preserves_a_concurrent_append() {
        let suffix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "gaoge-rollout-concurrent-append-{}-{suffix}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        let file = root.join("rollout-racing.jsonl");
        let original = concat!(
            "{\"type\":\"session_meta\",\"payload\":{\"id\":\"racing\",\"model_provider\":\"custom\"}}\n",
            "{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"id\":\"item_1234567890abcdef12345678\",\"role\":\"assistant\",\"content\":[]}}\n"
        );
        let appended = "{\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\"}}\n";
        fs::write(&file, original).unwrap();

        let append_target = file.clone();
        let (provider_changed, _, _, normalized, warning) =
            rewrite_rollout_for_official_with_before_replace(&file, || {
                let mut target = fs::OpenOptions::new()
                    .append(true)
                    .open(&append_target)
                    .unwrap();
                target.write_all(appended.as_bytes()).unwrap();
                target.sync_all().unwrap();
            }, false)
            .unwrap();

        assert!(!provider_changed);
        assert_eq!(normalized, 0);
        assert!(warning.is_some());
        assert_eq!(
            fs::read_to_string(&file).unwrap(),
            format!("{original}{appended}")
        );
        let _ = fs::remove_dir_all(root);
    }

