    #[test]
    fn rollout_scan_cache_skips_unchanged_bodies_and_invalidates_on_change() {
        with_temp_user_home("codex-rollout-scan-cache", |root| {
            let codex_home = root.join(".codex");
            let sessions = codex_home.join("sessions");
            fs::create_dir_all(&sessions).unwrap();
            let file = sessions.join("rollout-cache.jsonl");
            fs::write(
                &file,
                [
                    json!({
                        "type": "session_meta",
                        "payload": {
                            "id": "session-cache",
                            "timestamp": "2026-07-23T00:00:00Z",
                            "model_provider": "openai",
                            "cwd": root.to_string_lossy(),
                            "source": {
                                "subagent": {
                                    "thread_spawn": {
                                        "parent_thread_id": "session-parent",
                                        "agent_nickname": "cache-worker",
                                        "depth": 1
                                    }
                                }
                            }
                        }
                    })
                    .to_string(),
                    json!({
                        "type": "event_msg",
                        "payload": {"role": "user", "content": "cache me"}
                    })
                    .to_string(),
                ]
                .join("\n")
                    + "\n",
            )
            .unwrap();

            let files = vec![file.clone()];
            let (first, first_errors, first_hits, first_misses) =
                scan_rollout_files(&files, "openai");
            assert!(first_errors.is_empty());
            assert_eq!((first_hits, first_misses), (0, 1));
            assert_eq!(first.len(), 1);

            // A missing compatibility counter is unchecked history, not zero
            // incompatible items. Rebuild the checkpoint before reusing it.
            let cache_path = rollout_scan_cache_path();
            let mut previous_release_cache = read_json_if_exists(&cache_path).unwrap().unwrap();
            for entry in previous_release_cache["entries"]
                .as_object_mut()
                .unwrap()
                .values_mut()
            {
                entry
                    .as_object_mut()
                    .unwrap()
                    .remove("legacy_api_incompatible_items");
            }
            fs::write(&cache_path, previous_release_cache.to_string()).unwrap();

            let (second, second_errors, second_hits, second_misses) =
                scan_rollout_files(&files, "openai");
            assert!(second_errors.is_empty());
            assert_eq!((second_hits, second_misses), (0, 1));
            assert_eq!(second[0].id, "session-cache");
            assert_eq!(second[0].thread_source, "subagent");
            assert_eq!(
                second[0].parent_thread_id.as_deref(),
                Some("session-parent")
            );
            assert_eq!(second[0].agent_nickname.as_deref(), Some("cache-worker"));

            let mut handle = fs::OpenOptions::new().append(true).open(&file).unwrap();
            writeln!(
                handle,
                "{}",
                json!({"type":"event_msg","payload":{"role":"assistant","content":"changed"}})
            )
            .unwrap();
            drop(handle);
            let (_, third_errors, third_hits, third_misses) = scan_rollout_files(&files, "openai");
            assert!(third_errors.is_empty());
            assert_eq!((third_hits, third_misses), (0, 1));
            assert!(rollout_scan_cache_path().exists());
            assert!(!codex_home.join("backups").exists());
        });
    }

    #[test]
    fn header_scan_reads_bounded_windows_for_large_rollouts() {
        with_temp_user_home("codex-rollout-header-scan", |root| {
            let file = root
                .join(".codex")
                .join("sessions")
                .join("rollout-large-header.jsonl");
            fs::create_dir_all(file.parent().unwrap()).unwrap();
            let meta = json!({
                "type": "session_meta",
                "payload": {
                    "id": "session-large-header",
                    "timestamp": "2026-09-27T00:00:00Z",
                    "model_provider": "openai",
                    "title": "Large history",
                }
            });
            let mut writer = BufWriter::new(fs::File::create(&file).unwrap());
            writeln!(writer, "{meta}").unwrap();
            // Keep the middle larger than the bounded header/tail window. The
            // summary must remain lightweight even when the body is huge.
            let filler = "x".repeat(16 * 1024);
            for _ in 0..32 {
                writeln!(
                    writer,
                    "{}",
                    json!({
                        "type": "response_item",
                        "payload": {"type": "message", "role": "assistant", "content": filler}
                    })
                )
                .unwrap();
            }
            writeln!(
                writer,
                "{}",
                json!({
                    "type": "event_msg",
                    "timestamp": "2026-09-27T00:05:00Z",
                    "payload": {"type": "token_count"}
                })
            )
            .unwrap();
            drop(writer);

            let entry = scan_rollout_file_header_details(&file).unwrap();
            assert!(entry.size_bytes > (FAST_ROLLOUT_WINDOW_BYTES as u64));
            assert!(!entry.body_scanned);
            assert!(!entry.summary.body_scanned);
            // A bounded scan intentionally reports an unknown line count; it
            // must not claim that it walked every body line.
            assert_eq!(entry.summary.line_count, 2);
            assert_eq!(entry.summary.id, "session-large-header");
            assert_eq!(entry.summary.title, "Large history");
            assert_eq!(entry.summary.provider, "openai");
        });
    }

