    #[test]
    #[ignore = "isolated large-history performance benchmark"]
    fn benchmark_incremental_session_sync() {
        with_temp_user_home("incremental-benchmark", |root| {
            let file = write_incremental_test_rollout(
                root,
                "01980e4f-4a31-7000-8000-000000000251",
                "openai",
                None,
                false,
            );
            let mut writer =
                BufWriter::new(fs::OpenOptions::new().append(true).open(&file).unwrap());
            let line = json!({"type":"response_item","payload":{"type":"function_call_output","output":"x".repeat(16 * 1024)}}).to_string();
            for _ in 0..16_384 {
                writeln!(writer, "{line}").unwrap();
            }
            drop(writer);
            let size = fs::metadata(&file).unwrap().len();
            let original = fs::read(&file).unwrap();
            let baseline_started = Instant::now();
            // Former official-switch path always scanned IDs and then rescanned
            // the whole summary after changing the provider header.
            sync_rollout_for_target_provider(&file, "custom", true).unwrap();
            sync_rollout_for_target_provider(&file, "openai", true).unwrap();
            let text = fs::read_to_string(&file).unwrap();
            std::hint::black_box(first_user_text_from_rollout(&text));
            std::hint::black_box(rollout_embedded_timestamp_millis(&text));
            std::hint::black_box(text.lines().filter(|line| !line.trim().is_empty()).count());
            drop(text);
            let baseline_ms = baseline_started.elapsed().as_secs_f64() * 1000.0;
            let cold_started = Instant::now();
            let cold = sync_sessions("openai", true).unwrap();
            let cold_ms = cold_started.elapsed().as_secs_f64() * 1000.0;
            let mut measurements = Vec::new();
            for provider in ["custom", "openai", "openai"] {
                let started = Instant::now();
                let result = sync_sessions(provider, true).unwrap();
                assert_eq!(result["rolloutBodyBytesScanned"], 0);
                measurements.push(json!({"provider":provider,"elapsedMs":started.elapsed().as_secs_f64()*1000.0,"bodyBytesScanned":result["rolloutBodyBytesScanned"]}));
            }
            assert_eq!(fs::read(&file).unwrap(), original);
            eprintln!(
                "SESSION_SYNC_BENCHMARK {}",
                json!({"sizeBytes":size,"formerScanMs":baseline_ms,"coldMs":cold_ms,"coldBytes":cold["rolloutBodyBytesScanned"],"warm":measurements})
            );
        });
    }

    #[test]
    #[ignore = "requires GAOGE_SESSION_CACHE_SOURCE; reads history and only writes the scan cache"]
    fn warm_existing_session_scan_cache_read_only() {
        let Some(source) = std::env::var_os("GAOGE_SESSION_CACHE_SOURCE") else {
            return;
        };
        let source = PathBuf::from(source);
        assert!(source.is_absolute() && source.is_dir());
        with_codex_dir(&source, || {
            let started = Instant::now();
            let files = rollout_files();
            let source_bytes: u64 = files
                .iter()
                .filter_map(|path| fs::metadata(path).ok())
                .map(|metadata| metadata.len())
                .sum();
            let (rollouts, warnings, hits, misses) = scan_rollout_files(&files, "");
            let cache = read_rollout_scan_cache();
            let mut validated = 0;
            let mut changed_during_scan = 0;
            for file in &files {
                let Some(entry) = cache
                    .entries
                    .get(&codex_path_identity(file))
                    .filter(|entry| entry.matches(file))
                else {
                    changed_during_scan += 1;
                    continue;
                };
                let reader = BufReader::new(fs::File::open(file).unwrap());
                let meta = reader
                    .lines()
                    .map_while(Result::ok)
                    .find_map(|line| session_meta_value_from_line(&line));
                if let Some(meta) = meta {
                    assert_eq!(
                        meta["payload"]["id"].as_str(),
                        Some(entry.summary.id.as_str())
                    );
                    let hierarchy = rollout_hierarchy_from_payload(&meta["payload"]);
                    assert_eq!(hierarchy.parent_thread_id, entry.summary.parent_thread_id);
                    validated += 1;
                }
            }
            eprintln!(
                "SESSION_CACHE_AUDIT {}",
                json!({
                    "files":files.len(), "sourceBytes":source_bytes, "cachedSummaries":rollouts.len(),
                    "cacheHits":hits, "bodyScans":misses, "warnings":warnings.len(),
                    "validatedIdsAndParents":validated, "changedDuringScan":changed_during_scan,
                    "elapsedMs":started.elapsed().as_millis() as u64,
                })
            );
        });
    }

