    #[test]
    fn sync_sqlite_spawn_edges_restores_nested_subagents() {
        let mut conn = Connection::open_in_memory().unwrap();
        conn.execute_batch(
            "CREATE TABLE threads (id TEXT PRIMARY KEY, thread_source TEXT);
             CREATE TABLE thread_spawn_edges (
                parent_thread_id TEXT NOT NULL,
                child_thread_id TEXT PRIMARY KEY,
                status TEXT NOT NULL
             );",
        )
        .unwrap();
        let parent_id = "01980e4f-4a31-7000-8000-000000000130";
        let child_id = "01980e4f-4a31-7000-8000-000000000131";
        let grandchild_id = "01980e4f-4a31-7000-8000-000000000132";
        for id in [parent_id, child_id, grandchild_id] {
            conn.execute(
                "INSERT INTO threads (id, thread_source) VALUES (?1, 'user')",
                params![id],
            )
            .unwrap();
        }
        let mut child = test_rollout(child_id, PathBuf::from("child.jsonl"), "Child");
        child.source = "subagent".to_string();
        child.thread_source = "subagent".to_string();
        child.parent_thread_id = Some(parent_id.to_string());
        child.subagent_depth = Some(1);
        let mut grandchild = test_rollout(
            grandchild_id,
            PathBuf::from("grandchild.jsonl"),
            "Grandchild",
        );
        grandchild.source = "subagent".to_string();
        grandchild.thread_source = "subagent".to_string();
        grandchild.parent_thread_id = Some(child_id.to_string());
        grandchild.subagent_depth = Some(2);

        let (changed, warning) = sync_sqlite_spawn_edges(&mut conn, &[child, grandchild]).unwrap();

        assert_eq!(changed, 2);
        assert!(warning.is_empty());
        let edges = conn
            .prepare(
                "SELECT parent_thread_id, child_thread_id, status
                 FROM thread_spawn_edges ORDER BY child_thread_id",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })
            .unwrap()
            .flatten()
            .collect::<Vec<_>>();
        assert_eq!(
            edges,
            vec![
                (
                    parent_id.to_string(),
                    child_id.to_string(),
                    "open".to_string()
                ),
                (
                    child_id.to_string(),
                    grandchild_id.to_string(),
                    "open".to_string()
                )
            ]
        );
    }

