    #[test]
    fn gaoge_api_auth_detection_does_not_match_chatgpt_login() {
        let relay_auth = build_codex_api_auth("relay-key");
        let registry = json!({
          "items": [{
            "accountKey": auth_account_key(&relay_auth),
            "authMode": "api_key",
            "accountName": "Gaoge API",
            "workspaceName": "Gaoge",
            "profileName": "Gaoge API"
          }]
        });
        let chatgpt_auth = json!({
          "auth_mode": "chatgpt",
          "tokens": {
            "access_token": "access",
            "refresh_token": "refresh"
          }
        });
        let personal_api_auth = build_codex_api_auth("personal-key");

        assert!(codex_auth_is_gaoge_managed_api_auth(
            &relay_auth,
            "relay-key",
            &json!({})
        ));
        assert!(codex_auth_is_gaoge_managed_api_auth(
            &relay_auth,
            "",
            &registry
        ));
        assert!(!codex_auth_is_gaoge_managed_api_auth(
            &chatgpt_auth,
            "relay-key",
            &registry
        ));
        assert!(!codex_auth_is_gaoge_managed_api_auth(
            &personal_api_auth,
            "",
            &json!({})
        ));
    }

