    #[test]
    fn account_state_and_export_skip_api_key_only_entries() {
        with_temp_user_home("account-state-skips-api", |root| {
            let api_auth = build_codex_api_auth("relay-key");
            let api_account_key = auth_account_key(&api_auth);
            let api_snapshot_path = snapshot_path_for_key(&api_account_key);
            write_json_pretty(&codex_auth_path(), &api_auth).unwrap();
            write_json_pretty(&api_snapshot_path, &api_auth).unwrap();

            let real_auth = json!({
              "auth_mode": "chatgpt",
              "tokens": {
                "access_token": "access-token",
                "refresh_token": "refresh-token"
              }
            });
            let real_metadata = json!({
              "accountKey": "chatgpt-session::real",
              "email": "real@example.com",
              "authMode": "chatgpt",
              "accountName": "Personal",
              "workspaceName": "Personal",
              "profileName": "Real User"
            });
            let real_account = upsert_account(&real_auth, Some(&real_metadata), false).unwrap();
            let real_account_key = real_account
                .get("accountKey")
                .and_then(Value::as_str)
                .unwrap()
                .to_string();

            let mut registry = read_registry().unwrap();
            registry["activeAccountKey"] = Value::String(api_account_key.clone());
            registry
                .get_mut("items")
                .and_then(Value::as_array_mut)
                .unwrap()
                .push(json!({
                  "accountKey": api_account_key,
                  "authMode": "api_key",
                  "accountName": "Gaoge API",
                  "workspaceName": "Gaoge",
                  "profileName": "Gaoge API",
                  "snapshotPath": api_snapshot_path.to_string_lossy().to_string()
                }));
            write_registry(&registry).unwrap();

            let state = get_accounts_state_inner().unwrap();
            let accounts = state.get("accounts").and_then(Value::as_array).unwrap();
            assert_eq!(accounts.len(), 1);
            assert_eq!(
                accounts[0].get("accountKey").and_then(Value::as_str),
                Some(real_account_key.as_str())
            );
            assert!(state.get("currentAccount").unwrap().is_null());

            let export_path = root.join("accounts-export.json");
            let export_result = gaoge_export_codex_accounts_inner(json!({
              "filePath": export_path.to_string_lossy().to_string()
            }))
            .unwrap();
            assert_eq!(export_result.get("count").and_then(Value::as_u64), Some(1));

            let export_payload = read_json_if_exists(&export_path).unwrap().unwrap();
            let exported_accounts = export_payload
                .get("accounts")
                .and_then(Value::as_array)
                .unwrap();
            assert_eq!(exported_accounts.len(), 1);
            assert_eq!(
                exported_accounts[0]
                    .get("accountKey")
                    .and_then(Value::as_str),
                Some(real_account_key.as_str())
            );
        });
    }

