    #[test]
    fn plugin_market_choices_survive_legacy_global_switches() {
        let config = r#"
model = "keep-model"
[plugins."custom@codex-plus-plugin-market-012345abcdef"]
enabled = false
[plugins."other@codex-plus-plugin-market-abcdef012345"]
enabled = true
[plugins."similar@codex-plus-plugin-market-012345abcde"]
enabled = true
[plugins."github@openai-curated"]
enabled = false
"#;
        for requested in [true, false] {
            let (next, _) = set_codex_plugin_config(config, requested);
            assert_eq!(next, config);
            let doc = next.parse::<toml_edit::Document>().unwrap();
            assert_eq!(doc["model"].as_str(), Some("keep-model"));
            assert_eq!(doc["plugins"]["custom@codex-plus-plugin-market-012345abcdef"]["enabled"].as_bool(), Some(false));
            assert_eq!(doc["plugins"]["other@codex-plus-plugin-market-abcdef012345"]["enabled"].as_bool(), Some(true));
            assert_eq!(doc["plugins"]["similar@codex-plus-plugin-market-012345abcde"]["enabled"].as_bool(), Some(true));
            assert_eq!(doc["plugins"]["github@openai-curated"]["enabled"].as_bool(), Some(false));
        }
    }

