    #[test]
    fn session_delete_bridge_validates_token_and_routes_status_only() {
        let token = "test-session-delete-token";
        let request = json!({
          "token": token,
          "id": "12",
          "path": "/status",
          "payload": {},
        })
        .to_string();
        let (request_id, path, payload) =
            parse_codex_session_delete_bridge_call(&request, token).unwrap();
        assert_eq!(request_id, "12");
        assert_eq!(path, "/status");
        assert!(payload.is_object());

        let status = handle_codex_session_delete_bridge_request(&path, &payload);
        assert_eq!(status.get("ok").and_then(Value::as_bool), Some(true));
        assert_eq!(status.get("active").and_then(Value::as_bool), Some(true));

        assert!(
            parse_codex_session_delete_bridge_call(&request, "wrong-token")
                .unwrap_err()
                .contains("令牌")
        );
        let unsupported = handle_codex_session_delete_bridge_request("/unknown", &json!({}));
        assert_eq!(
            unsupported.get("status").and_then(Value::as_str),
            Some("failed")
        );
    }

