    #[test]
    fn codex_cdp_startup_connection_failures_are_treated_as_transient() {
        for error in [
            "由于目标计算机积极拒绝，无法连接。 (os error 10061)",
            "连接尝试失败，因为连接方在一段时间后没有正确答复。 (os error 10060)",
            "读取 Codex CDP 注入结果失败：A connection attempt failed because the connected party did not properly respond after a period of time. (os error 10060)",
            "读取 Codex CDP 注入结果失败：operation timed out",
            "Connection refused",
            "The target actively refused the connection",
            "读取 Codex CDP 注入结果失败：IO error: 远程主机强迫关闭了一个现有的连接。 (os error 10054)",
            "Connection reset by peer",
            "An existing connection was forcibly closed by the remote host",
            "WebSocket protocol error: Connection reset without closing handshake",
        ] {
            assert!(is_transient_codex_cdp_connection_error(error));
        }
        assert!(!is_transient_codex_cdp_connection_error(
            "Codex CDP returned invalid JavaScript"
        ));
    }

    #[test]
    fn codex_fuel_status_log_distinguishes_injection_from_cache_projection_and_redacts_values() {
        let mut injection = json!({ "fuelRuntimePresent": true, "fuelRuntimeVersion": 15, "fuelRuntimeReady": true,
            "fuelRuntimeEnabled": true, "fuelRuntimeUsageCache": {"installed": true,
                "enabled": false, "supported": 1, "unlocked": 0, "reason": "new-target-pending"} });
        let summary = codex_fuel_cache_log_summary(&injection);
        assert!(json_bool(&summary, "injected"));
        assert_eq!(json_str(&summary, "cacheState"), "缓存适配未启用");
        injection["fuelRuntimeUsageCache"]["enabled"] = json!(true);
        injection["fuelRuntimeUsageCache"]["unlocked"] = json!(1);
        assert_eq!(json_str(&codex_fuel_cache_log_summary(&injection), "cacheState"), "额度缓存已改写");
        injection["fuelRuntimeUsageCache"]["reason"] = json!("secret-token-and-message");
        injection["fuelRuntimeUsageCache"]["account_id"] = json!("private-account");
        let summary = codex_fuel_cache_log_summary(&injection).to_string();
        assert!(!summary.contains("secret-token-and-message"));
        assert!(!summary.contains("private-account"));
    }

