    #[test]
    fn session_delete_bridge_live_fixture_responds_when_provided() {
        let Ok(websocket_url) = std::env::var("CODEX_SESSION_DELETE_CDP_WEBSOCKET") else {
            return;
        };
        ensure_codex_session_delete_bridge(&websocket_url).unwrap();
        let status = cdp_evaluate_script(
            &websocket_url,
            r#"
(async () => {
  const result = await window.__gaogeSessionDeleteBridge("/status", {});
  return {
    bridgeReady: window.__gaogeSessionDeleteBridgeReady === true,
    ok: result?.ok === true,
    active: result?.active === true,
  };
})()
"#,
        )
        .unwrap();
        let injection = cdp_evaluate_script(
            &websocket_url,
            &codex_plugin_cdp_script("live-fixture", None, false, true, None),
        )
        .unwrap();
        let cleanup = cdp_evaluate_script(
            &websocket_url,
            &codex_plugin_cdp_script("live-fixture", None, false, false, None),
        );
        stop_codex_session_delete_bridge();
        cleanup.unwrap();
        assert_eq!(
            status.get("bridgeReady").and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(status.get("ok").and_then(Value::as_bool), Some(true));
        assert_eq!(status.get("active").and_then(Value::as_bool), Some(true));
        assert!(codex_session_delete_injection_verified(&injection));
        let rows = injection
            .get("sessionRows")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let buttons = injection
            .get("sessionDeleteButtons")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        if rows > 0 {
            assert!(buttons > 0);
        }
    }

    #[test]
    fn configure_lock_recovers_immediately_from_a_previous_process() {
        with_temp_user_home("codex-stale-configure-lock", |_root| {
            let lock_dir = codex_dir().join("locks");
            fs::create_dir_all(&lock_dir).unwrap();
            let lock_path = lock_dir.join("gaogeaii-configure.lock");
            fs::write(
                &lock_path,
                serde_json::to_vec_pretty(&json!({
                    "pid": 2_147_483_647u32,
                    "processInstanceId": "previous-process",
                    "ownerToken": "previous-owner",
                    "createdAt": unix_now(),
                }))
                .unwrap(),
            )
            .unwrap();

            let guard = acquire_codex_lock("configure").unwrap();
            let current = read_json_if_exists(&lock_path).unwrap().unwrap();
            assert_eq!(
                current.get("pid").and_then(Value::as_u64),
                Some(std::process::id() as u64)
            );
            drop(guard);
            assert!(!lock_path.exists());
        });
    }

    #[test]
    fn configure_lock_drop_does_not_delete_a_new_owners_lock() {
        with_temp_user_home("codex-configure-lock-aba", |_root| {
            let guard = acquire_codex_lock("configure").unwrap();
            let lock_path = codex_dir().join("locks").join("gaogeaii-configure.lock");
            fs::write(
                &lock_path,
                serde_json::to_vec_pretty(&json!({
                    "pid": std::process::id(),
                    "processInstanceId": PROCESS_INSTANCE_ID.as_str(),
                    "ownerToken": "replacement-owner",
                    "createdAt": unix_now(),
                }))
                .unwrap(),
            )
            .unwrap();

            drop(guard);
            assert!(lock_path.exists());
            fs::remove_file(lock_path).unwrap();
        });
    }

    #[test]
    fn poisoned_operation_mutex_is_recovered_instead_of_reported_busy() {
        let mutex = Arc::new(Mutex::new(()));
        let worker_mutex = Arc::clone(&mutex);
        let _ = thread::spawn(move || {
            let _guard = worker_mutex.lock().unwrap();
            panic!("poison test mutex");
        })
        .join();

        assert!(mutex.is_poisoned());
        let guard = try_lock_recover(&mutex, "busy").unwrap();
        assert!(!mutex.is_poisoned());
        drop(guard);
    }

    #[test]
    fn helper_process_timeout_kills_and_reaps_the_child() {
        #[cfg(target_os = "windows")]
        let mut command = {
            let mut command = hidden_command("powershell.exe");
            command.args(["-NoProfile", "-Command", "Start-Sleep -Seconds 5"]);
            command
        };
        #[cfg(not(target_os = "windows"))]
        let mut command = {
            let mut command = hidden_command("sh");
            command.args(["-c", "sleep 5"]);
            command
        };
        command.stdout(Stdio::piped()).stderr(Stdio::piped());
        let child = command.spawn().unwrap();
        let started = Instant::now();
        let error =
            wait_child_output_with_timeout(child, Duration::from_millis(100), "timeout-test")
                .unwrap_err();

        assert!(error.contains("timed out"));
        assert!(started.elapsed() < Duration::from_secs(2));
    }

