    #[test]
    fn plugin_market_verification_requires_native_evidence_not_catalog_or_marker() {
        let marker_only = json!({ "ok": true, "localMarketplaces": 78,
            "runtimeInjected": true, "__gaogeCodexPluginCdpFallbackV2": 1 });
        assert!(!codex_cdp_injection_verified(&marker_only, true));
        let state = json!({ "version": CODEX_PLUGIN_RUNTIME_VERSION, "disposed": false, "enabled": true, "runtimeReady": true,
            "runtimeInjected": true, "nativeEntryReady": true, "listVerified": true });
        assert!(codex_plugin_state_verified(&state));
        for key in ["runtimeReady", "runtimeInjected", "nativeEntryReady", "listVerified", "enabled"] {
            let mut incomplete = state.clone(); incomplete[key] = json!(false);
            assert!(!codex_plugin_state_verified(&incomplete), "missing {key}");
        }
        let mut stale = state.clone(); stale["version"] = json!(CODEX_PLUGIN_RUNTIME_VERSION - 1);
        assert!(!codex_plugin_state_verified(&stale));
        let mut disposed = state.clone(); disposed["disposed"] = json!(true);
        assert!(!codex_plugin_state_verified(&disposed));
        let mut legacy = state.clone(); legacy["needsRestart"] = json!(true);
        assert!(!codex_plugin_state_verified(&legacy));
        let mut failed = state.clone(); failed["error"] = json!("denied");
        assert!(!codex_plugin_state_verified(&failed));
        let pending = json!({ "version": CODEX_PLUGIN_RUNTIME_VERSION, "disposed": false, "enabled": true, "runtimeReady": false });
        assert!(codex_plugin_monitor_installed(&pending, true));
        assert!(!codex_plugin_state_verified(&pending));
        assert!(!codex_plugin_monitor_installed(&pending, false));
        assert!(!codex_plugin_monitor_installed(&json!({"version": CODEX_PLUGIN_RUNTIME_VERSION, "enabled": true, "disposed": true}), true));
        assert!(!codex_plugin_monitor_installed(&json!({"version": CODEX_PLUGIN_RUNTIME_VERSION - 1, "enabled": true}), true));
        assert!(include_str!("codex_plugin_runtime.js").contains(&format!("var CODEX_PLUGIN_RUNTIME_VERSION = {};", CODEX_PLUGIN_RUNTIME_VERSION)));
        let source = include_str!("lib.rs");
        let toggle = source.split("fn gaoge_set_codex_plugins_inner_v2(").nth(1).unwrap()
            .split("fn codex_plugin_active_debug_port(").next().unwrap();
        assert!(!toggle.contains("stop_prepare_and_launch"));
        assert!(!toggle.contains("stop_codex_app"));
        assert!(toggle.contains("runtime.configure"));
    }

