    #[test]
    fn macos_process_parser_filters_unrelated_apps_and_normalizes_helpers() {
        let output = concat!(
            "101 /Applications/Gaoge Free.app/Contents/MacOS/Gaoge Free\n",
            "102 /Applications/Safari.app/Contents/MacOS/Safari\n",
            "201 /Applications/ChatGPT.app/Contents/MacOS/ChatGPT\n",
            "202 /Applications/ChatGPT.app/Contents/Frameworks/ChatGPT Helper (Renderer).app/Contents/MacOS/ChatGPT Helper (Renderer)\n",
            "301 /Applications/Codex.app/Contents/MacOS/Codex\n",
        );

        let processes = parse_macos_running_codex_processes(output, None);
        assert_eq!(processes.len(), 3);
        assert_eq!(
            processes[0].app_dir,
            PathBuf::from("/Applications/ChatGPT.app")
        );
        assert_eq!(
            processes[1].app_dir,
            PathBuf::from("/Applications/ChatGPT.app")
        );
        assert_eq!(
            processes[2].app_dir,
            PathBuf::from("/Applications/Codex.app")
        );
        assert!(processes
            .iter()
            .all(|process| !process.app_dir.to_string_lossy().contains("Gaoge Free")));
    }

