            fs::write(portable_resources.join("app.asar"), b"portable-asar").unwrap();
            set_codex_install_dir_override(Some(portable.clone()));

            let store = root
                .join("WindowsApps")
                .join("OpenAI.Codex_26.721.4979.0_x64__publisher")
                .join("app");
