            fs::write(store_resources.join("app.asar"), b"store-asar").unwrap();

            let preferred = vec![portable.clone(), store.clone()];
            let runtime_selection = choose_runtime_enhancement_codex_app_dir(preferred.clone());
            let normal_selection = choose_auto_launchable_codex_app_dir(preferred);
