    #[test]
    fn enabling_plugins_registers_existing_local_marketplace() {
        with_temp_user_home("codex-plugin-marketplace-existing", |root| {
            let codex_home = root.join(".codex");
            let marketplace_root = codex_home.join(".tmp").join("plugins");
            fs::create_dir_all(marketplace_root.join(".agents").join("plugins")).unwrap();
            fs::create_dir_all(marketplace_root.join("plugins")).unwrap();
            fs::write(
                codex_openai_curated_marketplace_json_path(&marketplace_root),
                r#"{"name":"openai-curated","plugins":[{"name":"gmail","path":"./plugins/gmail"}]}"#,
            )
            .unwrap();
            fs::write(
                codex_home.join("config.toml"),
                "model_provider = \"custom\"\n",
            )
            .unwrap();

            let target = CodexDirTarget {
                dir: codex_home.clone(),
                source: "default",
                primary: true,
            };
            let result =
                with_codex_dir(&codex_home, || set_codex_plugins_current_dir(&target, true))
                    .unwrap();
            let config = fs::read_to_string(codex_home.join("config.toml")).unwrap();

            assert!(config.contains("[marketplaces.openai-curated]"));
            assert!(config.contains("source_type = \"local\""));
            assert!(!config.contains("[plugins.\"github@openai-curated\"]"));
            assert_eq!(
                result
                    .get("pluginMarketplace")
                    .and_then(|value| value.get("configured"))
                    .and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                result
                    .get("pluginMarketplace")
                    .and_then(|value| value.get("initialized"))
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                result
                    .get("pluginMarketplace")
                    .and_then(|value| value.get("pluginCount"))
                    .and_then(Value::as_u64),
                Some(1)
            );
        });
    }

    #[test]
    fn local_marketplace_payload_expands_manifest_for_cdp_script() {
        with_temp_user_home("codex-plugin-marketplace-payload", |root| {
            let codex_home = root.join(".codex");
            let marketplace_root = codex_home.join(".tmp").join("plugins");
            let plugin_root = marketplace_root.join("plugins").join("demo");
            fs::create_dir_all(marketplace_root.join(".agents").join("plugins")).unwrap();
            fs::create_dir_all(plugin_root.join(".codex-plugin")).unwrap();
            fs::write(
                codex_openai_curated_marketplace_json_path(&marketplace_root),
                r#"{"name":"openai-curated","plugins":[{"name":"demo","path":"./plugins/demo","composerIconPath":"icon.svg"}]}"#,
            )
            .unwrap();
            fs::write(
                plugin_root.join(".codex-plugin").join("plugin.json"),
                r#"{"displayName":"Demo Plugin","interface":{"composerIcon":"icon.svg"}}"#,
            )
            .unwrap();
            fs::write(
                codex_home.join("config.toml"),
                "[plugins.\"demo@openai-curated\"]\nenabled = true\n",
            )
            .unwrap();

            let payload = local_plugin_marketplaces();
            let marketplaces = payload.as_array().unwrap();
            assert_eq!(marketplaces.len(), 1);
            let plugin = marketplaces[0]
                .get("plugins")
                .and_then(Value::as_array)
                .and_then(|plugins| plugins.first())
                .unwrap();
            assert_eq!(
                plugin.get("displayName").and_then(Value::as_str),
                Some("Demo Plugin")
            );
            assert_eq!(plugin.get("installed").and_then(Value::as_bool), Some(true));
            assert!(
                plugin
                    .get("composerIconPath")
                    .and_then(Value::as_str)
                    .unwrap()
                    .ends_with("plugins\\demo\\icon.svg")
                    || plugin
                        .get("composerIconPath")
                        .and_then(Value::as_str)
                        .unwrap()
                        .ends_with("plugins/demo/icon.svg")
            );

            let helper = CodexSessionHelper {
                base_url: "http://127.0.0.1:45678".to_string(),
                token: "test-token".to_string(),
            };
            let script = codex_plugin_cdp_script("26.616.0", Some(&helper), true, false, None);
            assert!(script.contains("window.__GAOGE_PLUGIN_MARKETPLACES__"));
            assert!(script.contains("window.__GAOGE_PLUGIN_ENHANCEMENTS_ENABLED__ = true"));
            assert!(script.contains("window.__GAOGE_SESSION_DELETE_ENABLED__ = false"));
            assert!(script.contains("window.__GAOGE_DESIRED_RUNTIME_REVISION__"));
            assert!(script.contains("window.__GAOGE_RUNTIME_REVISION__ = runtimeRevision"));
            assert!(script.contains("window.__GAOGE_PLUGIN_RUNTIME_READY__"));
            assert!(script.contains("window.__GAOGE_SESSION_DELETE_RUNTIME_READY__"));
            assert!(script.contains("window.__GAOGE_THEME_RUNTIME_READY__"));
            assert!(script.contains("Demo Plugin"));
            assert!(script.contains("mergeLocalPluginMarketplaces(result)"));
            assert!(script.contains("installPluginMarketplaceBridgePatch"));
            assert!(script.contains("installPluginMarketplaceWindowEventPatchOnly"));
            assert!(script.contains(CODEX_PLUGIN_LEGACY_BEFORE_VERSION));
            assert!(script.contains(CODEX_PLUGIN_BRIDGE_FROM_VERSION));
            assert!(script.contains("gaoge-codex-session-delete"));
            assert!(
                script.rfind("hideSessionRows(sessionId);").unwrap()
                    < script
                        .find("await deleteThread(sessionId, title);")
                        .unwrap()
            );
            assert!(script.contains("toast(\"已删除会话\")"));
            assert!(!script.contains("正在后台删除"));
            assert!(
                script
                    .find("openReplacementSession(replacementRow, sessionId);")
                    .unwrap()
                    < script
                        .find("await deleteThread(sessionId, title);")
                        .unwrap()
            );
            assert!(script.contains("X-Gaoge-Token"));
            assert!(script.contains("http://127.0.0.1:45678"));
        });
    }

